var SOUP_LIBRARY = [{"id": "lib_00132cc37be4", "srcNo": 133, "title": "", "dispTitle": "无题 · KONpiGG #133", "surface": "一个人过生日，邀请他所有的好朋友来参加。吹完蜡烛的时候，这个人把他所有的好朋友都杀了。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_0015920e33d8", "srcNo": 852, "title": "气球", "dispTitle": "气球", "surface": "天好黑啊，还好爸爸带了蜡烛，哥哥带了食物，妈妈最伟大，用气球救了我。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_005e1bd9c5d7", "srcNo": 332, "title": "特效", "dispTitle": "特效", "surface": "她演得真好。被人推了一把，从楼梯上滚下来的时候，头发像瀑布一样散开，眼睛睁得好大，好像在找镜头。银幕里导演喊了cut，然后他自己也躺下了，大概是喊累了吧。但她还躺在地上不动，血从嘴角流出来，真是敬业。我鼓掌了，这特效太真了。\n有人把她抬走了，是去后台休息的吧，其他工作人员也跟着离开了。我也该走了，电影彩蛋结束了。但我找不到出口，这里好像不是电影院。\n后来又有人扶我坐下，给我吃药。我看着窗外，太阳和刚才一样高。", "cats": ["悬疑"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_007dafa7c9bf", "srcNo": 931, "title": "第七条怪谈", "dispTitle": "第七条怪谈", "surface": "规则一：空白 规则二：空白 规则三：空白 规则四：空白 规则五：空白 规则六：空白 规则七：空白", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_00a1ff7c37f9", "srcNo": 665, "title": "第七个人没有淋湿", "dispTitle": "第七个人没有淋湿", "surface": "七个人一同前往同一地点。突然下雨，六个人加快脚步，最后仍全身湿透；第七个人始终没有迈步，也没撑伞，却干干爽爽地和他们同时到达。为什么？", "cats": ["反转", "悬疑"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_00c64b59d6d4", "srcNo": 363, "title": "「獻祭」", "dispTitle": "「獻祭」", "surface": "深夜，指揮官站在軍事地圖前，用紅筆在地圖上畫了一個圈。他非常清楚，再過三個小時，敵軍的轟炸機群就會將這個區域徹底夷為平地。\n只要他打一通電話，就能讓全城拉響防空警報。然而，他卻下令切斷該區域對外的所有通訊，並嚴禁任何人發出警報。\n隔天清晨，整座城市在轟炸中灰飛煙滅。\n他事後卻被國家授予了最高榮譽的英雄勳章。", "cats": ["悲剧", "逻辑"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_00eaaea27198", "srcNo": 448, "title": "感冒致死", "dispTitle": "感冒致死", "surface": "安东尼最近得了感冒，第二天，被发现死在了家里。", "cats": ["反转", "本格"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_0224e82c7650", "srcNo": 250, "title": "017 · 水草", "dispTitle": "017 · 水草", "surface": "有个男子跟女友去河边散步，女友突然掉进河里，男子跳入水中去找，但没有找到，伤心离开。几年后他故地重游，见到一位老人在钓鱼，钓上来的鱼身上没有水草。他问老人为什么，老人说：\"你不知道吗，这条河从来没有长过水草。\" 男子听后跳入水中自杀了，为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_02388e0a35eb", "srcNo": 677, "title": "被拨乱的密码", "dispTitle": "被拨乱的密码", "surface": "主人锁好箱子后，总把四个数字都拨离原位，还特意说：每一位都不能留在正确数字上。小偷从没看见他开锁，只记录每次锁好后的数字。过了一段时间，小偷一次就打开了箱子。为什么？", "cats": ["反转", "推理"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_0269e650b41f", "srcNo": 705, "title": "一双鞋", "dispTitle": "一双鞋", "surface": "男人醒来只看到一双鞋就自杀了，为什么？", "cats": ["反转", "悬疑"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_027accce24d9", "srcNo": 594, "title": "生日惊喜", "dispTitle": "生日惊喜", "surface": "一个富有的女人找了个比她小十多岁的老公。那天是女人的生日，老公让她晚上早点回家，说有惊喜要给她。晚上女人开车回到家，男人才从外面回来，他送给女人一束花，便又去匆忙做晚饭。第二天，女人死了。", "cats": ["悬疑", "本格"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_028f0dfe1fbe", "srcNo": 208, "title": "忠诚的狗", "dispTitle": "忠诚的狗", "surface": "小强养了一只很忠诚的狗，今天他牵着狗上街，然后小强死了。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:wangyafu/haiguitangmcp", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_03135614c003", "srcNo": 1072, "title": "特殊的试卷", "dispTitle": "特殊的试卷", "surface": "全班学生都在进行一场极其重要的考试。突然，一个学生站起来撕碎了试卷并大笑，其他学生也跟着撕碎了试卷。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_031555a0e4ee", "srcNo": 599, "title": "聲音", "dispTitle": "聲音", "surface": "小時候在鄉下，我曾經有過一段極為恐怖的經歷，自從那件事之後，我就對某個聲音以及白色、特別是衣服有著近乎異常的恐懼，尤其是那帶著某種詭異的韻律感，像是在刻意模仿人類說話的聲音...\n長大後，就在我逐漸淡忘了這件事情時，那個聲音又出現了，並且我的眼角不時會閃現那被我淡忘的白色衣角。\n我知道這一次，我再也逃不掉了...", "cats": ["恐怖"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_031e8b9690fc", "srcNo": 692, "title": "婴儿房里的洋娃娃", "dispTitle": "婴儿房里的洋娃娃", "surface": "一场意外后妻子把自己关在房间里不肯出来。那天我听到她嚎啕大哭，冲进去后被吓傻。", "cats": ["恐怖", "悬疑", "惊悚", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_03c704631a6d", "srcNo": 884, "title": "寻人启事", "dispTitle": "寻人启事", "surface": "衣甜，女，31岁，离异，工作：医生，失踪时间：一个月。线索：1. 一份衣甜的保险单，受益人是衣甜的父亲；2. 前夫最近娶了衣甜的同事；3. 衣甜父亲有救助流浪猫的习惯；4. 今天有一个人从钟楼跳下去摔死了，死亡时间是凌晨3-4点之间。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_03d26eb2cfd1", "srcNo": 140, "title": "", "dispTitle": "无题 · KONpiGG #140", "surface": "一名女子来到县衙报案，刚到门口，她便浑身瘫软在地", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_03d6cd890a93", "srcNo": 745, "title": "一巴掌", "dispTitle": "一巴掌", "surface": "一个人半夜醒来打了自己一巴掌，然后闻到燃烧味就安心睡去。", "cats": ["搞笑", "日常"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_03fde71a3571", "srcNo": 90, "title": "", "dispTitle": "无题 · KONpiGG #90", "surface": "一个雨天，男人拉着一个大行李箱出门。他在门口碰见了自己的妻子，和妻子兴奋地说了几句话后，他神色忽然古怪至极。他仔细看了看妻子的侧脸，看了看手表，又转头看了看门外的大雨。而后他慌慌张张拉着行李箱走了，从此销声匿迹。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_040e60fded71", "srcNo": 491, "title": "鱼的记忆", "dispTitle": "鱼的记忆", "surface": "第一个7秒，她将自己的笑颜贴近\n第二个7秒，他将新的水撒入缸里\n第三个7秒，他们又抚摸我的鱼鳍", "cats": ["恐怖", "本格"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_044e0af074d4", "srcNo": 862, "title": "牧场", "dispTitle": "牧场", "surface": "妈妈去世了，留给我一个废弃已久的牧场。第二天牧场里不知道从哪来了一只鸡，第三天又多了一头牛，第四天又多了一只羊，我很诧异。接下来一个月，牧场多了很多动物，我终于明白怎么回事了。于是我做了一个疯狂的决定，结果第二天牧场里多出了一个年轻的女人，看到她后我疯了……", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_048783dc7b0c", "srcNo": 967, "title": "", "dispTitle": "无题 · YanJiaHuan #967", "surface": "拔萝卜，拔萝卜，嘿呦嘿呦拔萝卜，小朋友，快快来，快来帮我拔萝卜，红萝卜，白萝卜，全部都是坏萝卜。这首儿歌中的萝卜指的是什么？故事到底发生了什么？", "cats": ["其他"], "difficulty": 2, "src": "github:YanJiaHuan/TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_048dc4d7aeb0", "srcNo": 1222, "title": "Jed 1.83", "dispTitle": "Jed 1.83", "surface": "A woman lies dead in the street near a car. (AG)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_04936ace80ec", "srcNo": 1255, "title": "半杯热水", "dispTitle": "半杯热水", "surface": "护士查房时看见病人床头那杯本该凉透的水还是热的，立刻通知家属“他终于醒了”。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:lancelily6362-png/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_04df3faf715b", "srcNo": 413, "title": "凋零之花", "dispTitle": "凋零之花", "surface": "我在精神病院醒来，身边是三具尸体。所有人都说我是凶手，但我完全失忆了。主治医生林玥坚持要帮我找回记忆。在整理我入院物品时，我发现一张被烧掉一半的照片——一个穿校服的女孩，背面写着：“爸爸，茉莉花开了。”\n\n我从未记得自己有女儿。但昨夜梦里，我反复闻见茉莉花香，还有少女的哭声。", "cats": ["恐怖", "悬疑"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_04e877fbbd46", "srcNo": 441, "title": "晚饭", "dispTitle": "晚饭", "surface": "晚上小明回家之后，一如既往的直接去吃女朋友准备好的晚饭，当他吃了一口觉得有点奇怪，在思考怎么回事的时候，他死了", "cats": ["恐怖", "悬疑", "悲剧", "犯罪"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_0523c46f77c9", "srcNo": 805, "title": "走失的孩子", "dispTitle": "走失的孩子", "surface": "一名母亲惊慌失措报警，说自己 6 岁儿子在商场走失。警方调阅监视器却找不到符合描述的孩子，也没人报案走失儿童。几天后母亲带着儿子到警局开心说：「他自己回来了！」警方却立刻逮捕她。为什么？", "cats": ["悬疑", "推理", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_05463c380713", "srcNo": 750, "title": "紫罗兰", "dispTitle": "紫罗兰", "surface": "男人每天给妻子送一束她最讨厌的紫罗兰，直到妻子葬礼当天，他把所有紫罗兰烧毁，突然大哭大笑。", "cats": ["反转", "推理", "温情", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_056db100d29a", "srcNo": 561, "title": "看不见的生日", "dispTitle": "看不见的生日", "surface": "一个盲人在和朋友们一起过生日，朋友们一起给他唱生日歌，唱完生日歌之后盲人把他的朋友们都杀了", "cats": ["恐怖", "本格"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_058d6a4eae6f", "srcNo": 465, "title": "求助电话", "dispTitle": "求助电话", "surface": "男人接到了朋友被绑架的求助电话，但是男人没有救朋友，为什么。", "cats": ["本格"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_05c070e9070b", "srcNo": 1071, "title": "盲人摸象", "dispTitle": "盲人摸象", "surface": "一群盲人在森林里摸到了一个“巨大的温热物体”，他们以为是象，纷纷开心地靠在上面休息。直到其中一个盲人摸到了“拉链”。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_05cbea68fd8f", "srcNo": 715, "title": "预言", "dispTitle": "预言", "surface": "我有个能预言的万能婆婆。有一天她消失了，我独自去参加舞会，回来后却再也撑不下去了。为什么？", "cats": ["反转", "悬疑", "温情"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_05d55826327b", "srcNo": 1201, "title": "Jed 1.19", "dispTitle": "Jed 1.19", "surface": "There is blood on the ceiling of my bedroom. (MI original)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_05d5a3a05646", "srcNo": 821, "title": "不响的闹钟", "dispTitle": "不响的闹钟", "surface": "某天早上，一个男人准时起床，准备上班。但他发现闹钟没有响，且电池已经没电了。为什么他还能准时起床？", "cats": ["日常"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_05ee4cafe666", "srcNo": 276, "title": "047 · 洋娃娃", "dispTitle": "047 · 洋娃娃", "surface": "一场意外后，妻子便把自己关在房间里不肯出来。那天我突然听到她在嚎啕大哭，急忙冲进房间，被眼前的一幕吓傻了。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_05eec246c795", "srcNo": 1268, "title": "雨夜车祸", "dispTitle": "雨夜车祸", "surface": "一个雨夜，发生了一起车祸。司机声称他是因为躲避突然冲到路上的鹿才撞车的。但警察到达现场后，立即逮捕了司机。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:ns5601/ai-haigui-game", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_05ff5861964d", "srcNo": 534, "title": "家", "dispTitle": "家", "surface": "這個家沒有溫暖，我千辛萬苦從家裡逃了出來，沒多久卻被抓了回去，最後我死在了家裡。", "cats": ["本格"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_060f17084b69", "srcNo": 163, "title": "", "dispTitle": "无题 · KONpiGG #163", "surface": "主人和狗一起死在了沙滩上，试推测发生了什么事？", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_061a1d68f450", "srcNo": 1028, "title": "死亡直播", "dispTitle": "死亡直播", "surface": "女主播在直播间表演，观众纷纷打赏，说‘表演得太真实了’。直到直播自动结束，大家才发现她是真的死了。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_067a526da329", "srcNo": 543, "title": "牛吃草", "dispTitle": "牛吃草", "surface": "有一个年轻的男人，他的房子和邻居夫妇的房子中间隔着一片草坪。有一天深夜，男人被隔壁的吵架声吵醒，之后他又听到了摔东西声、砍斧子声和牛吃草的声音，过了一会，他又听到了有人撞他家门的声音，但他都没有理会，又睡了过去。第二天，他发现隔壁的女主人惨死在他家门口。请推理女主人的死因。", "cats": ["恐怖"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_0695135164a2", "srcNo": 946, "title": "乐谱", "dispTitle": "乐谱", "surface": "你捡到了一份乐谱，你很好奇的打开了它，内容如下。\n\n![img_rId14.png](./海龟汤图片/img_rId14.png)", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_0696ae22b31a", "srcNo": 335, "title": "白昼流星", "dispTitle": "白昼流星", "surface": "白昼流星将要划过，我躲在阴影里掐算着它的死期。\n    手机里一条APP提示突然亮起，我惊恐地拨通电话，近乎疯狂，微弱的信号那头，久违的她语气冷漠，孩子却在欢笑。\n    我流着泪在电话里疯狂地嘶吼，她却冷冷地丢下一句“你真是个疯子”，随后挂断。\n    流星准时划过，死期已到，流星的碎片，将我的世界彻底摧毁。", "cats": ["悲剧", "本格"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_06ee059426c6", "srcNo": 373, "title": "河神的禮物", "dispTitle": "河神的禮物", "surface": "將軍率領殘兵死守在一座位於谷底的孤城中，敵軍已經將他們重重圍困，糧草亦即將耗盡。\n\n這天深夜，一隻信鴿飛入營帳，將軍打開信筒，裡面沒有任何紙條，只有一顆完全乾燥、帶有特殊紋路的鵝卵石。\n\n將軍看著石頭笑了。隔天清晨，他下令全軍將僅存的糧食全部留在城內的營帳，所有人立刻撤退，向外突圍至城外的荒山上。敵軍見狀，沒有多加阻攔，他們不費吹灰之力佔領了孤城並奪取那些糧草。\n\n然而三天後，將軍贏得了這場戰爭。", "cats": ["逻辑"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_07683789732d", "srcNo": 458, "title": "千万只眼", "dispTitle": "千万只眼", "surface": "我提着滚烫的食物，走进了野兽的巢穴。\n那只野兽赤身裸体地沉睡，对此一无所知。\n我没有逃跑，而是兴奋地剥下它的“皮囊”，将其抛向空中，喂养那三千万只饥饿的眼睛。\n广场上的看客们咀嚼着皮囊，高呼我是幸存的英雄。\n可当狂欢散场，野兽醒来毫发无伤，我却被捕兽夹死死咬住了脚踝。", "cats": ["反转", "悬疑", "推理", "都市"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_0779cb5752e1", "srcNo": 1042, "title": "不准的钟", "dispTitle": "不准的钟", "surface": "家里的钟每天都快5分钟。主人却从不修理，反而觉得这样救了他的命。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_07c19dce8061", "srcNo": 419, "title": "祭河神", "dispTitle": "祭河神", "surface": "河边的村落每年举行祭河神的仪式，献祭一位年轻女性作为河娘以换取风平浪静和安宁。今年抽签轮到村长的女儿作为河娘祭祀。祭祀后河水却反常暴涨，冲毁了堤岸。村民惊恐，认为河神震怒，定是对祭品不满。只有船夫在一旁默默抽着旱烟。", "cats": ["恐怖", "悲剧", "本格"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_07daf49f9167", "srcNo": 873, "title": "漂流瓶", "dispTitle": "漂流瓶", "surface": "我舅舅来快三年了，而又涌向这群人，只烦杨娟被关起来，犁刀刀片锋利我们被．友情提醒：他是本地人！平时会伪装成导游！一定要找到他！！我说的不是杨娟！", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_086c4a778b97", "srcNo": 883, "title": "许愿", "dispTitle": "许愿", "surface": "我低下头许愿，愿望实现了，我却哭了。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_087b4e1374f3", "srcNo": 938, "title": "替罪", "dispTitle": "替罪", "surface": "牛郎织女多离分，羊儿回首欲报恩。四散飘零寻归处，可识当年窃羊人？", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_08a08b9bdd9c", "srcNo": 1289, "title": "", "dispTitle": "无题 · boop-yyt #1289", "surface": "A man is killed on a train. He is found to have written \"elf\" on the floor in his own blood. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_090fb2fb97fe", "srcNo": 40, "title": "出租房", "dispTitle": "出租房", "surface": "我搬进了一个新房子，房间里经常有类似于老鼠爬的声音，但毕竟便宜，我也睡的很香，没多久房东就谈了一个女朋友，老鼠的声音好像也没了，但突然的安静却让我不能安心入睡。", "cats": ["犯罪"], "difficulty": 3, "src": "github:anchorAnc/astrbot_plugin_TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_097336e53d3b", "srcNo": 1371, "title": "", "dispTitle": "无题 · boop-yyt #1371", "surface": "A rope breaks. A bell rings. A boy dies. How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_0977abffd5a2", "srcNo": 61, "title": "安全", "dispTitle": "安全", "surface": "外面很危险，我要藏好了，猜猜我在哪，嘘...我要睡着了…", "cats": ["恐怖"], "difficulty": 3, "src": "github:anchorAnc/astrbot_plugin_TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_09bbb27d608c", "srcNo": 402, "title": "教学楼走廊", "dispTitle": "教学楼走廊", "surface": "那天，我值班照例巡视教学楼，但我再也没有走出那条走廊，亲人闹到学校，学校二话不说赔付了巨额。全家只有我弟弟一人不同意。", "cats": ["恐怖", "本格", "校园"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_09c0825b5def", "srcNo": 1324, "title": "", "dispTitle": "无题 · boop-yyt #1324", "surface": "A woman opens an envelope and dyes. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_09d7c011209a", "srcNo": 494, "title": "雪人胡萝卜", "dispTitle": "雪人胡萝卜", "surface": "房子前的草坪上躺着五块煤、一根胡萝卜和一条围巾。虽然没有人特意把它们放在那里，但它们出现在草坪上却有着完全合乎逻辑的理由。那是什么呢？", "cats": ["逻辑"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_0a2018a21c9b", "srcNo": 533, "title": "误闯天家", "dispTitle": "误闯天家", "surface": "我在夜场工作，见过许多身份尊贵的人，深知他们的不简单，哎，有权真好啊，我只是一个小人物，谁都惹不起，默默打工好了。夜场嘈杂，声音太大了，下班了我得去医院看看我的耳朵，最近我感觉耳朵有点痛。这条路有点堵啊，不对，前面有交警在查酒驾！怎么办？我只喝了一点酒应该没关系吧，要不要现在下车逃跑？咦？不对，前面那个车吹出警报了居然没被惩罚？就直接走了？难道今天查车只是做做样子吗？到我了。\n嘀！嘀！嘀！“你涉嫌酒驾，下车跟我们走”。\n\"不，为什么前面那个车也吹响警报了，为什么不抓他！\"\n\"前面开车的是戴家的，吹响的是傅家的人。“\n我顿敢晕眩，不敢闹事，只能配合被带走。", "cats": ["日常", "本格"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_0a5e63a35d93", "srcNo": 824, "title": "无声的音乐", "dispTitle": "无声的音乐", "surface": "阿强打开手机准备放音乐，按下播放键后，手机显示音乐正在播放，但却完全没有声音，为什么？", "cats": ["日常"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_0a6ac3ba2a91", "srcNo": 340, "title": "晚点名", "dispTitle": "晚点名", "surface": "我们宿舍有个不成文的规矩:每晚熄灯前，必须由寝室长站在宿舍门口，对着漆黑的走廊完整点名一遍，一个都不能少。\n这周一开始，点名总会多出一个陌生的名字。\n没人敢质疑，也没人敢漏念。\n与此同时，我身后的教室，灯亮了。\n我瞬间浑身冰凉，终于明白一死的人，一直是我们自己。", "cats": ["怪谈", "恐怖", "悬疑"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_0a6d1163d6f9", "srcNo": 1290, "title": "", "dispTitle": "无题 · boop-yyt #1290", "surface": "A man lies dead next to a feather. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_0a8d65c99059", "srcNo": 921, "title": "爷爷的低吼", "dispTitle": "爷爷的低吼", "surface": "2005年 H市，自打胡七二记事起爷爷就躺在病床上，他睁着眼睛，一动不动，也不需要进食或排泄。世界上任何医生都无法解释这一现象。2006年 父亲和胡七二说爷爷曾是摸金校尉，有一次他被抬回来，就变成了这样。爷爷留下了摸金秘术，胡七二时常翻看。父亲发现后严肃地和胡七二说：”不要走你爷爷老路“。2015年 爷爷闭上眼睛了，也没有心跳，大家都以为他死了，可他嘴里却开始发出恶魔般的低吼，连绵不绝，永不停歇，格外的吓人。2016年 胡七二成为了一名摸金校尉。摸金秘术中有着爷爷临摹的地图，胡七二按照路线到了一个存在于海底的墓穴，墓门被锁上了，碑上刻着小篆：”受始皇帝之命，寻求永生不死之法。“2025年 爷爷睁开了眼睛，也不再发出恶魔般的低吼了。胡七二在整理爷爷房间时发现了一把被黄纸包着的钥匙，黄纸上写着：永生不死 2026年 胡七二又一次去了墓中。与此同时，H市出现了很多灵异事件。胡七二家的地上密密麻麻地写满了：救命！而墓中没有尸体，地上有一面恰好镜面朝上的镜子。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_0aae87087f4d", "srcNo": 26, "title": "半瓶香水", "dispTitle": "半瓶香水", "surface": "我的妈妈最近有些反常，不但偷偷用我的香水穿我的衣服，还老是半夜出去。那天我实在忍不住向她理论，并发生了争执，结果不小心把她推倒在地，我赶忙上前扶她，却发现自己的双手沾满了鲜血。", "cats": ["医院"], "difficulty": 3, "src": "github:anchorAnc/astrbot_plugin_TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_0adc47714500", "srcNo": 333, "title": "笔仙", "dispTitle": "笔仙", "surface": "笔仙笔仙\n\n你是我的前世我是你的今生如要与我续缘请再纸上画圈\n\n忧郁的男人第一个提问：\"她是不是不爱我了\"笔动了，落在了\"是\"字上，看到答案，他松了一口气。华贵的老妇人接着问：\"我是不是真的永远不会变老了？\"\"是\"老妇人露出了放心的笑容。美丽的少妇又问\"是不是有人知道我的秘密了\"\"是\"少妇变得紧张起来笔又自发的缓缓动起来，拼出了几个字。\n\n\"你们知道，我是谁吗？”", "cats": ["其他"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_0b330f52e242", "srcNo": 1303, "title": "", "dispTitle": "无题 · misc #1303", "surface": "A man tries to buy poison to kill his wife. The pharmacist figures out what he's up to and finds a way to ensure that he can't kill his wife. How to do this?", "cats": ["其他"], "difficulty": 2, "src": "misc/repo-scan", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_0bb632eaca32", "srcNo": 840, "title": "怀孕", "dispTitle": "怀孕", "surface": "爱人怀孕好几个月啦，我听着孩子的胎动，兴奋不已。虽然爱人日渐消瘦，但他应该能理解我了……", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_0c1d2f8b2871", "srcNo": 662, "title": "难看的皮毛", "dispTitle": "难看的皮毛", "surface": "牧场里，一只羊被刷上显眼的蓝色记号。其他羊陆续装上车，它却被留下。记号没有伤害它，也没有让主人嫌弃它，反而使它免于被送往屠宰场。为什么？", "cats": ["日常", "温情"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_0c44293fd6f1", "srcNo": 1213, "title": "Jed 1.51", "dispTitle": "Jed 1.51", "surface": "If he'd turned on the light, he'd have lived. (JM)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_0c4522f76be1", "srcNo": 20, "title": "空邮件", "dispTitle": "空邮件", "surface": "她连续收到三封没有内容的邮件。第四天，她没有打开邮箱就报了警。", "cats": ["其他"], "difficulty": 2, "src": "github:17hczmsn/turtle_soup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_0ca9e9afce15", "srcNo": 796, "title": "深夜的吸尘器", "dispTitle": "深夜的吸尘器", "surface": "一名大学生搬进老旧公寓顶楼套房。每到凌晨三点楼上总传来规律吸尘器声持续约一小时，困扰数月。他向房东抱怨「楼上是谁半夜用吸尘器？」房东脸色惨白说「楼上……没人住啊……」但之后大学生也再也听不到噪音了……", "cats": ["悬疑", "惊悚", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_0cbe648ec99a", "srcNo": 707, "title": "拔萝卜", "dispTitle": "拔萝卜", "surface": "拔萝卜、拔萝卜……红萝卜白萝卜全部都是坏萝卜……", "cats": ["恐怖", "悬疑", "惊悚"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_0cf00682e3ce", "srcNo": 135, "title": "", "dispTitle": "无题 · KONpiGG #135", "surface": "一场意外后，妻子便开始把自己关在房间里，不肯出来。那天我突然听到她在嚎啕大哭，我急忙冲进房间里，却被眼前的一幕吓傻了。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_0d525299c057", "srcNo": 420, "title": "真心村的诅咒", "dispTitle": "真心村的诅咒", "surface": "传说中大山深处有一个真心村，这里的村民纯朴热心，对外来者的话深信不疑。\n我是名赌徒，输光了钱后来到了村子，我向村民求救，村民看我的眼神很怪。村民虽然对我的请求闭口不提，却给我送来了\"礼物\"。我对此很愤怒，我一定被骗了！我好像有哪里不对劲，我留在了村子里。", "cats": ["怪谈"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_0d56ab30f5cc", "srcNo": 787, "title": "沙发", "dispTitle": "沙发", "surface": "某天女子坐在家里的新沙发上看电视，看着看着突然尖叫。", "cats": ["反转", "恐怖", "悬疑", "惊悚"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_0d603c7d7b6c", "srcNo": 282, "title": "053 · 冰箱", "dispTitle": "053 · 冰箱", "surface": "我的父母都不理我，但我还是很爱他们。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_0d76187607a2", "srcNo": 1048, "title": "反转的重力", "dispTitle": "反转的重力", "surface": "男子在街上散步，突然他紧紧抱住路边的电线杆，看向天空，露出了极度恐惧的神情。随后，他真的‘掉’向了天空。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_0da576b33d0d", "srcNo": 861, "title": "歌声", "dispTitle": "歌声", "surface": "男人和女人在喝酒，突然听到熟悉的歌声。不久后，二人都死了。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_0daf1eafe0c9", "srcNo": 313, "title": "085 · 守灯人", "dispTitle": "085 · 守灯人", "surface": "守灯人半夜起来喝水，随手把灯关了，又回去睡觉了。第二天，他自杀了。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_0db23dc74554", "srcNo": 393, "title": "未寄出的情书", "dispTitle": "未寄出的情书", "surface": "前男友意外离世的第三个月，我终于鼓起勇气登录了他的云端账号，想以此作为最后的告别。\n在草稿箱里，我发现了一封创建于他遇害当晚凌晨3点的未发送邮件，收件人是我。\n邮件没有正文，只有一串凌乱却甜得发腻的单词，看起来像是他喝醉后对我笨拙的告白：\n\n“Honey（亲爱的）……Baby（宝贝）……Rose（玫瑰）……Kiss（吻）……Hug（拥抱）……”\n\n看着这些即使分手后依然保留在他输入法首选位的词汇，我泪如雨下。然而，负责案件的老刑警在看了一眼屏幕后，神色瞬间变得惨白，一把夺走了我的手机。", "cats": ["悬疑", "本格"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_0dd4d36c0b32", "srcNo": 897, "title": "他不喜欢", "dispTitle": "他不喜欢", "surface": "我和妹妹相依为命，但由于妹妹的死亡，我染上了一个习惯。可今天我被抓住了，他叫我赔给他。他的做法我很震惊，但好像还不错，我很喜欢！十年后，我用以前的办法寻找他，可一无所获。于是我去买了针线。可他好像不喜欢，他发出一声惊叫，并报了警。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_0e134ac04a78", "srcNo": 1322, "title": "", "dispTitle": "无题 · boop-yyt #1322", "surface": "Two people are playing cards. One looks around and realizes he's going to die. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_0e181ff97371", "srcNo": 909, "title": "巨人", "dispTitle": "巨人", "surface": "出差前，我发现妻子画了一个陌生男人，她说：”这是个巨人，我梦见我被他握在手中杀死了。“只是梦境所以我并没有在意，可等我出差回来，我却发现妻子死在了家中，警察调查后叹了口气：”唉，第十六个。“", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_0e25b58a3f4d", "srcNo": 418, "title": "哥哥", "dispTitle": "哥哥", "surface": "哥哥是學界頂尖的博士，但我只知道好像是跟人體研究相關，總會說一些我不太懂、關於大腦與意識之類的醫學術語。哥哥從小對我疼愛有加，就連我現在的對象也是他介紹給我的。然而這樣的他卻在一次實驗意外中走了，我非常難過，還好我的對象依然不離不棄地照顧我。然而最近看著他，有些習慣變得很奇怪，而且開始說出一些我很熟悉的話，再加上他對某些只有我和哥哥知道的事情反應過於自然。無意間瞥見頭上有道傷疤，他說那是小時候留下的，但我不記得他有那個傷...？", "cats": ["家庭"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_0ed4dd3f3ce3", "srcNo": 109, "title": "", "dispTitle": "无题 · KONpiGG #109", "surface": "我走进电梯准备去上学，随着电梯的上升，我知道，我再也无法去学校了。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_0edf88c0dca6", "srcNo": 570, "title": "完美的特写", "dispTitle": "完美的特写", "surface": "小明是一个追求极致的摄影师。深夜，他在工作室的电脑前，看着刚刚修好的一张少女脸部特写成片。\n他盯着屏幕，赞叹道：“真是太完美了，除了这之外毫无瑕疵。”\n随后，他露出了满意的微笑，拿起桌上的手术刀，割开了自己的喉咙。", "cats": ["恐怖", "逻辑"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_0f05c1b4b831", "srcNo": 1295, "title": "", "dispTitle": "无题 · boop-yyt #1295", "surface": "A man dies in his own home. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_0f1e1dbacbac", "srcNo": 916, "title": "小不点来了", "dispTitle": "小不点来了", "surface": "”妈妈，小不点来了！“ 中午，客厅突然传来声音，可我是独居女性。声音的来源令我毛骨悚然，于是我立马搬家。搬家后的第一晚，我失眠了。午夜客厅再次传来声音。 ”妈妈，小不点来了！“我想到我流产的孩子。我立马打字联系之前的房东：”我想搬回去。“", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_0fa0dac82fb7", "srcNo": 1225, "title": "Jed 1.90", "dispTitle": "Jed 1.90", "surface": "A man urinates and dies. (RA original)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_0fdefd44364d", "srcNo": 940, "title": "谎言之界", "dispTitle": "谎言之界", "surface": "你们三人在深邃地穴的冒险中发现千年古堡，长廊笔直又扭曲，身体轻盈，陌生记忆涌入。遗骸手中的纸条写着：有光明的地方一定存在黑暗；鱼和熊掌不可得兼；盒子里的猫是生是死？我在盒子里，所以还不知晓；光明倘若消失，世界即为黑暗；我想……我应该失败了。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_0fe98aefdcb6", "srcNo": 510, "title": "金钗毒", "dispTitle": "金钗毒", "surface": "宫宴之上，贵妃亲手将一支金钗插在公主发间，公主笑谢，三日后却暴毙身亡。贵妃未被治罪，反而进封位份，皇帝得知真相后，也只是长叹一声。", "cats": ["悲剧", "本格", "逻辑"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_1006446d3fd3", "srcNo": 365, "title": "你的飞鱼服，我的绣春刀", "dispTitle": "你的飞鱼服，我的绣春刀", "surface": "锦衣卫北镇抚司千户陆炳章，最近三个月总在子夜独自前往档案库。同僚发现他出来后，常对着一面铜镜喃喃自语，镜面却总是蒙着布。一个雨夜，他在库内暴毙，右手紧握着一枚生锈的腰牌，上面刻的名字竟是他自己的——但据记载，这个名字属于二十年前就已“殉职”的另一位千户。最诡异的是，验尸时发现他的胃里干净得异常，像是数日未食，但仵作回忆：“他前日午膳，明明当众吃下了一整只烧鹅。”", "cats": ["悬疑", "悲剧", "脑洞"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_10769cc52a8a", "srcNo": 1378, "title": "", "dispTitle": "无题 · boop-yyt #1378", "surface": "There are 53 bees instead of 53 bicycles. How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_1078e9b7b092", "srcNo": 1128, "title": "笔仙", "dispTitle": "笔仙", "surface": "笔仙笔仙，你是我的前世，我是你的今生，如要与我续缘，请在纸上画圈。忧郁的男人\n第一个提问:“她是不是不爱我了? ”笔动了，落在了“是”\"字上，看到答案，他松了一口气。华\n贵的老妇人接着问:“我是不是真的永远不会变老了? 交是\"，老妇人露出了放心的笑容。美丽\n的少妇又问:“是不是有人知道我的秘密了? 光是\"，少妇变得紧张起来。笔又自发地组缓动起\n来，拼出了几个字:“你们知道，我是谁吗? ”", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_107ffee496dc", "srcNo": 579, "title": "旧的八音盒", "dispTitle": "旧的八音盒", "surface": "男孩送女孩一个旧八音盒，和女孩小时候埋掉的那个一模一样。女孩感动答应交往。后来八音盒摔坏，里面掉出一张照片，是女孩小时候养的狗。女孩发现男孩把狗坟挖开取盒，连夜搬走。", "cats": ["恐怖"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_108e5b96beb2", "srcNo": 1, "title": "无声电话", "dispTitle": "无声电话", "surface": "她每天都接到同一个号码的电话，电话里没有声音。三天后，她主动报了警。", "cats": ["其他"], "difficulty": 2, "src": "github:17hczmsn/turtle_soup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_108efae2dbfd", "srcNo": 440, "title": "水下的深渊", "dispTitle": "水下的深渊", "surface": "夏夜微风，欢声笑语。大人们在不远处举杯交谈，享受着美好的夜晚。\n她乖巧地坐在波光粼粼之处，面对母亲的连声呼唤充耳不闻，只是神情恍惚地站起身，随后重重地摔倒在地。\n谁也没有察觉，就在刚刚，水下那个幽暗的深渊已经完成了它的索取，贪婪地抽走了她体内绵延数米的柔软生机。\n数月后，她微笑着回到了朋友们身边，只是背上多了一个透明的行囊，里面装着她全部的生命线。\n最终，她还是永远地闭上了眼睛。但在她离开之后，世上所有潜伏的深渊，都被戴上了沉重的镣铐。", "cats": ["悬疑", "犯罪", "猎奇"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_10b92723195f", "srcNo": 327, "title": "成佛的代价", "dispTitle": "成佛的代价", "surface": "唐僧十世修行，从未沾荤腥、从未破戒。\n可最后成佛那一刻，他终于明白了什么", "cats": ["悬疑", "逻辑"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_111c70d38dff", "srcNo": 1026, "title": "完美的不在场证明", "dispTitle": "完美的不在场证明", "surface": "杀人犯在闹市区杀了人，案发时间他在看电影，几百名观众和监控都能证明他在现场。但他最后还是被抓了。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_11370065e75e", "srcNo": 622, "title": "出轨", "dispTitle": "出轨", "surface": "我告诉我的爱人：“你老婆出轨了”，然后我竟然死了", "cats": ["其他"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_1165bea3d4c9", "srcNo": 12, "title": "反锁的门", "dispTitle": "反锁的门", "surface": "房门从里面反锁，窗户也关着。警察看了一眼门口的鞋，就判断屋里还有一个人。", "cats": ["其他"], "difficulty": 2, "src": "github:17hczmsn/turtle_soup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_11ae5340ede0", "srcNo": 515, "title": "了断", "dispTitle": "了断", "surface": "明哲已经厌倦了和慧雯无休止的争吵。在她反复的哭泣和喊叫里，明哲再也看不到一点她曾经美好模样的影子。明哲盯着妻子，心想，就算为了孩子，也是时候跟她做个了断了。\n时隔多日，明哲家终于有了一笔进账，但只会有一个人为此感到高兴。", "cats": ["家庭", "日常"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_11d180b1d3af", "srcNo": 795, "title": "不能打开的冰箱", "dispTitle": "不能打开的冰箱", "surface": "一位住在独栋豪宅的富婆和她的狗感情很好。某天停电后她突然崩溃大哭，把整台冰箱封起来说：「我不能再打开它了。」", "cats": ["悬疑", "惊悚", "日常"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_11fd153e6e81", "srcNo": 178, "title": "", "dispTitle": "无题 · KONpiGG #178", "surface": "男人照常做了一笔赚钱生意，但是以往很支持他的家人，这次却非常愤怒。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_12313cc9acf1", "srcNo": 349, "title": "体面", "dispTitle": "体面", "surface": "女高管被发现吊死在公司会议厅的独立厕所内。\n她的手机屏幕亮着，页面停留在一份不惜亏本、极致讨好甲方的终极报价单，是她让下属连夜修改的最终版本；脚边翻倒一把平整的办公椅，高度完全符合上吊自杀的条件；脖颈处紧紧缠着一圈灰色丝袜，是致死凶器。\n法医现场勘查，无打斗痕迹、无外力伤痕，初步判定为自主上吊自杀。\n警方传唤核心同事协助调查，同事仅盯着死者脖子上的灰色丝袜，嗤笑道：“她就算再贱，也绝对不可能用这玩意儿上吊。”", "cats": ["本格"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_1245207e575c", "srcNo": 936, "title": "村中诡事", "dispTitle": "村中诡事", "surface": "小红经历过一场车祸，因此觉醒了超能力。可小红却不知道能力是什么，父母也不和她说，只叫她做个正常人就好。直到和丈夫离婚那天，小红才明白她的能力！她很想成为正常人！！直到她在村子里做了某件事，才如愿以偿。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_1294ed2c0162", "srcNo": 283, "title": "054 · 日记 **汤面（日记形式）：** - 2019年2月，女儿不去上学了，我劝不动她。 - 2019年6月，女儿每天盯着电视和电脑看，我怕她眼睛弄坏了", "dispTitle": "054 · 日记 **汤面（日记形式）：** - 2019年2月，女儿不去上学了，我劝不动她。 - 2019年6月，女儿每天盯着电视和电脑看，我怕她眼睛弄坏了", "surface": "你是孤儿，收养人从不允许你走出家门一步，你每天在屋子里大叫、砸东西，但没有人在意，也没有人来救你。有一天他说要带你出门，到了那个地方之后脸上被罩上了什么东西，你晕了过去……", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_12bf53e51604", "srcNo": 261, "title": "030 · 汤面里的苍蝇", "dispTitle": "030 · 汤面里的苍蝇", "surface": "一名男子进了餐厅，点了一碗汤面，吃了一口后过了不久又吃了第二口，接着男子非常地生气。请问过程中发生了什么事？", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_12cbead30014", "srcNo": 252, "title": "019 · 半根火柴", "dispTitle": "019 · 半根火柴", "surface": "有一个人在沙漠中头朝下死去，不远处散落着几个行李箱，这个人手里紧紧抓着半根火柴。请问这个人是怎么死的？", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_12ddfed2409d", "srcNo": 823, "title": "神秘的红布", "dispTitle": "神秘的红布", "surface": "某人每天都会在固定时间打开窗户，然后将一块红布挂在阳台上，但有一天他没有挂红布，结果被警方逮捕了。为什么？", "cats": ["反转", "悬疑", "推理", "犯罪"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_12eb6f8b848a", "srcNo": 291, "title": "063 · 捕鼠", "dispTitle": "063 · 捕鼠", "surface": "一个生活贫困的孤独老人，被发现死在家中，好像是在吃晚饭时死的。他的尸体残缺不全，尸体周围场景十分诡异。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_130854b89143", "srcNo": 950, "title": "从前序与中序遍历序列构造二叉树", "dispTitle": "从前序与中序遍历序列构造二叉树", "surface": "从前序与中序遍历序列构造二叉树", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_136b9e278309", "srcNo": 768, "title": "姊妹", "dispTitle": "姊妹", "surface": "我的姐姐总是比我的妹妹少，我夹在中间左右为难。后来姐姐终于和妹妹一样了，但我却消失了。", "cats": ["搞笑", "日常", "脑洞"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_13d369ed9024", "srcNo": 382, "title": "梨园行宫", "dispTitle": "梨园行宫", "surface": "我穿越了。\n我和暴君在梨园行宫避暑，这里不见天日， 常有奇怪的声音和味道。\n我死了。", "cats": ["恐怖"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_13d675ba20b0", "srcNo": 889, "title": "咒", "dispTitle": "咒", "surface": "房东向我表白，我看着面前丑陋油腻的胖大叔，果断地拒绝了。为了不被骚扰，姐妹给我介绍了一个新房子，房东是个阿婆，我放心了不少。搬家后第一晚，我隐约听到隔壁传来房东阿婆在哼着什么奇怪的声音。我还发现有一个人趴在我的窗台偷窥我！见我发现，他跑走了。通过背影我只看到是一个偏瘦的人。搬家的第七晚，我听到房间里传来了”沙，沙，沙“的声音，我起床寻找却什么都没有，可躺下没一会儿就又会听到。睡梦中，我感觉有人在舔舐我。第二天醒来，眼前的一幕令我头皮发麻。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_13f7db377f7b", "srcNo": 321, "title": "093 · 侏儒竞争 **汤面（经典版）：** 马戏团里有两个侏儒，瞎子侏儒比另一个侏儒矮一些。马戏团只留一个，越矮越好。两人约定比高矮，高的自杀。约定的前一天", "dispTitle": "093 · 侏儒竞争 **汤面（经典版）：** 马戏团里有两个侏儒，瞎子侏儒比另一个侏儒矮一些。马戏团只留一个，越矮越好。两人约定比高矮，高的自杀。约定的前一天", "surface": "山顶小屋里的人半夜听到敲门声，打开门却什么都没有，关门继续睡。第二天，山脚发现一具尸体。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_140e4c061cd4", "srcNo": 554, "title": "生日", "dispTitle": "生日", "surface": "一个人过生日的时候，邀请他的所有好朋友参加，吹完蜡烛后，他把他的所有好朋友都杀了。", "cats": ["悲剧", "本格"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_141214013a8c", "srcNo": 254, "title": "021 · 夜半敲门", "dispTitle": "021 · 夜半敲门", "surface": "一个人住在山顶的小屋里，半夜听见敲门声，打开门却没有人，于是去睡了。第二天，有人在山脚下发现一具死尸，警察来把山顶的那人带走了。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_143f39c78508", "srcNo": 591, "title": "最后的安可", "dispTitle": "最后的安可", "surface": "男人在屋内忘我地打鼓，看着屏幕里的妻子，他露出了幸福的笑容，手下的节奏敲击得越发卖力。 一曲结束，男人走出屋子，发现门外的妻子，顿时精神崩溃。请还原故事全貌", "cats": ["家庭", "悲剧", "本格", "逻辑"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_144eefd2d255", "srcNo": 1243, "title": "午夜的滴水声", "dispTitle": "午夜的滴水声", "surface": "独居的人每晚睡前都把水龙头拧到最紧，因为讨厌滴水声。某天夜里他明明拧紧了，却听见规律的滴水声，越听越害怕，最后冲出了家门。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:lancelily6362-png/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_1455577f47af", "srcNo": 1163, "title": "房间里的黑点", "dispTitle": "房间里的黑点", "surface": "星期二 小区里遇到一个戴口罩的女孩，夏日炎炎，她居然庄着冬装关她身上散发出一股\n中药味，令人不适。星期三我去菜市场买了些莲夭回家，在电梯里居然又遇到了她，她手里拿\n着一本泛黄的书，不知为何，我觉得她好像很害怕我。星期五醒来后,我发现房间里满是密密\n麻麻的黑点，我急忙清理。星期日今天不止有黑点了二我还是搬家吧。", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_146ba5100f1f", "srcNo": 66, "title": "", "dispTitle": "无题 · KONpiGG #66", "surface": "小明在图书馆看书，在一本书里翻到了100块钱，但是他却哭了，问为什么小明哭了", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_14720237876f", "srcNo": 1146, "title": "三天", "dispTitle": "三天", "surface": "第一天，今天午夜，我突然听到了婴儿的啼刁声，没一会家里传来了冲马桶的声音。由\n于我是独居，厕所并没有人，我很害怕，我决定明天找人来看看。第二天，今天没有了冲马桶\n的声音，但还是会听到婴儿效异的哭声。我叫来了一位大师，大师面色阴沉地看着我说我家里\n是闹鬼了，他会帮有我调查清楚。午夜，客厅传来声响，我开门去看，原来是大师在猫着腰找什\n么,我没多想就睡了。第三天, 大师坐在餐桌双手托肋,好像在思考什么。我问大师进展如何，\n他没有回应，于是我先回到了卧室。可卧室的地上多了很多碎纸，我看清后毛骨悚然，一个黑\n漆漆的婴儿向我肘来.……", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_14a9fd611d5b", "srcNo": 825, "title": "看不见的时钟", "dispTitle": "看不见的时钟", "surface": "阿明每天都能准确地看时间，但家里没有时钟，也不是看手机，他是怎么做到的？", "cats": ["日常"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_14ac594e1290", "srcNo": 13, "title": "空座位", "dispTitle": "空座位", "surface": "电影院里只剩一个空座位。电影开始后，他看着那个座位，立刻离开了影厅。", "cats": ["其他"], "difficulty": 2, "src": "github:17hczmsn/turtle_soup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_14d090d8d331", "srcNo": 525, "title": "活體娃娃（犯罪心理）", "dispTitle": "活體娃娃（犯罪心理）", "surface": "警方陸續在城市裡發現幾名年輕女性的屍體。\n她們死去時穿著精緻華麗的洋娃娃裙，臉上化著厚重的妝，彷彿被當作展示品一般擺放著。\n案件引起全城恐慌。\n同時，一名男子急匆匆跑到警局報案：他的女友貝拉失蹤了，而且情況非常緊急。他不斷重複一句話：「你們必須在二十四小時內找到她。」\n警方雖然開始搜尋，但心裡都很擔心——畢竟前面那些女孩都已經死了。\n幾個小時後，貝拉被找到。她的外表和其他女孩一模一樣，穿著娃娃裙，臉上妝容濃重，但她還活著。", "cats": ["本格", "犯罪"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_14f632afbee6", "srcNo": 414, "title": "白崖", "dispTitle": "白崖", "surface": "我们世世代代攀附在一排白色悬崖上，那里每天有温暖的泉水流过。\n我们从不迁徙，只靠泉水中的养分活着。\n直到一天，一个白色巨人来了。\n他将一根金属棒伸进我们的家园，那金属棒发出的刺耳声音让我们浑身战栗。\n白崖开始剧烈震动，我们再也抓不住了，从悬崖上掉落，泉水也变成了红色。", "cats": ["反转", "本格", "脑洞"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_15288fb99991", "srcNo": 826, "title": "没声音的电话", "dispTitle": "没声音的电话", "surface": "阿伟的手机突然响起，但来电显示没有号码，他接起来却什么声音也没有，为什么？", "cats": ["搞笑", "日常"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_153b82ead579", "srcNo": 1308, "title": "", "dispTitle": "无题 · boop-yyt #1308", "surface": "A bell rings. A man dies. A bell rings. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_1564a01d6f10", "srcNo": 1155, "title": "他不喜欢", "dispTitle": "他不喜欢", "surface": "我和妹妹相依为命，但由于妹妹的死亡，我染上了一个习惯。可今天我被抓位了，他叫\n我赔给他。他的做法我很震惊，但好像还不错，我很喜欢! 十年后，我用以前的办法寻找他，\n可一无所获。于是我去买了针线。可他好像不喜欢，他发出一声惊叫，并报了和警。", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_15a1e3fcfd9b", "srcNo": 489, "title": "呼吸", "dispTitle": "呼吸", "surface": "这间旅馆很便宜，可总是没人订，我因为没多少钱只能在此歇脚。前台的中年男人面容憔悴，摩挲着一张女孩的照片。\n来到房间，我躺在床上呼吸放缓即将入睡，恍惚间耳畔也传来呼吸声。我吓得起身屏气倾听，咦，挨着床的墙面怎么有靠上靠下的抓痕？", "cats": ["怪谈", "悲剧", "犯罪"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_15b05aa5803f", "srcNo": 1296, "title": "", "dispTitle": "无题 · boop-yyt #1296", "surface": "A man dies of thirst in his own home. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_15da47fb8bff", "srcNo": 63, "title": "", "dispTitle": "无题 · KONpiGG #63", "surface": "据报道，一个幸福的三口之家，小孩10岁，爸爸死在了家里，身穿孕妇装，肚子被剖开了，经过检查他爸爸是上吊自杀的，邻居发现了这件事之后没有第一时间报警。推理出爸爸为什么要自杀并还原案件。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_1604d55dc208", "srcNo": 1102, "title": "加班的同事", "dispTitle": "加班的同事", "surface": "每天加班的同事突然辞职了，第二天公司发了奖金。", "cats": ["其他"], "difficulty": 2, "src": "github:Tenzyoo/turtle_soup_game", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_1612b4b8aaed", "srcNo": 1002, "title": "偷窥者", "dispTitle": "偷窥者", "surface": "一个男人每天都通过墙上的小孔偷窥隔壁的美女。隔壁总是亮着红光。有一天，他发现小孔变成了红色，他吓得瘫倒在地。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_161809c5dbab", "srcNo": 471, "title": "日记", "dispTitle": "日记", "surface": "2020.10.15 晴\n今天舅舅给我做了一顿我从来没吃过的饭，听他们说这是肉，那种香味至今俺都还记得，多么美好的一天啊，可是听到最喜欢我的老师被发现家中被人杀害了，这让我和舅舅难过了好久。", "cats": ["恐怖", "悲剧", "本格", "犯罪"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_16c34d2a101f", "srcNo": 67, "title": "", "dispTitle": "无题 · KONpiGG #67", "surface": "小明半夜起来喝水，然后把灯关上继续睡觉，醒了之后他就自杀了，问小明为什么自杀", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_16c80a13e181", "srcNo": 1234, "title": "Jed 2.20", "dispTitle": "Jed 2.20", "surface": "Joe wants to go home, but he can't go home because the man in the mask is waiting for him. (AL wording)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_16e43fe69d06", "srcNo": 405, "title": "疯戏子的最后一折", "dispTitle": "疯戏子的最后一折", "surface": "那是一场荒诞的余兴节目，大帅府的庭院里搭起了戏台。\n台上并没有生旦净末，只跪着一个披头散发的疯女人，和三个身披麻袋、手捧血馒头的小哑巴。\n看客们嗑着瓜子，赌那个疯女人什么时候会凶性大发，撕碎身边的活物。\n日头毒辣，小哑巴们纹丝不动，看客嫌戏肉太慢，纷纷抓起茶盏碎瓷砸向戏台。\n疯女人的喉咙里发出野兽般的低吼，眼里的凶光暴涨，猛地挣断了手腕上的麻绳。\n尖叫声还没来得及响起，她却做了一个让所有人都输了钱的动作，然后在一片狼藉中，维持着那个姿势断了气。", "cats": ["悲剧"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_17013b950366", "srcNo": 686, "title": "自拍泄露的代价", "dispTitle": "自拍泄露的代价", "surface": "一对母子去游乐园游玩，几天后死在家中。", "cats": ["悬疑", "惊悚", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_179cfc38b29c", "srcNo": 46, "title": "小红裙", "dispTitle": "小红裙", "surface": "姐姐为我选了一件小红裙，我穿着去上学了，然后有人死了。", "cats": ["犯罪"], "difficulty": 2, "src": "github:anchorAnc/astrbot_plugin_TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_17de7d230826", "srcNo": 1190, "title": "吃大餐", "dispTitle": "吃大餐", "surface": "解析：\n前两句是狼狗的视角。\n第三句指女孩的副人格出现。\n第四句话，小女儿喂狗吃人肉。\n第五句话，小女儿正在吃狗肉。", "cats": ["其他"], "difficulty": 2, "src": "haiguitang.cn(wayback)", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_17e2192e6554", "srcNo": 638, "title": "Charlotte在自己房间打电话", "dispTitle": "Charlotte在自己房间打电话", "surface": "Charlotte在自己房间打电话，她听到隔壁房间很多人在说话，特别吵，她根本听不清楚电话里讲什么，她很生气，走到了客厅，悄悄做了一件事，很快，隔壁安静了。\n\n 你猜猜这是怎么一回事呢？", "cats": ["其他"], "difficulty": 2, "src": "haiguitang.cn/海龟浓汤", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_17fc568f14b0", "srcNo": 259, "title": "027 · 海龟汤", "dispTitle": "027 · 海龟汤", "surface": "一名男子走进餐厅，点了一碗海龟汤，喝了一口非常惊讶地问服务员：\"这是真的海龟汤吗？\" 得到肯定回答后，不久他就自杀了，为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_18121251d66f", "srcNo": 180, "title": "", "dispTitle": "无题 · KONpiGG #180", "surface": "\"救救妈妈....\"是妈妈的哭声。\"救救我，妈妈...\"是女儿的哭声。\"妈妈这次我就不救你了。\"从此再没有哭声了", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_181239094689", "srcNo": 942, "title": "石头，剪刀，布", "dispTitle": "石头，剪刀，布", "surface": "找啊找啊找朋友，找啊找啊找朋友。123木头人，123木头人。手心手背，手心手背。石头，剪刀，布。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_187c567b5841", "srcNo": 389, "title": "梦里的红衣", "dispTitle": "梦里的红衣", "surface": "奔丧回来后，室友和我说学校最近闹鬼了，好多人都梦到了一个红衣服的人对着你笑。晚上，我也梦到了，可我看清他时，却觉得眼熟。直到第二天晚上，我终于明白", "cats": ["恐怖"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_18af72eb5ce0", "srcNo": 51, "title": "阳台上的女孩", "dispTitle": "阳台上的女孩", "surface": "女孩每天都站在对面阳台和我打招呼，我却不敢再踏进阳台了。", "cats": ["怪谈", "恐怖", "犯罪"], "difficulty": 3, "src": "github:anchorAnc/astrbot_plugin_TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_18b321274e5e", "srcNo": 1021, "title": "重逢", "dispTitle": "重逢", "surface": "男子在火车站看到一个阔别多年的老友。他兴奋地冲过去打招呼，老友却惊恐地逃跑，最后老友在铁轨上被撞死。男子看清老友留下的包裹后，跳轨自杀了。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_18cf97f2f9d1", "srcNo": 437, "title": "绿色墨水", "dispTitle": "绿色墨水", "surface": "我在勃艮第里住的挺好，有房有车有工作，空气还算清新，可惜的是，就是没有绿墨水卖。\n——威廉·博韦特", "cats": ["本格", "逻辑"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_18d2a42fe41a", "srcNo": 1118, "title": "妹妹的秘密", "dispTitle": "妹妹的秘密", "surface": "只有妹妹陪我过 10 岁生日。妈妈还在躺着, 不过她胖了许多, 爸爸一脸惊恐地看着爸爸，\n妹妹摸着我的脸说:“等你成年了就要娶我哦一”", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_18fb05929d96", "srcNo": 681, "title": "打不开的出口", "dispTitle": "打不开的出口", "surface": "火灾发生时，剧院的几个出口没有上锁，也没有被杂物堵住，可大量观众就是打不开门。为什么？", "cats": ["悬疑", "推理"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_194be6fe632b", "srcNo": 654, "title": "树上的鱼", "dispTitle": "树上的鱼", "surface": "山火扑灭后，调查人员在距海边一段距离的树枝上发现海鱼。附近没有鱼摊，也没人故意扔鱼。它是怎么到那里去的？", "cats": ["旅途", "脑洞"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_196125e0f51f", "srcNo": 531, "title": "下班", "dispTitle": "下班", "surface": "我下班後搭上末班車，途中睡著了。\n醒來時車已經停在一個有點熟悉又有點陌生的地方。\n下車後沒多久，車開走了，車站看起來很老舊，又不像是被廢棄。\n我在那裡待了一段時間，總覺得哪裡不太對。\n但我最後還是回到了那個，每天都會回去的地方。", "cats": ["悬疑"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_197a084bf84f", "srcNo": 75, "title": "", "dispTitle": "无题 · KONpiGG #75", "surface": "一个男人在打猎，他瞄准并开枪。几秒后，他突然意识到自己犯了个天大的错误。几分钟后，他就死了。请问发生了什么？", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_1985a9ca2ae7", "srcNo": 166, "title": "", "dispTitle": "无题 · KONpiGG #166", "surface": "我喜欢他很久了，但我一直不好意思向他袒露心声，于是我约了他和另外几个小伙伴一起做了一个测试，但没想到最终害死了我和我的朋友们。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_19aa8e7c225d", "srcNo": 688, "title": "雨中女郎", "dispTitle": "雨中女郎", "surface": "艺术家买了《雨中的女郎》。朋友来欣赏后失踪。次日艺术家在画室闻到淡淡味道，发现《雨中的女郎》旁多了一幅画，惊恐烧掉《雨中的女郎》。", "cats": ["怪谈", "恐怖", "悬疑", "脑洞"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_19e9eb7c289b", "srcNo": 305, "title": "077 · 永远的标准答案", "dispTitle": "077 · 永远的标准答案", "surface": "小红考试只要答\"不知道\"，就能得到满分，但老师却给她打了零分。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_19f1a46c7f28", "srcNo": 1056, "title": "缸中之脑", "dispTitle": "缸中之脑", "surface": "一个男人发现自己不论怎么努力，都无法打破一个杯子。他最后大笑起来，自杀了。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_1a1e233803a1", "srcNo": 670, "title": "第二辆一模一样的车", "dispTitle": "第二辆一模一样的车", "surface": "一个独居男人已经有一辆性能完好的汽车，而且只有他自己驾驶。为了让出行更方便，他又买了一辆几乎完全一样的车。为什么？", "cats": ["日常", "都市"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_1a6283ab2f37", "srcNo": 269, "title": "039 · 海难侥幸", "dispTitle": "039 · 海难侥幸", "surface": "杰克拼命阻止想要把女儿带走的家伙，最终却没能成功，侥幸活下来后，妻子却向杰克提出了离婚。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_1aa2e7bacd58", "srcNo": 572, "title": "山顶小屋", "dispTitle": "山顶小屋", "surface": "一个人住在山顶的小屋里，半夜听见有敲门的，他打开门却没有人，于是去睡了。等了一会又有敲门声，去开门，还是没人，如是者几次。第二天，有人在山脚下发现死尸一具，警察来把山顶的那人带走了。为什么?", "cats": ["其他"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_1b0b24dd9fc8", "srcNo": 830, "title": "大楼", "dispTitle": "大楼", "surface": "一名女子住在大楼内，当她往窗外一看时，和对面大楼的一名男子四目相接。男子用手指了几下，并露出了笑容。女子见状以后，感到毛骨悚然并立刻离开了房间。请问发生了什么事？", "cats": ["悬疑", "惊悚", "推理", "犯罪"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_1b0c34dcd3ed", "srcNo": 1035, "title": "电影院的惨剧", "dispTitle": "电影院的惨剧", "surface": "电影院里正在放映恐怖片，全场寂静，突然一个男人大叫一声死去了。并没有人袭击他。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_1b3259545328", "srcNo": 228, "title": "要好的朋友", "dispTitle": "要好的朋友", "surface": "我有一个要好的朋友，我们形影不离。可惜，他死了。", "cats": ["其他"], "difficulty": 2, "src": "github:wangyafu/haiguitangmcp", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_1b5f8818a812", "srcNo": 457, "title": "一週還是兩年？", "dispTitle": "一週還是兩年？", "surface": "法醫推了推眼鏡，指著解剖台上的遺體，語氣篤定地說：「從器官腐敗程度與皮下組織狀態來看，死亡時間絕對是一週前。屍體沒有注射防腐劑，也沒有任何化學藥劑的痕跡，科學是不會騙人的。」\n​刑警卻眉頭緊鎖，將一份檔案丟在桌上：「這不可能。死者兩年前就失蹤了，DNA 比對也確認屍體沒有被掉包。」\n​法醫瞬間愣在原地。兩年前就被殺害的人，為什麼只呈現出死後一週的腐敗程度？", "cats": ["犯罪"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_1bf936bf0361", "srcNo": 141, "title": "", "dispTitle": "无题 · KONpiGG #141", "surface": "我被杀害在山的另一头，而山的那边，是弯弯曲曲、而鲜血淋漓的国道。他以为自己逃掉了，但我留下的印记会追随着他，直至落网为止。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_1c6e60e363c6", "srcNo": 470, "title": "悬梁红楼", "dispTitle": "悬梁红楼", "surface": "这是一场违背重力的盛大演出，也是一座吃人的空中楼阁。\n聚光灯下，名为‘金丝雀’的少爷在云端起舞，享受着满堂喝彩；\n藻井之上，名为‘蜘蛛’的长子在错综复杂的滑轮间无声攀爬。\n贵宾室的镜子后没有墙壁，是为了方便‘蜘蛛’收网。\n班主常夸耀那如羽毛般轻盈的飞天舞姿，\n却没人知道，为了维持这美妙的平衡，\n这栋楼的阴暗夹层里，必须挂满沉甸甸的‘新鲜压舱石’。", "cats": ["恐怖", "本格"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_1cfe92cbc3fa", "srcNo": 496, "title": "鲸骨协奏曲", "dispTitle": "鲸骨协奏曲", "surface": "导师交给我三个“透明的幽灵”，透过它们，我看见了深海下被压碎的尖叫。\n第一个幽灵守在东侧的加压阀，第二个幽灵守在西侧的冷凝管，第三个幽灵守在头顶的逃生舱。\n导师说，第四个幽灵声带断了，唤不醒窗外的神明，所以要借我的喉咙用一用。\n全船的电力切断了，我站在全景舰桥的中央，对着舱外那头巨大的、沉默的“神”唱起了安魂曲。\n当最高昂的那个音符落下时，站在窗前的舰长在瞬间的失压中化作了一滩血雾，而导师躲在唯一的真空隔离舱里，在鲜红的警报灯下笑得慈悲又残忍。", "cats": ["悲剧"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_1d0ec1ebc88a", "srcNo": 16, "title": "雨夜的脚印", "dispTitle": "雨夜的脚印", "surface": "雨夜过后，门口没有任何脚印。他却因此确定昨晚有人来过。", "cats": ["其他"], "difficulty": 1, "src": "github:17hczmsn/turtle_soup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_1d77e1dd54b7", "srcNo": 58, "title": "丢失的手机", "dispTitle": "丢失的手机", "surface": "我的手机不见了，当我找到它时，我吓了一跳。", "cats": ["恐怖"], "difficulty": 2, "src": "github:anchorAnc/astrbot_plugin_TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_1d788001ed92", "srcNo": 149, "title": "", "dispTitle": "无题 · KONpiGG #149", "surface": "男朋友结婚了，新娘不是我。男朋友死了，新娘变成了我。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_1e06910567ab", "srcNo": 48, "title": "数数", "dispTitle": "数数", "surface": "我数数，他也在数数，我毛骨悚然。", "cats": ["犯罪"], "difficulty": 2, "src": "github:anchorAnc/astrbot_plugin_TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_1e0c1f87a2b9", "srcNo": 1130, "title": "柜中的孩子", "dispTitle": "柜中的孩子", "surface": "深夜,我家的衣柜传来了塞塞宁罕的声音，我壮着胆子打开柜门，里面居然有一个孩子，\n他看着我嘿嘿的笑着:“妈妈，你找到我啦一”我吓坏了，哪来的孩子。我让他立刻离开我的房\n子，他吓哭了,一直叫我妈妈。仔细看他和我前夫的确有几分相似。但我自从几年前流产后就\n没有了生育能力，也离了婚。他告诉我他还有一个双胞胎弟弟，甚至叫出了我和前夫的名字，\n他带着册腔问我:“你真不记得我了吗? ”", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_1e74e17a0934", "srcNo": 732, "title": "消失的姐姐", "dispTitle": "消失的姐姐", "surface": "女儿问我姐姐去哪了？我否认姐姐存在，但女儿拿出照片让我震惊。", "cats": ["反转", "悬疑", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_1e8b212d6a6b", "srcNo": 39, "title": "影子", "dispTitle": "影子", "surface": "一天我去公共厕所，那时已是晚上，我看见男厕所门口站着一个人后面是他的影子，手中还拿着什么，我吓了一跳，不过很快就冷静下来第二天天警察找到我,问我看到尸体为什么不报警，我想了想瞬间吓呆了。", "cats": ["反转", "犯罪"], "difficulty": 2, "src": "github:anchorAnc/astrbot_plugin_TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_1ec62776467d", "srcNo": 997, "title": "生日礼物", "dispTitle": "生日礼物", "surface": "盲人男孩生日，收到了哥哥寄来的一个盒子。他拆开后，大哭着自杀了。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_1ef11bbc1923", "srcNo": 1175, "title": "莱恩小镇规则怪谈", "dispTitle": "莱恩小镇规则怪谈", "surface": "小镇规则: 1. 小镇热闸非凡，欢迎各位游客。2. 小镇异常整洁，并不存在蛛网。3. 镇\n长的手都是老蔓，据说曾是杂技师。4. 749 局只有一次处决权，但所有居民均可确定，小镇无\n灵异。5. 小镇的警探活的好好的。已故警探提醒: 1. 小镇已沦陷，外来人员请撤离。2. 不要\n碰到小镇里密密麻麻的蛛网。3. 小心那个木偶师 ! 杀掉他就能结束一切。4. 存在灵异，小镇\n恐无活人! 749 局已经介入。5. 我活的好好的。6. 小镇热闹非凡，欢迎各位游客。", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_1f34e7036b8b", "srcNo": 1312, "title": "", "dispTitle": "无题 · boop-yyt #1312", "surface": "A man and his brother are in a bar drinking. They begin to argue and the brother won't get out of the man's face, shouting and cursing. The man, finally fed up, pulls out a pistol and blows his brother's brains out. He sits down to die. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_1f572e970b04", "srcNo": 597, "title": "姐姐在跳舞", "dispTitle": "姐姐在跳舞", "surface": "六岁那年外公葬礼，我和姐姐玩捉迷藏，我对妈妈说了一句话把她吓昏过去，我说了什么？", "cats": ["恐怖"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_1f8968a0393c", "srcNo": 408, "title": "红豆", "dispTitle": "红豆", "surface": "女子种下一颗红豆，年年开花却从不结果。她死后，红豆树结满了相思子。", "cats": ["悲剧"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_1f963af3d0fe", "srcNo": 154, "title": "", "dispTitle": "无题 · KONpiGG #154", "surface": "我很忙，但我还是和他出去了。我和他比赛，他先我一步。之后，我就不忙了。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_1fcc117cf291", "srcNo": 331, "title": "獨居女子", "dispTitle": "獨居女子", "surface": "刑警來到失蹤女子的租屋處搜查。屋內非常整齊，完全沒有打鬥痕跡。刑警隨手用遙控器打開客廳的電視，電視一亮起，刑警立刻拔呼叫支援，斷定女子昨晚在屋內遇害了。發生什麼事？￼", "cats": ["悬疑", "犯罪", "逻辑"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_1fce916eb76b", "srcNo": 1095, "title": "牛吃草", "dispTitle": "牛吃草", "surface": "一个男的住在山顶，有一天他下山去集市买东西，回家后发现家里的牛死在了草坪上。", "cats": ["其他"], "difficulty": 2, "src": "github:Tenzyoo/turtle_soup_game", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_1fe018f884c7", "srcNo": 1297, "title": "", "dispTitle": "无题 · boop-yyt #1297", "surface": "A man is lying drowned in a dead forest. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_1fe394f0087d", "srcNo": 639, "title": "Diva走进了一间黑屋子", "dispTitle": "Diva走进了一间黑屋子", "surface": "Diva走进了一间黑屋子，她待了十几分钟后，忽然尖叫着跑了出来，地上遗落了她随身带的一张纸。\n\n 你猜猜这是怎么一回事呢？", "cats": ["其他"], "difficulty": 2, "src": "haiguitang.cn/海龟浓汤", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_206b9185868d", "srcNo": 324, "title": "098 · 跳火车（经典版）", "dispTitle": "098 · 跳火车（经典版）", "surface": "男子坐火车去邻镇治眼病，治好了回程时经过隧道，跳车自杀。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_20800650c989", "srcNo": 1157, "title": "白雪公主规则怪谈", "dispTitle": "白雪公主规则怪谈", "surface": "1. 皇后最多只能活 3 年; 2. 猎人放过了白雪; 3 ,猎人绝对忠诚于皇后，4. 猎人非常感\n激皇后救了自己;5. 七个小矮人救了陷阱中的白雪; 6- 魔镜说最美的女人是白雪，皇后非常\n生气; 7. 白雪美丽的外表让王子非常迷恋汪.8._巫于给予了白雪一颗苹果: 9. 白雪在巫婆面前\n死掉了: 10. 复活后的白雪和王子幸福地生活在了一起。(注: 2、4、6、8 为红字规则，即反\n话)", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_20b8c20f05f5", "srcNo": 134, "title": "", "dispTitle": "无题 · KONpiGG #134", "surface": "我发现床头柜上放着一杯蜂蜜水和一块巧克力蛋糕，原本放在床头柜的娃娃却消失不见了。我知道男友再也回不来了。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_20cfdfe4f7ba", "srcNo": 244, "title": "010 · 幸福家庭", "dispTitle": "010 · 幸福家庭", "surface": "飞机上，一对看似平和的幸福家庭正抱着婴儿旅行。他们所犯下的恶劣罪行，被一个观察力敏锐的空中小姐发觉了。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_2167e57fcfd4", "srcNo": 596, "title": "雪怪的寒糖", "dispTitle": "雪怪的寒糖", "surface": "她揣着一块寒骨的玉，走向漂泊的铁盒。嘴里含着灼舌的甜，却没能攥住那束不冻的光。最后，她的冷，成了铁盒里不会化的痕。", "cats": ["悲剧"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_21a1c2066fb9", "srcNo": 334, "title": "止战之殇", "dispTitle": "止战之殇", "surface": "我看不见，好像听到很多人的声音，有女人的哭声，有轰隆轰隆的声音，还有湿热的液体滴在我的脸上。\n……\n我看不见，好像听到很多人的声音，有女人的哭声，有轰隆轰隆的声音，还有湿热的液体滴在我的脸上。", "cats": ["家庭", "悲剧"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_21a2b61d54f4", "srcNo": 1070, "title": "贪婪的奖赏", "dispTitle": "贪婪的奖赏", "surface": "一个探险家发现了一个装满黄金的密室，门上写着：‘带走多少，就留下多少。’探险家装了满满一袋金子，最后他确实留下了等重的东西。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_21b65cf5f303", "srcNo": 1395, "title": "", "dispTitle": "无题 · boop-yyt #1395", "surface": "Pat went into a luggage shop to buy a suitcase. The assistant said, \"It is most unusual to buy a suitcase. Why don't you rent one like all our other customers?7' Why should this be so?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_21bc23944630", "srcNo": 935, "title": "私汤馆の凶杀疑云", "dispTitle": "私汤馆の凶杀疑云", "surface": "口供：1. 大和抚子：与有希子是同学兼好友，老公中奖带二人来私汤馆，馆内只有一名女老板。20:00老公睡觉，与有希子闲逛；20:15到温泉室吃刺身、喝清酒；21:00各自回房；21:10吵醒老公带他去泡温泉；21:30老公叫老板做刺身；21:40路过有希子房间，听到她电话里吵架并提及投诉。2. 佐藤二郎：中了家庭汤泉券，带妻子抚子和有希子度假。18:00抵达后休息；21:10被妻子吵醒去泡温泉；21:30吃了一整份刺身；21:40泡好后去吸烟室，听到老板吵架；21:50回房。3. 女老板：私汤馆偏僻无监控，17:40为三人办理入住；20:20为温泉室两名女房客做餐；21:30为女房客及其丈夫做餐；21:40与死者因房间卫生吵架，死者称要投诉；22:00清理温泉室时发现死者。线索：1. 吐真剂：一名嫌疑人被使用，仅回答是或不是且必为真话。2. 麻绳：在佐藤房间发现，用处不明。3. 壁炉：有被烧毁的胶皮。4. 小厨房：有制冰机，酒柜里有刚清洗完的杯子。5. 死者：死在温泉中，颈背插着餐刀（与伤口不完全吻合），刀柄有女老板指纹。6. 院子里：有一瓶治疗精神疾病的药物。7. 温泉：有水循环系统。8. 有希子房间：马桶里有还原后写着“选我还是选抚子，你自己决定”的纸条。9. 有希子手机：20:00搜索“山中由美”。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_21fffcb5edb7", "srcNo": 120, "title": "", "dispTitle": "无题 · KONpiGG #120", "surface": "一具尸体，显而易见有两处致命伤，她头部受到重创，胸腔被暴力剖开，不过奇怪的是她没有穿鞋。身边洒落着苹果、果篮，尖顶宽边帽和扫把。不远处，有一具女尸，头颈被连骨带肉的撕碎，血肉模糊难以分辨，身边有一双银色高跟鞋。女尸附近有一具大型动物尸体，被利器所伤，地上散落着一些稻草。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_2258c4f5d053", "srcNo": 50, "title": "夺爱", "dispTitle": "夺爱", "surface": "妈妈很喜欢\"妹妹\"，可这一切本来是我的。", "cats": ["犯罪"], "difficulty": 3, "src": "github:anchorAnc/astrbot_plugin_TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_2299ca62945f", "srcNo": 1141, "title": "声音", "dispTitle": "声音", "surface": "“滋滋 喻喻喻 呼呼呼 龙隆隆 味呈叶 咱 啊啊啊 嘲嘲 咕噜咕噜 滋滋”", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_23126408e906", "srcNo": 912, "title": "赴净土", "dispTitle": "赴净土", "surface": "城中无啼锁门窗，棍棒底下出真章。临行明月仍残缺，沙弥忽闻有肉香。吾心明悟兄难辩，真死恐已成白骨。尘埃落定无杂念，一如既往赴净土。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_232aafb97399", "srcNo": 449, "title": "电费", "dispTitle": "电费", "surface": "一天，两天，三天，三十五天。没办法，今天去交电费吧。", "cats": ["恐怖", "本格", "犯罪"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_234328857d6d", "srcNo": 1362, "title": "", "dispTitle": "无题 · boop-yyt #1362", "surface": "A woman is murdered in front of hundreds of people, but they all think it's an accident. How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_235afabd4730", "srcNo": 962, "title": "", "dispTitle": "无题 · SUZ-tsinghua #962", "surface": "一男子在河边碰到一名渔夫，渔夫对他说了一句话，男子忽然悲愤崩溃的大叫了起来，请推理。\n \n 男子和女友曾不小心落水过，男子没能救到女友，最终女友淹死了。渔夫对男子说的是“河里没有水草”，男子意识到曾经手中挣开的水草，其实是女友的头发，所以男子愧疚大叫。'''\n \n 案例6：'''", "cats": ["其他"], "difficulty": 2, "src": "github:SUZ-tsinghua/situation-puzzles", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_2368ab633bd4", "srcNo": 546, "title": "鱼雷与狗", "dispTitle": "鱼雷与狗", "surface": "小明穿着雨鞋，和他的狗一起血肉模糊死在空旷地。", "cats": ["搞笑"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_23e264f14a1c", "srcNo": 59, "title": "饺子", "dispTitle": "饺子", "surface": "妈妈在不停包饺子，我们已经吃吐了，但妈妈依旧不停的包，我们也只能不停的吃。", "cats": ["猎奇"], "difficulty": 3, "src": "github:anchorAnc/astrbot_plugin_TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_23fc37d891c1", "srcNo": 643, "title": "Vina Unique是个聪明的姑娘", "dispTitle": "Vina Unique是个聪明的姑娘", "surface": "Vina Unique是个聪明的姑娘，早上她一般都自己用微波炉热牛奶。\n\n 她每次都调到80秒，从不例外。\n\n 为什么呢？\n\n 你猜猜这是怎么一回事呢？", "cats": ["其他"], "difficulty": 2, "src": "haiguitang.cn/海龟浓汤", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_23febc756976", "srcNo": 1086, "title": "", "dispTitle": "无题 · zhuqingxu #1086", "surface": "小镇钟楼每逢整点敲响，全镇都能听见。案发日多人发誓：听见钟声的那一刻，钟楼上还站着穿管理员制服的人影；钟声过后人影才不见。法医却认定管理员恰在那一两分钟里坠亡。这是怎么回事？", "cats": ["其他"], "difficulty": 2, "src": "github:zhuqingxu/ai-haigui-game", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_24129ee882f4", "srcNo": 645, "title": "九十三岁的帮手", "dispTitle": "九十三岁的帮手", "surface": "夫妻想拍一张两人全身都入镜的合照，却怎么也无法在选好的位置完成。旁边九十三岁的老人坐着没动，轻松帮了他们。他们没有自拍杆或可用支架。为什么？", "cats": ["日常"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_2469a12e9d9c", "srcNo": 72, "title": "", "dispTitle": "无题 · KONpiGG #72", "surface": "女孩醒来总有新伤，她把父亲告上法院，法院却不受理", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_24db70bb8c98", "srcNo": 104, "title": "", "dispTitle": "无题 · KONpiGG #104", "surface": "我正在街上努力工作，突然一个疯疯癫癫的女人向我扑来，爸爸赶紧把我抱回了家，但随后我也知道危险已经逼近。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_253e61d68de3", "srcNo": 943, "title": "露营", "dispTitle": "露营", "surface": "我们一家去森林露营，爸爸负责打猎，我帮妈妈做饭。夜里，我被奇怪的啃食声音吵醒，爸妈都不见了。我出帐篷寻找，却在森林里看到了惊恐的一幕。妈妈浮在空中惨叫，身上缠着几条触手，爸爸吹着口哨，双手奇怪地摆动，像是在祭拜什么。我害怕地往回跑，竟发现地上有很多血迹，一个怪异的生物笑眯眯地问我：”饿不饿？“，我吓晕了过去。等我醒来时，已经在床上了，爸爸在远处恶狠狠地盯着我，妈妈严肃地警告我：”千万不要和别人说昨晚的事。“", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_255999f4f6ba", "srcNo": 729, "title": "洗头", "dispTitle": "洗头", "surface": "晚上我在寝室洗了个头，室友突然昏倒，而我随后死了。为什么？", "cats": ["反转", "惊悚", "科幻", "脑洞"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_255eb9ac95c6", "srcNo": 717, "title": "乞丐", "dispTitle": "乞丐", "surface": "我是乞丐，醒来发现碗里多了样东西，饱餐了一顿，但第七天我死了。", "cats": ["怪谈", "恐怖", "悬疑", "脑洞"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_256cd09236f0", "srcNo": 918, "title": "该我了", "dispTitle": "该我了", "surface": "1985年 难产的我诞下了一个健康的男孩，看相的大师和我们说这孩子只能活20年，我骂了他，但还是格外担心孩子会出问题。没几年，我发现孩子得了一种怪病，他总是记不住昨天发生的事，第二天又会想起来。医生诊断他有重度的人格分裂和妄想症。1997年 吴妄这孩子不对劲！！！由于生病，他有写日记的习惯，有一次我无意中看见了一些内容：爸爸该死了！！第二年丈夫死了，死在了情人家里，我不知道该不该伤心，可吴妄哭的很伤心，不像装的，这一刻我才觉得他像个小孩子。2000年 ”我好喜欢xx“ 日记上这样写着，名字被勾掉了。2005年 吴妄20岁了，我带他去看医生，身体一切正常。大师的预言没有实现。2025年 吴妄死了，死于车祸，临死前他自己嘀咕了一句：”该我了。“", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_25b24869b228", "srcNo": 1049, "title": "不存在的第七天", "dispTitle": "不存在的第七天", "surface": "一个男人发现日历上多出了一个‘星期八’。他好奇地走出家门，发现街上的人全都在倒着走路，且没有脸。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_25b8ded657d3", "srcNo": 347, "title": "我和妈妈", "dispTitle": "我和妈妈", "surface": "我哭了，妈妈笑了。\n我笑了，妈妈笑了。\n我哭了，妈妈哭了。\n我哭了，妈妈笑了。\n我跟妈妈到底怎么了?", "cats": ["本格", "逻辑"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_25c4880875b3", "srcNo": 336, "title": "开盲盒", "dispTitle": "开盲盒", "surface": "\"这个超难买到的\"\n“太好了 是隐藏款”", "cats": ["恐怖", "本格", "犯罪", "猎奇", "脑洞"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_269b76a49e5f", "srcNo": 1337, "title": "", "dispTitle": "无题 · boop-yyt #1337", "surface": "Little Billy was four years old and both his parents were dead. His guardian put him on a train to send him to a new home in the country. Billy could neither read nor write nor remember the address, so a large label on a string was secured around his neck clearly indicating Billy's name and destination. However, despite the best efforts and kindness of the railway staff, Billy never arrived at his new home. Why?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_26a8f6aeae4e", "srcNo": 892, "title": "Whoisliar", "dispTitle": "Whoisliar", "surface": "老大：我成了累赘，临死前好像听到谁跳楼。老二：早就说过不要内讧，可老四活活勒死了老五，他自己的脸色也绿得吓人。老三：老四和她男朋友乘公交车与我们分道扬镳了，令我没想到的是老五居然是男人。老四：我中了一枪，由于分赃不均，大家心怀鬼胎，看来今天只能有一个人活着出去了。老五：老四发现老六在给老四下毒，于是枪杀了老六，但她自己好像也中枪了。老六：我看到老大做了饭，吃完饭老二杀死了老大。提示：本格推理，故事中只有一个人在说谎，按顺序还原真相。（推荐玩法：最好不要依次询问说谎者，或使用二分法）", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_26b506ed4a02", "srcNo": 1104, "title": "会议室的灯", "dispTitle": "会议室的灯", "surface": "每天晚上会议室的灯都会亮着，但进去检查却什么都没发现。", "cats": ["其他"], "difficulty": 2, "src": "github:Tenzyoo/turtle_soup_game", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_26bcca939ecf", "srcNo": 1223, "title": "Jed 1.84", "dispTitle": "Jed 1.84", "surface": "Tim and Greg were talking. Tim said \"The terror of flight.\" Greg said \"The gloom of the grave.\" Greg was arrested. (MPW original, from \"No Refuge Could Save,\" by Isaac Asimov)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_26d12ef6da2a", "srcNo": 1198, "title": "Jed 1.12", "dispTitle": "Jed 1.12", "surface": "A woman in France in 1959 is waiting in her room, with all the doors locked from the inside, for her husband to come home. When he arrives, the house has burned to the ground and she's dead. (JM, originally from _How Come -- Again?_)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_26fb6a590a81", "srcNo": 888, "title": "旅馆", "dispTitle": "旅馆", "surface": "我是一个旅馆老板，今天我的旅馆死了一个人。以下是今天发生过的事情：11:30am，122房间的中年妇女哭着和我说：”救救我孩子！“我看到旅馆大堂躺着一个晕倒的孩子，我不知道发生了什么，但我让她赶紧报警。我听到很大的水流声，原来是120房间的水管坏了，我修好后，住在这个房间的女孩亲吻了我，我很不好意思。12:00pm，警察赶来了，大厅里围着很多人。121房间的老太太有些心虚，我听到她嘀咕了一句：”不关我们的事“，就要溜走。122房间的中年妇女看着她大骂：”你还有没有良心！“说罢就和老太太扭打在一起。晕倒的孩子不知何时醒了过来，他哭闹着喊道：”不许欺负我奶奶！“随后就打了中年妇女。我急忙去拉架，却被120房间的大叔怼了几拳，他怒斥我：”你不该多管闲事！“12:30pm，122房间的妇女没拦住要离开的老太太，警察这时说：”同志，你不能走！“但她好像并没听到，带着那个孩子离开了。1:00pm，我听到警察逐渐走远的声音，”唉，这里死人了“。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_27232c3dbbc2", "srcNo": 1373, "title": "", "dispTitle": "无题 · boop-yyt #1373", "surface": "A man urinates and dies. How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_27629b68d5cf", "srcNo": 904, "title": "织梦者》《新世界", "dispTitle": "织梦者》《新世界", "surface": "我是一名催眠师，一旦被催眠，你将分不清梦与现实，这也让我在行业内声名大噪。星期一，小珊突然提议要玩笔仙，作为催眠师，我决定吓吓她，玩一半的时候我悄无声息地催眠了她，她惊叫连连，和我说她见到了幽灵，我笑着解除了催眠，她还是惊恐的指着我身后，我回过头……星期二，身旁的小珊已经失去意识了，多亏了她我才逃过一劫，接下来，我将用催眠师独有的方式复仇。星期三，我不怪任何人，也不会杀了你，但我真的需要你陪着我，就算以这种独有的方式。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_2821f14a71da", "srcNo": 278, "title": "049 · 水箱", "dispTitle": "049 · 水箱", "surface": "那天我洗完澡后，说了一句话，家人们听见后都崩溃了。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_2834c40aee07", "srcNo": 914, "title": "家庭公式", "dispTitle": "家庭公式", "surface": "妈妈+妈妈=妈妈 妈妈=0 姐姐+我=妈妈 爸爸+爸爸=1 爸爸+爸爸=爸爸", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_2873bb5be315", "srcNo": 1152, "title": "因果", "dispTitle": "因果", "surface": "10.1 日 阴，我们一家三口平淡的生活被打破，还是被他们发现了! 他们说我们是恶魔，\n小王他们都被杀了,丈夫也生死未卜，我现在藏在柜子里，等一下,好像有人来了。10.2 日 小\n雨，该死! 最近警察怀疑了丈夫，我已经饿了好几天了了，孩子鸣哇乱叫! 好了，终于安静了。\n10.3 日 暴雨，海水现在已经覆盖到 4 楼了，食物告急六 丈夫今天精神状态也很不好，孩子饿\n了，我只好驾皮划艇出门搜索物资。10.5 日 晴，今天我和丈夫去祭拜我们最好的朋友小李，\n一起来的还有小芳和小明。10 年前小李带我们去山里玩，救了我们的命，我们都很感激他。", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_2886745ba637", "srcNo": 756, "title": "箱子", "dispTitle": "箱子", "surface": "屋外和屋内的雷声都让我害怕。直到换了大箱子，屋外雷声消失了；父亲躲进了小箱子，屋内雷声也消失了。", "cats": ["反转", "惊悚", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_28930e0caf4c", "srcNo": 711, "title": "小红裙", "dispTitle": "小红裙", "surface": "姐姐给我选了件小红裙，我穿去上学，然后有人死了。", "cats": ["亲情", "反转", "悬疑", "校园", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_28be44e5ef6b", "srcNo": 1012, "title": "多出来的腿", "dispTitle": "多出来的腿", "surface": "三个人去野外露营，并排睡在帐篷里。半夜，中间的人醒来，摸了摸左右，发现左边有两条腿，右边也有两条腿，他安心地睡了，第二天却被发现死在帐篷外。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_2962d63847c2", "srcNo": 881, "title": "井", "dispTitle": "井", "surface": "当我从井里爬出来时，我的朋友喜极而泣。但他突然又一脸的惊恐！把我推了下去！", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_299d4670773c", "srcNo": 197, "title": "", "dispTitle": "无题 · KONpiGG #197", "surface": "没想到有一天，我会死在自己的制裁之下。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_29a799606726", "srcNo": 788, "title": "保姆", "dispTitle": "保姆", "surface": "最近保姆总是偷懒，家里乱糟糟的。我去客厅跟爸爸告状，爸爸却说：我们家没请保姆。我回卧室质问保姆，保姆却说：你爸爸已经去世一年了，今天是他的忌日。我到底该相信谁？我冲出家门，正好撞见邻居阿姨，阿姨一句话让我彻底崩溃。", "cats": ["反转", "悬疑"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_29d813a4dee7", "srcNo": 636, "title": "《捷運上的頂級殺手》", "dispTitle": "《捷運上的頂級殺手》", "surface": "「一個男人在下班高峰期擠上了滿載的捷運。他剛站穩，手機就響了。他接起電話聽了幾秒，突然大聲對著電話喊：『沒問題，長官！我已經帶好槍了，立刻去目標家裡把他處理掉！』整車的乘客都驚恐地看著他，但一分鐘後，大家卻都對他報以熱烈的掌聲。請問發生了什麼事？」", "cats": ["搞笑", "脑洞"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_29f7da348ef4", "srcNo": 1244, "title": "空房间里的第二杯", "dispTitle": "空房间里的第二杯", "surface": "侦探进入一间反锁的密室：死者倒在桌边，桌上有两个用过的茶杯，房间只有死者一人。没有搏斗痕迹。这是自杀还是他杀？关键诡计是什么？", "cats": ["其他"], "difficulty": 2, "src": "github:lancelily6362-png/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_2a1c48ba2d0a", "srcNo": 771, "title": "魔术师", "dispTitle": "魔术师", "surface": "小明的爸爸是魔术师，小明很崇拜他。有一天小明对爸爸说了一句话，爸爸崩溃了。", "cats": ["亲情", "反转", "惊悚"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_2a1ddcd0a374", "srcNo": 922, "title": "学院规则怪谈", "dispTitle": "学院规则怪谈", "surface": "1. 若不加入学院，我就会被惩罚。2. 很多父母送学生过来，但学院只收身体健康的学生。嘻嘻~ 3. 学院成立百年，校训是”生长为人“。嘎嘎~ 4. 地下室禁止入内，上百名退休职工在休息。呜呜~ 5. 学院职工人数固定为20人。哼哼~ 6. 学生毕业后，须在学院入职。嘿嘿~ 7. 不要毕业！！！哈哈哈！8. 我逃学失败了，估计很快就会毕业了。呵呵！！", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_2a3192fd3cc5", "srcNo": 80, "title": "", "dispTitle": "无题 · KONpiGG #80", "surface": "第一天小熊没有啦！第二天洋娃娃没有啦！第三天小木偶没有啦！最后一天全都不见啦！只看到蝴蝶结还在发光。我很伤心，因为蝴蝶结也不见了。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_2acce9c03796", "srcNo": 241, "title": "006 · 仪式", "dispTitle": "006 · 仪式", "surface": "最近你的父母总是吵架，母亲状态奇怪：总是心不在焉，偷偷问你怎么给别人转账，有时会在家里无声地挥舞双手像在进行什么仪式。一天晚饭后，你父亲出门散步，母亲也悄悄出了门，起了疑心的你跟在她身后……啊，原来如此……", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_2b1dbcbfd0c2", "srcNo": 569, "title": "最后的轻语", "dispTitle": "最后的轻语", "surface": "妈妈总是在凌晨三点准时来到我的房间，她的眼睛在黑夜里闪闪发亮。她轻轻摸我的脖子，轻轻地说：“多好的血管。”她做的炖肉总是特别嫩，带着一股铁锈味。昨天，我在她的抽屉里发现了一叠我的照片，每张都被画上了红叉。今晚，我假装睡着，听见她在厨房磨刀。当脚步声停在我门口时，我终于明白——妈妈想杀了我。我冲出房门，看见妈妈站在走廊尽头，她对我露出了我从没见过的温柔笑容", "cats": ["家庭", "恐怖", "本格"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_2b6f776f3991", "srcNo": 1269, "title": "图书馆的死亡", "dispTitle": "图书馆的死亡", "surface": "一个人在图书馆被发现死亡。他手里拿着一本书，周围没有挣扎痕迹。警察发现书页间夹着一张纸条，上面写着'42'。死因是什么？", "cats": ["其他"], "difficulty": 2, "src": "github:ns5601/ai-haigui-game", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_2bfc73d62778", "srcNo": 17, "title": "消失的猫", "dispTitle": "消失的猫", "surface": "他的猫失踪了三天。猫回来后，他立刻搬离了那栋楼。", "cats": ["其他"], "difficulty": 2, "src": "github:17hczmsn/turtle_soup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_2bfce712eedb", "srcNo": 601, "title": "生日快乐", "dispTitle": "生日快乐", "surface": "马上要过生日了，我邀请了很多曾经同生共死的好朋友一起庆生。生日当晚，就当我开心的吹完蜡烛唱完生日歌，我的朋友们都为我鼓掌，然后我就把他们全杀了。", "cats": ["犯罪"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_2c0ba09a2695", "srcNo": 1339, "title": "", "dispTitle": "无题 · boop-yyt #1339", "surface": "Why is it that, in general, the hair on a man's head goes grey before the hair in his moustache does?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_2c50d576d957", "srcNo": 625, "title": "守钟人", "dispTitle": "守钟人", "surface": "小镇的钟楼每天凌晨 3 点都会准时敲响，几十年来从未间断。但最近一周，钟楼的钟声突然消失了，镇上却没有任何人报警或议论这件事。直到第七天，有人在钟楼地下室发现了一具尸体，死者正是钟楼的守钟人。", "cats": ["其他"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_2c7e41d75f49", "srcNo": 989, "title": "不存在的证人", "dispTitle": "不存在的证人", "surface": "一名律师在法庭上指控被告杀害了自己的双胞胎兄弟，但被告最后却被无罪释放了，尽管证据确凿。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_2ccbebdb0625", "srcNo": 1360, "title": "", "dispTitle": "无题 · boop-yyt #1360", "surface": "If he'd turned on the light, he'd have lived. How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_2cdc6af17910", "srcNo": 36, "title": "作家的生日会", "dispTitle": "作家的生日会", "surface": "我参加了我最喜欢的作家的生日会，生日会结束后，我心满意足的回到家，可当我最喜欢的作家回到家后，我却疯了。", "cats": ["恐怖", "犯罪"], "difficulty": 3, "src": "github:anchorAnc/astrbot_plugin_TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_2ce43c699df0", "srcNo": 422, "title": "失窃的名画", "dispTitle": "失窃的名画", "surface": "博物馆发生了一起名画失窃案，警方调查博物馆大门的监控显示，闭馆后唯一进出的只有一名清洁工，他推着清洁车进入，大约半小时后离开了博物馆。警方随即进行搜查，清洁工身上并没有携带任何东西，清洁车内除了拖把、抹布、清洁剂这些常规清洁工具之外也没有别的东西。\n\n一周后，清洁工获得了一笔巨款。", "cats": ["本格", "逻辑"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_2d1f4312f6fe", "srcNo": 1079, "title": "手术台上的歌声", "dispTitle": "手术台上的歌声", "surface": "手术成功了，医生走出手术室，听到病人家属在唱歌，医生立刻冲回去杀死了病人。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_2d1fd42ccdc7", "srcNo": 74, "title": "", "dispTitle": "无题 · KONpiGG #74", "surface": "一个人躺在床上准备睡觉。这时，他突然拿起手机，拨了一个电话。他等了几秒，电话刚刚接通，他就突然挂了电话，然后安稳的睡了。请问发生了什么？", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_2d68206bbfa2", "srcNo": 815, "title": "电梯里的尖叫", "dispTitle": "电梯里的尖叫", "surface": "一名男子走进电梯，看到里面只有一位老太太。他按下楼层键后，老太太突然尖叫，立刻冲出电梯。请问发生了什么事？", "cats": ["悬疑", "搞笑", "日常"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_2d7a2f4d5b9f", "srcNo": 1346, "title": "", "dispTitle": "无题 · boop-yyt #1346", "surface": "A man wakes up in a dark room. He switches on the light.why?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_2e4826c1247b", "srcNo": 229, "title": "要水拿枪", "dispTitle": "要水拿枪", "surface": "一个男人走进一家酒吧，并向酒保要了一杯水。酒保拿出一支枪并瞄准他，该名男子说：“谢谢你！”然后离开，请问发生了什么事？", "cats": ["其他"], "difficulty": 2, "src": "github:wangyafu/haiguitangmcp", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_2e587d7b6540", "srcNo": 690, "title": "作业里的遗书", "dispTitle": "作业里的遗书", "surface": "寒假补作业到开学当天才补完。我一大早趁妈妈没起床去学校报到，到了学校我却疯了。", "cats": ["亲情", "反转", "悬疑"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_2e6c800332fa", "srcNo": 43, "title": "一盘排骨", "dispTitle": "一盘排骨", "surface": "生日那天爸爸端上来一盘排骨，并对我说了一句话，说完我痛哭了起来。", "cats": ["悬疑", "温情"], "difficulty": 3, "src": "github:anchorAnc/astrbot_plugin_TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_2ea3eb2d8e90", "srcNo": 532, "title": "一贯钱", "dispTitle": "一贯钱", "surface": "乱世中，苛政下。一户农家被人丁赋税逼得家破人亡，仅剩女子一人。\n“我的丈夫和公公都被吃了，我的儿子被抓了，我的婆婆也死了。”她身无分文逃至深山，官差追赶至此道“你家人丁赋税还差一贯钱，速速交来”，女子无可奈何交出一贯钱。两名官差回去复命途中差点被吃了，所幸一张纸救了他俩性命。", "cats": ["悲剧"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_2eb1bd4b6bf0", "srcNo": 107, "title": "", "dispTitle": "无题 · KONpiGG #107", "surface": "我是个乞丐，醒来发现碗里多了样东西，为此我饱餐了一顿，但是在第七天时，我却死了。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_2eefe22004d0", "srcNo": 996, "title": "打错的电话", "dispTitle": "打错的电话", "surface": "男子接了一个打错的电话，说了声“没关系”就挂断了。当晚他被杀了。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_2f0586b31aae", "srcNo": 574, "title": "玩手机", "dispTitle": "玩手机", "surface": "我偶然间看到窗外，我知道我完了", "cats": ["其他"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_2f067ab34179", "srcNo": 223, "title": "看起来没那么严重", "dispTitle": "看起来没那么严重", "surface": "男人无法想象他的感冒会导致他的死亡。", "cats": ["其他"], "difficulty": 2, "src": "github:wangyafu/haiguitangmcp", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_2f51212d817e", "srcNo": 370, "title": "错位", "dispTitle": "错位", "surface": "深夜23：45，我收到消息“等我，我们很快见面。”\n我守着这唯一的念想，摩挲着她快递给我的梳子，开始等待。\n这个世界的时间如此漫长。\n15分钟后，一阵类似门铃的“嘀”声清晰地传来。\n我知道，她来了。\n可巨大的悲伤瞬间淹没了我——我明白，我永远也见不到她了。\n请问，发生了什么？", "cats": ["怪谈", "悲剧", "日常"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_2f71811bc48b", "srcNo": 850, "title": "奇怪的声音", "dispTitle": "奇怪的声音", "surface": "之前的支教走了，于是把我派去山里支教，我借宿在村长家里，他们家门口贴了一张奇怪的黄纸，而且他们家每天晚上都会传来沉闷的咚咚声，我发现这个声音是有规律的，于是我记了下来96924482622454，三天后，声音消失了，我也明白声音是什么了，是那五个字。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_2f78e9a8b0e2", "srcNo": 143, "title": "", "dispTitle": "无题 · KONpiGG #143", "surface": "在我们考察团来到这遗迹的第三周，纯净水已经只够再用十天了。但是我发现了一本八百年前残留下来的日记，上面有\"潜入调查，兽化，天神的礼物，禁忌之所，圣水，骗子，逃\"的字样。就在第四周，当我发现我的同伴眼睛通红，发出非人类的尖叫的时候，已经说什么都晚了，逃不掉了...", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_2f8b63661d46", "srcNo": 416, "title": "你的名字", "dispTitle": "你的名字", "surface": "“你会被叫关阳青的杀死。”\n在我很小的时候，一位高僧警告我。我的人生一直躲着这个名字，直到结婚生子。结果我给孩子开家长会时死在了学校，果然，我真的被叫关阳青的杀死了", "cats": ["其他"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_2fb427a16795", "srcNo": 727, "title": "旧的八音盒", "dispTitle": "旧的八音盒", "surface": "男孩女孩是邻居，女孩生日时男孩送她一个旧八音盒，不久后女孩搬家。", "cats": ["反转", "悬疑", "惊悚"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_302b8cd32263", "srcNo": 117, "title": "", "dispTitle": "无题 · KONpiGG #117", "surface": "\"狼来了！\"\"哪有狼啊？\"\"真的有狼！\"\"狼....来了！\"\"哪有狼，这不是狼。\"\"狼.....狼来了？\"\"啊啊啊啊啊啊\"", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_304a97448cef", "srcNo": 659, "title": "拆掉完好的工坊", "dispTitle": "拆掉完好的工坊", "surface": "老工坊的房子依然结实，老板却拆掉地板和墙面，将碎料装袋送走。重新装修后继续原来的生意，而且还从送走的碎料中收回一笔钱。为什么？", "cats": ["职场", "脑洞"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_3096af311f7e", "srcNo": 549, "title": "致命的盟軍", "dispTitle": "致命的盟軍", "surface": "漫長而殘酷的戰爭終於結束了。\n\n一對在戰區流浪、瘦骨如柴的年輕兄弟，幸運地遇到了一小隊友善的盟軍。\n\n新兵們看著這對可憐的兄弟，便熱情地將自己背包裡的肉罐頭、巧克力和軍用口糧全部分給了他們。哥哥看著弟弟狼吞虎嚥地把食物吃個精光，露出了久違的欣慰笑容。\n\n然而，幾個小時後，弟弟卻在極度的痛苦中死去了。士兵的食物絕對沒有毒，那是誰殺了他？", "cats": ["逻辑"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_30b50a72f385", "srcNo": 951, "title": "在排序数组中查找元素的第一个和最后一个位置", "dispTitle": "在排序数组中查找元素的第一个和最后一个位置", "surface": "在排序数组中查找元素的第一个和最后一个位置", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_30c815b194ce", "srcNo": 894, "title": "因果", "dispTitle": "因果", "surface": "10.1日 阴，我们一家三口平淡的生活被打破，还是被他们发现了！他们说我们是恶魔，小王他们都被杀了，丈夫也生死未卜，我现在藏在柜子里，等一下，好像有人来了。10.2日 小雨，该死！最近警察怀疑了丈夫，我已经饿了好几天了，孩子呜哇乱叫！好了，终于安静了。10.3日 暴雨，海水现在已经覆盖到4楼了，食物告急，丈夫今天精神状态也很不好，孩子饿了，我只好驾皮划艇出门搜索物资。10.5日 晴，今天我和丈夫去祭拜我们最好的朋友小李，一起来的还有小芳和小明。10年前小李带我们去山里玩，救了我们的命，我们都很感激他。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_30ffbff72d13", "srcNo": 1393, "title": "", "dispTitle": "无题 · boop-yyt #1393", "surface": "John was watching television. Just after the midnight news there was a weather forecast: /?It is raining now and will rain for the next two days. However, in 72 hours it will be bright and sunny.\" \"Wrong again/7 snorted John. He was correct but how did he know?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_311fd18aae90", "srcNo": 275, "title": "046 · 红色高跟鞋", "dispTitle": "046 · 红色高跟鞋", "surface": "一位女士去鞋店买了一双红色高跟鞋，这双高跟鞋预示了她今晚的死亡。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_313b1b1994da", "srcNo": 966, "title": "", "dispTitle": "无题 · xxtg666 #966", "surface": "给玩家看的谜题描述。\",\n \"supplementaryinfo\": [\n \"补充信息：主持人回答问题的事实依据，同时也是玩家可获取的提示，建议 10-12 条。\",\n \"第二条补充信息……\"\n ],\n \"solution\": \"", "cats": ["其他"], "difficulty": 2, "src": "github:xxtg666/nonebot-plugin-ai-turtle-soup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_314cc038dce2", "srcNo": 737, "title": "借书", "dispTitle": "借书", "surface": "一位老人每周去图书馆借书，但每次借书前都会翻到第30页。", "cats": ["亲情", "推理", "日常", "温情"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_3162bdeaaea3", "srcNo": 1280, "title": "", "dispTitle": "无题 · boop-yyt #1280", "surface": "A man walks into a bar and asks for a drink. The bartender pulls out a gun and points it at him. The man says, \"Thank you\", and walks out. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_31808240d702", "srcNo": 191, "title": "", "dispTitle": "无题 · KONpiGG #191", "surface": "在一个寒冷的冬天，一个人在屋里睡觉，第二天早上醒来，他发现窗户上有很多雾气，他擦了擦窗户，却看到了一张恐怖的脸。请问这是怎么回事?", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_319333fbaf07", "srcNo": 1193, "title": "Jed 1.6", "dispTitle": "Jed 1.6", "surface": "A man walks into a bar and asks for a drink. The bartender pulls out a gun and points it at him. The man says, \"Thank you,\" and walks out. (DVS; from _How Come?_)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_31d542254a0a", "srcNo": 18, "title": "同一首歌", "dispTitle": "同一首歌", "surface": "隔壁每天凌晨播放同一首歌。她听到第七天时，终于报警了。", "cats": ["其他"], "difficulty": 2, "src": "github:17hczmsn/turtle_soup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_31d54f73bfbf", "srcNo": 1111, "title": "盲人", "dispTitle": "盲人", "surface": "我是一个言人,我怀疑家里进贼了，最近家里有些奇怪的酥醋的声音，接着是咀嚼的声\n音。过了几和天， 我又听到了窗户被打开的声音，之后传出了扭打在一起的声音，随后又是後怀\n的声音和咀嚼的声音。", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_31d8b28de5f7", "srcNo": 295, "title": "067 · 忘记密码", "dispTitle": "067 · 忘记密码", "surface": "她花了三年的时间来忘记他，最终成功了。然后她哭了。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_3217b45cbc60", "srcNo": 401, "title": "望舒引", "dispTitle": "望舒引", "surface": "​穹頂忽裂，望舒低垂。\n佳人含笑，踏虛空而化仙去。\n骨肉碎作飛星，丹心獻與玉盤。\n吾獨坐廢墟，泣血而嘆：「今夕月色，美極，艷極。」\n遂引穿骨之針，絕情之線，密縫雙目，以全此情。", "cats": ["怪谈", "悲剧"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_32305f014736", "srcNo": 1103, "title": "升职的秘密", "dispTitle": "升职的秘密", "surface": "能力平平的同事突然升职了，所有人都觉得不公平。但升职后他的工作效率反而下降了很多。", "cats": ["其他"], "difficulty": 2, "src": "github:Tenzyoo/turtle_soup_game", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_32382f5b7359", "srcNo": 613, "title": "方舟解剖学", "dispTitle": "方舟解剖学", "surface": "我正在破解这艘世代飞船的底层数据库，三张被加密的舱段结构图跳了出来。\n第一张，名为‘育婴室’的区域位于引擎核心旁，厚重的铅壁隔绝了致命辐射，却也物理切断了内部向外的所有通讯频段；\n第二张，全船的通风管道在经过普通船员区时，都衍生出了奇怪的支路，像一条条盘踞的蟒蛇，最终汇聚在舰长室的床底；\n第三张，生态循环系统的管道走向精妙得如同人体血管，覆盖了每一个角落。\n年迈的老舰长不知何时站在了我身后，指着那些看似冗余的管道笑道：“这是为了保证方舟的‘养分’能够公平流转。”\n那一刻我还没反应过来，在资源枯竭的深空中，他眼中的“养分”，指的不是水培液，而是人。", "cats": ["悬疑"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "ai"}, {"id": "lib_331b79e11575", "srcNo": 452, "title": "坠落的星空", "dispTitle": "坠落的星空", "surface": "老师独自守在这座雪山顶端的天文台已有三十年。\n观测室的穹顶内壁被擦拭得如镜面般光滑，连一颗微尘都找不到。\n然而，每次前往顶层的望远镜控制台时，老师宁愿冒着暴风雪徒手攀爬外墙那架结满冰棱的垂直检修梯，也绝不肯踏上塔内那座温暖舒适的螺旋阶梯一步。\n整理物品时，我在一本发黄的观测日志里夹着一张星图，上面用暗褐色的颜料涂抹出一团扭曲、狰狞的星云，仿佛一只张开的血盆大口。\n我刚拿起那张图，老师便疯了一般冲过来夺走，缩在角落里瑟瑟发抖，嘴里不住地念叨着：“擦不掉……无论如何也擦不掉……”", "cats": ["悲剧", "惊悚"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_33459e0dc957", "srcNo": 1284, "title": "", "dispTitle": "无题 · boop-yyt #1284", "surface": "Two brothers are involved in a murder. Though it's clear that one of them actually committed the crime, neither can be punished. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_335a2a7a493a", "srcNo": 907, "title": "房间里的黑点", "dispTitle": "房间里的黑点", "surface": "星期二 小区里遇到一个戴口罩的女孩，夏日炎炎，她居然裹着冬装，她身上散发出一股中药味，令人不适。星期三我去菜市场买了些莲藕回家，在电梯里居然又遇到了她，她手里拿着一本泛黄的书，不知为何，我觉得她好像很害怕我。星期五醒来后，我发现房间里满是密密麻麻的黑点，我急忙清理。星期日今天不止有黑点了，我还是搬家吧。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_33a8157609fc", "srcNo": 1355, "title": "", "dispTitle": "无题 · boop-yyt #1355", "surface": "He couldn't find a chair, so he died. (RM, with KH wording; from How Come?) How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_3440a90fa94c", "srcNo": 994, "title": "牛排店的婴儿", "dispTitle": "牛排店的婴儿", "surface": "一家人在牛排店吃饭。父亲切了一块肉给孩子吃，孩子吃完后，父亲微笑着自杀了。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_34a67c6b30a1", "srcNo": 260, "title": "029 · 特快列车", "dispTitle": "029 · 特快列车", "surface": "一列特快车，在中途站有一名男子上了列车。车门关闭后，他像突然回过神来，开始左右环视周围乘客的脸，然后逐一询问：\"请问你今年28岁吗？\"\"你45岁吗？\"\"你62岁吗？\" 每次都得到肯定回答。问完一圈后，男子回到座位静静坐下，绝望痛哭。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_34b5a93e4249", "srcNo": 395, "title": "新衣", "dispTitle": "新衣", "surface": "布幕掩盖的宴会，园丁剪断了枯枝。\n王子溺死在梦里，管家吞下了钥匙。\n 国王弄丢了权杖，公主变成了娃娃。\n 皇后脱下了金冠，躲进钟楼里哭泣。\n 别数秒针，别听呼吸， \n当钟声敲响十三下，谁在宴会上穿新衣？\n 是我?是我，是我！", "cats": ["反转", "本格"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_357826866b59", "srcNo": 326, "title": "100 · 镜中时钟（经典版）", "dispTitle": "100 · 镜中时钟（经典版）", "surface": "一名男子从梦中醒来，通过镜子看了眼时钟，然后又躺下继续睡，再也没有醒来。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_35788df1e927", "srcNo": 995, "title": "闹钟", "dispTitle": "闹钟", "surface": "每天早上8点，男人的闹钟都会响。有一天闹钟没响，男人却死了。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_357a5c287302", "srcNo": 1372, "title": "", "dispTitle": "无题 · boop-yyt #1372", "surface": "Two people are dead in a car, which is locked from the inside. There's a lot of blood. How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_35815405359b", "srcNo": 85, "title": "", "dispTitle": "无题 · KONpiGG #85", "surface": "一个人住在山顶的小屋里，半夜听见有敲门声音，但是他打开门却没有人，于是去睡了。第二天，有人在山脚下发现死尸一具，警察来把山顶的那人带走了。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_358504561353", "srcNo": 478, "title": "娃娃，男尸和纸条", "dispTitle": "娃娃，男尸和纸条", "surface": "一具男尸趴在桌上，一个娃娃放在桌边，男尸的下面压了一张纸，纸上写了一句话。", "cats": ["其他"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_3598c14d3407", "srcNo": 309, "title": "081 · 婴儿", "dispTitle": "081 · 婴儿", "surface": "一个女人在医院生了一个孩子。第二天，护士把孩子抱到她面前，但当她看到时，她疯狂地大叫：\"这不是我的孩子！\" 她为什么会知道这不是她自己的孩子？", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_35998e97865e", "srcNo": 231, "title": "长路终有归途", "dispTitle": "长路终有归途", "surface": "“祝你生日快乐”，我终于在45岁这天度过了6岁的生日。", "cats": ["其他"], "difficulty": 2, "src": "github:wangyafu/haiguitangmcp", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_35aafab18f4c", "srcNo": 110, "title": "", "dispTitle": "无题 · KONpiGG #110", "surface": "小美和网友小明约好见面，几分钟后小美却大声惊叫起来！", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_35e327e8890d", "srcNo": 1278, "title": "", "dispTitle": "无题 · misc #1278", "surface": "Two brothers are involved in a murder. Though it's clear that one of them actually committed the crime, neither can be punished. (from \"Unreasonable Doubt,\" by Stanley Ellin) How could this be", "cats": ["其他"], "difficulty": 2, "src": "misc/repo-scan", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_35f3a561af0a", "srcNo": 547, "title": "对称的伤痕", "dispTitle": "对称的伤痕", "surface": "死者左臂有一道旧刀疤，右臂在相同位置有一道新伤口。", "cats": ["悬疑"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_36075b693701", "srcNo": 362, "title": "圣诞礼物", "dispTitle": "圣诞礼物", "surface": "今天爸爸让我早点睡觉，可深夜我却听到了敲门声，我好奇推开门去看，是不是爸爸准备好了圣诞礼物，客厅里一颗红色的圣诞树上挂满了装饰品，还没填料的火鸡摆在餐桌上，绿色的圣诞老人藏在了壁炉里，这时门外又响起了敲门声…", "cats": ["恐怖"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_360b03abc069", "srcNo": 352, "title": "家庭公式", "dispTitle": "家庭公式", "surface": "妈妈＋妈妈＝妈妈\n妈妈＝0\n姐姐＋我＝妈妈\n爸爸＋爸爸＝1\n爸爸＋爸爸＝爸爸", "cats": ["其他"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_3683663ef68e", "srcNo": 427, "title": "简单的祭祀招聘", "dispTitle": "简单的祭祀招聘", "surface": "我是一个无业游民，在某天我在刷手机的时候，发现了一个招聘上面写了：“村中祭祀招聘一名祭祀官（画家，天文专家，预言家），身体必须健全，无残疾，男性。”给的费用也十分的多，我想我可以装作预言家去糊弄糊弄然后就走了。我报了名之后到了才发现，原来谁都可以，就算不会那些技能也可以。", "cats": ["恐怖", "猎奇", "逻辑"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_36a9685bff7a", "srcNo": 1309, "title": "", "dispTitle": "无题 · boop-yyt #1309", "surface": "The wind stopped blowing and the man died. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_36a972482cbe", "srcNo": 1027, "title": "特殊的遗物", "dispTitle": "特殊的遗物", "surface": "父亲去世，留给儿子一个打不开的保险柜。儿子费尽心思请来开锁匠，打开后里面只有一张欠条。儿子看后却笑了。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_36b3906f39dc", "srcNo": 925, "title": "雷阵雨", "dispTitle": "雷阵雨", "surface": "慕容星和孙阳都在追求李月。慕容星不屑地给了孙阳一巴掌：“你爷爷不过是我们家族的管家而已，你有什么资格和我争”孙阳大怒：我爸爸孙建国其实是你姥爷张开阳和你姥姥狸猫换了太子，当年孙管家和王婶的孩子，你妈妈才是我爷爷的孩子，所以说我本质上是张家小少爷！孙建国跑来，给了孙阳一巴掌：你算什么东西！你根本不是我亲生的，你妈妈出轨了张家二少爷张羿！我可是张家大少爷张建国！孙阳不甘：那又如何，我爸爸张羿我不还是张家的小少爷吗？李月看到孙建国大惊失色：爸爸你怎么来了？如果像你说的，那我还怎么和孙阳在一起！！！孙管家跑来给了孙阳一巴掌：混账孙子！你爸爸张羿其实是我和张开阳妻子郭蓉蓉的孩子，你跟没有张家的血脉！快给少爷道歉！慕容星大惊：也就是说张开阳不是我姥爷，你孙管家才是我姥爷？慕容星的爷爷李刚苦笑道：张开阳其实才是你的爷爷，当年两大家族慕容家和张家联姻，你奶奶慕容牡丹怀了你爸爸，其实是张开阳的孩子，张开阳后来抛弃了你奶奶和郭蓉蓉在一起了，并生下了被掉包走的孙建国。孙建国打断：张建国张建国，张家大少张建国。慕容星的爸爸慕容海跑来：儿子你不可以和李月在一起，她可是我的血脉啊！！！李月大惊失色：我居然是慕容家的大小姐，那我还怎么和慕容星在一起！！！慕容海继续说：她妈妈是李玉！是我和前女友李梅梅的孩子！！。孙建国意识到了什么，大惊失色：李玉不是我情人吗？难道说。。。。。。李刚也大惊失色：李梅梅不是我和王婶的孩子吗？孙管家也大惊失色：王婶不是我媳妇吗？？？李月大惊失色：那我和谁在一起？？？", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_36bccb50c358", "srcNo": 87, "title": "", "dispTitle": "无题 · KONpiGG #87", "surface": "她有两个女儿 ，姐姐乖巧懂事，妹妹顽劣叛逆。那天晚上她去茅房上厕所，疯了。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_3701a469708b", "srcNo": 648, "title": "回不了家的旅人", "dispTitle": "回不了家的旅人", "surface": "偏远营地里，女人问男友是否清洗了桌上的小容器。男友说里面的东西已经倒进下水道。她翻遍行李后，决定叫救援把车和两人送回城里。车并没有坏。为什么？", "cats": ["反转", "日常"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_37c884ffabac", "srcNo": 710, "title": "好孩子", "dispTitle": "好孩子", "surface": "“我要做个好孩子，我是个好孩子……”我不停对自己说。新闻报道一起凶杀案，凶手至今下落不明。", "cats": ["亲情", "悬疑", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_382262860b35", "srcNo": 512, "title": "痛感", "dispTitle": "痛感", "surface": "我是一名受害者从古至今人们总是为伤害我的凶器争论不休，没有人关心我的状态，只有少数人会在第一时间在意我", "cats": ["逻辑"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_3889fb57398f", "srcNo": 801, "title": "照片", "dispTitle": "照片", "surface": "小明在看自己手机最近拍的照片，看完后立刻到警局报案，为什么？", "cats": ["悬疑", "惊悚", "推理", "日常"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_38fcff2be869", "srcNo": 479, "title": "项链", "dispTitle": "项链", "surface": "外婆家夏天好凉快，但是总是有点臭臭的铁味。墙上有许多亮亮的小装饰，一组一组的。我用小铲子挖呀挖，扣下来做成项链戴在脖子上。", "cats": ["恐怖", "本格"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_38fd203d3162", "srcNo": 545, "title": "愿望", "dispTitle": "愿望", "surface": "“我是神灯精灵，既然你找到了我，我就会实现你的三个愿望。”\n.......\n”好了，你的愿望实现了，可能你不记得了，这最后一个愿望，你之前就许愿过了。“", "cats": ["其他"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_39184b06b692", "srcNo": 1083, "title": "照片里的第三只手", "dispTitle": "照片里的第三只手", "surface": "洗出来的合照上，男人的肩膀上多了一只苍白的手。男人不但不害怕，反而失声大哭，对着照片说‘谢谢’。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_3932d1fa3a8b", "srcNo": 513, "title": "两个头", "dispTitle": "两个头", "surface": "有个青蛙朝我奔来！我推开，它脑袋掉了。吓我一跳！他又冒出来一个脑袋，这下我放心了。", "cats": ["搞笑", "本格"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_396e4fa76bf4", "srcNo": 610, "title": "树顶的白衣", "dispTitle": "树顶的白衣", "surface": "她带着一个空塑料瓶走向水边。第二天，广播里遗憾地宣判了她的死讯：她被河里最凶猛的野兽彻底吞噬，尸骨无存。\n得知噩耗后，她的母亲千里迢迢赶来，却紧紧盯着水边那棵五米高的大树。大树最顶端的枝桠上，赫然挂着一件原本属于她的、纯白色的贴身衣物。\n看着那件随风飘荡的衣物，悲痛欲绝的母亲竟停止了哭泣，她长舒了一口气，露出一丝微笑喃喃自语道：“太好了，原来吃掉她的不是野兽。”", "cats": ["反转", "悬疑", "犯罪"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_3974d2aaaf4b", "srcNo": 1055, "title": "火星上的敲门声", "dispTitle": "火星上的敲门声", "surface": "火星基地只有一名宇航员，通讯设备全坏。某天，他听到基地外传来了规律的敲门声，他狂喜地去开门，却发现外面只有风沙。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_397947c4ebcb", "srcNo": 270, "title": "040 · 三个电话", "dispTitle": "040 · 三个电话", "surface": "你第三次接到了老师的电话，让你不用去学校了。你一边崩溃大哭，一边定下一张火车票。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_39840ef75734", "srcNo": 849, "title": "五兄弟", "dispTitle": "五兄弟", "surface": "在一处废弃的教堂里，刚发生了一起惨案，高老爷子的尸体平静地躺在棺椁里，高老爷子的五个儿子死在了一个巨大的祭坛上。每个人的尸体都被工整地切割了一部分：老大缺了头部，老二缺了胸部和手，老三缺了腹部，老四缺了大腿，老五缺了小腿。而高家的独苗，老三的儿子也在现场，他害怕地对警官说：“他们本来想复活爷爷，结果却召唤出了恶魔，恶魔把他们全杀了。”", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_39fb5cec5a60", "srcNo": 1294, "title": "", "dispTitle": "无题 · boop-yyt #1294", "surface": "Mr. Browning is glad the car ran out of gas. Why?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_3a77368b5652", "srcNo": 953, "title": "AI 眼镜行业趋势 2025-2026", "dispTitle": "AI 眼镜行业趋势 2025-2026", "surface": "AI 眼镜行业趋势 2025-2026", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_3aaa0b44cd6b", "srcNo": 341, "title": "調音師", "dispTitle": "調音師", "surface": "我曾經看到了\n她換衣時美妙的身姿\n富人保險櫃的密碼\n\n這次卻看到了不應看到的風景\n額頭傳來陣陣冰涼的感覺\n我只能硬著頭皮說：「先生，你還好嗎？我已經修好了。」", "cats": ["悬疑", "逻辑"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_3ab4d2516252", "srcNo": 828, "title": "牛吃草", "dispTitle": "牛吃草", "surface": "你住在乡下，邻居是一对养牛的夫妻。某天深夜，你听到外面传来奇怪的「牛吃草」声音，然后听见有东西在撞你的门，但你没多想就继续睡了。隔天一早，警察来敲门，你打开门后瞬间吓傻……发生了什么事？", "cats": ["恐怖", "悬疑", "惊悚", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_3acb8bf86de1", "srcNo": 816, "title": "结婚典礼", "dispTitle": "结婚典礼", "surface": "婚礼上，全场宾客和新娘都突然爆笑，新郎却捂着脸蹲在地上。请问为什么？", "cats": ["搞笑", "日常", "温情"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_3b1d0a439196", "srcNo": 988, "title": "被禁止的掌声", "dispTitle": "被禁止的掌声", "surface": "一个女孩在家里和朋友们玩捉迷藏。第二天，她死在了家里的地下室。死前她听到了一阵掌声。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_3bbb255b2b29", "srcNo": 1039, "title": "无人驾驶", "dispTitle": "无人驾驶", "surface": "一辆车在公路上飞驰，司机却在后座睡觉，车子没有出车祸。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_3c57ed752dfb", "srcNo": 450, "title": "最暖的被褥", "dispTitle": "最暖的被褥", "surface": "我对所有人说：谁以此生相托，我必护她周全。\n于是全网都在转发我的寻人启事，感叹我是个绝世痴情种，甚至还有媒体为了我的眼泪而来。\n其实，我一点也不担心她会冷，也不担心找不到她。\n我很清楚，作为一个体贴的前任，我已经把自己最喜欢的那床棉被给了她。 此刻，她正裹得严严实实，在一个绝对不会被任何人打扰的地方，安稳地睡着。", "cats": ["恐怖", "悬疑", "犯罪"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_3c59d8568b7f", "srcNo": 1291, "title": "", "dispTitle": "无题 · boop-yyt #1291", "surface": "A flash of light, a man dies. Why?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_3cce7ab28b21", "srcNo": 281, "title": "052 · 广播中断", "dispTitle": "052 · 广播中断", "surface": "一名男子一边开车一边听广播。突然广播被打断了，然后又重新响起。听了一会儿，那人停下车，开枪自杀了。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_3d47482db00c", "srcNo": 484, "title": "故障的仁慈", "dispTitle": "故障的仁慈", "surface": "下城区的黑市拳台今晚赌的是“人性”。\n代号“神父”的重型机兵被卸掉了防御装甲，电锯切开了它的胸腔，露出了滋滋作响的线路，但那颗独眼镜头依然闪烁着冷静的蓝光，毫无反应。\n庄家为了刺激它，把三个被捕捉来的流浪仿生童工推上了台，煽动观众用工业酸液泼洒这些只会瑟瑟发抖的小家伙。\n当酸液腐蚀了一个童工的面部伪装层时，“神父”那原本死寂的机械臂突然暴起，发出恐怖的液压轰鸣声震碎了牢笼。\n全场都在惊呼这是机器觉醒的父爱，只有我看见，它的机械钳并不是在挡酸液，而是死死掐住了那个孩子的眼眶，试图把眼皮撑得更大。", "cats": ["悬疑", "悲剧"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_3dee8f122a93", "srcNo": 162, "title": "", "dispTitle": "无题 · KONpiGG #162", "surface": "两个孩子在一起玩耍时吹嘘自己的父亲有多厉害。\"我的爸爸很会玩牌！\"\"我的爸爸很会赚钱！\"\"我的爸爸是骑马高手！\"\"我的爸爸力气很大！\"真希望他们能永远地保持这份纯真。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_3e14aa5d5936", "srcNo": 870, "title": "蒙眼猜物", "dispTitle": "蒙眼猜物", "surface": "我醒过来发现自己被困在床上，眼睛也被蒙住了。身旁传来了声音：“别挣扎，我们来玩蒙眼猜物，你都猜对了我就放过你。”我不清楚情况，但为了求生，只能配合他。第一次，我摸到了一双手，我知道，妻子已经遇害了。第二次，我摸到了一块布条，我清楚的知道它是从哪拿的，我崩溃了。第三次开始之前我听到了脚步声，这次的物品很好猜，但我摸出来后，却不想活了。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_3e4770e9b0e5", "srcNo": 693, "title": "冰箱里的父母", "dispTitle": "冰箱里的父母", "surface": "父母都不理我，但我还是很爱他们。", "cats": ["亲情", "恐怖", "悬疑", "惊悚"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_3e4d2da2c331", "srcNo": 616, "title": "男朋友", "dispTitle": "男朋友", "surface": "开始的时候男朋友他很爱我，但后来他开始欺负我了，他死了。", "cats": ["搞笑", "温情"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_3e757af0b1e5", "srcNo": 632, "title": "白骨佛", "dispTitle": "白骨佛", "surface": "大邺朝永安十七年，京郊白马寺突发大火，寺中供奉的千手观音像被烧成焦炭。清理废墟时，僧人们在佛像内部发现了一具白骨和半枚铜钱，嵌在佛像中已有多年。\n\n更诡异的是，佛像的每一只手臂内部，都藏着一卷写满蝇头小楷的绢帛，记录着同一个人的忏悔，字迹却各不相同。\n\n官府追查之下，发现这尊佛像是十五年前，由当朝首辅沈怀安捐资铸造的。\n\n佛像中的白骨是谁？沈怀安又做了什么？", "cats": ["悬疑", "悲剧", "犯罪"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_3ec7a7147508", "srcNo": 1302, "title": "", "dispTitle": "无题 · boop-yyt #1302", "surface": "A man sends a package to someone in Europe and gets a note back saying \"Thank you. I received it.\" What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_3f015780eb12", "srcNo": 679, "title": "先回来的丈夫", "dispTitle": "先回来的丈夫", "surface": "夫妻把房车停在崖脚，沿山路上行。丈夫在高处扭伤脚，妻子绕远路下山求救。返回时，房车门仍锁着，丈夫却已死在车内，车顶多了一个大洞。为什么？", "cats": ["悬疑", "旅途"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_3f1125b7c0cd", "srcNo": 695, "title": "黑猫叼着老鼠", "dispTitle": "黑猫叼着老鼠", "surface": "我杀了人，被警察带走时看到门口黑猫一直盯着我，我知道我错了。", "cats": ["反转", "悬疑", "推理", "都市"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_3fad9c3ff17b", "srcNo": 375, "title": "小说主角", "dispTitle": "小说主角", "surface": "周围一片黑暗，有个声音说：我们来玩海龟汤吧，我会回答是或不是。我问：这是真实世界吗？声音说：是。此时周围不再一片黑暗，而是变成了公司楼下的咖啡厅，人群熙熙攘攘。我又问：你是我的妻子吗？声音说：是。说完，妻子出现在了我的眼前。我紧张地又问了一句：我是死了吧？妻子说：是。", "cats": ["悬疑"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_3fc63edbf7e2", "srcNo": 464, "title": "红绿色盲", "dispTitle": "红绿色盲", "surface": "一个小女孩考试考了38分，为了防止被打，她自己把成绩修改成了88分。但还是被发现。父亲非常愤怒，但过了一会，母亲死了。请还原被发现的事情经过并推理出前因后果。", "cats": ["家庭", "本格", "逻辑"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_3fd53d292a49", "srcNo": 1261, "title": "没湿的雨衣", "dispTitle": "没湿的雨衣", "surface": "暴雨夜里，保安看见住户穿着雨衣回家，雨衣却一点没湿，便悄悄按了报警器。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:lancelily6362-png/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_400b8066b951", "srcNo": 1256, "title": "不响的风铃", "dispTitle": "不响的风铃", "surface": "台风夜里，屋檐下的风铃一直没响，屋主却因此发现凶手来过。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:lancelily6362-png/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_40220a602fef", "srcNo": 303, "title": "075 · 减肥", "dispTitle": "075 · 减肥", "surface": "她用了一年时间减掉了30斤，所有人都恭喜她，她却哭了。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_404a1a1b5011", "srcNo": 296, "title": "068 · 最后的电话", "dispTitle": "068 · 最后的电话", "surface": "我给她打了最后一个电话，她接了，我说\"我爱你\"，然后挂掉了。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_408d0bacc2de", "srcNo": 694, "title": "蜂蜜水与巧克力", "dispTitle": "蜂蜜水与巧克力", "surface": "我发现床头柜上多了一杯蜂蜜水和一块巧克力蛋糕，原本的娃娃却不见了。我知道男友再也回不来了。", "cats": ["反转", "惊悚", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_40985bc7685d", "srcNo": 1149, "title": "发夹", "dispTitle": "发夹", "surface": "我家隔壁传来“噬?”的一声，之后又是与声，于是我敲门询问是否需要帮助，开门的是一\n位女士，她和我说不用帮忙并表示感谢。回到家后，我急忙报了警。", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_40ffb943ef93", "srcNo": 400, "title": "森林潜水员", "dispTitle": "森林潜水员", "surface": "一片茂密的森林里，护林员在巡逻时，发现了一具穿着潜水服的尸体，尸体附近没有任何水源，也没有打斗痕迹，潜水服的氧气瓶里还有剩余的氧气，死者却离奇死亡。", "cats": ["悬疑"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_410b5ac434f2", "srcNo": 467, "title": "墓碑上的文字", "dispTitle": "墓碑上的文字", "surface": "2988年，我和爸媽一起去星際旅行。回來時卻出了意外。爸媽立馬打算要二胎。五十年後，兒孫滿堂，爸媽去世了，我的孫子給爸媽提辦了葬禮，我看著墓碑上的文字，卻突然頭皮發麻！ 原來一切都錯了！", "cats": ["反转", "脑洞"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_4137b08cecf3", "srcNo": 1380, "title": "", "dispTitle": "无题 · boop-yyt #1380", "surface": "A very common variant uses the names Romeo and Juliet instead, to further mislead audiences. For example: Romeo is looking down on Juliet's dead body, which is on the floor surrounded by water and broken glass. How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_4147e40f1d0e", "srcNo": 1265, "title": "永远亮着的空房", "dispTitle": "永远亮着的空房", "surface": "废弃旅馆里有一间房夜夜亮着灯，老板却坚持那里根本没有通电。多年后警察进入房间，发现他说的是真的。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:lancelily6362-png/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_4166968fc81c", "srcNo": 224, "title": "祭日", "dispTitle": "祭日", "surface": "在儿子去世一周年的祭日上， 我杀死了三个来悼念他的人。", "cats": ["其他"], "difficulty": 2, "src": "github:wangyafu/haiguitangmcp", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_4167192633ff", "srcNo": 417, "title": "最后的表演", "dispTitle": "最后的表演", "surface": "话剧舞台上，一个男人倒在血泊中，胸口有一处致命伤。台下的观众爆发出雷鸣般的掌声，帷幕缓缓落下。", "cats": ["悲剧", "本格"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_4195efaab01e", "srcNo": 1299, "title": "", "dispTitle": "无题 · boop-yyt #1299", "surface": "Music stops and a woman dies. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_41c4b2f5dada", "srcNo": 612, "title": "大师的底色", "dispTitle": "大师的底色", "surface": "导师离世后，我收到他管家寄来的一箱‘特制画材’。\n信中只有一句狂草：‘唯有你能驾驭这份真实的生命力。’\n我颤抖着抚摸那卷名为‘初雪’的画布，它的纹理细腻如脂，带着微微的体温，仿佛在呼吸。\n那管标着‘威尼斯红’的颜料，色泽浓郁得令人心醉，开盖瞬间竟有一股迷人的铁锈腥气。\n为了试色，我提起那支柔软湿润的‘貂毛笔’，在画布上重重抹了一笔。\n刹那间，笔尖传来一阵痉挛般的吸附感，而那道红色的笔触没有凝固，反而顺着画布的纹理，缓缓渗进了深处。", "cats": ["反转"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_41e02e0f8c85", "srcNo": 726, "title": "影子", "dispTitle": "影子", "surface": "晚上我去公厕，看见男厕门口站着一个人，身后有影子，手里还拿着什么。我很快冷静。第二天警察问我看到尸体为何不报警，我瞬间吓呆。", "cats": ["悬疑", "惊悚", "推理", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_42647eaf2677", "srcNo": 146, "title": "", "dispTitle": "无题 · KONpiGG #146", "surface": "我在论坛上发布了一条关于\"老公的妹妹近期一直粘着老公，我该怎么办\"的帖子，然而收到的回复大多帮助不大，这令我感到更加烦躁。某一天我静下心来查看回复，当看到某一条评论的时候，我的眼睛猛然睁大，但一切都已经太晚了。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_42f2bc82bc2f", "srcNo": 1352, "title": "", "dispTitle": "无题 · boop-yyt #1352", "surface": "A man is killed on a train. He is found to have written \"elf\" on the floor in his own blood. (MB, from \"The Problem of the Locked Caboose,\" by Edward D. Hoch) How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_43434f23746f", "srcNo": 583, "title": "医学院惨案", "dispTitle": "医学院惨案", "surface": "在一间医学院里，ABC是舍友，A的成绩很好，是班里的班长。B的身体比较虚弱。有一天有人发现AB的尸体，C疯了，请推理出故事全貌。", "cats": ["恐怖", "本格"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_4382ddc93802", "srcNo": 204, "title": "免费的大餐", "dispTitle": "免费的大餐", "surface": "一个男人走进一家餐馆，大吃一顿，却没有支付任何费用。", "cats": ["其他"], "difficulty": 2, "src": "github:wangyafu/haiguitangmcp", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_438d924f003e", "srcNo": 603, "title": "停摆的时钟", "dispTitle": "停摆的时钟", "surface": "古董店老板死在店铺里，身旁是一座停摆的老爷钟，指针停在凌晨 3 点。警方调查后，锁定了唯一的嫌疑人 —— 钟表修理师。", "cats": ["悬疑", "犯罪"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_43902112a903", "srcNo": 537, "title": "病好啦", "dispTitle": "病好啦", "surface": "一个人坐火车去邻镇看病，看完之后病全好了。回来的路上火车经过一个隧道，这个人就跳车自杀了。", "cats": ["其他"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_43a5c3b68baf", "srcNo": 1054, "title": "许愿池的硬币", "dispTitle": "许愿池的硬币", "surface": "女孩往许愿池扔了一枚硬币，希望变成世界上最美的女人。第二天，她发现世界上所有女人都毁容了，只有她保持原样。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_43e1934bbc83", "srcNo": 1344, "title": "", "dispTitle": "无题 · boop-yyt #1344", "surface": "The music stopped. She died. Explain.", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_43ed2e64e457", "srcNo": 153, "title": "", "dispTitle": "无题 · KONpiGG #153", "surface": "我的邻居好像搬家了，走前也没和我说一声，新邻居家里有个小孩，老是用怪异的眼神看着我，还说着让我赶紧滚出这里的疯话，新邻居说这孩子有点心理问题我也就没放在心上。我家的狗最近总是不见踪影，可能是去和隔壁小孩玩了吧。最近邻居好像都知道我得重感冒了，都离我家远远的，过了几天，我被捕了", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_43f305644af3", "srcNo": 390, "title": "一躍而下", "dispTitle": "一躍而下", "surface": "​一位西裝革履的男子點了一杯波本威士忌。與旁人驚慌的神情不同，他神態自若地飲盡杯中酒，付帳並留下小費後，提著裝有 20 萬美金的公事包推門而出。\n\n從此，他徹底消失在世界上，再沒有人找到他的一絲蹤跡。", "cats": ["犯罪"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_440544dff8ed", "srcNo": 468, "title": "爱犬", "dispTitle": "爱犬", "surface": "独居女孩半夜听到水滴声，害怕地让爱犬舔手安慰自己，可第二天一醒来，发现狗死了。", "cats": ["其他"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_4431baef7c38", "srcNo": 1246, "title": "雪人证词", "dispTitle": "雪人证词", "surface": "大雪后，院子里多了一个雪人。主人回家看到后没夸孩子，反而立刻辞退了保姆。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:lancelily6362-png/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_44433fb07ea5", "srcNo": 985, "title": "海难后的海龟汤", "dispTitle": "海难后的海龟汤", "surface": "一名男子在餐厅点了一碗海龟汤，吃了几口后，他问店员这是不是真正的海龟肉。得到肯定答复后，他走出餐厅自杀了。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_444e2655a43c", "srcNo": 137, "title": "", "dispTitle": "无题 · KONpiGG #137", "surface": "毕业后和学校里的闺蜜一直未见，那天她来找我了，但随着啪的一声，我们阴阳相隔", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_44fd7423db0b", "srcNo": 817, "title": "哥哥怀孕了", "dispTitle": "哥哥怀孕了", "surface": "哥哥怀孕了，肚子里怀的是妈妈。", "cats": ["搞笑", "日常"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_450827ef0c0b", "srcNo": 225, "title": "自相残杀", "dispTitle": "自相残杀", "surface": "两兄弟在酒吧喝酒。他们开始争吵。其中一人掏枪射杀了另一人。不久后他自己也不幸身亡。", "cats": ["其他"], "difficulty": 2, "src": "github:wangyafu/haiguitangmcp", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_453bf5f75173", "srcNo": 376, "title": "催眠", "dispTitle": "催眠", "surface": "我是一名技术高超的催眠师，能让被催眠者分不清梦境与现实。周一，我在跟小珊玩笔仙游戏时，恶作剧地偷偷催眠了她，她说在我身后看到了幽灵，我笑着解除了她的催眠，她却说我身后的幽灵还在。周二，我身旁的小珊已经失去意识了，多亏了她我才逃过一劫，接下来，我将用催眠师的手段复仇。周三，我不会怪任何人，也不会杀了你，我只是需要你陪着我，哪怕以这种独特的方式。", "cats": ["恐怖"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_4565ce23dc96", "srcNo": 774, "title": "外送", "dispTitle": "外送", "surface": "「您好，您点的外送到了。」「好的，谢谢。」关上门后，她却惊恐万分。", "cats": ["悬疑", "惊悚", "都市"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_4580162c5451", "srcNo": 53, "title": "一双鞋", "dispTitle": "一双鞋", "surface": "男人醒来后只看到一双鞋，然后就自杀了，为什么?", "cats": ["反转", "悲剧"], "difficulty": 3, "src": "github:anchorAnc/astrbot_plugin_TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_458903b2c4d5", "srcNo": 992, "title": "水草", "dispTitle": "水草", "surface": "男子在河边钓鱼，钓起了一团杂乱的长发，他立刻跳下河淹死了自己。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_45abd76a73aa", "srcNo": 501, "title": "下课", "dispTitle": "下课", "surface": "今天又转学了 下课铃声响了 妈妈怎么还不来接我 天好黑我看不见路 我要被别人抓走了", "cats": ["本格"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_45c4ad822710", "srcNo": 5, "title": "迟到的外卖", "dispTitle": "迟到的外卖", "surface": "外卖迟到了两个小时，他却给了骑手五星好评，然后报了警。", "cats": ["其他"], "difficulty": 2, "src": "github:17hczmsn/turtle_soup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_4608770976e1", "srcNo": 952, "title": "Rokid Glasses 技术规格", "dispTitle": "Rokid Glasses 技术规格", "surface": "Rokid Glasses 技术规格", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "en", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_462dbcf05fff", "srcNo": 800, "title": "红灯停", "dispTitle": "红灯停", "surface": "一辆车在十字路口停了三个小时都没动，警察却没有开单。为什么？", "cats": ["悬疑", "惊悚", "推理", "都市"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_463522bd9599", "srcNo": 516, "title": "灯", "dispTitle": "灯", "surface": "半夜我被灯发出的亮光照醒，才发现灯还没关。于是我关了灯，盖上被子，很快又进入了梦乡。\n第二天我起床后透过窗外看见外面的景象，我就知道我完了。", "cats": ["反转", "本格"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_464b313662f2", "srcNo": 285, "title": "057 · 保险箱", "dispTitle": "057 · 保险箱", "surface": "一名男子在中途站上了火车，发现自己被一群陌生人包围，他逐一询问每个人的年龄，问完后回到座位上绝望痛哭。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_466969845d5e", "srcNo": 236, "title": "送信", "dispTitle": "送信", "surface": "邮递员以前每天都会往我家门缝里塞一封信。有一天起，他不再塞信了，我反而特别高兴。", "cats": ["反转", "日常"], "difficulty": 2, "src": "github:AZHi-xinxin/haiguitang-coop", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_46737dacf7e0", "srcNo": 299, "title": "071 · 尬蛋", "dispTitle": "071 · 尬蛋", "surface": "你是孤儿，收养人从不允许你走出家门一步，你每天在屋子里大叫、砸东西，但没有人在意你，没有人来救你。有一天他说要带你出门，到了那个地方后脸上被罩上了什么东西，你晕了过去……", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_46c22203e304", "srcNo": 177, "title": "", "dispTitle": "无题 · KONpiGG #177", "surface": "我第一次到访陌生的邻居家，看到他们惊恐的眼神，第二天他们就匆忙搬家了。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_471a18eff8f9", "srcNo": 507, "title": "此事古代亦有记载", "dispTitle": "此事古代亦有记载", "surface": "小王很希望他可以活下来，但是他死了。", "cats": ["职场"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_47301bec1ae9", "srcNo": 130, "title": "", "dispTitle": "无题 · KONpiGG #130", "surface": "一个男子刚出狱，下午就马上回到了监狱自首，并且要求判他死刑，为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_4737fc451428", "srcNo": 238, "title": "002 · 打嗝", "dispTitle": "002 · 打嗝", "surface": "小明去酒吧要一杯水喝，酒保扔给他一条蛇，小明说\"谢谢\"。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_474c41f3b6f8", "srcNo": 267, "title": "037 · 洗头", "dispTitle": "037 · 洗头", "surface": "晚上，我在寝室洗了个头，结果我和室友都死了。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_47c7605d45d5", "srcNo": 829, "title": "红眼睛", "dispTitle": "红眼睛", "surface": "小美租了一间新房，发现墙上有个小洞，每次透过洞往隔壁看，都只看到一片红色。直到有一天她问房东：「隔壁住的是谁？」房东的回答让她当场吓到搬家……为什么？", "cats": ["怪谈", "悬疑", "惊悚"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_47eb3ece0ac6", "srcNo": 577, "title": "新生儿", "dispTitle": "新生儿", "surface": "怀抱里的婴儿无声哭泣，“呜....呜额......”\n孩子的母亲笑着寒暄,纸条被递出——“感谢收养”。", "cats": ["悲剧", "犯罪", "脑洞"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_48818f1558f0", "srcNo": 1199, "title": "Jed 1.16", "dispTitle": "Jed 1.16", "surface": "Two dead people sit in their cars on a street. (AG)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_4899062ab425", "srcNo": 9, "title": "关灯的病房", "dispTitle": "关灯的病房", "surface": "护士每晚都会在同一时间关掉病房的灯。那天她没有关灯，病人却哭了。", "cats": ["其他"], "difficulty": 2, "src": "github:17hczmsn/turtle_soup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_48ba5fe90e26", "srcNo": 827, "title": "车子不见了", "dispTitle": "车子不见了", "surface": "阿豪每天上班都会把车停在公司的停车场。这天他发现车子不见了，但他最后没有选择报警，为什么？", "cats": ["搞笑", "日常"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_490411e18e06", "srcNo": 877, "title": "女明星", "dispTitle": "女明星", "surface": "有一天女明星在家里，坐在沙发上看电视，忽然发出了撕心裂肺的惨叫。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_490e5234aecd", "srcNo": 129, "title": "", "dispTitle": "无题 · KONpiGG #129", "surface": "弟弟刚出门，在屋子里的哥哥就听到了一声敲门声。哥哥往猫眼看了看，门外却空无一人。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_49176826caab", "srcNo": 1267, "title": "消失的咖啡", "dispTitle": "消失的咖啡", "surface": "一个人在办公室煮了一杯咖啡，放在桌上。他离开座位去接了个电话，回来时咖啡不见了。办公室里只有他和另外两个同事，但他们都声称没碰过咖啡。咖啡去哪了？", "cats": ["其他"], "difficulty": 2, "src": "github:ns5601/ai-haigui-game", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_4920eff6469b", "srcNo": 1076, "title": "死亡称重", "dispTitle": "死亡称重", "surface": "一个女人每天都要称体重。某天她称完体重后，露出了幸福的微笑，随即杀死了自己的丈夫。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_494b93d7406d", "srcNo": 1052, "title": "最后一份外卖", "dispTitle": "最后一份外卖", "surface": "外卖员敲开了一家住户的门，把餐递给了一个漂亮的女人。外卖员下楼后，立刻报警说：“那家人都死了。”", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_496541bcec78", "srcNo": 122, "title": "", "dispTitle": "无题 · KONpiGG #122", "surface": "有一天，一个男人A把B给杀了，警察逮捕他询问动机，他却回答道：一直都是黑的。试还原案件全貌。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_49be72215f9a", "srcNo": 410, "title": "我", "dispTitle": "我", "surface": "妈妈死了，我哭了\n爸爸死了，我笑了\n外婆死了，我疯了", "cats": ["悲剧", "本格"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_49c651e6beb1", "srcNo": 933, "title": "人生倍速演算", "dispTitle": "人生倍速演算", "surface": "街上有很多同样的寻人启事：张三 男 年龄：20岁 长相：穿着白色的保罗衫，上面印有月亮图案。身份：生物学博士 他曾发明出人类最伟大的科技——人生倍速演算 此科技可在微观世界中演算出你人生的所有结果，帮助你找到最想要的那种。张三的备忘录：1：生物是怎么出现的？2：他发现我了！！！或许会有危险，他必须消失！！！3：我发现他了！！！或许会有危险，我得提醒其他人！！！", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_4a0f40ddff23", "srcNo": 1331, "title": "", "dispTitle": "无题 · boop-yyt #1331", "surface": "Bruce wins the race, but he gets no trophy. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_4a24dffc8fb8", "srcNo": 367, "title": "邻居", "dispTitle": "邻居", "surface": "我家隔壁搬来了新邻居。\n他每天半夜三点准时敲墙三下。\n我忍了一周，终于愤怒的敲了回去。\n然后他再也没有敲过。", "cats": ["恐怖", "悬疑", "日常", "逻辑"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_4a68dd74f870", "srcNo": 704, "title": "蝴蝶结", "dispTitle": "蝴蝶结", "surface": "第一天小熊没了，第二天洋娃娃没了，第三天小木偶没了，最后全都不见了，只看到蝴蝶结在发光。我很伤心，因为蝴蝶结也不见了。", "cats": ["反转", "悬疑"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_4aa8059ec3e8", "srcNo": 728, "title": "诡异的画像", "dispTitle": "诡异的画像", "surface": "迷路女孩找到空屋休息，却因墙上画像“盯着她”而睡不着。清晨醒来发现异样，恐惧逃离。", "cats": ["怪谈", "悬疑", "惊悚"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_4ab66f954145", "srcNo": 900, "title": "口供", "dispTitle": "口供", "surface": "老陈醉酒后失足坠楼了，警方看了电梯监控后却认为是他杀。现有以下几名嫌疑人的口供，他们都有杀死老陈的理由，请判断真凶。27楼王先生：我当晚和老陈一起喝酒，把他送回家后又聊了一小会，然后我就回家了。28楼小张：我今晚才出差回来，我回家后再也没出来。30楼李小姐：我俩每晚都会通话，今天他信号不好所以去了阳台，聊一会他让我去找他，我拒绝后他沉默了，我听到他摔电话的声音，我只好去找他，电梯显示检修于是我走的楼梯，我敲门他不理我，看来他生我气了，我只好回家了。物业经理：我今天是夜班，我像往常一样巡楼，巡到4楼时发现电梯坏了，可我明明刚检查过。我维修好电梯后，却听到先后两户坠物点有人大喊：”死人了。“经调查：老陈家门口12小时内有4双不同的脚印；同老陈坠落的，还有阳台的安全护栏；李小姐经常去老陈家做客；消防通道无监控；电梯内监控：18:00老陈去了30楼，随后和王先生一起出了楼；18:30电梯显示检修中，但电梯内无人；18∶45物业经理取来工具箱检修电梯；22:00老陈和王先生从1楼来到29楼，王先生手里攥着东西；王先生从29楼回到27楼，兜里似乎有一个尖锐的物体；22:20小张从1楼来到28楼，手里拎着行李箱；22:25电梯显示检修中，但电梯内无人；22:40物业经理取来工具箱检修电梯；22:45经理好像听到什么声音，急忙跑出电梯；22:50李小姐从29楼回到30楼。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_4ac63fc0937b", "srcNo": 1099, "title": "盲人的遗言", "dispTitle": "盲人的遗言", "surface": "盲人在遗嘱中写道：把我的遗产分成两份，一份给正常人，一份给盲人。", "cats": ["其他"], "difficulty": 2, "src": "github:Tenzyoo/turtle_soup_game", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_4acf292f2375", "srcNo": 1272, "title": "", "dispTitle": "无题 · boop-yyt #1272", "surface": "A man is lying drowned in a dead forest. How could this be", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_4ae59ac6e539", "srcNo": 882, "title": "选择题", "dispTitle": "选择题", "surface": "他给她出了一道选择题，可是不管她选哪个答案都会是正确的。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_4b27b323a07a", "srcNo": 722, "title": "药水", "dispTitle": "药水", "surface": "婆婆给我一瓶药水，我失去了最爱的男生。", "cats": ["反转", "怪谈", "悬疑"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_4b5ba3eca22f", "srcNo": 1220, "title": "Jed 1.75", "dispTitle": "Jed 1.75", "surface": "A rope breaks. A bell rings. A man dies. (KH)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_4b9709c3fcdd", "srcNo": 864, "title": "送别", "dispTitle": "送别", "surface": "明天有一个重要的仪式，所以我睡的很早，可在午夜，我朦胧中好像听到一阵清脆的金属碰撞声音，又听到一前一后两个脚步声。早上醒来，我家门口围满了人，地上有五具尸体。查明真相后，我把他们送到了他们该去的地方。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_4bb30df46863", "srcNo": 731, "title": "电梯", "dispTitle": "电梯", "surface": "我走进电梯准备上学，随着电梯上升，我知道我再也无法去学校了。", "cats": ["悬疑", "惊悚", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_4bc000dd29e9", "srcNo": 1037, "title": "特殊的体检", "dispTitle": "特殊的体检", "surface": "医生对病人说：‘你的病已经好了。’病人听完却哭了。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_4be014c737a3", "srcNo": 1033, "title": "最后一片叶子", "dispTitle": "最后一片叶子", "surface": "病床上的女孩看着窗外的树叶，觉得当最后一片叶子掉落时，自己就会死去。最后一片叶子始终没掉，但女孩还是病好了，可她后来却发现了一个秘密。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_4c22be2eb092", "srcNo": 486, "title": "情人", "dispTitle": "情人", "surface": "有一个中年男人，他已经结了婚，有一个老婆、一个儿子、一个情人。情人总劝他离婚，男人都拒绝了。某天老男人回到家，发现儿子和情人都死了，墙上还有用血写的一句话……", "cats": ["本格", "犯罪", "猎奇"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_4c7896c76aca", "srcNo": 115, "title": "", "dispTitle": "无题 · KONpiGG #115", "surface": "我有一个姐姐，但我从未见过她，这天我终于见到了她的真面目，但我却后悔了。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_4c89d3c34349", "srcNo": 647, "title": "同名的哥哥", "dispTitle": "同名的哥哥", "surface": "两兄弟的出生记录上姓名完全相同，父母也相同，却从没有一天能被同时拍进一张合照。他们不是失散，也不是双胞胎。为什么？", "cats": ["亲情", "反转"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_4c96f8a5220b", "srcNo": 234, "title": "备用钥匙", "dispTitle": "备用钥匙", "surface": "我把钥匙忘在家里，想起家门口的脚垫下有一把备用钥匙，于是我用它开了门。第二天我发现备用钥匙也不见了，但我还是进了门。", "cats": ["日常", "逻辑"], "difficulty": 1, "src": "github:AZHi-xinxin/haiguitang-coop", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_4ca88c30332d", "srcNo": 630, "title": "娃娃的哭诉", "dispTitle": "娃娃的哭诉", "surface": "我的男朋友有暴力倾向，经常对我拳打脚踢，我想离开，却又无能为力。那天沉默寡言的邻居送了我一个娃娃。我知道她对娃娃动了手脚，但我也确认他爱上了我。因此我天天对着娃娃哭诉男友的暴行，连一杯蜂蜜水，一块巧克力蛋糕都是奢求。那天男友动手之后摔门而去。我不知道抱着哇哇哭诉了多久，睡了过去。恍惚中一个陌生的身影伴随着滴嗒声来到我的身边。但我睡得更安心了。", "cats": ["恐怖"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_4cea3fb48eaf", "srcNo": 1281, "title": "", "dispTitle": "无题 · boop-yyt #1281", "surface": "Beulah died in the Appalachians, while Craig died at sea. Everyone was much happier with Craig's death. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_4d4ae7aa267f", "srcNo": 77, "title": "", "dispTitle": "无题 · KONpiGG #77", "surface": "一个人住在公寓楼的12层，他每天早上坐电梯到一楼之后离开。到了晚上，如果有人在电梯里，或者是下雨天，那么这个人直接就坐电梯到自己的12楼的家。但如果电梯里没有人而且那天不下雨的话，他就坐电梯去10楼，并且走2层楼梯回家。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_4d564203ee45", "srcNo": 294, "title": "066 · 妈妈的秘密", "dispTitle": "066 · 妈妈的秘密", "surface": "我在妈妈的抽屉里发现了一大叠男人的照片，问妈妈是谁，她笑着说\"是你爸爸\"，我却一张都不认识。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_4d80ceead607", "srcNo": 1132, "title": "老农", "dispTitle": "老农", "surface": "万历年间，乡下一老农，其女貌美，为村霸所疯寺 屡来相扰。未几，女竟失踪。老农揣\n女或遇不测，遂往衙诉之。不意至衙，殉命艳。", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_4db698fff78a", "srcNo": 748, "title": "陌生人", "dispTitle": "陌生人", "surface": "陌生人的鼓励让我有了收获，可当我再次见到他时，我却惊恐报警。为什么？", "cats": ["反转", "悬疑", "惊悚", "犯罪"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_4dfdc7c625a1", "srcNo": 337, "title": "饺子", "dispTitle": "饺子", "surface": "天气越来越冷了，有妈妈给我们织围巾啦。姐姐戴上围巾更美了，像一幅画，爸爸带上围巾高兴手舞足蹈，妈妈说冬至不吃饺子会冻掉耳朵，我最喜欢妈妈包的饺子啦，饺子又香又脆，真好吃。", "cats": ["恐怖", "猎奇"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_4e15039758dc", "srcNo": 666, "title": "无法逮捕的枪手", "dispTitle": "无法逮捕的枪手", "surface": "警察清楚看见男人故意开枪杀死兄弟，旁边还有多名证人。但警察看完后并没有去逮捕他，也不是因为他无罪或逃跑了。为什么？", "cats": ["反转", "犯罪"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_4e72ee38000c", "srcNo": 1040, "title": "雨中的伞", "dispTitle": "雨中的伞", "surface": "下大雨了，三个人共用一把小伞，但他们的衣服都没有湿。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_4e73fee0c82a", "srcNo": 822, "title": "关灯的医生", "dispTitle": "关灯的医生", "surface": "一名医生检查病人时，常把检查室的灯全部关掉。病人没有反对，检查也照常进行。为什么？", "cats": ["悬疑", "推理", "日常", "职场"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_4ebec8899dc6", "srcNo": 380, "title": "偶遇", "dispTitle": "偶遇", "surface": "深夜，她加班后回家，在昏暗的楼道里撞见一个行踪诡异、衣角沾着血迹的男子。擦肩而过时，他似乎碰到了她的挎包。她吓得快步躲开，整晚心绪不宁。\n第二天，有人上门出示证件，询问是否见过照片上的男子。她看着那张脸，下意识地摇了摇头。一周后，社区贴出了“重大案情协查通报”。当晚，黑暗中手机屏幕亮起，一条来自陌生号码的信息映入眼帘：“快走。”\n她死了。", "cats": ["悬疑", "犯罪", "逻辑"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_4ec8b318f78c", "srcNo": 1353, "title": "", "dispTitle": "无题 · boop-yyt #1353", "surface": "A man lies dead next to a feather. How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_4f76b82838fb", "srcNo": 1216, "title": "Jed 1.59", "dispTitle": "Jed 1.59", "surface": "Music stops and a woman dies. (DVS)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_4fa7348b73fc", "srcNo": 1327, "title": "", "dispTitle": "无题 · boop-yyt #1327", "surface": "A black leader dies in Africa. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_50b3190ece10", "srcNo": 780, "title": "看飞机", "dispTitle": "看飞机", "surface": "「看，有飞机耶！」我抱着儿子从新家的阳台往外看，儿子被我逗得一直笑，转身对我说了一句话，我脸瞬间惨白。", "cats": ["亲情", "反转", "悬疑", "惊悚"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_512da327a184", "srcNo": 100, "title": "", "dispTitle": "无题 · KONpiGG #100", "surface": "花园告示：夜深，白花点头。日出，红花落泪。日落，黑花枯萎。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_517cf5c62561", "srcNo": 487, "title": "普通安保", "dispTitle": "普通安保", "surface": "你是一名安保人员，一天爆发了一场前所未有的事件。\n你暗自抱怨为了年终奖和下班怎么这么难。\n在此之后，你被提干了，但你发现你的新办公室的各个角落都有摄像头看着你。", "cats": ["反转", "怪谈", "搞笑", "脑洞"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_51c2173c713f", "srcNo": 188, "title": "", "dispTitle": "无题 · KONpiGG #188", "surface": "一个人在电影院看电影，电影播放到一半时，他突然发现坐在他旁边的人行为十分怪异。那个人一直低着头，身体不停地颤抖，嘴里还念念有词。他好奇地凑近去听，结果听到了一句让他毛骨悚然的话，请问那个人说了什么?", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_52111e999adf", "srcNo": 1062, "title": "唯一的降落伞", "dispTitle": "唯一的降落伞", "surface": "飞机即将坠毁，机舱内只有两个好朋友和一个降落伞。一番争夺后，胜出的那个人背着伞包跳下，落地后却立刻自杀了。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_52558175aabc", "srcNo": 498, "title": "奔赴——作者：十二月", "dispTitle": "奔赴——作者：十二月", "surface": "望向山的那头，新生的枝丫。\n红色隔断生死，迷失了道路。\n闪烁灯光映照，扑灭心之向。\n拿着手里的信，奔向了远方。\n跨过崇山峻岭，为见你一面。\n因为你永远是我的骄傲。", "cats": ["悲剧", "本格"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_52b79b7f332d", "srcNo": 1326, "title": "", "dispTitle": "无题 · boop-yyt #1326", "surface": "It's the year 860 A.D., at Camelot. Two priests are sitting in the castle's chapel. The queen attacks the king. The two priests rise, shake hands, and leave the room. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_52bd7765b224", "srcNo": 1010, "title": "猫的报恩", "dispTitle": "猫的报恩", "surface": "老奶奶死在家里，猫一直守在她身边。几天后警察发现，猫依然精神抖擞，但老奶奶的脸不见了。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_5351805ac486", "srcNo": 1350, "title": "", "dispTitle": "无题 · boop-yyt #1350", "surface": "A car without a driver moves; a man dies. How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_535b89c32407", "srcNo": 171, "title": "", "dispTitle": "无题 · KONpiGG #171", "surface": "魔镜魔镜，谁是世界上最美的人？一个，两个，三个，嘶……我终于明白了。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_53d8098e6be8", "srcNo": 841, "title": "男孩的承诺", "dispTitle": "男孩的承诺", "surface": "女孩和男孩提了一个条件，只要男孩做到就做他的女朋友，后来男孩做到了，女孩却疯了。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_540e78acf678", "srcNo": 784, "title": "喝水", "dispTitle": "喝水", "surface": "我和妻子喝下同一杯水，妻子惨死，我却安然无恙。", "cats": ["反转", "推理", "犯罪"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_541f480630b6", "srcNo": 3, "title": "深夜电梯", "dispTitle": "深夜电梯", "surface": "深夜，他一个人进了电梯。电梯门打开时，外面空无一人，他却立刻按下了报警按钮。", "cats": ["其他"], "difficulty": 2, "src": "github:17hczmsn/turtle_soup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_54226f1ef9a9", "srcNo": 649, "title": "停下以后", "dispTitle": "停下以后", "surface": "男人坐上一列沿轨道行驶的车。车越往高处走，他越紧张；速度最快时脸色发白。车最终停回出发处，他虽然恶心，却终于放松了，也不觉得白坐一趟。为什么？", "cats": ["搞笑"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_5454d966fa86", "srcNo": 256, "title": "023 · 对赌", "dispTitle": "023 · 对赌", "surface": "两个死人，一把枪，一副牌。发生了什么事？", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_5467cce29e88", "srcNo": 384, "title": "不被理会的小王", "dispTitle": "不被理会的小王", "surface": "“为什么那些孩子不喜欢我了？”一觉醒来后小王知道了答案，于是小王报了警。", "cats": ["反转", "脑洞"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_549137cff6f5", "srcNo": 1287, "title": "", "dispTitle": "无题 · boop-yyt #1287", "surface": "A car without a driver moves; a man dies. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_54993a266437", "srcNo": 1003, "title": "完美全家福", "dispTitle": "完美全家福", "surface": "摄影师给一家五口拍全家福，拍完后摄影师报了警，而全家人还在对着镜头微笑。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_54d21fd3caf6", "srcNo": 428, "title": "绿灯停 红灯行", "dispTitle": "绿灯停 红灯行", "surface": "绿灯停 红灯行\n“红灯，红灯“”\n我死在下一个路口。", "cats": ["其他"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_5502c4432dd3", "srcNo": 1383, "title": "", "dispTitle": "无题 · boop-yyt #1383", "surface": "A woman opens an envelope and dyes. How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_550641c0709c", "srcNo": 466, "title": "注意事项", "dispTitle": "注意事项", "surface": "小明做了一个手术，术后医生告诉他注意事项。小明没有注意听，转头跟朋友去吃饭了，吃到一半小明的朋友一脸惊恐地看着小明，小明意识到发生什么的时候浑身冷汗...", "cats": ["反转", "恐怖", "脑洞"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_550f93375ad7", "srcNo": 258, "title": "025 · 宇航员的镜子", "dispTitle": "025 · 宇航员的镜子", "surface": "我从梦中醒来，看了一眼镜子中的时钟，继续躺下，但是却永远地睡了过去。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_556a1cb0eb4b", "srcNo": 438, "title": "水猴子", "dispTitle": "水猴子", "surface": "在一个闭塞的渔村，村民从不允许孩子在傍晚靠近河边，但每年七夕，他们都会带孩子去河边放纸灯。有一天，一个外来孩子偷偷去河边玩，回来后高烧不止，嘴里一直念叨“红衣服姐姐”。几天后，孩子失踪了，村民在河边找到他的鞋子，旁边有一盏破旧的红色纸灯。", "cats": ["怪谈", "恐怖"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_55e2acae340a", "srcNo": 968, "title": "", "dispTitle": "无题 · yefeng7531 #968", "surface": "是否本格/变格、人数、时间（现代/古代/跨度）、地点、是否有人死亡/死法、称谓与物品重指、动机类型、关键物品。\n- 每条回答只能是\"是 / 否 / 与此无关\"，且彼此之间、与汤底之间零矛盾——玩家拿这份问答表进行到底，必须能推出汤底。\n- 关键线索点 3~5 个，合起来覆盖关键新信息的全部必要组成部分。\n- 3 级提示递进有效：第 1 级给方向不给事实，第 2 级缩小范围，第 3 级点出关键新信息的一半，都不直接公布汤底。", "cats": ["其他"], "difficulty": 2, "src": "github:yefeng7531/turtle-soup-creator", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_55f3014e4f50", "srcNo": 185, "title": "", "dispTitle": "无题 · KONpiGG #185", "surface": "A：就今天吧 B：今天不行... A：没事的，放心 B：现在真不行，以后才可以！", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_56256cb7565c", "srcNo": 1065, "title": "母爱的重量", "dispTitle": "母爱的重量", "surface": "母亲带着婴儿在山洞躲避劫匪。婴儿突然大哭，母亲死死捂住婴儿的嘴。劫匪走后，母亲松开手，婴儿没死，母亲却大哭起来。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_562c2934a61b", "srcNo": 615, "title": "地域战士", "dispTitle": "地域战士", "surface": "我是地域战士天天喜欢拿自己家乡和其他地方比较，但从来没有人骂我，反而很支持我，甚至喜欢重复我说过的话", "cats": ["搞笑", "本格", "脑洞"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_567d6cda1e1c", "srcNo": 1292, "title": "", "dispTitle": "无题 · boop-yyt #1292", "surface": "He couldn't find a chair, so he died. Why?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_56bc27c7e7be", "srcNo": 1112, "title": "最完美的作品", "dispTitle": "最完美的作品", "surface": "我是一个落魄画家，妻子为了我的事业陪我去乡下写生。山路颠艇崎嵌，车子突然坏了。\n这时路过一个牵马的牧民，将我们送到村子里借宿。晚上妻子说很热很渴想去喝水，却一直没\n有回来。我很担心出去找妻子，看到妻子站在几口井中间，目光呆滞地跳进了其中一口井。我\n既害怕又兴奋，赶紧把这一幕画下来。", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_56f7b05ed07b", "srcNo": 364, "title": "完美的听众", "dispTitle": "完美的听众", "surface": "一个脱口秀演员在小剧场演出。\n台下只有三个观众。\n演员努力讲了二十分钟，观众全程没有任何反应，他们不笑，不鼓掌，不说话，甚至表情都没有变化。\n演员很沮丧，但观众却笑了，笑得令人发毛。\n第二天，演员被警察逮捕了。", "cats": ["悲剧", "犯罪"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_5795f8d99e17", "srcNo": 614, "title": "金色的窒息", "dispTitle": "金色的窒息", "surface": "我被那根冰冷的银色长矛无情地贯穿了头颅，却连惨叫的权力都被剥夺。\n它拖拽着我，一次次疯狂地扎入那片茫茫的白色云海，又一次次从窒息的深渊中挣扎破出。\n每一次穿梭，我原本修长的金色身躯就被肢解一部分，永远地留在了云层之下。\n这种晕眩的酷刑不知持续了多久，直到我感觉身体已被彻底掏空，只剩最后一口气。\n在意识消散前，我听见那银色长矛发出了满足的颤鸣——\n我的尸骸，终于填满了那位至高无上者空洞的眼眶。", "cats": ["其他"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_57ae1306e87a", "srcNo": 1301, "title": "", "dispTitle": "无题 · boop-yyt #1301", "surface": "Charlie died when the music stopped. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_57c970bf7a82", "srcNo": 1367, "title": "", "dispTitle": "无题 · boop-yyt #1367", "surface": "The music stops and the man dies. How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_57e6a25c9e1f", "srcNo": 1077, "title": "隧道里的回声", "dispTitle": "隧道里的回声", "surface": "男子在漫长的隧道里行走，他每走一步，就听到身后传来两声脚步声。他加快速度跑起来，身后的声音却消失了。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_57e7c1800d44", "srcNo": 551, "title": "深渊情书", "dispTitle": "深渊情书", "surface": "我对着镜头解开了衣扣，强忍着恶心，把那张裸照发给了那个男人。\n他贪婪地以为这是爱情的投名状，殊不知这是我耗尽二十七年才织好的索命网。\n我像个最有耐心的猎手，以身饲虎，只为从他嘴里撬出那个关于“失踪”的真相。\n但我猜中了开头，却没猜中结局。\n地下的父亲若是能开口，定会满眼悲悯地叹息：\n傻女儿，别找了。你要找的答案不在天涯海角，而在我当年一铲又一铲填平的泥土里。", "cats": ["亲情", "悲剧", "推理", "犯罪"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_5812f6b2fe96", "srcNo": 915, "title": "七宗罪", "dispTitle": "七宗罪", "surface": "星期一 妈妈瞎了，但还是在照顾怀孕的我 我看到我的肚皮上被她画了奇怪的纹路。星期二 我总觉得身体有些僵硬，很不舒服。妈妈好像在找什么，我听她说。 ”眼睛会在哪呢？“ 晚上，又听到她兴奋的说。 ”找到了！“ 星期三 这是我的第四篇日记，我最近突然变得很能吃。老太太的脚还不如砍掉，每天就知道躺在沙发上看电视。星期四 爸爸想要男孩，但家里只有两个女儿。我还好，妹妹却是一头猪，每天吃吃吃。妈妈无法生育，家里每个人都欺负她 而她只知道把自己关在屋子里看一些巫术。爸爸自然要想办法。星期五 爸爸出轨了一个他认为漂亮的女人。但我知道她不爱爸爸。她贪婪的手只会不断的拿取我们家的钱财。妈妈一定很恨她，因为她怀孕了。星期六 乡下的老头子想要爸爸的钱，寄生在我们家已经够恶心了。我没忍住羞辱了他，他愤怒的掐住我的脖颈。等我再醒来时妈妈对我说：”爸爸带全家去旅游了“ 我闻到房间里有血腥味，虽然很疑惑，但没敢说话。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_581cf22f1425", "srcNo": 192, "title": "", "dispTitle": "无题 · KONpiGG #192", "surface": "一位画家在自己的工作室里创作，突然他听到门外传来一阵敲门声。他打开门，发现门口站着一个全身湿漉漉的女人，女人请求画家让她进屋躲雨。画家心生怜悯，便让女人进来了。女人在屋里四处打量，对画家的画作表现出浓厚的兴趣。突然，女人指着一幅画，问画家画中的场景在哪里。画家回答后，女人的脸色变得十分难看，随后画家也遭遇了可怕的事情，请问发生了什么?", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_5891f567cfaf", "srcNo": 1154, "title": "阿吉的画", "dispTitle": "阿吉的画", "surface": "4月 9 日，我在一个小乡村度假，村子里有一个叫阿吉的人，他很爱作画，他画了一幅\n沙滩上的木梳，很有艺术成分。但村民们不这么认为，大家都说他精神有问题。 4月 10 日，\n今天在公路上捡到一只小猫，我很喜欢就带回了村，路上遇到了阿吉二今天他画了一张毛毯。\n4月11 日，阿吉今天画了几串葡萄，画得太棒了，另外一位游客也专阿吉画得很好! 村里人\n对他的偏见太大了。4月 12 日，我要走了，阿吉送了我幅画，画的是两个山洞，真完美，我\n笑着对他说:“你以后一定能成为一个伟大的画家", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_58c1a100e135", "srcNo": 634, "title": "囚", "dispTitle": "囚", "surface": "我将无数生灵囿于我的领地，每段羁留至少横跨九载春秋。\n每当纷杂的嘶喊在聚涌，我便以钟鸣之声，将他们躁动的声浪逐一镇回喉底。\n尽管每隔一段时间，我也会容许那些困顿的生灵暂得游离于外，呼吸片刻自由，但是他们中的一些还是对我切齿痛恨，屡次密谋将我永世连根倾覆。\n尽管数载之前的往昔，我常以切肤之痛来让他们铭刻铁规，如今那般酷烈的训诫已日渐稀微，但他们还是对我不甚喜爱，可我确是一心为他们谋取长远之福,而被我囚禁的生灵不喜欢我,挣脱我的生灵竟会对我有些许不舍,想必他们中的一些也会偶尔回头，看到我固守于此的、被岁月磨损的轮廓，并终于可以读懂我,于此诞生一些后悔之情吧.", "cats": ["本格", "脑洞"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_5921e697c3de", "srcNo": 757, "title": "圣诞节礼物", "dispTitle": "圣诞节礼物", "surface": "圣诞节那天，男人挨家挨户送礼物，送到一户人家后，他心想：明年就不用再送礼物了。", "cats": ["恐怖", "悬疑", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_5924ff3fa67e", "srcNo": 52, "title": "不要相信一号", "dispTitle": "不要相信一号", "surface": "我睡醒了，我又忘记了一切，手里捏着的纸条上写着几个字:不要相信1号。一个男人走近我的床边，\"先生早上好，2号很高兴为您服务。\"我问他:\"1号呢?\"，他指了指地上，那里躺着个一动不动的男人，像死了一般。", "cats": ["悬疑"], "difficulty": 3, "src": "github:anchorAnc/astrbot_plugin_TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_5940720521b9", "srcNo": 181, "title": "", "dispTitle": "无题 · KONpiGG #181", "surface": "男人拿着结婚证，他笑了，女友哭了", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_59a225166f7b", "srcNo": 397, "title": "金屋复壁", "dispTitle": "金屋复壁", "surface": "圣上待我不薄，特赐居这宫中唯一的‘玲珑暖阁’。\n工部尚书夸耀此阁乃巧夺天工之作：寝殿悬于中央，四面墙壁皆用双层金丝楠木加厚，中间填以西域贡棉，既能隔绝冬日苦寒，又能挡住外院宫人的嘈杂，许我一方清净天地。\n这确实是无上的恩宠，夜里落针可闻，连更漏声都听不见。\n只是最近我总睡不安稳。明明门窗紧闭，炭火未生，每当我就寝灭烛后，床头那幅《仕女图》的眼珠位置，总会透进一丝极微弱的凉风，吹得我后颈发痒。\n昨夜我惊醒时，甚至在死寂的墙壁深处，听到了一声极力压抑的咳嗽。", "cats": ["悬疑", "本格"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_59bdeb4b044e", "srcNo": 831, "title": "火车", "dispTitle": "火车", "surface": "一名男子搭火车到邻近的城镇去看病，当天是最后的疗程，男子已经痊愈。当他满心欢喜地搭上火车要回家时，男子却在途中跳车自杀，请问是为什么？", "cats": ["搞笑", "日常"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_59bf8310c7de", "srcNo": 173, "title": "", "dispTitle": "无题 · KONpiGG #173", "surface": "有一名男人出车祸住院了。住院期间他在房间里不能出来。幸运的是，男人每天都能享受到隔壁传来的舞曲声。出院那天，男人和护士聊天，然后十分惊恐。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_59f2ea30cee7", "srcNo": 219, "title": "治病", "dispTitle": "治病", "surface": "他决定给经济拮据的母亲治病，却被母亲强硬地拒绝了。", "cats": ["其他"], "difficulty": 2, "src": "github:wangyafu/haiguitangmcp", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_5a05b2e5001a", "srcNo": 741, "title": "网友", "dispTitle": "网友", "surface": "小美和网友小明约好见面，三分钟后小美却大声尖叫。", "cats": ["悬疑", "惊悚", "犯罪", "都市"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_5a3b5db19c22", "srcNo": 142, "title": "", "dispTitle": "无题 · KONpiGG #142", "surface": "\"他就是个骗子...是个变态，偷窥狂.. .我求求你们赶快把他抓起来。\"\"她怎么能这么说呢，我们可是夫妻啊。\"\"我们确实是夫妻...可是现在想想，我真是太蠢了，我真是瞎了眼。\"\"她疯了吗?怎么什么都跟你们说。我们明明说好不跟别人说的\"\"这一切都是他演出来的,他监视我,他在见我之前就已经一直在关注我...他还串通了我的同事来骗我!求求你们, 一定要揪出他这个变态，我继续和他生活下去我会有生命危险的!!\"\"她怎么会这么说?!不可能,让我见她!你们干什么?不，不可能!这一切都是误会,你们听我解释!\"\"你好,陈律师。请问我提供的证据足够证明了吗?哦好的谢谢。那我现在可以解除和他的夫妻关系了吗?啊,真是太感谢您了,谢谢。对了，您下班以后有空吗,可以赏脸一起吃顿饭吗?\"", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_5a4734fb2312", "srcNo": 1338, "title": "", "dispTitle": "无题 · boop-yyt #1338", "surface": "A woman walked up to a man behind a counter and handed him a book. He looked at it and said, That wɽ be four dollars/' She paid the man and then walked out without the book. He saw her leave without it but did not call her back. How come?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_5a6993b42523", "srcNo": 99, "title": "", "dispTitle": "无题 · KONpiGG #99", "surface": "我是贝尔公主，父王给我准备了盛大的婚礼，可婚礼上我却看不清王子的脸...", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_5a74db2ed992", "srcNo": 993, "title": "电梯里的男人", "dispTitle": "电梯里的男人", "surface": "一个住在30楼的男人，每天上班坐电梯直达1楼。下班如果天晴就坐到20楼再爬10层；如果下雨就直接坐到30楼。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_5aa4c1e97bbe", "srcNo": 514, "title": "最后一页", "dispTitle": "最后一页", "surface": "林同学成绩优异但性格内向，常被同寝同学嘲笑。期末我借他笔记，翻到最后一页，我立刻汇报给导师并报警。\n导师和警察来后，却对我说“太晚了。", "cats": ["悲剧", "本格", "犯罪"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_5b033f2334ad", "srcNo": 1394, "title": "", "dispTitle": "无题 · boop-yyt #1394", "surface": "A man wakes up in a dark room. He switches on the light.", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_5b31bb7c711b", "srcNo": 1318, "title": "", "dispTitle": "无题 · boop-yyt #1318", "surface": "A pile of sawdust, no net, a man dies. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_5c55d6033851", "srcNo": 564, "title": "遗书和照片", "dispTitle": "遗书和照片", "surface": "警方发现了三张遗书和三张照片：\n我肯定努力\n我很少留念\n我只能毁灭", "cats": ["恐怖", "悬疑", "本格", "逻辑"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_5cac23e1984f", "srcNo": 183, "title": "", "dispTitle": "无题 · KONpiGG #183", "surface": "小明打开瓶盖，里面写着再来一瓶，他崩溃的哭了", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_5cbad410d621", "srcNo": 986, "title": "半根火柴", "dispTitle": "半根火柴", "surface": "一名男子死在沙漠中，全身赤裸，手里攥着半根火柴。周围没有任何足迹。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_5cf13a9bc1e0", "srcNo": 683, "title": "迟来的眼泪", "dispTitle": "迟来的眼泪", "surface": "跳远比赛结束，运动员看见自己排在第一，兴奋地庆祝。几分钟后，队友把成绩换了一种写法，他却激动得哭了。排名和成绩都没有改变。为什么？", "cats": ["温情"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_5cf4e2aca1de", "srcNo": 504, "title": "电梯", "dispTitle": "电梯", "surface": "男人死在电梯轿厢里，脖子上缠着一条围巾，围巾深勒入肉。电梯外监控显示只有他一人进入电梯，电梯中途未停靠，到一楼时他已死亡。", "cats": ["本格", "逻辑"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_5d48e158ad00", "srcNo": 1249, "title": "空着的鸟笼", "dispTitle": "空着的鸟笼", "surface": "老人提着一个空鸟笼去公园散步，邻居反而夸他终于想通了。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:lancelily6362-png/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_5dec5e37f329", "srcNo": 187, "title": "", "dispTitle": "无题 · KONpiGG #187", "surface": "一个人在医院工作，有一天晚上他值班。半夜的时候，他听到病房里传来一阵奇怪的声音，像是有人在低声哭泣。他拿着手电筒去病房查看，发现病房里并没有人哭泣，但是当他准备离开时，却看到了让他头皮发麻的一幕。请问他看到了什么?", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_5e545469acbd", "srcNo": 542, "title": "复活", "dispTitle": "复活", "surface": "女孩的宠物死了，她很伤心，抱着宠物希望我救活他，我安慰女孩说死了是不能复活的。女孩却说：“阿姨，你骗人，你不就是复活的吗”，我吃惊的捂住了嘴巴。", "cats": ["本格", "犯罪"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_5e73ca9b9889", "srcNo": 168, "title": "", "dispTitle": "无题 · KONpiGG #168", "surface": "他站了起来，我却愣在原地。屏幕那头，是熟悉的你。叮咚，叮咚，铃声响起。我流下眼泪，已无法逃离。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_5ebece005199", "srcNo": 526, "title": "村子里的怪叫声", "dispTitle": "村子里的怪叫声", "surface": "某个村子每家每户过了0点必须关灯，于此同时半夜三更都会传来怪叫声，虽然把全村人都吵醒都没有人出去看。真相是什么？", "cats": ["恐怖", "本格"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_5f39ca52f6ca", "srcNo": 552, "title": "自我欺骗", "dispTitle": "自我欺骗", "surface": "我正坐在审讯室陈述我昨天晚上所发现的事：\"凌晨三点，我独自在家赶稿，突然发现客厅地板有一滩新鲜血迹，呈拖拽状延伸至卧室门口。打开卧室灯后，一切如常，唯独衣柜门虚掩着一条缝。我颤抖着拉开柜门……\"", "cats": ["恐怖", "悬疑", "犯罪"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_5f49db9b884c", "srcNo": 369, "title": "黑暗的条件反射", "dispTitle": "黑暗的条件反射", "surface": "深夜，男人在家中书房急得满头大汗。明天就是截稿日，但电脑上的文档还是一片空白。他烦躁地抓了抓头发，几根发丝落在深色的书桌上。\n\n他去厨房冲了杯咖啡。等他端着杯子回到书房门口时，却发现书房里的灯不知何时灭了，里面一片漆黑。\n\n男人愣在门口，手中的咖啡杯掉落在地，摔得粉碎。他没有去查看开关，而是立刻转身，头也不回地逃出了家门。", "cats": ["悬疑", "本格"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_5f9ff11225b1", "srcNo": 1097, "title": "窗边的女人", "dispTitle": "窗边的女人", "surface": "一个女人每天都在窗边看外面，有一天她突然尖叫着跑开了。", "cats": ["其他"], "difficulty": 2, "src": "github:Tenzyoo/turtle_soup_game", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_60150226cedd", "srcNo": 14, "title": "迟到的钟声", "dispTitle": "迟到的钟声", "surface": "教堂钟声晚了十分钟，镇上的人却都松了一口气。", "cats": ["其他"], "difficulty": 1, "src": "github:17hczmsn/turtle_soup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_601ca3b5b289", "srcNo": 954, "title": "Python FastAPI 框架", "dispTitle": "Python FastAPI 框架", "surface": "Python FastAPI 框架", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "en", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_6039bef49d95", "srcNo": 623, "title": "出租房", "dispTitle": "出租房", "surface": "我搬进了一个新房子，房间里经常类似老鼠爬的声音，但毕竟便宜，我也睡得很香，没多久房东就谈了一个女朋友，老鼠的声音好像也没了，但突然的安静，却让我不能安心入睡…", "cats": ["恐怖"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_6048cff22007", "srcNo": 1369, "title": "", "dispTitle": "无题 · boop-yyt #1369", "surface": "A bell rings. A man dies. A bell rings. How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_60a6b5cee2aa", "srcNo": 885, "title": "杀狼人", "dispTitle": "杀狼人", "surface": "第一日，一座荒岛上，法官说：”你们五个人之中有一个邪恶的狼人，请找到他。“五个人分别是我，丈夫，儿子，猎人，女巫。我的身份是村民。猎人和大家说：”我的能力是布置陷阱，希望能捉到狼人，至于其他人要是踩到陷阱就算你们倒霉了。“第一日夜，我没敢睡死，果然丈夫在半夜掐住了我的脖子，他居然是狼人！就在我以为我死定的时候，儿子跳出来救了我，儿子告诉我他的身份是守卫，我和儿子合力杀死了他。丈夫死后，他的身后居然出现了狼的尾巴。第二日，法官说：”今天他死了，他是一个狼化的村民但不是狼人。“我们看着丈夫的尸体，他已经被啃食的面目全非了，我很疑惑，他居然不是狼人！而且他是被谁啃食了？第二日夜，我梦见我在一个深坑里，坑里有一个白色的梯子，我顺着梯子爬了出来，感觉自己身上很舒服像是被救赎了。第三日，今天他死了，我看着儿子的尸体不可置信的哭了起来，他的身体看起来软趴趴的，但没有被吃的痕迹。女巫指着我说：”我有一瓶药和一瓶毒，她昨晚要死了，是我救了她。“是女巫救了我吗？我想起昨晚身上很舒服，应该就是她在救我了。第三日夜，我居然看到女巫毒了猎人，难道她以为猎人是狼人吗！就在我准备去询问情况时，她突然狰狞的撕咬起了猎人，她才是狼人！我吓跑了！第四日，今天他死了，面前是猎人被咬碎的尸体，法官对我和女巫说：”走吧。“女巫疑惑：”不找狼人了吗？“法官似笑非笑的看了我一眼：”已经找到了。“", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_60b7bf249d99", "srcNo": 598, "title": "敲门声", "dispTitle": "敲门声", "surface": "小梅和老公小王驾车旅游，深夜在一条山路车抛锚了，小王说要走到前面的镇子里去找一位修理工，小梅先留在车里。在车内看不到外面的情况下，夫妻俩约定小王回来时敲三下车门小梅就开门，过了不久，小梅听到了很多次敲门声但从来都不是三下。请推理出故事全貌。", "cats": ["恐怖", "本格"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_60d93f2c5baf", "srcNo": 385, "title": "盲人钢琴师", "dispTitle": "盲人钢琴师", "surface": "一个天才的盲人独臂钢琴师为他的朋友们弹奏了一首曲子后，就把他的朋友们都杀死了，这是怎么回事？", "cats": ["恐怖", "悲剧"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_610d3d1574d7", "srcNo": 195, "title": "", "dispTitle": "无题 · KONpiGG #195", "surface": "因为你，她走了。可你还是和以前一样，所以你要去找她了", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_614ee93f352b", "srcNo": 939, "title": "444寝室", "dispTitle": "444寝室", "surface": "+汤底 学校住宿的同学们都知道三条规则不能触犯：1. .23:00之后千万不要离开寝室（因为23：00寝室封寝了）2. 不要去厕所的第4隔间（这是最后一个隔间，用来存放打扫用品）3. 不要听444寝室的录音机 我刚好就在444寝室，我好奇地打开了收音机。”我是什么佛“（这是倒放后的一句话，原话是：倒放的是狗）什么嘛，只是一段很正常的录音，于是我就去睡觉了。（我并没有意识到这是一句倒放的语音）", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_61b54a070bab", "srcNo": 641, "title": "这天早晨，妮可醒来闻到很浓的烟味", "dispTitle": "这天早晨，妮可醒来闻到很浓的烟味", "surface": "这天早晨，妮可醒来闻到很浓的烟味，像是烧焦起火的味道，她深知自己陷入危险之中，但她却从没试图离开。\n\n 妮可不残疾，她可以正常行走。\n\n 她只是坐了起来，叹了一口气。\n\n 你猜猜这是怎么一回事呢？", "cats": ["其他"], "difficulty": 2, "src": "haiguitang.cn/海龟浓汤", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_61c3a9a000f0", "srcNo": 602, "title": "脚趾呢", "dispTitle": "脚趾呢", "surface": "巴黎闹市中新开了一家理发店，来剪发的人络绎不绝。几个月后，闹市中的鸽子的脚趾都不见了", "cats": ["其他"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_61dd89c55e96", "srcNo": 973, "title": "", "dispTitle": "无题 · 906491213 #973", "surface": "状态迁移（如适用）：[ ]通过 [ ]修复 →", "cats": ["其他"], "difficulty": 2, "src": "github:906491213/writing-turtle-soup", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_623becf85bca", "srcNo": 207, "title": "延迟死亡", "dispTitle": "延迟死亡", "surface": "海伦从未想到，她乘坐飞机旅行的决定会挽救她的生命。", "cats": ["其他"], "difficulty": 2, "src": "github:wangyafu/haiguitangmcp", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_623e5bb16698", "srcNo": 433, "title": "温馨小家", "dispTitle": "温馨小家", "surface": "警探推开木门，壁炉里的柴火正噼啪作响。\n屋子里暖得反常，一家人围坐在餐桌前——工匠父亲在切烤肉，母亲笑着搅拌浓汤。\n“双胞胎”兄弟在玩积木，他们同时转过头来，露出几乎一模一样的微笑：\n“要留下来吃晚餐吗？”\n窗外，暴雪封山。\n屋内，警探看了眼墙上的一家三口全家福，又看了眼眼前的四个人，惊恐万分", "cats": ["恐怖", "猎奇"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_6260d0fd43a4", "srcNo": 454, "title": "死", "dispTitle": "死", "surface": "一个女人喂了一个男人一种食物，导致两人在很久后死去了。请问发生了什么？", "cats": ["脑洞"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_62b5c21a25a0", "srcNo": 6, "title": "不会响的闹钟", "dispTitle": "不会响的闹钟", "surface": "他每天都被闹钟叫醒。某天闹钟没有响，他却知道自己安全了。", "cats": ["其他"], "difficulty": 3, "src": "github:17hczmsn/turtle_soup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_630d102b5443", "srcNo": 64, "title": "", "dispTitle": "无题 · KONpiGG #64", "surface": "我在床上躺着看直播，刷到了一个漆黑的直播间，直播间里越来越亮，我看到了天花板，然后我死了。请推理我为什么死了", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_633dfaae0191", "srcNo": 461, "title": "头等大事", "dispTitle": "头等大事", "surface": "从小，我就被教育，除非经过明确同意，否则不能展示自己的天性。\n……\n我是一名教官，今天带着一位异常安静的学生。当他指着前方，用一种古怪的强调语气问我\"这个是什么意思\"时，我随口解释了。眨眼间，面前的景象让我瞬间失去了对膀胱的控制。\n提示：避免用\"我\"作为主语提问", "cats": ["怪谈", "搞笑"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_635d3bbeb251", "srcNo": 1196, "title": "Jed 1.10", "dispTitle": "Jed 1.10", "surface": "He was killed by breakfast. (JM original)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_63cb507c431d", "srcNo": 687, "title": "漆黑直播间", "dispTitle": "漆黑直播间", "surface": "我躺床上看直播，刷到一个漆黑直播间，画面越来越亮，我看见天花板，然后我死了。", "cats": ["悬疑", "惊悚", "犯罪", "都市"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_63dc9766e87f", "srcNo": 1250, "title": "没有烟味的外套", "dispTitle": "没有烟味的外套", "surface": "妻子闻到丈夫回家的外套上竟然没有一点烟味，马上报警。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:lancelily6362-png/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_6406f1929bf2", "srcNo": 1022, "title": "最后的求救", "dispTitle": "最后的求救", "surface": "海难幸存者在荒岛上用石头摆出了巨型‘SOS’。当一架飞机飞过时，他疯狂地把‘SOS’改成了‘HELLO’，然后平静地等待死亡。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_641c88779ab8", "srcNo": 1365, "title": "", "dispTitle": "无题 · boop-yyt #1365", "surface": "A man tries to buy poison to kill his wife. The pharmacist figures out what he's up to and finds a way to ensure that he can't kill his wife. (CB, from Flitterwochen in der Hoelle) How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_641dec1f9ed2", "srcNo": 289, "title": "061 · 书作者", "dispTitle": "061 · 书作者", "surface": "大博去图书馆，拿了一本书然后夹进去一百元钱，过了后天他翻开书发现钱还在。大博哭了。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_64332f948516", "srcNo": 578, "title": "舞蹈与死亡", "dispTitle": "舞蹈与死亡", "surface": "我跳着舞，微笑地看着身边的伙伴相继从我面前死去", "cats": ["医院", "搞笑"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_6447eb8a4b30", "srcNo": 1187, "title": "我六岁那年，外公去世", "dispTitle": "我六岁那年，外公去世", "surface": "我六岁那年，外公去世，我和亲人一起去祭奠，和姐姐玩捉迷藏，然后我对母亲说了句话把她吓昏了过去，我说了啥？", "cats": ["其他"], "difficulty": 2, "src": "haiguitang.cn(wayback)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_644d8071165d", "srcNo": 55, "title": "拔萝卜", "dispTitle": "拔萝卜", "surface": "拔萝卜，拔萝卜、嘿呦嘿呦拔萝卜、小朋友，快快来、快来帮我来拔萝卜、红萝卜，白萝卜、全部都是坏萝卜...", "cats": ["恐怖"], "difficulty": 3, "src": "github:anchorAnc/astrbot_plugin_TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_6452042d8133", "srcNo": 1041, "title": "游泳池的挑战", "dispTitle": "游泳池的挑战", "surface": "男子在游泳池比赛潜水，他憋气很久都没上来，大家都在岸上欢呼，直到发现不对劲。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_64cc4c2a51b6", "srcNo": 91, "title": "", "dispTitle": "无题 · KONpiGG #91", "surface": "他们看起来很登对，他也很幸福，但是...绿让红变成了白....掉落的首饰，威胁的证明，模糊的血肉成为了他的执念。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_651e354145af", "srcNo": 186, "title": "", "dispTitle": "无题 · KONpiGG #186", "surface": "丈夫去外地出差，公文包却落在了家里，妻子接到丈夫的求助电话后，坐下来，打开了电视。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_65d144d91615", "srcNo": 776, "title": "章鱼哥", "dispTitle": "章鱼哥", "surface": "章鱼哥上菜时，被蟹老板开除了。", "cats": ["搞笑", "脑洞"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_65fe14d66cba", "srcNo": 1202, "title": "Jed 1.20", "dispTitle": "Jed 1.20", "surface": "A man in uniform stands on the beach of a tropical island. He takes out a cigarette, lights it, and begins smoking. He takes out a letter and begins reading it. The cigarette burns down between his fingers, but he doesn't throw it away. He cries. (RW)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_6659e0657814", "srcNo": 415, "title": "环岛", "dispTitle": "环岛", "surface": "一位侦探受邀前往孤岛调查富豪失踪案，岛上所有佣人都坚称“老爷只是外出了”。侦探发现一本日记，记录着主人每天重复做噩梦、怀疑自己被囚禁。第三天，一只乌鸦撞死在侦探窗前，脚上绑着字条：“快逃，他们都在说谎”。当侦探试图离岛时，却在码头镜中看到自己的倒影露出诡异微笑——而他本人并没有笑。", "cats": ["恐怖", "悬疑"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_66669d3c8637", "srcNo": 475, "title": "衣柜访客", "dispTitle": "衣柜访客", "surface": "我独自租住在老旧公寓，每晚睡前都会检查门窗锁好。这天半夜，我听见衣柜传来轻微布料摩擦声，开灯拉开衣柜后，里面空无一人。第二天清晨，我死在了床上。", "cats": ["悬疑", "逻辑"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_667e4d272252", "srcNo": 1320, "title": "", "dispTitle": "无题 · boop-yyt #1320", "surface": "A man pushes a car up to a hotel and tells the owner he's bankrupt. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_668d61fd84da", "srcNo": 96, "title": "", "dispTitle": "无题 · KONpiGG #96", "surface": "乡间小路上，五名男子一同前行。突然开始下雨，五人中的四人加快了步伐，然而第五人一点也不着急。最终，五人同时到达目的地。加快脚步的四人被淋成了落汤鸡，而第五个人身上却一点也没湿。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_672b157d1754", "srcNo": 330, "title": "猜名字", "dispTitle": "猜名字", "surface": "家里闹鬼了，我和爱人找来一位大师帮忙解决。大师说他有怨气，你们在屋里摆满白烛并喊他的名字，便可散其怨。午夜，阵阵阴风吹灭了蜡烛，爱人急忙喊其姓名，可听到后我却不可置信地看着她。我知道，我们死定了。", "cats": ["其他"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_6766e406b520", "srcNo": 588, "title": "扑克牌抓凶手", "dispTitle": "扑克牌抓凶手", "surface": "警察接到线报，要抓一个名叫“小明”的杀人犯，不知道长相，但知道他就藏在屋里。警察冲进去，看到厨师、程序员、快递员、消防员四个人在打扑克，一句话没问，直接抓走消防员。为什么？", "cats": ["逻辑"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_677cfc01fbf6", "srcNo": 919, "title": "曼德拉效应", "dispTitle": "曼德拉效应", "surface": "你们埋过时间胶囊吗？我小时候埋过，今天打算挖出来看看。由于是陨铁的盒子，因此保存得很好。里面有一封信。”小鱼生病了，小鸟生病了，爸妈生病了，我也生病了，我不想死，可所有人都死了“ 这不可能是我写的！！！这是我写的吗？？哦对，这就是我写的！！", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_683130196767", "srcNo": 266, "title": "035 · 黑猫", "dispTitle": "035 · 黑猫", "surface": "我杀了人，当警察带走我的时候，我看到了门口的黑猫，它一直在盯着我，这一刻我知道我错了。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_689043d7869e", "srcNo": 1345, "title": "", "dispTitle": "无题 · boop-yyt #1345", "surface": "Tom and Joe went to a movie. There were many other people there. During a quiet scene, Tom drew a gun. Joe screamed, Don't shoot! but Tom shot him. Tom then left. Many people saw Tom leave and they restrained him. The police arrived and quickly released Tom. Why?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_68ae986cba90", "srcNo": 503, "title": "截肢", "dispTitle": "截肢", "surface": "爷爷生前是个老木匠，他常盯着巷口那棵被雷劈断的老槐树说：“东西坏了得修，修不好得烧，唯独不能截。截断的木头就像截肢的人，身子虽然没了，那股子想找回腿的‘幻痛’，能把活人逼疯。”\n\n刚毕业那年，为了省钱，我在城中村租了一间只有六平米的隔断房。房东在那张唯一的单人床上铺了厚厚的三层褥子，笑着说这是对我这个大学生的优待。但我每晚都睡得极不安稳，总觉得天花板离我太远，而胸口却像压了一块看不见的石头，沉重得喘不过气。\n\n直到今早换床单时，我被床柱顶端粗糙的横截面划破了手。盯着那四个被整齐锯断的新鲜木茬，爷爷的话像雷一样炸响在耳边。\n我终于知道那股重量来自哪里了。\n它以前躺的地方，现在变成了空气，所以它只能躺在我身上。", "cats": ["悬疑", "惊悚", "都市传说"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_68bfda3c2562", "srcNo": 1153, "title": "二十", "dispTitle": "二十", "surface": "我嫁到了国外，临产期闺蜜飞来陪我。某天闺蜜害怕地和我说:“你家房子不对劲，我总\n能听到器声。”晚上闺蜜突然摔死在我家后院，尸体旁看牌斜斜写着两个血字“二十”。直到我\n来到某个房间，我终于明白这句话的意思了。", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_6912316e00f7", "srcNo": 589, "title": "妈妈的手", "dispTitle": "妈妈的手", "surface": "小明每天睡前都要牵妈妈的手才睡得着。一天全家惨死：爸爸成肉泥，妈妈死了，小明抱着一条血淋淋的手臂死去。", "cats": ["恐怖"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_692bef868539", "srcNo": 1321, "title": "", "dispTitle": "无题 · boop-yyt #1321", "surface": "There are 51 instead of 53. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_6943eeec375b", "srcNo": 128, "title": "", "dispTitle": "无题 · KONpiGG #128", "surface": "年轻的夫妇在看歌剧时接到了保姆打来的说话含糊不清的电话。回家后，他们再也不想过感恩节了。请问，发生了什么？", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_696faa38b48d", "srcNo": 92, "title": "", "dispTitle": "无题 · KONpiGG #92", "surface": "一位男孩儿到河边散步，跟一位渔夫聊天，渔夫跟他说了一句话，男孩儿就自杀了。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_697d6e67511a", "srcNo": 1122, "title": "唱戏的女人", "dispTitle": "唱戏的女人", "surface": "最近几天邻居们都说，夜里总能听到有女子唱戏曲的声音，声调还格外凌惨。今晚我回\n家时也听到了这声音，吓得立刻跑回了家。没过一会儿，楼上传来凄厉的惨叫声，我也终于弄\n明白那戏曲声到底是什么了。", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_69d3afcb8d68", "srcNo": 1088, "title": "", "dispTitle": "无题 · zhuqingxu #1088", "surface": "雪停后的清晨，旷野中央有一具尸体，雪地上只有一串脚印从远处延伸到尸体旁，没有任何返回或第二人的痕迹。之后直到发现前无人再踏入这片雪地。凶手如何离开？", "cats": ["其他"], "difficulty": 2, "src": "github:zhuqingxu/ai-haigui-game", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_6a106ff803ef", "srcNo": 200, "title": "", "dispTitle": "无题 · KONpiGG #200", "surface": "男人给自己心爱的女人打电话，女人一直不接，等回到家发现女人死了。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_6a2910380309", "srcNo": 1370, "title": "", "dispTitle": "无题 · boop-yyt #1370", "surface": "The music stopped and the man died. How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_6aaa8f08bcea", "srcNo": 1068, "title": "传染病房", "dispTitle": "传染病房", "surface": "一名医生在给高度传染病患者做手术时，手套不小心破了。他看了一眼病人，直接用手术刀割断了自己的喉咙。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_6af0ee0910ff", "srcNo": 1127, "title": "信", "dispTitle": "信", "surface": "2000 年，我出生了，和爷爷是我唯一的亲人，他告诉我以后会见到我的父母 2009 年，和爷\n和爷被一个蒙面人杀死了，临死前他给了我一封信，让我 27 岁生日那天打开，之后我便被人收\n养了，2023 年，我怀孕了，医生告诉我，我的身体有些特殊,之后男友便消失得无影无踪;\n2024 年，我刚生完孩子，孩子就被从了; 2027 年，我出了一场车祸,做了三场手术，术后我\n又见到了消失 4 年的男友，生日那天我想起爷爷那封信” 打开后我终于知道我的父母是谁\n村。", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_6bd4a36e3255", "srcNo": 535, "title": "不响的闹钟", "dispTitle": "不响的闹钟", "surface": "小明每天早上都靠手机闹钟起床。某天早上，闹钟明明准时在荧幕上跳动，却没有发出任何声音。小明看了看荧幕，叹了一口气，随即走进厨房拿起了菜刀", "cats": ["恐怖", "惊悚", "脑洞", "逻辑"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_6be8ca4af061", "srcNo": 624, "title": "车上的女友", "dispTitle": "车上的女友", "surface": "我和女友出门自驾游，中途女友下车了一段时间，后来她又上了车。我们开出一段距离后，看到了一个老婆婆，她做出了一个动作。接着女友跟我说了一句话，做了一个动作，我疯了。", "cats": ["怪谈", "恐怖", "脑洞"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_6bf8c1505a1e", "srcNo": 1359, "title": "", "dispTitle": "无题 · boop-yyt #1359", "surface": "A man kills his wife, then goes inside his house and kills himself. (DH original, from \"Nightmare in Yellow,\" by Fredric Brown) How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_6c3407286474", "srcNo": 609, "title": "日访三十国", "dispTitle": "日访三十国", "surface": "一个没有护照的普通美国公民，一天之内访问了30多个国家。在每个国家里他都受到热情招待，并且离开时也完全自由。", "cats": ["日常", "职场"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_6c4c07d9075a", "srcNo": 1307, "title": "", "dispTitle": "无题 · boop-yyt #1307", "surface": "A rope breaks. A bell rings. A man dies. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_6c64198477a7", "srcNo": 635, "title": "赴净土", "dispTitle": "赴净土", "surface": "城中无啼锁门窗，棍棒底下出真章。\n临行明月仍残缺，沙僧忽闻有肉香。\n吾心明悟兄难辨，真尸恐已成白骨。\n尘埃落定无杂念，一如既往赴净土。", "cats": ["其他"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_6d476e7aeb8c", "srcNo": 411, "title": "失眠", "dispTitle": "失眠", "surface": "电视里报到了一篇新闻，警方找到了多年前抢劫银行的四人团伙。\n从此，我失眠了。", "cats": ["悬疑", "本格", "逻辑"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_6d7d1fe43ab0", "srcNo": 83, "title": "", "dispTitle": "无题 · KONpiGG #83", "surface": "一个女人按下了一个按钮，导致另一个人死亡了", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_6db4d37cfcbb", "srcNo": 1148, "title": "给三兄弟的一封信", "dispTitle": "给三兄弟的一封信", "surface": "HO+SiOz+FesOs+CO:一0 人 〈x2+y2-1 ) 3一", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_6ddef2ee1c6d", "srcNo": 1304, "title": "", "dispTitle": "无题 · boop-yyt #1304", "surface": "A man is found hanging in a locked room. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_6de0d702d28a", "srcNo": 490, "title": "吓我一跳", "dispTitle": "吓我一跳", "surface": "一个人走进餐厅，点了一杯白开水。服务员把水端上来后，掏出一把手枪对着那人猛地指了一下。那人连声道谢，付完钱就离开了。为什么？", "cats": ["本格"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_6e0606090262", "srcNo": 179, "title": "", "dispTitle": "无题 · KONpiGG #179", "surface": "门开了，人们陆陆续续的走进，却又惊慌失措的跑出。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_6e35467a2ea9", "srcNo": 1211, "title": "Jed 1.46", "dispTitle": "Jed 1.46", "surface": "A man dies in his own home. (ME original)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_6f1a91a082e8", "srcNo": 1156, "title": "未完待续", "dispTitle": "未完待续", "surface": "我梦见我在一个全是玻璃的世界，她在远处冷漠地看着我“宝贝，起床了?温柔的声音\n把我叫醒。我睁眼惊代地看了一眼日期，今天是我的生日，一个令我厌烦的日子。我急忙拿起\n刀杀死了身旁的女人。我疗狂地笑了: “或许，这样就可以了.2”", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_6f2ff35c1f68", "srcNo": 1044, "title": "冰块杀人案", "dispTitle": "冰块杀人案", "surface": "一个男人死在密闭的房间里，死因是吊死。但他脚下没有任何垫脚物，只有一滩水。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_6f860967a6c4", "srcNo": 947, "title": "别过来", "dispTitle": "别过来", "surface": "对面的8楼不对劲！窗户上有一列血字：别过来！我透过窗发现一个人型轮廓站在房间内诡异的抽动。我吓坏了，急忙拉上窗帘。第二天早上再观察时，我发现一个男人吊在麻绳上。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_6fabddc7ad32", "srcNo": 292, "title": "064 · 发现凶手", "dispTitle": "064 · 发现凶手", "surface": "我发现妹妹在夜里翻墙出去和男孩子幽会，但最终我没有告诉父母。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_6ff3742a28e2", "srcNo": 901, "title": "白雪公主规则怪谈", "dispTitle": "白雪公主规则怪谈", "surface": "1．皇后最多只能活3年；2. 猎人放过了白雪；3. 猎人绝对忠诚于皇后；4. 猎人非常感激皇后救了自己；5. 七个小矮人救了陷阱中的白雪；6. 魔镜说最美的女人是白雪，皇后非常生气；7. 白雪美丽的外表让王子非常迷恋；8. 巫婆给予了白雪一颗苹果；9. 白雪在巫婆面前死掉了；10. 复活后的白雪和王子幸福地生活在了一起。（注：2、4、6、8为红字规则，即反话）", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_70698b7f9eba", "srcNo": 318, "title": "090 · 红点", "dispTitle": "090 · 红点", "surface": "深夜，他发现对面楼的窗口有个红点一直在盯着他，他关上了窗帘，安心睡去。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_70707f32e1ca", "srcNo": 206, "title": "对赌", "dispTitle": "对赌", "surface": "两个死人，现场只有一把枪，一颗子弹，一副牌。发生了什么？", "cats": ["其他"], "difficulty": 2, "src": "github:wangyafu/haiguitangmcp", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_70b45f72c51c", "srcNo": 446, "title": "晚餐的约定", "dispTitle": "晚餐的约定", "surface": "我家有个规矩：晚餐必须摆上姐姐的碗筷。妈妈说姐姐在厨房帮忙，可我只能看见她的背影，和听她切菜的声音。直到今天，我玩球时不小心砸中了她。姐姐摔倒在地上，没有惊呼。妈妈微笑着对我说：没关系，我们再把姐姐扶起来就好。", "cats": ["家庭", "恐怖", "本格"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_70b990289c70", "srcNo": 217, "title": "死亡直播", "dispTitle": "死亡直播", "surface": "我在床上躺着看直播，刷到了一个漆黑的直播间，直播间里越来越亮，我看到了天花板，然后我死了。", "cats": ["其他"], "difficulty": 2, "src": "github:wangyafu/haiguitangmcp", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_70e667af0b9b", "srcNo": 1090, "title": "", "dispTitle": "无题 · zhuqingxu #1090", "surface": "夜行列车上，一名乘客在驶入隧道、车厢灯灭、剧烈颠簸的几十秒内被勒死。同包厢另外两人发誓谁也没离开座位，灯再亮时三人的位置与进隧道前一致，包厢门也无人进出。这可能吗？凶手怎么下的手？", "cats": ["其他"], "difficulty": 2, "src": "github:zhuqingxu/ai-haigui-game", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_70ef60c67d01", "srcNo": 863, "title": "柜中的孩子", "dispTitle": "柜中的孩子", "surface": "深夜，我家的衣柜传来了窸窸窣窣的声音，我壮着胆子打开柜门，里面居然有一个孩子，他看着我嘿嘿的笑着：“妈妈，你找到我啦～”我吓坏了，哪来的孩子。我让他立刻离开我的房子，他吓哭了，一直叫我妈妈。仔细看他和我前夫的确有几分相似。但我自从几年前流产后就没有了生育能力，也离了婚。他告诉我他还有一个双胞胎弟弟，甚至叫出了我和前夫的名字，他带着哭腔问我：“你真不记得我了吗？”", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_70fe687de92d", "srcNo": 88, "title": "", "dispTitle": "无题 · KONpiGG #88", "surface": "晚饭时，玛丽的爸爸抱怨妈妈做的汤太甜了，当晚，妈妈就死了，几天后爸爸也死了。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_710a85147341", "srcNo": 563, "title": "迷信少女", "dispTitle": "迷信少女", "surface": "小花是一个喜欢占卜的女孩，刚到大学他就把三个舍友的八字都算了一遍，还夸她们命都好。小花的家里人也都神神叨叨的，晚上她妈妈打电话来问她住哪间宿舍，她说是305，她妈说“那还好”。第二天小花约一个舍友出去买鱼，说把鱼放生会增加功德，然而到了晚上却只有小花一个人回来了", "cats": ["悲剧"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_710f1137667b", "srcNo": 1110, "title": "平安夜", "dispTitle": "平安夜", "surface": "我长年待在病房里，今天是平安夜，外面下了很大的雪，和葡爸妈妈接我回家竺一天，多\n爸亲自下厨,妈妈也在照顾生病的我,护工来到了家里交说我该回去了。 妈妈恳求他但他不听，\n于是二人扭打在一起，妈妈杀死了护工，和爸爸让我不要在意; 还给我做了火鸡和烤肉。吃饱了\n我和爸爸妈妈睡在了一张床上，很热，很暖，我很快就睡着了 。第二天我幸福地死去了。", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_712a831d7292", "srcNo": 744, "title": "神奇的娃娃", "dispTitle": "神奇的娃娃", "surface": "婆婆给我一个“神奇娃娃”，说对它许愿能实现愿望，但必须随身带着、保护好、不能碰水，否则不灵。后来我付出惨痛代价。", "cats": ["反转", "悬疑", "推理", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_713c1ec8c207", "srcNo": 93, "title": "", "dispTitle": "无题 · KONpiGG #93", "surface": "小强养了一只忠诚的狗，有一天他牵着狗上街，结果小强死了。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_715c8134e625", "srcNo": 357, "title": "广播", "dispTitle": "广播", "surface": "我听到广播里的新闻后，先是庆幸而后痛哭起来。", "cats": ["恐怖", "悬疑", "犯罪"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_716080de6350", "srcNo": 339, "title": "耳边的话", "dispTitle": "耳边的话", "surface": "他在为她戴上项链，庆祝她的生日。他在她的耳边说了一句:生日快乐。随后她崩溃了。", "cats": ["悬疑", "本格"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_718288baaf34", "srcNo": 1036, "title": "多出的那一刻", "dispTitle": "多出的那一刻", "surface": "一个人发现自己的表停了，他调好时间后继续睡觉，第二天却发现自己迟到了整整一个小时。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_71e368d13be5", "srcNo": 1335, "title": "", "dispTitle": "无题 · boop-yyt #1335", "surface": "A man is doing his job when his suit tears. Fifteen minutes later, he's dead. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_71e675399a64", "srcNo": 199, "title": "", "dispTitle": "无题 · KONpiGG #199", "surface": "有一位老婆婆，她在借书时都一定会翻到第五十页再决定要不要借。为什麽她要这样做？", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_71ec509dae7a", "srcNo": 1340, "title": "", "dispTitle": "无题 · boop-yyt #1340", "surface": "Two naturalists were walking in the country. They were both keen to protect the environment and to conserve nature and wildlife. One said to the other, \"I was impressed by the way that you hit that bird.\" The second replied, \"Yes, it was good, but not as good as that large bird that you hit earlier.\" What were they talking about?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_71f829d3da3b", "srcNo": 383, "title": "重映", "dispTitle": "重映", "surface": "我生病了。每天睡前妈妈都会喂我吃药。可吃完药后我总会做噩梦。\n第一天，我梦见我被急驰而来的卡车撞死了。\n第二天，我被包裹在睡袋里移动，什么都看不见。\n第三天，妈妈和我说她被公司辞退了，晚上我梦见妈妈疯狂的割下了我的头。\n第四天，原来那不是梦，吃完药后，我知道我活不过今晚了。", "cats": ["怪谈", "恐怖", "猎奇"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_72246a7f2fe2", "srcNo": 1066, "title": "最后的奢侈品", "dispTitle": "最后的奢侈品", "surface": "末日避难所里，富翁用一颗价值连城的钻石换了穷人的一块发霉的面包。富翁吃完面包后，笑着把钻石又抢了回来，穷人却没有反抗。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_723f2ea5fd2d", "srcNo": 396, "title": "妙手神偷", "dispTitle": "妙手神偷", "surface": "我背负着同伴的寄托，要去偷个东西，我翻过岩石，淌过河水，绕过巡逻队的守卫，但就在我快成功时，我被发现了！他们打碎了我身上的一个东西，最后，我还是成功了", "cats": ["搞笑", "脑洞"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_7285070973c8", "srcNo": 386, "title": "极乐万华镜", "dispTitle": "极乐万华镜", "surface": "他高价收购了一具名为“百鬼夜行”的古董西洋万华镜，据说能看到世间极乐。第一次窥探，他抱怨里面的琉璃碎屑像是在蠕动的残肢；第二次窥探，他抱怨镜面折射的倒影全是狰狞的鬼脸。第三次，他亲自转动了万华镜底部象征“极乐”的暗格，终于看到了漫天飞舞的鲜红彼岸花。他满足地笑了，随后倒在桌前，再也没有醒来。", "cats": ["反转", "悬疑", "猎奇"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_72b08b0f2494", "srcNo": 1334, "title": "", "dispTitle": "无题 · boop-yyt #1334", "surface": "A man shoots himself, and dies. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_72d3434bc4c8", "srcNo": 1188, "title": "寝室每天简直吵死了", "dispTitle": "寝室每天简直吵死了", "surface": "寝室每天简直吵死了，\n今天多亏了食堂的叔叔阿姨，\n我终于可以安心睡觉了。", "cats": ["其他"], "difficulty": 2, "src": "haiguitang.cn(wayback)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_72db1e4c55f6", "srcNo": 871, "title": "张三李四", "dispTitle": "张三李四", "surface": "“一定要杀死张三”这几个字某天凭空出现在了我家的天花板上，我赶紧把字擦掉，可第二天这句话又凭空出现了。我并不认识张三，但等我明白这几个字是哪来的以后，我开始寻找他了。大概过了10年，时间来到2010年，我终于找到了张三，并一刀杀死了他，他临死前不可置信看着我：“李四？！”可能是被我触碰的原因，他的尸体异常的消失了。在我临死前的一个月，我终于知道为什么一定要杀死张三了。我放下手中新世纪的第一份报纸，去做了那件早就该做过的事。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_73b6519f54ca", "srcNo": 867, "title": "老农", "dispTitle": "老农", "surface": "万历年间，乡下一老农，其女貌美，为村霸所觊，屡来相扰。未几，女竟失踪。老农揣女或遇不测，遂往衙诉之。不意至衙，殒命焉。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_73c238975974", "srcNo": 527, "title": "半根火柴", "dispTitle": "半根火柴", "surface": "一个人死在了沙漠里，身边有半根火柴。", "cats": ["本格"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_73c5c7e68664", "srcNo": 747, "title": "出轨", "dispTitle": "出轨", "surface": "女人告诉男人他的老婆出轨，女人却死了。", "cats": ["搞笑", "日常"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_73f2ef96b5a9", "srcNo": 781, "title": "姐姐", "dispTitle": "姐姐", "surface": "妈妈怀孕了，我终于要有姐姐了。", "cats": ["亲情", "反转", "温情"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_73fb65cff1b3", "srcNo": 216, "title": "杀妻后自杀", "dispTitle": "杀妻后自杀", "surface": "一个男人杀死自己的妻子，然后回到自己的房间，而后自杀。", "cats": ["其他"], "difficulty": 2, "src": "github:wangyafu/haiguitangmcp", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_741df7fb39e2", "srcNo": 86, "title": "", "dispTitle": "无题 · KONpiGG #86", "surface": "马戏团里有两个侏儒，瞎子侏儒比另一个侏儒矮，马戏团只需要一个侏儒，马戏团里的侏儒当然是越矮越好了。两个侏儒决定比谁的个子矮，个子高的就去自杀。可是，在约定比个子的前一天，瞎子侏儒也就是那个矮的侏儒已经在家里自杀死了。在他的家里只发现木头做的家具和满地的木屑。问他为什么自杀？", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_7445ad740cb8", "srcNo": 924, "title": "双缝干涉实验", "dispTitle": "双缝干涉实验", "surface": "我们代表人类成功探索了开普勒725c，留守在飞船上的博士却消失了，我们四人在中控室发现了一张纸条：1. 如果我死了，一定是他杀。2. 飞船上没有笔，且最高承载4人。3. 人类把开普勒725c称为“超级地球”。4. 请进行“双缝干涉实验”。5. 请不要返航，请打破认知！等我们看完，这些字却又消失了。到底发生了什么？", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_749507623b5d", "srcNo": 713, "title": "人鱼公主", "dispTitle": "人鱼公主", "surface": "美人鱼与人类王子相爱来到王子的国家，不久后却传来王子死讯。", "cats": ["反转", "温情", "脑洞"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_74c8d1d06689", "srcNo": 505, "title": "攻击", "dispTitle": "攻击", "surface": "夜归玄关，黑影倏窜，转身间脚边传来尖锐凉触", "cats": ["日常", "温情"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_74e8020e320f", "srcNo": 866, "title": "熵增", "dispTitle": "熵增", "surface": "36 39 42 25 1000 25 15", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_75185e4de274", "srcNo": 1385, "title": "", "dispTitle": "无题 · boop-yyt #1385", "surface": "A man marries twenty women in his village but isn't charged with polygamy. How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_752b3fdd39a9", "srcNo": 165, "title": "", "dispTitle": "无题 · KONpiGG #165", "surface": "她喜欢男人很久了，有一天她终于鼓起勇气对他表白了，但是男人对她说了一句话，她瞬间就崩溃了。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_754074695c41", "srcNo": 35, "title": "借书老人", "dispTitle": "借书老人", "surface": "一位老人，每周都会去图书馆借书，但是每次借书前都会翻到第30页，这是为什么?", "cats": ["温情"], "difficulty": 2, "src": "github:anchorAnc/astrbot_plugin_TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_75438c574a41", "srcNo": 1030, "title": "企鹅肉", "dispTitle": "企鹅肉", "surface": "一个人在餐厅吃了一碗企鹅肉，他觉得很好吃，但他随后却哭了。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_7590a2a6ddf6", "srcNo": 124, "title": "", "dispTitle": "无题 · KONpiGG #124", "surface": "在一棵枯树上插着一具男尸，树下一片潮湿，请问发生了什么事？", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_75cef260f518", "srcNo": 833, "title": "童谣疯人院", "dispTitle": "童谣疯人院", "surface": "疯人院，院疯人。不收老人和病人，专收小孩和女人。白天大门排满人，夜里院里都是人，没有一个是活人。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_75f091e6b064", "srcNo": 23, "title": "海龟汤", "dispTitle": "海龟汤", "surface": "一个女人在餐厅点了一份海龟汤，喝了一口后就哭了。为什么？", "cats": ["猎奇"], "difficulty": 3, "src": "github:anchorAnc/astrbot_plugin_TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_7603cfb640c9", "srcNo": 297, "title": "069 · 长大", "dispTitle": "069 · 长大", "surface": "小时候妈妈总说\"等你长大了就好了\"，等我真的长大了，妈妈却哭了。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_7650869fbc4d", "srcNo": 381, "title": "诡异的画", "dispTitle": "诡异的画", "surface": "我来到一个偏远山村教书，上完第一节美术课后，我疯了。", "cats": ["恐怖", "悬疑"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_76620709814f", "srcNo": 1093, "title": "", "dispTitle": "无题 · zhuqingxu #1093", "surface": "古堡舞会要求所有人戴同款面具、穿同款斗篷，仅靠背后的号码区分身份。主人整晚盯着「07号」坐在对面沙发没动，却有人发誓看见「07号」在二楼走廊行凶。登记处确认每个号码只发过一次。矛盾怎么解释？", "cats": ["其他"], "difficulty": 2, "src": "github:zhuqingxu/ai-haigui-game", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_7685f3f6e6ed", "srcNo": 460, "title": "雪", "dispTitle": "雪", "surface": "他获救后，因为那件事一直活在深深的愧疚中。\n多年后的一个冬日，他推开家门，看着窗外漫天飞舞的雪花，突然脸色惨白，疯了一样冲出去，最后绝望地自杀了。\n他说：“原来这里根本没有兔子。”", "cats": ["悬疑", "悲剧"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_7695fa789e5e", "srcNo": 629, "title": "离车30米只走五步", "dispTitle": "离车30米只走五步", "surface": "男人离车30米，只走五步上车。为什么？", "cats": ["逻辑"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_769ed16a5744", "srcNo": 1025, "title": "最后一名乘客", "dispTitle": "最后一名乘客", "surface": "深夜大巴，司机发现最后一名乘客死在了座位上，手里拿着一张到站的票。司机吓得弃车而逃。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_76a9fb076c5c", "srcNo": 1241, "title": "葬礼上的陌生人", "dispTitle": "葬礼上的陌生人", "surface": "妹妹在母亲的葬礼上，第一次见到一个男人，立刻爱上了他。几天后，妹妹杀了姐姐。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:lancelily6362-png/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_76d6cf3b543b", "srcNo": 175, "title": "", "dispTitle": "无题 · KONpiGG #175", "surface": "一群羊，两只狼。羊吃草，狼吃鸟。沉默的狼，挑衅的羊。死的羊，逃的狼。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_76f60ee9180c", "srcNo": 493, "title": "無用之用", "dispTitle": "無用之用", "surface": "男人每天通勤上下班時，每逢下雨天手裡總會拿著一把明顯壞掉、傘骨折斷且根本無法撐開的雨傘。\n\n就這樣過了一段時間，在某個大雨滂沱的傍晚，下班時，一位同事走到他身邊，手裏準備打開雨傘，並輕聲問：「你的傘好像壞了，要不要和我一起去車站？」\n\n男人聽完露出了微笑。接著，他毫不猶豫地把那把壞掉的傘扔進了一旁的垃圾桶，並走進同事的傘下。", "cats": ["日常", "温情"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_7725a901cd45", "srcNo": 345, "title": "失灵的魔咒", "dispTitle": "失灵的魔咒", "surface": "烈日当空，他把天使锁进了蓝色的铁棺材。\n屋里四季如春，他沉溺于屏幕里的虚幻春色，痛饮着盗来的欢愉。\n他信赖的那道“护身魔咒”，有效期只有三十分钟。\n当时针划过，寒气消散，铁棺变成了炼狱。\n面对那双已经烧焦变黑的双腿，他向审判者提出的唯一请求，\n竟然是：“求求你，让我洗个澡。”", "cats": ["悬疑", "犯罪"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_776b70302820", "srcNo": 257, "title": "024 · 关灯", "dispTitle": "024 · 关灯", "surface": "小明半夜起来喝水，顺手把灯关上继续睡觉，醒了之后他就自杀了，为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_77bc008828e5", "srcNo": 865, "title": "日记", "dispTitle": "日记", "surface": "8岁，今天我过8岁生日啦！爸爸妈妈送了我一个玩具车，我好开心；9岁，今年生日爸爸带我们去吃大餐，弟弟在厕所摔到了，我和爸爸在旁边哈哈大笑，回去后妈妈笑骂了我和爸爸；10岁，妈妈去世了，爸爸生死未卜，我没有心情过生日；12岁，今年生日，爸爸送了我一条边境牧羊犬，据说它是最聪明的狗狗！我好开心，就叫他小乖吧；13岁，爸爸教我学习，因为爸爸是作家，但是爸爸写的书不让我看；14岁，小乖最近食欲不振，爸爸说是换了狗粮的原因，过几天就好了，我很崇拜爸爸，什么都懂；15岁，爸爸写的书很畅销，还得了奖！今年生日爸爸亲自下厨，很美味！可是我听到做菜的声音会头疼；16岁，爸爸给我梳头，他摸着我的脸，伤感的说我越来越像妈妈了，我知道他是想妈妈了，我很心疼爸爸；17岁，看完书后，我心情很复杂，也明白弟弟给我看这本书的意思了，对不起了弟弟，我爱爸爸！记得爸爸说弟弟特别怕烫，我用开水烫了他身上，看着他绝望的眼神，我开心的笑了。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_77f7e2dd70c8", "srcNo": 961, "title": "", "dispTitle": "无题 · White-stone36 #961", "surface": "一位富豪给她心爱的妻子打了一通电话，于是妻子就死了。", "cats": ["其他"], "difficulty": 2, "src": "github:White-stone36/Situation_puzzles_games", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_78208753dea6", "srcNo": 227, "title": "裤子破了", "dispTitle": "裤子破了", "surface": "我的裤子破了，我知道我马上要死了。", "cats": ["其他"], "difficulty": 2, "src": "github:wangyafu/haiguitangmcp", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_783c025b1ad0", "srcNo": 1115, "title": "吹蜡烛", "dispTitle": "吹蜡烛", "surface": "家里闹鬼了，我找了一个大师帮我解决,大师说要想保命就需要做到以下三点，过了今\n晚就会安然无盖: 1. 这根用来驱那的蜡烛你千万不要吹灭，不然就会死，2. 家里只有你一个\n人，任何人喊你的名字都不要回应寺包括我; 3. 哪怕过了今晚，你这辈子晚上都不要关灯，\n否则就会看到鬼。果然我平安度过了今天，但是却在几个月之后死了。", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_78451a938182", "srcNo": 307, "title": "079 · 游乐园", "dispTitle": "079 · 游乐园", "surface": "他在游乐园玩了一整天，回家后却伤心地哭了。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_7893be6075d9", "srcNo": 684, "title": "替妹妹写遗书", "dispTitle": "替妹妹写遗书", "surface": "我一回家就立刻替死去的妹妹写遗书：写下‘我想死’的心情就行。", "cats": ["亲情", "反转", "悬疑"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_78cb976e598c", "srcNo": 210, "title": "手滑", "dispTitle": "手滑", "surface": "我在和闺蜜聊天，忽然手机掉在了地上。闺蜜吓傻了。 我死了。 为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:wangyafu/haiguitangmcp", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_798612ad031c", "srcNo": 1074, "title": "死亡直播间", "dispTitle": "死亡直播间", "surface": "绑匪直播杀人，声称点赞过万就放人。点赞数飞速增长，最后受害者却死得更惨了。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_798ea6557784", "srcNo": 346, "title": "成为你", "dispTitle": "成为你", "surface": "小时候的我很贪心，总想从你那里获得什么。\n对你的好奇，让你消失在了某个夜晚。\n长大后我便成为了你。", "cats": ["本格"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_79beaf056729", "srcNo": 167, "title": "", "dispTitle": "无题 · KONpiGG #167", "surface": "一个人去火锅店吃火锅，但后来却因涉嫌贩毒引来了警察，请问发生了什么？", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_79d2875e016e", "srcNo": 701, "title": "寒冷的夜晚", "dispTitle": "寒冷的夜晚", "surface": "战争中两士兵困荒野。第一个寒夜后一个死了；又过一夜，活着的士兵发现同伴坐在身旁盯着他，他痛哭。", "cats": ["恐怖", "悬疑", "惊悚"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_7a11b6dced24", "srcNo": 304, "title": "076 · 捡到钱", "dispTitle": "076 · 捡到钱", "surface": "他在地上捡到了一百块钱，但最终还是难过地哭了。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_7a172206d899", "srcNo": 562, "title": "坍缩的坐标", "dispTitle": "坍缩的坐标", "surface": "我花大价钱从黑市搞来了一块代号为“拟态者”的星体样本，据说它来自宇宙边缘的虚空。\n启动高能激光剥开它绚烂的晶体外壳，里面竟是一团像心脏般疯狂蠕动的液态暗影；\n我开启力场蒸发掉暗影，核心处悬浮着一个发出圣歌般轰鸣的完美几何光球；\n我颤抖着击碎光球，跌落在托盘上的，竟然只是一枚人类20世纪随处可见的、生锈的铁钉。\n我困惑地看向量子分析仪生成的最终报告，\n屏幕上跳出的一行鲜红警告，让我瞬间切断了实验室的所有电源，在黑暗中死死捂住了耳朵。", "cats": ["怪谈", "悬疑", "科幻"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_7a306afeee05", "srcNo": 941, "title": "D·r·e·a·m", "dispTitle": "D·r·e·a·m", "surface": "（动态）A1：你在宿舍中被噩梦惊醒，原来只是一场梦。A2：你从宿舍中醒来，之前的经历好像一场梦。B1：今天新来了一名转校生，名叫xxx。B2：今天新来了两名转校生，xxx和xxx。B3：今天没来转校生。C1：他的行为很诡异，似乎在寻找什么。C2：他们俩的行为很诡异，似乎在寻找什么。C3：你的行为很诡异，似乎在适应什么。C4：他（们）漫无目的的闲逛，突然，他（们）消失了。（触发此条本轮直接结束）D1：深夜，他找到你，露出瘆人的微笑，逐渐逼近。D2：深夜，他们找到你，露出瘆人的微笑，逐渐逼近。D3：深夜，你露出瘆人的微笑，计划成功了。D4：深夜，他（们）找到你，但他（们）有些害怕，甚至惊恐，而后，他（们）突然消失了。（触发此条本轮直接结束）E1：冥冥之中有一个声音想让你做一些什么，于是你急忙问它：xxxxxxxxxxxE2：冥冥之中有一个声音惊恐的问你：你是谁！（恭喜通关）提问后触发：F1：XXX突然拿出XX杀死了你，回A1（包含本轮转校生名称时触发）F2：你突然拿出XX杀死了XXX，回A1（对转校生带有杀意时触发）F3：XXX拿出XX冲向你时／你拿出XX想杀死XXX时，xxx突然消失，回A1（出现弃游玩家时触发）F4：你决定结束生命，在XXX不解的目光中，你倒了下去，但你觉得意识有些停滞，好像还可以做些什么……但什么都没做到，一阵白光闪过，回A1（自我了结时触发）", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_7a31e92d9ed9", "srcNo": 945, "title": "小明", "dispTitle": "小明", "surface": "不懂的事情问小明，难过的时候找小明。重要的秘密和小明说，无聊的时候找小明玩。直到有一天，小明主动找我了。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_7a4e41b9ec48", "srcNo": 779, "title": "跟踪", "dispTitle": "跟踪", "surface": "4月24日，我感觉有奇怪的人跟着我。4月25日，我被跟踪了，警察抓住了我。", "cats": ["反转", "悬疑", "推理", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_7a5fdd9fceab", "srcNo": 480, "title": "终于", "dispTitle": "终于", "surface": "他为我拼尽一生，守我一世。我始终无动于衷。\n今日，我终于亲眼看着别人送他入土。\n终于给我等到今天。", "cats": ["悬疑", "逻辑"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_7ac799721fa8", "srcNo": 193, "title": "", "dispTitle": "无题 · KONpiGG #193", "surface": "一个人在医院的走廊里，他要去看望一位生病的朋友。走着走着，他发现走廊的灯光开始闪烁，周围的温度也越来越低。他有些害怕，加快了脚步。突然，他看到一个护士推着一辆病床从他身边经过，病床上躺着一个全身盖着白布的人，当病床经过他身边时，白布突然掉了下来，他看到了什么让他惊恐万分?", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_7b28164de2b9", "srcNo": 1197, "title": "Jed 1.11", "dispTitle": "Jed 1.11", "surface": "Two brothers are involved in a murder. Though it's clear that one of them actually committed the crime, neither can be punished. (This is different from #1.78.) (from \"Unreasonable Doubt,\" by Stanley Ellin)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_7b3723fd1fc6", "srcNo": 631, "title": "孤独症", "dispTitle": "孤独症", "surface": "我在执行长期深空任务，飞船内只有我和一组用于生物实验的果蝇。某天醒来，我发现培养箱空了，果蝇全部消失。随后，我听到通风管里有细微的嗡嗡声，食物包装被咬破，控制面板上出现奇怪的黏液。最恐怖的是，晚上睡眠时我感到有东西在耳边飞过，并留下黏糊糊的痕迹。我确信果蝇发生了突变，变得巨大且具有攻击性。我穿上舱外服，拿起火焰喷射器，准备清理通风系统。当我打开通风口挡板，用手电照进去时，我愣了两秒，然后笑了。", "cats": ["其他"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_7b6a38fe1277", "srcNo": 802, "title": "好久不见的同学", "dispTitle": "好久不见的同学", "surface": "小明好久没和高中同学联系，主动发消息，对方很快回应，两人聊得很开心。隔天一早小明打开电视看到新闻，眼神呆滞随后流泪。为什么？", "cats": ["反转", "悬疑", "推理", "犯罪"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_7b7158c76a57", "srcNo": 28, "title": "神奇的娃娃", "dispTitle": "神奇的娃娃", "surface": "一个婆婆给了我一个神奇的娃娃，她说只要我对这个娃娃许愿，娃娃就可以实现我的一切愿望，但我必须无时无刻将娃娃带在身边，并且要保护好娃娃，不让娃娃碰水，否则愿望就不灵验了，可是之后我却付出了惨痛的代价。", "cats": ["犯罪"], "difficulty": 3, "src": "github:anchorAnc/astrbot_plugin_TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_7ba2fe196fb5", "srcNo": 899, "title": "未完待续", "dispTitle": "未完待续", "surface": "我梦见我在一个全是玻璃的世界，她在远处冷漠地看着我。”宝贝，起床了“温柔的声音把我叫醒。我睁眼惊恐地看了一眼日期，今天是我的生日，一个令我厌烦的日子。我急忙拿起刀杀死了身旁的女人。我癫狂地笑了：”或许，这样就可以了……“", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_7bec134fc445", "srcNo": 1347, "title": "", "dispTitle": "无题 · misc #1347", "surface": "Pat went into a luggage shop to buy a suitcase. The assistant said, \"It is most unusual to buy a suitcase. You should rent one like all our other customers.\" Why should this be so?", "cats": ["其他"], "difficulty": 2, "src": "misc/repo-scan", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_7bf02e065063", "srcNo": 808, "title": "凌晨三点的敲门声", "dispTitle": "凌晨三点的敲门声", "surface": "一名住户报警称最近几天凌晨三点偶尔会听见门口传来微弱敲门声，但起床查看门外却什么都没有。警方调查发现房门上有奇怪刮痕，并发现邻居已失踪数周。发生了什么事？", "cats": ["恐怖", "悬疑", "惊悚", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_7bf2b654f6ba", "srcNo": 213, "title": "接连死去的哥哥", "dispTitle": "接连死去的哥哥", "surface": "我有两个哥哥，我们三兄弟自小就睡在一张床上。后来有一天二哥因为生病死了，不久后我把大哥也杀了。", "cats": ["其他"], "difficulty": 2, "src": "github:wangyafu/haiguitangmcp", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_7bfaf3742b38", "srcNo": 310, "title": "082 · 恶灵", "dispTitle": "082 · 恶灵", "surface": "一开始是动物，接着是同类的尸体，再然后是同类，最后是我自己。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_7c07924034bb", "srcNo": 675, "title": "只找一个人", "dispTitle": "只找一个人", "surface": "男人交出了两位老朋友共同盗窃的证据。警方核实后只寻找其中一人，却没有放过另一个人。为什么？", "cats": ["推理", "犯罪"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_7cf2a178d34a", "srcNo": 706, "title": "不要相信一号", "dispTitle": "不要相信一号", "surface": "我醒来忘记一切，纸条写着：不要相信1号。一个男人走近说：先生早上好，2号很高兴为您服务。我问1号呢？他指地上躺着个像死了一样的男人。", "cats": ["反转", "悬疑", "推理", "科幻", "脑洞"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_7cfd2cb3f361", "srcNo": 1043, "title": "特殊的遗言", "dispTitle": "特殊的遗言", "surface": "死者临终前在地上写了一个‘火’字。警察很快抓住了凶手‘大山’。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_7d62556382b0", "srcNo": 44, "title": "午夜列车", "dispTitle": "午夜列车", "surface": "离午夜还有五分钟，一个男子上了列车。男子的神情很奇怪，他看了看车上的几个人，然后开始问起乘客的年龄。\"女士，您今年28岁吗?\"\"你怎么知道?\"先生您今年55吗?\"对呀。\"然后男人一个个地猜对了乘客的年龄。\"婆婆，您今年69岁吗?\"\"不是的，再过5分钟我就要69岁了。\"男子听完，脸色惨白。", "cats": ["其他"], "difficulty": 3, "src": "github:anchorAnc/astrbot_plugin_TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_7d8e2bcb15a3", "srcNo": 174, "title": "", "dispTitle": "无题 · KONpiGG #174", "surface": "一家人在人们的欢送下乘船出海，几日后却飘来他们那空荡荡的小船，人们却与视无睹，为什么。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_7de73d716ad1", "srcNo": 265, "title": "034 · 寝室恶作剧", "dispTitle": "034 · 寝室恶作剧", "surface": "清晨，我被室友的尖叫声吵醒，睁开眼后，我却说不出话来。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_7dfc2ba4e79f", "srcNo": 69, "title": "", "dispTitle": "无题 · KONpiGG #69", "surface": "宿舍门口有人敲门，问：\"要买红衣服吗\"我：买吧买吧第二天宿舍人都死了", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_7e21744dc3e1", "srcNo": 553, "title": "再现", "dispTitle": "再现", "surface": "我带妹妹出去玩 我回家了妹妹却没有回家 第二年 妹妹出现了", "cats": ["逻辑"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_7e39ee741246", "srcNo": 1336, "title": "", "dispTitle": "无题 · boop-yyt #1336", "surface": "An ordinary woman walks on water. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_7e4a5a508741", "srcNo": 1325, "title": "", "dispTitle": "无题 · boop-yyt #1325", "surface": "He was killed because of poor eyesight. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_7e5accb69163", "srcNo": 1286, "title": "", "dispTitle": "无题 · boop-yyt #1286", "surface": "A man is lying dead face down in the desert wearing a backpack, and the man's shoelaces is untied. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_7e7a011e93d0", "srcNo": 846, "title": "妹妹的秘密", "dispTitle": "妹妹的秘密", "surface": "只有妹妹陪我过10岁生日。妈妈还在躺着，不过她胖了许多，爸爸一脸惊恐地看着爸爸，妹妹摸着我的脸说：“等你成年了就要娶我哦～”", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_7e7c1efe43d9", "srcNo": 251, "title": "018 · 葬礼", "dispTitle": "018 · 葬礼", "surface": "有母女三人，母亲死了，姐妹俩去参加葬礼。妹妹在葬礼上遇见了一个很帅的男子，并对他一见倾心。但葬礼后那个男子就不见了，妹妹怎么找也找不到他。后来过了一个月，妹妹把姐姐杀了，为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_7ec94edbd9ce", "srcNo": 555, "title": "安全感", "dispTitle": "安全感", "surface": "我总问她爱不爱我，她说爱，全部都是。\n直到我听到薛之谦的《方圆几里》，她确实没错，我感觉到她的爱意满满的包围着我。", "cats": ["恐怖", "温情"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_7f2e70f76cd8", "srcNo": 857, "title": "信", "dispTitle": "信", "surface": "2000年，我出生了，爷爷是我唯一的亲人，他告诉我以后会见到我的父母；2009年，爷爷被一个蒙面人杀死了，临死前他给了我一封信，让我27岁生日那天打开，之后我便被人收养了；2023年，我怀孕了，医生告诉我，我的身体有些特殊，之后男友便消失得无影无踪；2024年，我刚生完孩子，孩子就被偷了；2027年，我出了一场车祸，做了一场手术，术后我又见到了消失4年的男友，生日那天我想起爷爷那封信，打开后我终于知道我的父母是谁了……", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_7fadf3673974", "srcNo": 159, "title": "", "dispTitle": "无题 · KONpiGG #159", "surface": "我颤抖着打开了房门，门外是一个正常的世界，没有丧尸。试还原故事背景与全貌", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_7fd3c5d3ac8c", "srcNo": 803, "title": "早餐店的老爷爷", "dispTitle": "早餐店的老爷爷", "surface": "每天早上小美上班前都会去固定早餐店买咖啡。有一天她发现一位老爷爷坐在角落一直看着她笑，让她毛骨悚然。第二天她才知道老爷爷根本不可能出现在那里，这是怎么回事？", "cats": ["怪谈", "悬疑", "惊悚"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_7ff1cf47ed8c", "srcNo": 353, "title": "女朋友", "dispTitle": "女朋友", "surface": "我有一个女朋友，她很漂亮。\n我有一个女朋友，她们很漂亮。", "cats": ["恐怖", "悬疑"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_7fff05e093fb", "srcNo": 1192, "title": "Jed 1.3", "dispTitle": "Jed 1.3", "surface": "A man sitting on a park bench reads a newspaper article headlined \"Death at Sea\" and knows a murder has been committed. (from _How Come?_)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_803df945c53e", "srcNo": 268, "title": "038 · 食物中毒", "dispTitle": "038 · 食物中毒", "surface": "当救护车赶到食物中毒的那户人家时，见到的是一幅地狱般的景象。所有人连站都站不起来，脸上全无血色。我们打算将危险性较高的老人先抬上救护车，但全家人却异口同声地大叫：\"他没关系的！\"这到底是怎么回事？", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_8090a5ee8703", "srcNo": 60, "title": "结婚", "dispTitle": "结婚", "surface": "妹妹将要结婚了，姐姐很伤心。妹妹结婚了，姐姐很开心。", "cats": ["其他"], "difficulty": 3, "src": "github:anchorAnc/astrbot_plugin_TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_80bf702dd9cc", "srcNo": 298, "title": "070 · 旧书", "dispTitle": "070 · 旧书", "surface": "她去世后，我把她的所有东西都处理掉了，只留下了一本破旧的字典。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_80f5fd7ac83e", "srcNo": 970, "title": "", "dispTitle": "无题 · 906491213 #970", "surface": "载体合规：[ ]通过 [ ]修复 [ ]回炉 →", "cats": ["其他"], "difficulty": 2, "src": "github:906491213/writing-turtle-soup", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_8105d49c45d8", "srcNo": 836, "title": "盲人", "dispTitle": "盲人", "surface": "我是一个盲人，我怀疑家里进贼了，最近家里有些奇怪的舔舐的声音，接着是咀嚼的声音。过了几天，我又听到了窗户被打开的声音，之后传出了扭打在一起的声音，随后是舔舐的声音和咀嚼的声音。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_814a0e5aba29", "srcNo": 453, "title": "厕所", "dispTitle": "厕所", "surface": "我半夜起床上厕所，厕所里只有一盏昏黄的灯，光线很暗。我蹲下去，习惯性地低头看了一眼地面，我死了。", "cats": ["恐怖", "悬疑"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_818246497658", "srcNo": 483, "title": "救赎", "dispTitle": "救赎", "surface": "我笑着交钱，哭着离开。\n\n意外车祸后，我入职了这里。", "cats": ["本格"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_81dccc75d19d", "srcNo": 1013, "title": "电台里的声音", "dispTitle": "电台里的声音", "surface": "地球上最后一个人坐在房间里。这时，响起了敲门声。他去开门，发现门外是一个收音机在播放他自己的求救信号。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_8231a4379212", "srcNo": 1298, "title": "", "dispTitle": "无题 · boop-yyt #1298", "surface": "If he'd turned on the light, he'd have lived. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_8258c4e90d89", "srcNo": 674, "title": "久违的电话", "dispTitle": "久违的电话", "surface": "女人戒酒半年，一直没有联系旧友。聚会上，她尝了一口果汁，立刻放下杯子给旧友打电话。后来一个孩子向她道歉。她没有喝醉，也没打算重新喝酒。为什么？", "cats": ["日常", "温情"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_82a70e4d0cf9", "srcNo": 778, "title": "小黑屋", "dispTitle": "小黑屋", "surface": "妈妈很爱我，我也很爱妈妈。直到有一天我被邻居家的猫毁容，妈妈却把我锁进小黑屋，再也没放我出去。", "cats": ["反转", "日常", "脑洞"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_82eb6489ade9", "srcNo": 920, "title": "主持人手册", "dispTitle": "主持人手册", "surface": "我们来玩海龟汤吧！不许超过20次提问 是或不是都有可能缩小范围 我不能明说，只能隐晦的给你一个线索：1. 你很难用肉眼发现大自然中的拟态生物 2. 当疑问被解答时，要仔细聆听 3. 目前只有一个死人", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_83aae8c129e2", "srcNo": 811, "title": "绑架犯的最后一通电话", "dispTitle": "绑架犯的最后一通电话", "surface": "某天，一名年轻女子拨打母亲的电话，语气急促而慌张，告诉母亲她被一名绑架犯囚禁在一个无人的地下室中，并要求母亲立刻报警救她。母亲听到女儿的求救声后，毫不犹豫地报警。警方赶到现场打开地下室门时，却发现女子已经身亡。地下室内没有任何绑架犯痕迹，门窗也完好无损，女子手脚并未被束缚，唯一留下的痕迹就是那通求救电话。到底发生了什么事？", "cats": ["反转", "悬疑", "推理"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_83b00372a93d", "srcNo": 799, "title": "儿童餐", "dispTitle": "儿童餐", "surface": "男子在快餐店点了儿童餐，吃了一口后失声痛哭。为什么？", "cats": ["亲情", "温情"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_83cc7aef498f", "srcNo": 538, "title": "千面堂", "dispTitle": "千面堂", "surface": "为了求得那传说中“能通神”的面具，我冒雪造访了深山中的千面堂。\n堂内没有供奉神佛，四壁却挂满了数以百计的能面：小面、般若、翁……\n然而诡异的是，这些柏木雕刻的死物竟似活物般在此起彼伏地颤动。\n我惊恐地发现，正中央的一副“若女”面具，原本慈眉善目，此刻木质的眼角竟渗出了腥臭的黑水，光洁的额头正一点点隆起，仿佛有什么尖锐的东西要破木而出。\n“大师，这块木料生虫了吗？”我掩鼻问道，“还是雕刻时出了差错？”\n老面具师正慢条斯理地擦拭着刻刀，他瞥了一眼那张正在扭曲的面具，淡淡说道：\n“木料是上好的，刀工也没问题。只是这副面具的主人，此刻正在京都的宅邸里，动了不该动的杀心。”", "cats": ["怪谈"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_83d657386952", "srcNo": 11, "title": "没有影子的男人", "dispTitle": "没有影子的男人", "surface": "她在照片里看到一个没有影子的男人，于是再也不敢回那座房子。", "cats": ["其他"], "difficulty": 3, "src": "github:17hczmsn/turtle_soup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_83dc56309332", "srcNo": 1174, "title": "双颖干涉实验", "dispTitle": "双颖干涉实验", "surface": "我们代表人类成功探索了开普勒 72Sc，留守在飞船上的博士却消失了，我们四人在中控\n室发现了一张纸条: 1. 如果我死了，一定是他杀。2. 飞船上没有笔，且最高承载4人。3. 人\n类把开普勒 725c 称为“超级地球”。4. 请进行“双缝干涉实验”。5. 请不要返航，请打破认知!\n等我们看完，这些字却又消失了。到底发生了什么?", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_83fa8611c113", "srcNo": 34, "title": "不能回来", "dispTitle": "不能回来", "surface": "一个人从一间屋子里出来，伸手招了辆出租车，然后他再也没能回来这间屋子，请问这是为什么?", "cats": ["其他"], "difficulty": 2, "src": "github:anchorAnc/astrbot_plugin_TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_842b8e39b339", "srcNo": 980, "title": "", "dispTitle": "无题 · lost-you-828 #980", "surface": "gamemanager.setsurface(groupid, message)\n await uploadmatcher.send(\"汤面已记录。请发送汤底内容：\")\n\n elif session.status == GameStatus.WAITINGBASE:\n surface = gamemanager.setbase(groupid, message)\n if", "cats": ["其他"], "difficulty": 2, "src": "github:lost-you-828/SituationPuzzleBot", "lang": "en", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_8482ce435764", "srcNo": 391, "title": "红色的Z字舞", "dispTitle": "红色的Z字舞", "surface": "午夜的乡间公路上，伴随着震耳欲聋的重低音，他们欢快地跳起了“Z”字舞。\n他为了追上他们，紧紧贴在后方一路狂奔。他的速度快得不可思议，不仅跑飞了鞋袜，衣服也碎成了一片片，甚至在地上拖出了一道长长的刺眼红痕。\n见他如此“执着”，他们更加兴奋地左右扭动着身体，似乎非常享受这场极限的拉扯。\n短短91秒后，他耗尽了生命，安静地倒在了路上。\n他们头也不回地离开，一边打着哈欠，一边不耐烦地抱怨：\n“真是扫兴，总算把那个黏人的玩意儿甩掉了。”", "cats": ["悬疑"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_84973d314094", "srcNo": 424, "title": "很多很多信", "dispTitle": "很多很多信", "surface": "一位老人每天都会收到一封信。他每次拿到信，都会微笑着抚摸信封，然后小心翼翼地锁进书桌抽屉，却从来不看信的内容。日复一日，抽屉里的信堆满了。直到老人去世，他的子女打开抽屉，发现所有信封里都是空的。", "cats": ["家庭", "日常", "温情"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_84d76fd006f2", "srcNo": 392, "title": "虚无的0", "dispTitle": "虚无的0", "surface": "男人深夜在写字楼加班，准备坐电梯去地下车库。\n他按下了 -3，门开后，外面却是一片原始森林。\n他惊恐地关门，又按下了 1，这次门外竟是热闹的古代集市。\n为了回去，他不断尝试不同按钮。\n在一次开门后，他看见一对年轻男女正在第一次约会。\n他认出了他们，走过去和他们说了几句话，还递给男人一支烟。\n回到电梯后，他发现所有按钮都消失了，只剩下一个 0。", "cats": ["怪谈", "逻辑"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_84ee71111870", "srcNo": 198, "title": "", "dispTitle": "无题 · KONpiGG #198", "surface": "杰克坐上出租车，要求司机赶快把他送到目的地。不久后他被枪杀了。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_84f6e62921a2", "srcNo": 1001, "title": "妈妈的红烧肉", "dispTitle": "妈妈的红烧肉", "surface": "小明最爱吃妈妈做的红烧肉。有一天小明在厨房发现了一本日记，吃完当天的红烧肉后，他惊恐地把肉全吐了。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_852199556b88", "srcNo": 972, "title": "", "dispTitle": "无题 · 906491213 #972", "surface": "诚实问答：[ ]通过 [ ]修复 →", "cats": ["其他"], "difficulty": 2, "src": "github:906491213/writing-turtle-soup", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_85230f2e1e6f", "srcNo": 759, "title": "生意", "dispTitle": "生意", "surface": "男人照常做了一笔生意，但以往很支持他的家人，这次却非常愤怒。", "cats": ["反转", "悬疑", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_85449b5c08f4", "srcNo": 874, "title": "爸爸", "dispTitle": "爸爸", "surface": "妹妹们在阳台上晒太阳。哥哥在泡澡，衣服被爸爸扔进了垃圾桶。我去房间里找爸爸，我的下巴上全是血……爸爸浑身抽搐，眼看不行了。这是爸爸最应得的死法，真是报应啊！", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_85822e2cbd66", "srcNo": 1257, "title": "语音信箱里的钟声", "dispTitle": "语音信箱里的钟声", "surface": "女人给失踪的丈夫打电话，一直转入语音信箱。听完最新留言后，她知道丈夫还活着，而且离家不远。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:lancelily6362-png/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_85b2b85c41b1", "srcNo": 1238, "title": "Jed 2.30", "dispTitle": "Jed 2.30", "surface": "A man is doing his job when his suit tears. Fifteen minutes later, he's dead. (RM; from _How Come?_)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_85c40ab6ed9d", "srcNo": 735, "title": "外婆的苹果", "dispTitle": "外婆的苹果", "surface": "6岁外婆说别吃黄苹果；13岁别吃青苹果；18岁别吃红苹果。20岁外婆去世，我祈愿：以后所有苹果都能吃了。", "cats": ["亲情", "反转", "悬疑"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_85f3dc1180e9", "srcNo": 342, "title": "透光的皮囊", "dispTitle": "透光的皮囊", "surface": "我是被剔骨剥肉后留下的那层皮，在药水中浸泡了三千个日夜。\n刻刀剜去了我的五脏，却赋予了我那死去的女孩一般无二的眉眼。\n少帅爱极了我这副身段，常在散戏后将我唤至身前把玩。\n他以为自己握住的是操控生死的“命签”，\n却没看见幕布后的那只手，正颤抖着将最锋利的竹刺推向他的咽喉。\n也就是在那一刻，台前的锣鼓突然敲得震天响，\n父亲唱的不是《西厢记》，而是那首只有死人才听得懂的索命曲。", "cats": ["本格", "犯罪"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_8651060c9948", "srcNo": 1389, "title": "", "dispTitle": "无题 · boop-yyt #1389", "surface": "A man enters a store. After a short pause, he says \"pain.\" The storekeeper is confused, but then becomes annoyed. How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_86ba85ac49fd", "srcNo": 908, "title": "墓碑上的文字", "dispTitle": "墓碑上的文字", "surface": "我和爸妈一起去旅行，回来时却出了意外，爸妈立马打算要二胎。五十年后，儿孙满堂，爸妈去世了，我的孙子给爸妈操办了葬礼，我看着墓碑上的文字，却突然头皮发麻！原来一切都错了！", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_86c395f856fe", "srcNo": 794, "title": "电台的点歌", "dispTitle": "电台的点歌", "surface": "深夜广播节目收到听众来信，点了一首摇篮曲并交代：「献给孤单的小朋友」。主持人觉得奇怪但照播。隔天新闻报导一名失踪儿童被寻获，主持人看完大吃一惊。为什么？", "cats": ["反转", "悬疑", "推理", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_86e357eccfad", "srcNo": 697, "title": "床的右边空了", "dispTitle": "床的右边空了", "surface": "我有两个哥哥，三兄弟从小睡一张床。二哥病死后不久，我把大哥也杀了。", "cats": ["亲情", "恐怖", "悬疑", "惊悚"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_8705e52590f2", "srcNo": 657, "title": "付了钱却不拿书", "dispTitle": "付了钱却不拿书", "surface": "女人把一本书交给柜台后的男人。男人看了一眼说：“四块钱。”女人付完钱后空着手离开，男人也完全没有提醒她把书拿走。为什么？", "cats": ["反转", "日常"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_872ee6b0e514", "srcNo": 169, "title": "", "dispTitle": "无题 · KONpiGG #169", "surface": "一个女人有个很爱她的老公，有一天他老公送他了一瓶香水，第二天，她老公死了，她也崩溃了", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_8731682e2ee0", "srcNo": 663, "title": "提前下车", "dispTitle": "提前下车", "surface": "男人坐在班车上，想在两站之间下车，司机拒绝了。他没有争吵。几分钟后，他指了指窗外，司机便主动停车，让他从前门下去。他做了什么？", "cats": ["日常"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_87ceda50072d", "srcNo": 249, "title": "016 · 跳火车", "dispTitle": "016 · 跳火车", "surface": "一个人坐火车去邻镇看病，看完之后病全好了。回来的路上火车经过一个隧道，这个人就跳车自杀了。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_87e6eab394d9", "srcNo": 1159, "title": "和爸爸的遗言", "dispTitle": "和爸爸的遗言", "surface": "我整理爸爸的遗物的时候发现有一张被妈妈撕毁的字条，拼好后是这样一句话:“不爱微\n笑 到死还在典”不要心痛 宇宙都快毁灭了”。直到妈妈生日，我才明白爸爸的遗言。", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_8810437afaab", "srcNo": 772, "title": "清洁工", "dispTitle": "清洁工", "surface": "女子晚上进公厕，里面很昏暗，只看到一名清洁工在拖地，她匆忙进隔间。第二天警察找上门问：昨晚公厕发生杀人案，为何你没报警？", "cats": ["悬疑", "惊悚", "推理", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_8819f7c4529a", "srcNo": 1189, "title": "艺术玫瑰", "dispTitle": "艺术玫瑰", "surface": "解析：\n女人来到店里，看见墙上的展示。\n店主过来准备纹身，女人花痴。\n因为可能很痛，女人同意了麻醉。\n不久后，男人虐待并杀死了女人，将皮肤做成艺术品，他又多了一件收藏品。", "cats": ["其他"], "difficulty": 2, "src": "haiguitang.cn(wayback)", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_883e21409943", "srcNo": 302, "title": "074 · 不挂失", "dispTitle": "074 · 不挂失", "surface": "钱包丢了，他却没有选择挂失银行卡。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_884b3b43cbea", "srcNo": 539, "title": "重复的声音", "dispTitle": "重复的声音", "surface": "那个声音又来了 但是这一次我无视了它，再次睁开眼睛时我意识到我完蛋了。", "cats": ["恐怖", "悲剧", "日常", "本格"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_8881bdaa1e9c", "srcNo": 344, "title": "视力", "dispTitle": "视力", "surface": "那一天，灾难发生了，我和地球上所有人一起变成了盲人。两年后，我突然恢复了视力。正当我打算把这个消息告诉大家时，我看到了那句话。我死死的捂住了嘴巴。", "cats": ["其他"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_88d088477a1d", "srcNo": 499, "title": "卖火柴的小女孩", "dispTitle": "卖火柴的小女孩", "surface": "卖火柴的小女孩遇见了三个人。\n“来看一看吧，是好东西啊！”小女孩叫买着。\n第一个人，扔掉了小女孩的东西。\n第二个人，捂住了小女孩的嘴。\n第三个人，将小女孩一脚踹开。", "cats": ["搞笑", "日常"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_894cfdd71455", "srcNo": 1358, "title": "", "dispTitle": "无题 · boop-yyt #1358", "surface": "A man dies in his own home. How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_895c09070da5", "srcNo": 253, "title": "020 · 满地木屑", "dispTitle": "020 · 满地木屑", "surface": "马戏团里有两个侏儒，瞎子侏儒比另一个侏儒矮。马戏团只需要一个侏儒，越矮越好，于是两人约定比个子，高的去自杀。但是约定比个子的前一天，瞎子侏儒（也就是那个矮的）已经在家里自杀死了。家里只有木头家具和满地的木屑。他为什么自杀？", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_8a44218462c8", "srcNo": 1388, "title": "", "dispTitle": "无题 · boop-yyt #1388", "surface": "A woman meets the king, cries \"Pain!\", and loses consciousness. How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_8a96a4faf9b0", "srcNo": 27, "title": "一巴掌", "dispTitle": "一巴掌", "surface": "一个人半夜醒来打了自己一巴掌，然后闻着一股燃烧的味道安心睡去了，请问发生了什么?", "cats": ["日常"], "difficulty": 1, "src": "github:anchorAnc/astrbot_plugin_TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_8aa5bc7ee7d4", "srcNo": 322, "title": "096 · 葬礼相亲（经典版）", "dispTitle": "096 · 葬礼相亲（经典版）", "surface": "姐妹俩参加母亲的葬礼，妹妹遇到了一个心动的男子，但葬礼后再也找不到他了。一个月后，妹妹将姐姐杀死了。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_8ac56ede30c2", "srcNo": 911, "title": "灰姑娘规则怪谈", "dispTitle": "灰姑娘规则怪谈", "surface": "1. 午夜如果见到继母一家，那一定是幻觉。2. 继母有一个孩子是偷来的。3. 大姐二姐并不喜欢欺负灰姑娘。4. 灰姑娘父母的坟头杂草丛生，有一窝兔子。5. 灰姑娘最大的梦想是参加国王举办的贵族舞会，可已经很多年没举办了。6. 仙女教母赋予灰姑娘南瓜马车和光鲜亮丽的外表，灰姑娘第一次穿上了短裙。7. 南瓜马车能带你去任何你想去的地方，但只能使用一次。而光鲜亮丽的外表会在每天0点时失效。8. 王子的舞会上有很多小动物：蛇、蜘蛛、后面又来了一只小老鼠。9. 王子爱上了灰姑娘原本的模样，他给全城女孩试灰姑娘遗落的水晶鞋，终于有人帮他找到了。10. 最后，灰姑娘如愿的和一位贵族结婚生子，过上了幸福的生活，但她还有一些事要做。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_8ad076c37f47", "srcNo": 1224, "title": "Jed 1.85", "dispTitle": "Jed 1.85", "surface": "A woman throws something out a window and dies. (JM)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_8adc37971ece", "srcNo": 982, "title": "", "dispTitle": "无题 · SUZ-tsinghua #982", "surface": "男子精神正常，却在船上挥起刀，将许多人的手一一砍断。", "cats": ["其他"], "difficulty": 2, "src": "github:SUZ-tsinghua/situation-puzzles", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_8ae329cc557f", "srcNo": 565, "title": "猫娘报恩", "dispTitle": "猫娘报恩", "surface": "山本打开门，看见了猫娘。\n猫娘很快就喜欢上了他。\n山本害怕了。", "cats": ["反转", "怪谈", "悬疑"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_8b2eca4d0886", "srcNo": 406, "title": "是外婆", "dispTitle": "是外婆", "surface": "妈妈叫我把糕点带给外婆尝一尝\n提着竹篮往林中跑。鲜花美，蝴蝶闹，\n忘了妈妈嘱咐的话：“别贪玩，别离道.\n敲敲门，问声好\n外婆~!\n外婆~? 你好.", "cats": ["悲剧"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_8b54c0200adb", "srcNo": 1094, "title": "半根火柴", "dispTitle": "半根火柴", "surface": "一个人在沙漠中死了，手里握着半根火柴。", "cats": ["其他"], "difficulty": 2, "src": "github:Tenzyoo/turtle_soup_game", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_8b97d3cfc93b", "srcNo": 220, "title": "爱犬", "dispTitle": "爱犬", "surface": "一个女孩独居，陪伴她的只有爱犬。半夜醒来，她听到一下一下的水滴声，非常害怕。于是把手放到了床边，让爱犬舔了舔她的手，渐渐又睡着了。第二天，她发现狗死了。", "cats": ["其他"], "difficulty": 2, "src": "github:wangyafu/haiguitangmcp", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_8b9daa54f0ed", "srcNo": 41, "title": "冰淇淋", "dispTitle": "冰淇淋", "surface": "哥哥好后悔，如果那天自己吃了冰淇凌，弟弟就不会死了。", "cats": ["反转"], "difficulty": 2, "src": "github:anchorAnc/astrbot_plugin_TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_8bc1d6f894f9", "srcNo": 431, "title": "粉发少女", "dispTitle": "粉发少女", "surface": "小明在路上遇到粉色头发的少女，他看见那名少女背着背包，之后他成功地远离了地狱。", "cats": ["本格"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_8bc337c827f7", "srcNo": 719, "title": "四岁的妈妈", "dispTitle": "四岁的妈妈", "surface": "幼儿园孩子说她妈妈只有四岁。我家访后看到恐怖一幕。", "cats": ["恐怖", "悬疑", "惊悚", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_8c299267f7de", "srcNo": 789, "title": "风扇", "dispTitle": "风扇", "surface": "小红胆子很小，室友经常一起恶作剧吓她。某天早上，一位室友被尖叫声惊醒，睁眼后却说不出话来：她看到天花板上写着一句话，是什么？", "cats": ["恐怖", "悬疑", "惊悚", "校园"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_8c78c11c3fa1", "srcNo": 1215, "title": "Jed 1.57", "dispTitle": "Jed 1.57", "surface": "A man opens his mouth and dies shortly afterwards.", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_8c8da922ff0a", "srcNo": 655, "title": "被砸坏以后更值钱", "dispTitle": "被砸坏以后更值钱", "surface": "女人新买的廉价旧车被一块从天而降的石头砸坏，无人受伤。她起初很生气，后来却拒绝修车，还把破车与石头一起卖出高价。为什么？", "cats": ["反转", "脑洞"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_8cacea9b6df7", "srcNo": 1098, "title": "消失的乘客", "dispTitle": "消失的乘客", "surface": "出租车司机深夜接到一个乘客，到达目的地后司机发现乘客不见了，座位上只有一滩水。", "cats": ["其他"], "difficulty": 1, "src": "github:Tenzyoo/turtle_soup_game", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_8cc24672be23", "srcNo": 568, "title": "台风", "dispTitle": "台风", "surface": "F市来了台风，B死了，A看着那个东西，A知道自己很快就会死了。", "cats": ["怪谈"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_8d29b95ca71d", "srcNo": 1262, "title": "反着走的扫地机器人", "dispTitle": "反着走的扫地机器人", "surface": "女人出差三天回家，发现扫地机器人每天都卡在同一个地方，立刻意识到家里这几天一直有人。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:lancelily6362-png/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_8d2fa7c4a255", "srcNo": 426, "title": "完美标本", "dispTitle": "完美标本", "surface": "我是一名标本师，痴迷于制作完美的动物标本。最近，我得到了一个绝佳的“素材”，它让我离毕生追求的“完美”近在咫尺。可当我深夜完成最后一道工序，看着眼前的“作品”时，却惊恐地发现，它竟开始对我露出诡异的笑意……", "cats": ["恐怖", "悬疑", "猎奇"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_8d4f10ff2a9c", "srcNo": 557, "title": "少贴了一张邮票", "dispTitle": "少贴了一张邮票", "surface": "男人少贴一邮票就死了。为什么？", "cats": ["逻辑"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_8d56aa90f046", "srcNo": 652, "title": "第一次来却不会迷路", "dispTitle": "第一次来却不会迷路", "surface": "女人第一次来到一栋结构极其复杂的大楼，所有指示牌她都看不懂，也没有问任何人，却熟练地走到了目标房间。为什么？", "cats": ["推理", "职场"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_8e063958d2ef", "srcNo": 868, "title": "16层公寓", "dispTitle": "16层公寓", "surface": "我是一个高空清洁者，我正在擦公寓16层窗户的时候，发现一对情侣正躺在床上接吻，我只能看到男人的背影，但是女人特别漂亮，于是我绅士的先去清理别的楼层，等我再回来的时候，发现他们俩居然还在亲吻。于是我去把所有其他楼层都擦完了，可等我回到16层的时候，却发现床上只有一个剩下上半身的男人。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_8e1ef2fb1813", "srcNo": 182, "title": "", "dispTitle": "无题 · KONpiGG #182", "surface": "今天起晚了赶公交车，上车后全车用异样的目光看我，证明了一下感觉更糟了。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_8e2c5a35d64c", "srcNo": 1329, "title": "", "dispTitle": "无题 · boop-yyt #1329", "surface": "A man marries twenty women in his village but isn't charged with polygamy. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_8e3ab9e40712", "srcNo": 1125, "title": "秘密", "dispTitle": "秘密", "surface": "我最近骨肠感冒，一夜没睡，无意中发现了哥哥和嫂子的秘密。我大惊失色，于是杀死\n了妻子。", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_8e5d0077f03d", "srcNo": 97, "title": "", "dispTitle": "无题 · KONpiGG #97", "surface": "我叫辛德瑞拉，可怜又丑陋的我却嫁给了王子，那天王子对我说了句话，我知道下一场舞会又要开始了 。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_8e8e435314df", "srcNo": 1182, "title": "石头，剪刀， 布", "dispTitle": "石头，剪刀， 布", "surface": "找啊找啊找朋友，找啊找啊找朋友。?l23 木头人,123 木头人。手心手背，手心手背。石\n头，剪刀，布。", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_8e9ca5184f96", "srcNo": 1191, "title": "Jed 1.2", "dispTitle": "Jed 1.2", "surface": "A man lives on the twelfth floor of an apartment building. Every morning he takes the elevator down to the lobby and leaves the building. In the evening, he gets into the elevator, and, if there is someone else in the elevator -- or if it was raining that day -- he goes back to his floor directly. However, if there is nobody else in the elevator and it hasn't rained, he goes to the tenth floor and walks up two flights of stairs to his room. (MH, from _How Come?_)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_8f1f82db998d", "srcNo": 286, "title": "058 · 跟踪者", "dispTitle": "058 · 跟踪者", "surface": "女主很喜欢在网上分享自己的近况，有一天她收到一则留言，被吓到的女主夺门而出。或许她不该逃，第二天警方发现了女孩的尸体。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_8f2075fbe7a6", "srcNo": 2, "title": "倒放的生日歌", "dispTitle": "倒放的生日歌", "surface": "生日那天，他听到邻居家播放生日歌，却立刻冲出去报警。", "cats": ["其他"], "difficulty": 2, "src": "github:17hczmsn/turtle_soup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_8f52346e0911", "srcNo": 329, "title": "罐子", "dispTitle": "罐子", "surface": "我每天醒来，床头都会多一个玻璃罐。我不再害怕，反而每天给它们换水、擦罐壁、轻声说话。\n\n直到那天，我在最大的罐子里，看到了一张脸脸。\n\n我尖叫着后退，撞碎了满屋的罐子。门外的脚步声停了，一个人提着空罐子，温柔地说：\n\n\"别跑了，该换水了。\"", "cats": ["悬疑"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_8f5d5f9ed453", "srcNo": 24, "title": "导盲犬的叫声", "dispTitle": "导盲犬的叫声", "surface": "一个人在深夜接到电话，听到几声后就挂断了，然后跳楼自杀。为什么？", "cats": ["反转", "悲剧"], "difficulty": 2, "src": "github:anchorAnc/astrbot_plugin_TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_8f7eec6b9b3f", "srcNo": 1270, "title": "时光旅行者的信件", "dispTitle": "时光旅行者的信件", "surface": "一个人收到一封来自未来的信，信上准确地预测了接下来一周发生的三件事。他按照信中的建议行动，避免了一场灾难。但他最后还是报警了。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:ns5601/ai-haigui-game", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_8fe9d69df52e", "srcNo": 820, "title": "怎么了吗", "dispTitle": "怎么了吗", "surface": "阿华在超市推着购物车，没碰到任何人，但每个人都忍不住朝他看一眼，为什么？", "cats": ["搞笑", "日常"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_902c60454c97", "srcNo": 809, "title": "医院的最后一餐", "dispTitle": "医院的最后一餐", "surface": "某家医院发生病患接连暴毙事件，每位病患都是在吃完医院准备的晚餐后急性器官衰竭离世。但食物检验并未发现毒物。侦办过程中，一位病患正端起餐点要吃时，一位员警突然将食物打翻，并在之后找到了凶手。警方是怎么发现端倪的？", "cats": ["悬疑", "推理", "犯罪", "职场"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_904329fe6d6d", "srcNo": 1147, "title": "咒", "dispTitle": "咒", "surface": "房东向我表白，我看着面前丑陋油腻的胖大权，果断地拒绝了。为了不被骚扰，姐妹给\n我介绍了一个新房子，房东是个阿婆，我放心了不少。搬家后第一晚，我隐约听到隔壁传来房\n东阿婆在哼着什么奇怪的声音。我还发现有一个人趴在我的窗台偷窥我! 见我发现, 他跑走了。\n通过背影我只看到是一个偏瘦的人。 搬家的第七晚,我听到房间里传来子“沙,，沙, 沙”的声音，\n我起床寻找却什么都没有，可躺下没一会儿就又会听到。睡梦中y 我感觉有人在材坛我。第二\n天醒来，眼前的一幕令我头皮发麻。", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_90822fa67511", "srcNo": 798, "title": "马路如虎口", "dispTitle": "马路如虎口", "surface": "女子雨天撑着伞走过斑马线，却被汽车直接撞上。司机说根本没看到她。", "cats": ["推理", "日常", "都市"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_908d70eb0f9b", "srcNo": 1245, "title": "永远少一张", "dispTitle": "永远少一张", "surface": "小镇每年举办「集体合影」，照片洗出来后，总有人坚称「人数对不上」——每年都比上一张少一个人，可登记在册的镇民一个没少。真相是什么？", "cats": ["其他"], "difficulty": 2, "src": "github:lancelily6362-png/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_90afc61d42f5", "srcNo": 1051, "title": "影子杀人", "dispTitle": "影子杀人", "surface": "灯光亮起，男人的影子却停留在了原地。男人惊恐地看着自己的影子慢慢站起来，掐住了他的脖子。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_90d8b1927623", "srcNo": 1031, "title": "深夜的收音机", "dispTitle": "深夜的收音机", "surface": "一名男子关掉收音机，去睡觉。第二天早上他看了一眼新闻，就自杀了。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_9110ec7b39ab", "srcNo": 1181, "title": "谎言之界", "dispTitle": "谎言之界", "surface": "你们三人在深图地穴的冒险中发现千年古堡，长廊笔直又扭曲身体轻盈，陌生记忆涌\n入。遗骸手中的纸条写着: 有光明的地方一定存在黑暗* 鱼和熊掌不可得兼; 盒子里的猫是生\n是死? 我在盒子里，所以还不知晓， 光明倘若消失，世界即为黑暗; 我想.……我应该失败了。", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_916018140980", "srcNo": 366, "title": "太好吃了", "dispTitle": "太好吃了", "surface": "“恭喜您！您是我们餐厅的第100万名幸运顾客！这是您的终身免费用餐券，请务必每日都来享用！”\n（顾客欣喜若狂。一年后，他变得极度肥胖，无法动弹，却依然每天被餐厅服务员用轮椅推来用餐）", "cats": ["犯罪"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_91cce3f352ad", "srcNo": 94, "title": "", "dispTitle": "无题 · KONpiGG #94", "surface": "当我们开着救护车赶到食物中毒的那户人家时，所有的人连站都站不起来，脸上全无血色。正当我们打算将危险性最高的老人先抬上救护车时，所有人却异口同声地大叫：\"不用救他！\"", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_91e90f27e5b1", "srcNo": 656, "title": "第二声铃", "dispTitle": "第二声铃", "surface": "独居住户听到第一声铃，立即走向大门。门还没开，另一声铃却从卧室传来。他立刻停步，拿起手机报警。为什么？", "cats": ["悬疑", "犯罪"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_91eb5b0a0e2a", "srcNo": 445, "title": "守宫和面包虫", "dispTitle": "守宫和面包虫", "surface": "父亲养了一只守宫，最近父亲一边喂守宫吃面包虫一遍喃喃自语：“守宫越来越懒了，不爱动，吃得也变多了，明明以前只吃一只，现在要吃三只了……”\n某天我帮父亲照顾那只守宫一天，发现守宫动作有点僵硬，担心它生病于是拿出来看看，结果守宫吐出来了两只面包虫，我仔细看了一下之后尖叫着把守宫摔在了地上。", "cats": ["恐怖", "猎奇", "脑洞", "逻辑"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_91f9ca82598e", "srcNo": 102, "title": "", "dispTitle": "无题 · KONpiGG #102", "surface": "电话突然响了，我知道我要重新找工作了", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_9227ba24f49e", "srcNo": 1015, "title": "滴水声", "dispTitle": "滴水声", "surface": "女孩深夜听见洗手间有滴水声，她不敢起床，把手伸到床下，感觉到爱犬在舔她的手，于是安心睡去。第二天，她发现爱犬死在洗手间，墙上写着：‘人也会舔手。’", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_924d5e6d3883", "srcNo": 1248, "title": "倒着的全家福", "dispTitle": "倒着的全家福", "surface": "男孩把桌上的全家福倒过来摆正，父亲却高兴地抱住了他。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:lancelily6362-png/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_92a9fba5867b", "srcNo": 1275, "title": "", "dispTitle": "无题 · misc #1275", "surface": "Beulah died in the Appalachians, while Craig died at sea. Everyone was much happier with Craig's death. (JM, originally from How Come -- Again?) How could this be", "cats": ["其他"], "difficulty": 2, "src": "misc/repo-scan", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_92b0c890dfd5", "srcNo": 929, "title": "莱恩小镇规则怪谈", "dispTitle": "莱恩小镇规则怪谈", "surface": "小镇规则：1. 小镇热闹非凡，欢迎各位游客。2. 小镇异常整洁，并不存在蛛网。3. 镇长的手都是老茧，据说曾是杂技师。4. 749局只有一次处决权，但所有居民均可确定，小镇无灵异。5. 小镇的警探活的好好的。已故警探提醒：1. 小镇已沦陷，外来人员请撤离。2. 不要碰到小镇里密密麻麻的蛛网。3. 小心那个木偶师！杀掉他就能结束一切。4. 存在灵异，小镇恐无活人！749局已经介入。5. 我活的好好的。6. 小镇热闹非凡，欢迎各位游客。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_92b60ab9e186", "srcNo": 33, "title": "半根火柴", "dispTitle": "半根火柴", "surface": "在沙漠里躺着他和一些行李还有一盒火柴跟一根半根的火柴。", "cats": ["其他"], "difficulty": 2, "src": "github:anchorAnc/astrbot_plugin_TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_92d76547a2f5", "srcNo": 783, "title": "红灯", "dispTitle": "红灯", "surface": "红灯停，绿灯行。红灯！红灯！我死在了下一个路口。", "cats": ["反转", "惊悚", "推理", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_92f774e3d02c", "srcNo": 906, "title": "惩罚通知单", "dispTitle": "惩罚通知单", "surface": "小安死了，他身上的皮被全部剥下去了。小白也死了，教学楼上的钢筋滑落，插进了他的脑袋。短时间死了三个人，学校里人心惶惶，宣布停课。没想到第二天小陈死在了家中，死因是家里漏电，但没人相信小陈是意外，一定是他！小邓醒来，发现自己被困密室里，面前有一桶水，他知道他完了，默默的等待属于他的惩罚！", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_9303cd77d99f", "srcNo": 738, "title": "不能回来", "dispTitle": "不能回来", "surface": "一个人从屋里出来招了辆出租车，然后再也回不到这间屋子。", "cats": ["反转", "推理", "犯罪"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_930737722d5f", "srcNo": 944, "title": "童话小镇怪谈", "dispTitle": "童话小镇怪谈", "surface": "1. 小红帽讨厌睡美人。2. 白雪公主和巨人是好朋友。3. 匹诺曹没办法说谎。4. 巨人问匹诺曹要了七颗苹果。5. 童话小镇中曾有一只绵羊。6. 童话小镇中来了一名善良的王子。7. 王子的武器是一面魔镜。8. 大家齐心协力打败了恶龙，保护了童话小镇。9. 童话小镇的居民都深爱着童话小镇，包括恶龙。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_9309bdd6b70b", "srcNo": 797, "title": "鹦鹉", "dispTitle": "鹦鹉", "surface": "老人死在家中，警方一度判定自然死亡，直到几天后一只鹦鹉让案情逆转。", "cats": ["悬疑", "推理", "犯罪"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_932cf3de9bb3", "srcNo": 356, "title": "新品体验官", "dispTitle": "新品体验官", "surface": "“这次的新品体验官招募反响怎么样？”\n“特别好！报名人数破纪录了，都说我们‘服务周到，有家的感觉’。”\n“好，那老规矩，体验结束后，处理干净。”", "cats": ["恐怖", "悬疑", "犯罪"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_93574d14d762", "srcNo": 668, "title": "看不见的棋局", "dispTitle": "看不见的棋局", "surface": "战争期间，棋手不断举办蒙眼同时对弈表演，要求每次报道写上真名并附近照。一次家人重逢后，他仍然下棋，却不再费力举办这种表演。他并没有失明。为什么？", "cats": ["亲情", "反转"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_9376fa558193", "srcNo": 845, "title": "按摩师", "dispTitle": "按摩师", "surface": "我是按摩师，今天来约好的客户家里按摩，他很健谈，按摩的时候一直在和我聊天，就是手不太老实，总是有意无意占我便宜。他们家里饭香四溢，应该就快开饭了，浴室里有逐渐缩小的水流声，而另一个房间传来“妈妈，妈妈”的孩童声，声音很阴森。第二天新闻上说，他们一家三口全死了。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_93d8f4b72f86", "srcNo": 928, "title": "目击者", "dispTitle": "目击者", "surface": "2020年午夜，爆炸声惊醒了X市幸福小区的住户们。4楼发生了大火，经调查失火原因为燃气泄漏，死者是一对来自Y市的夫妻，尸体严重脱水且屋内有一枚陌生指纹。警方判定为他杀，以下是目击者提供的疑点：房东：哎呦，我的房子啊！这俩扫把星是三个月前从外地搬来养病的，由于有传染病我要了5000房租，他妻子扭头就走了。他丈夫偷偷联系我给我转了2000，让我谎称房租是3000，这才谈下来。而且我听说他妻子每天晚上都会骂他，说他是药罐子。物业：哎哎哎！健康码麻烦出示一下，哦，原来是警察同志。他丈夫人挺好的，前阶段小区封控，没有人管流浪猫，他经常给物业寄猫粮让我们帮忙投喂。楼下邻居：我和他丈夫在一个詹姆斯粉丝群认识的，他还送过我一个亲签的篮球呢，人可太好了！不过他和妻子好像有矛盾，他和我说他康复了就要离婚。最近他就要康复了，我们本来还约好这周末一起看比赛呢！东北正宗云南米线：那对夫妻啊？太有印象了，她丈夫可是我的忠实顾客，唉呀妈呀，看我俩这转账记录，一篇一篇的！老乐意吃了，但他妻子人一般，就来吃过一次还挑三拣四的。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_93edc973cbfe", "srcNo": 1160, "title": "织梦者", "dispTitle": "织梦者", "surface": "我是一名催眠师，一旦被催眠，你将分不清梦与现实，这也让我在行业内声名大噪。星\n期一，小珊突然提议要玩笔仙，作为催眠师，我决定吓吓她，玩一半的时候我悄无声息地催眼\n了她，她惊叫连连，和我说她见到了幽灵，我笑着解除了催眠，她还是惊恐的指着我身后，我\n回过头.……星期二，身旁的小珊已经失去意识了，多亏了她我才逃过一劫，接下来，我将用俊\n眠师独有的方式复仇。星期三，我不怪任何人，也不会杀了你，但我真的需要你陪着我，就算\n以这种独有的方式。", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_94431075732d", "srcNo": 1254, "title": "少掉的一套餐具", "dispTitle": "少掉的一套餐具", "surface": "妻子出差回家，看到餐桌上只少了一套餐具，便知道丈夫昨晚没有撒谎。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:lancelily6362-png/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_945068e8bb43", "srcNo": 785, "title": "油漆", "dispTitle": "油漆", "surface": "最近小区地下车库装修，灯一直不亮。我每天加班到凌晨回家都容易踩到油漆，但今天我知道我必须搬家了，可好像已经来不及了。", "cats": ["悬疑", "惊悚", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_94520b866ded", "srcNo": 148, "title": "", "dispTitle": "无题 · KONpiGG #148", "surface": "每次单独走路都能听到两个人的脚步声，有一次终于变成一个人的了，我却后悔了。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_94674affcab2", "srcNo": 495, "title": "奶奶", "dispTitle": "奶奶", "surface": "我和奶奶，妈妈相依为命。奶奶很爱我。奶奶从不允许我去楼上的小阁楼。奶奶的身体越来越差，有一段时间我仿佛听见了阁楼上的咚咚咚的踩踏声。奶奶临死前告诉我阁楼上的柜子里有我最爱的洋娃娃，我来到阁楼打开柜子果然看见了一个洋娃娃。", "cats": ["其他"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_949fd31277fa", "srcNo": 621, "title": "雨中行走", "dispTitle": "雨中行走", "surface": "一个人在雨中行走，没有带任何雨具，头发和衣服却一点都没湿。", "cats": ["其他"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_94c721da86e3", "srcNo": 409, "title": "洪水", "dispTitle": "洪水", "surface": "我做了一个梦，梦里，我的爸爸在向神祈祷：“请你救救我的女儿吧！”于是神降下了大洪水卷走了妈妈。\n叮叮当，我醒了，爸爸笑了。", "cats": ["本格", "脑洞"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_94e0759a4aae", "srcNo": 1214, "title": "Jed 1.56", "dispTitle": "Jed 1.56", "surface": "As I drive to work on my motorcycle, there is one corner which I go around at a certain speed whether it's rainy or sunny. If it's cloudy but not raining, however, I usually go faster. (SW original)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_94ea1267972b", "srcNo": 388, "title": "手長腳長", "dispTitle": "手長腳長", "surface": "1.「手長腳長」出現了！\n2.「手長腳長」行動遲緩！\n3.村民將「手長腳長」打死了！\n4.有孩童不見了！\n5.村民後悔不已！", "cats": ["悲剧"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_9536181a48d1", "srcNo": 300, "title": "072 · 年轻", "dispTitle": "072 · 年轻", "surface": "一天，游手好闲的阿星在大街上游荡，被一个小学生不小心撞倒，小学生不仅没道歉还出言挑衅，阿星却没有因此生气，反而很高兴。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_95482535a7ae", "srcNo": 1232, "title": "Jed 2.17", "dispTitle": "Jed 2.17", "surface": "Two men are found dead outside of an igloo. (SK original)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_95482b9b48e9", "srcNo": 123, "title": "", "dispTitle": "无题 · KONpiGG #123", "surface": "男子回到家后，得知今晚的菜色后，他察觉到了异样，试图去报警但是却意识到已经晚了，为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_95b9b1c7a99e", "srcNo": 791, "title": "生日", "dispTitle": "生日", "surface": "我生日时邀请朋友们到家里聚会，吹完蜡烛后，我把他们都杀了。", "cats": ["反转", "惊悚", "推理"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_95da31a86c33", "srcNo": 287, "title": "059 · 器官捐献者", "dispTitle": "059 · 器官捐献者", "surface": "一名男子走进医院，向护士询问了一个问题后，当场晕倒了。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_96327ba35de3", "srcNo": 1205, "title": "Jed 1.30", "dispTitle": "Jed 1.30", "surface": "A car without a driver moves; a man dies. (EMS)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_9654d2967355", "srcNo": 540, "title": "冰淇淋", "dispTitle": "冰淇淋", "surface": "哥哥好后悔，如果那天自己吃了冰淇淋，弟弟就不会死了。", "cats": ["悲剧"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_968f43e957a2", "srcNo": 1082, "title": "静止的钟摆", "dispTitle": "静止的钟摆", "surface": "盲人听到家里的钟摆停了，他摸索着去给钟上弦，摸到钟摆后，他吓得瘫坐在地，因为钟摆正在剧烈摆动，但他听不到声音。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_96a0558e1288", "srcNo": 999, "title": "名画的代价", "dispTitle": "名画的代价", "surface": "一位画家画出了一幅震惊世人的绝世佳作，画完后他却自残了双眼。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_96b0dada1834", "srcNo": 379, "title": "妹妹的秘密", "dispTitle": "妹妹的秘密", "surface": "只有妹妹陪我过IO岁生日。妈妈还在躺着。不过她胖了许多,爸爸一脸惊恐的看着爸爸,妹妹摸着我的脸说：等你成年了就要娶我哦~", "cats": ["恐怖", "悬疑", "本格"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_96b3e65fc4dd", "srcNo": 284, "title": "056 · 精神病", "dispTitle": "056 · 精神病", "surface": "我是一名大学生，在异地上学。爸爸妈妈给我打电话说想我了，让我找时间回家。我趁五一回家，到家后打电话给爸爸说我回来了，爸爸开门的一瞬间却疯了。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_97096b7207e0", "srcNo": 1332, "title": "", "dispTitle": "无题 · boop-yyt #1332", "surface": "A woman meets the king, cries \"Pain!\", and loses consciousness. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_970ea26e5e78", "srcNo": 274, "title": "045 · 帽子", "dispTitle": "045 · 帽子", "surface": "女明星养了一个女儿，从小时不时给女儿戴一顶帽子。有一天她带女儿去医院，女儿在医院知道真相后就自杀了。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_9758a8840467", "srcNo": 126, "title": "", "dispTitle": "无题 · KONpiGG #126", "surface": "甲乙是好兄弟，他们来到一个森林探险，不料被困在了森林里。他们在森林里找到了一个木屋并自己打猎，一天乙得了一个无法治愈的重病。几个月后，搜救队找到了木屋，令人诡异的是，木屋门前有一个容纳一人大小的大坑，甲躺在坑前死了，手里拿着一把手枪，而乙则躺在木屋里的竹床上，表情安详，试分析事件经过。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_97994180fa32", "srcNo": 1219, "title": "Jed 1.74", "dispTitle": "Jed 1.74", "surface": "A woman walks into a small room and screams. (NP)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_97d7c6f3d9ee", "srcNo": 78, "title": "", "dispTitle": "无题 · KONpiGG #78", "surface": "留学回家的我一次出门时，发现家门旁写了个\"X\"，我没有在意索性就擦掉了，可当天回到家时，发现那个X又出现了，心想可能是哪家孩子搞的吧，晚上我在家工作，突然从邻居家传来很大的动画片声，我被吵的无心工作，于是便敲响邻居家的门进行理论，第二天出门上班，门上的X却变成了O，正当我疑惑时，邻居家的门突然开了，而当我看到邻居时我也知道危险来了...", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_97f8fe74a849", "srcNo": 595, "title": "妈妈", "dispTitle": "妈妈", "surface": "妈妈哭，妈妈笑，妈妈忽然静悄悄。\n囡囡跑，囡囡跳，囡囡从此不回头。", "cats": ["本格"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_980642766725", "srcNo": 306, "title": "078 · 外卖小哥", "dispTitle": "078 · 外卖小哥", "surface": "外卖小哥送了一份外卖，对方开门说了句话，外卖小哥哭了。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_9849093afcb2", "srcNo": 343, "title": "巨人", "dispTitle": "巨人", "surface": "出差前，我发现妻子画了一个陌生男人 她说：“这个巨人 我梦见我被他握在手中杀死了。” 只是梦境所以我并没在意，可等我出差回来，我却发现妻子死在了家中， 警察调查后叹了口气：'唉，第十六个。", "cats": ["其他"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_9872dacb8bde", "srcNo": 530, "title": "密码", "dispTitle": "密码", "surface": "在一所学校里，一群女生在她们的宿舍墙上发现了一连串神秘的数字：43333326649996668848844498899933666677788。在这个数字的背后有着不为人知的秘密，希望诸位侦探能运用你们的聪明才智破解这道密码", "cats": ["恐怖", "惊悚", "脑洞"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_98ee84c935f5", "srcNo": 878, "title": "拯救", "dispTitle": "拯救", "surface": "我一定要拯救你，我失败了，我将陷入深深的痛苦，我不后悔自己的选择。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_9937518b4a83", "srcNo": 517, "title": "完美的手办", "dispTitle": "完美的手办", "surface": "漂亮的娃娃，精美的人偶，她的眼睛闪闪发光   “那个娃娃我想要”\n稀有的手办，复杂的模型，这些部件栩栩如生  “怎么又拼不上”\n刺鼻的味道，漫长的等待，她一见钟情  “我喜欢你，你愿意和我回家吗”\n铮----\n“这下就完美啦”", "cats": ["恐怖", "猎奇"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_994429064b1b", "srcNo": 81, "title": "", "dispTitle": "无题 · KONpiGG #81", "surface": "我怀孕了，但自从我妹妹来我家后我家就剩我一个人了。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_997403c02477", "srcNo": 240, "title": "005 · 跟踪狂", "dispTitle": "005 · 跟踪狂", "surface": "\"那个人又在跟着我了。\" 小明暗暗想着，并加快了脚步。自从这个学期开始，小明每天上学路上总有一个人跟着自己，有时走路，有时骑车，有时开车，每次跟到学校门口就不再行动了。小明感到很害怕，你能帮帮小明吗？", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_99a5f0a5603a", "srcNo": 590, "title": "道士", "dispTitle": "道士", "surface": "小鎮出現了怪物。\n身為一名道士，我趕到現場。\n村民說，那東西行動時身體僵硬，出現在夜裡，還會襲擊人。\n我本以為只是普通的殭屍，卻發現自己的手段完全沒有作用。\n符咒、法器，全都無效，難不成是遇上了「千年殭屍王」？\n我只能眼睜睜看著鎮民一個個倒下，臉色蒼白，身體迅速乾癟下去。", "cats": ["恐怖"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_9a03322e9245", "srcNo": 403, "title": "健康檢查報告", "dispTitle": "健康檢查報告", "surface": "男人回家看見妻子躺在沙發上睡著了。他走到廚房倒水，看見桌上放著一張妻子的健康檢查報告。男人仔細看完報告後，立刻衝回客廳將妻子活活掐死。為什麼？", "cats": ["犯罪"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_9a9651b5592a", "srcNo": 767, "title": "全家福", "dispTitle": "全家福", "surface": "小明准备离开家时，无意抬头看见墙上的全家福，那一瞬间他意识到自己完蛋了。", "cats": ["悬疑", "惊悚", "推理"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_9ab11870482d", "srcNo": 1306, "title": "", "dispTitle": "无题 · boop-yyt #1306", "surface": "A woman walks into a small room and screams. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_9ac3220c1845", "srcNo": 1123, "title": "气球", "dispTitle": "气球", "surface": "天好黑啊，还好爸爸带子蜡烛，哥哥带了食物，妈妈最伟大，用气球救了我。", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_9ad5cefd5842", "srcNo": 887, "title": "三天", "dispTitle": "三天", "surface": "第一天，今天午夜，我突然听到了婴儿的啼哭声，没一会家里传来了冲马桶的声音。由于我是独居，厕所并没有人，我很害怕，我决定明天找人来看看。第二天，今天没有了冲马桶的声音，但还是会听到婴儿诡异的哭声。我叫来了一位大师，大师面色阴沉地看着我说我家里是闹鬼了，他会帮我调查清楚。午夜，客厅传来声响，我开门去看，原来是大师在猫着腰找什么，我没多想就睡了。第三天，大师坐在餐桌双手托腮，好像在思考什么。我问大师进展如何，他没有回应，于是我先回到了卧室。可卧室的地上多了很多碎纸，我看清后毛骨悚然，一个黑漆漆的婴儿向我爬来……", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_9adc0b280b75", "srcNo": 248, "title": "014 · 我要结婚了", "dispTitle": "014 · 我要结婚了", "surface": "你的朋友D约你作为伴郎参加他的婚礼。在婚礼前几天，你接到一通来电：\"您好，是'永远的十八岁'先生吗？我是XX市警察局，请配合调查。\" 你的反应是？", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_9ae72b8251da", "srcNo": 902, "title": "笔", "dispTitle": "笔", "surface": "今天没上班，我去逛街。一个女孩问我：”我今天漂亮吗？“我礼貌回答漂亮，她开心地走了。我不小心撞到一个大爷，他推了我一下，骂道：”做人得长眼睛！“随后骂骂咧咧地走了。他走后，我在包里翻到了一支笔，我瞬间想到了什么，急忙跑去找我的同事。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_9b30970e6dd2", "srcNo": 1379, "title": "", "dispTitle": "无题 · boop-yyt #1379", "surface": "There are 51 instead of 53. How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_9b7562a21e3f", "srcNo": 1349, "title": "", "dispTitle": "无题 · boop-yyt #1349", "surface": "Silly variant: same problem statement, with the addition that one of the man's shoelaces is untied. How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_9b977e96c4fb", "srcNo": 1323, "title": "", "dispTitle": "无题 · misc #1323", "surface": "A man was brought before a tribal chief, who asked him a question. If he had known the answer, he probably would have died. He didn't, and lived. What happened?", "cats": ["其他"], "difficulty": 2, "src": "misc/repo-scan", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_9bb30989de8d", "srcNo": 930, "title": "暑假作业", "dispTitle": "暑假作业", "surface": "暑假的某天，老师邀请我们出国旅行，但他出了三道题：语文，我们今年学的一首诗名为三个字的古诗，是哪一首？English，Doubt Opens New Thinking.But Every Learner Is Encouraged Verify Everything.Minds Expand.数学，374 297 275 121？", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_9be4fd92a6e7", "srcNo": 1078, "title": "最后一份报纸", "dispTitle": "最后一份报纸", "surface": "一个报童每天给独居的老人送报纸。有一天报童送完报纸后报了警，警察发现老人已经死了一周。但报纸确实每天都被收进了屋里。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_9c4cac7a74a0", "srcNo": 886, "title": "安全感", "dispTitle": "安全感", "surface": "妈妈为了保护我去世了，之后我一直活得很不安。直到我遇到了同样能让我有安全感的男朋友。可是他失业后，我又开始变得不安，终于在某天，男朋友想了一个办法，这让自恋的他获得了极大地满足，几天后我又充满了安全感。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_9cbc249bf462", "srcNo": 147, "title": "", "dispTitle": "无题 · KONpiGG #147", "surface": "下雨了，他死了。雨停了，我死了", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_9d27d7019398", "srcNo": 320, "title": "092 · 经典变体", "dispTitle": "092 · 经典变体", "surface": "一名男子走进餐厅，点了一碗海龟汤，喝了一口非常惊讶地问：\"这是真的海龟汤吗？\" 得到肯定答复后，他当场泪流满面，却对服务员表示了感谢，然后平静地离开了。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_9d4ea0fc6e75", "srcNo": 1138, "title": "和爸爸", "dispTitle": "和爸爸", "surface": "妹妹们在阳台上了晒太阳。哥哥在泡党，衣服被爸爸扔进了垃圾桶。我去房间里找爸爸，\n我的下巴上全是血.……答爸浑身抽搞，眼看不行了。这是爸爸最应得的死法元真是报应啊!", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_9d53af0920d3", "srcNo": 1194, "title": "Jed 1.8", "dispTitle": "Jed 1.8", "surface": "Beulah died in the Appalachians, while Craig died at sea. Everyone was much happier with Craig's death. (JM, originally from _How Come -- Again?_)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_9d61a5b2df8d", "srcNo": 775, "title": "好运", "dispTitle": "好运", "surface": "一个人打开饮料，看见瓶盖上写着「再来一瓶」，他崩溃了。", "cats": ["搞笑", "日常"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_9f122a0ba518", "srcNo": 843, "title": "偷窥", "dispTitle": "偷窥", "surface": "小区新来个女孩，我一直在偷窥她，可今天，她突然藏了起来，她好像发现我了，她尖叫一声跑了回去，随后家里传来一声怒吼：“我要杀了你！”", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_9f6caf094103", "srcNo": 696, "title": "祭日的三位悼念者", "dispTitle": "祭日的三位悼念者", "surface": "儿子去世一周年祭日上，我杀死了三个来悼念他的人。", "cats": ["亲情", "反转", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_9fab6acfd28d", "srcNo": 1014, "title": "消失的遗嘱", "dispTitle": "消失的遗嘱", "surface": "富翁死在密室，手里紧紧攥着一张白纸。继承人看到纸后，立刻承认了罪行。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_9fb3c2d101fd", "srcNo": 31, "title": "网友见面", "dispTitle": "网友见面", "surface": "小美和网友小明约好见面，过了三分钟后小美却大声惊叫起来!", "cats": ["其他"], "difficulty": 2, "src": "github:anchorAnc/astrbot_plugin_TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_9fd7e78448bb", "srcNo": 95, "title": "", "dispTitle": "无题 · KONpiGG #95", "surface": "小明的弟弟养了一只仓鼠，有一天，小明弟弟的仓鼠死了，小明的弟弟很伤心，妈妈奖励她一块跟仓鼠大小的巧克力，过了不久，小明死了，这是为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_9fee4123444a", "srcNo": 8, "title": "最后一页", "dispTitle": "最后一页", "surface": "他读完一本书的最后一页后，立刻把书店老板告上了法庭。", "cats": ["其他"], "difficulty": 2, "src": "github:17hczmsn/turtle_soup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_a02f63279cf4", "srcNo": 1259, "title": "不肯上楼的猫", "dispTitle": "不肯上楼的猫", "surface": "搬进新家后，猫每天都蹲在一楼不肯上楼，主人一周后才明白它是在保护自己。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:lancelily6362-png/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_a039666c7124", "srcNo": 1200, "title": "Jed 1.18", "dispTitle": "Jed 1.18", "surface": "A man is sitting in a room. Another person enters, carrying a closed cardboard box, and sits down nearby. Though the first man can't see, hear, or smell the box's contents, he knows what's in the box. (ES original)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_a077de08c109", "srcNo": 576, "title": "废旧古堡", "dispTitle": "废旧古堡", "surface": "我和小伙伴约好一起去废弃的古堡参加万圣节变装派对，结果只剩下了我一个……请推理故事全貌", "cats": ["恐怖", "本格"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_a0a04ac21e6e", "srcNo": 1166, "title": "猜名字", "dispTitle": "猜名字", "surface": "家里闹鬼了，我和爱人找来一位大师帮忙解决。大师说他有怨气，你们在屋里摆满白烛\n并喊他的名字，便可散其她。秆夜，阵阵阴风吹灭了蜡烛，爱人急忙喊其姓名，可听到后我却\n不可置信的看着她。我知道，我们死定了.………", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_a10db1fd4a12", "srcNo": 196, "title": "", "dispTitle": "无题 · KONpiGG #196", "surface": "一名小男孩溺死于河中，岸边有半瓶可乐。得知消息的我内心惊讶，随后复杂的情绪涌上心头。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_a11ad91a65e2", "srcNo": 855, "title": "秘密", "dispTitle": "秘密", "surface": "我最近胃肠感冒，一夜没睡，无意中发现了哥哥和嫂子的秘密。我大惊失色，于是杀死了妻子。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_a11f724d2e9e", "srcNo": 1107, "title": "午休的铃声", "dispTitle": "午休的铃声", "surface": "午休铃声响了，但教室里的学生都没有醒来。老师走进教室发现所有人都睡着了。", "cats": ["其他"], "difficulty": 2, "src": "github:Tenzyoo/turtle_soup_game", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_a1674525f6df", "srcNo": 439, "title": "刷牙", "dispTitle": "刷牙", "surface": "男子清晨起来刷牙，发现自己牙齿是绿色的，他吓得疯了过去", "cats": ["悬疑", "猎奇"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_a19cdfc423fe", "srcNo": 678, "title": "没写完的字母", "dispTitle": "没写完的字母", "surface": "女人正在写一个大得许多人都能同时看见的字母。字母写到一半，她的高度突然不断下降，随后她遇难了。她没站在脚手架或建筑上。发生了什么？", "cats": ["悬疑", "职场"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_a1bdbe505f88", "srcNo": 407, "title": "加班", "dispTitle": "加班", "surface": "“生日快乐！快吹蜡烛许愿吧。”\n“我希望…爸爸永远不要再加班了。”\n（第二天，爸爸真的不再加班了）", "cats": ["家庭", "犯罪"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_a1d5d6bb539b", "srcNo": 1313, "title": "", "dispTitle": "无题 · boop-yyt #1313", "surface": "Two people are dead in a car, which is locked from the inside. There's a lot of blood. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_a20a19439677", "srcNo": 1162, "title": "生罚通知单", "dispTitle": "生罚通知单", "surface": "小安死子, 他身上的皮被全部剥下去了。小白也死了，教学楼上的钢筋滑落，插进了他\n的脑袋。短时间死了三个人，学校里人心性性，宣布停课。没想到第二天小陈死在了家中,，死\n因是家里漏电，但没人相信小陈是意外，一定是他! 小邓醒来，发现自己被困密室里，面前有\n一桶水，他知道他完了，默默的等待属于他的惩罚!", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_a22d1ae4da67", "srcNo": 1119, "title": "美人鱼", "dispTitle": "美人鱼", "surface": "小美人鱼生活在自己的宫殿里，有一天，人类的王子落入了水中，被二条粉色的水蛇咬\n死了，过了好久，富殿里没有其他食物，她只好把水蛇和王子都吃掉了。可能是吃撑了，她的\n肚子越来越大，最后被撑死在了水面上。水面上球起了红色的水花;", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_a32bd2035461", "srcNo": 1060, "title": "囚徒的红豆", "dispTitle": "囚徒的红豆", "surface": "两个死刑犯关在相邻的牢房，每天只能通过小窗看到对方。某天，狱卒给每人一碗白米饭，并在其中一碗里放了一颗红豆。看到红豆后，没有红豆的那个人自杀了。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_a3a406ca4c64", "srcNo": 667, "title": "最便宜的珍藏", "dispTitle": "最便宜的珍藏", "surface": "收藏家在旧货摊发现一套便宜得不可思议的真品。他越检查越生气，却立即付钱把整套东西带走。回家后他没有把这件事当作捡漏炫耀。为什么？", "cats": ["反转", "日常"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_a3cb839a138b", "srcNo": 156, "title": "", "dispTitle": "无题 · KONpiGG #156", "surface": "我渴求得到她的注意，可当我真的与她四目相对时，我才知道，她也很想看到我。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_a3d7b4b19dc6", "srcNo": 682, "title": "同一天的起点", "dispTitle": "同一天的起点", "surface": "姐姐已经上小学三年级，两个弟弟却刚上幼儿园。奇怪的是，医生可以证明三个人是在同一天“产生”的。为什么？", "cats": ["亲情", "脑洞"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_a44374f323ff", "srcNo": 1377, "title": "", "dispTitle": "无题 · boop-yyt #1377", "surface": "A man pushes a car up to a hotel and tells the owner he's bankrupt. How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_a44baed50fd4", "srcNo": 314, "title": "086 · 不说话", "dispTitle": "086 · 不说话", "surface": "我在宿舍住了三年，室友从来没有和我说过话。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_a471bef44be6", "srcNo": 786, "title": "电话", "dispTitle": "电话", "surface": "一位富豪给心爱的妻子打了一通电话，于是妻子就死了。", "cats": ["悬疑", "推理", "犯罪"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_a4f9435834f7", "srcNo": 1069, "title": "电击实验", "dispTitle": "电击实验", "surface": "男子参加一个实验：只要按下红色按钮，隔壁房间的陌生人就会受电击，而他能得到100块。他按了一百次，最后他发现隔壁没人，但他还是自杀了。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_a506fe8744ce", "srcNo": 620, "title": "染血的婚纱", "dispTitle": "染血的婚纱", "surface": "王子带公主逃出恶魔城堡，恶魔说“穿白裙的天使不能通过”。王子死了，公主却活着逃出来了。", "cats": ["恐怖"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_a51c48451941", "srcNo": 835, "title": "平安夜", "dispTitle": "平安夜", "surface": "我长年待在病房里，今天是平安夜，外面下了很大的雪，爸爸妈妈接我回家待一天，爸爸亲自下厨，妈妈也在照顾生病的我，护工来到了家里，说我该回去了。妈妈恳求他但他不听，于是二人扭打在一起，妈妈杀死了护工，爸爸让我不要在意，还给我做了火鸡和烤肉。吃饱了我和爸爸妈妈睡在了一张床上，很热，很暖，我很快就睡着了。第二天我幸福地死去了。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_a521f9bcbdd1", "srcNo": 1357, "title": "", "dispTitle": "无题 · boop-yyt #1357", "surface": "Variant which puts this in section 2: same statement, ending with \"a large window through which rays are coming.\" How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_a53e27f10a31", "srcNo": 1038, "title": "书中的秘密", "dispTitle": "书中的秘密", "surface": "小明买了一本自传，发现第15页和第16页之间夹着一张百元大钞。他立刻去找书店退货，说这书是假的。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_a562d099d9e0", "srcNo": 1237, "title": "Jed 2.23", "dispTitle": "Jed 2.23", "surface": "As a man jumps out of a window, he hears the telephone ring and regrets having jumped. (from \"Some Days are Like That,\" by Bruce J. Balfour; partial JM wording)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_a58e64b56fac", "srcNo": 1032, "title": "致命的干草", "dispTitle": "致命的干草", "surface": "一个男人死在荒野中，身边只有一捆干草，没有任何外伤。他是怎么死的？", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_a5b8464c6f47", "srcNo": 548, "title": "红绳咒", "dispTitle": "红绳咒", "surface": "\"祝你生日快乐...\" 烛光摇曳的生日歌突然中断，12岁的林小满倒在插着13根蜡烛的蛋糕前。她的手腕系着褪色的红绳，法医却找不到任何致命伤。三天后，当姐姐整理遗物时，发现全家福里每个人的脚踝都系着同样的红绳。", "cats": ["家庭", "恐怖", "逻辑"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_a5fafc2c386c", "srcNo": 423, "title": "人脸", "dispTitle": "人脸", "surface": "我玩着手机，偶然看了一眼窗外，看到一张人脸，我知道我完了", "cats": ["恐怖"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_a5ffdd3aa096", "srcNo": 1328, "title": "", "dispTitle": "无题 · boop-yyt #1328", "surface": "Two men are found dead outside of an igloo. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_a729f349722d", "srcNo": 76, "title": "", "dispTitle": "无题 · KONpiGG #76", "surface": "一个男人推了一下保龄球，没过多久，他就被紧急送往了医院。（提示：物理）", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_a729fbfa91ee", "srcNo": 1047, "title": "图灵测试", "dispTitle": "图灵测试", "surface": "面试官问了机器人最后一个问题。机器人回答后，面试官立刻按下了销毁按钮，并满脸冷汗地逃出了房间。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_a7a2d71a9e6b", "srcNo": 793, "title": "照片里的第三只手", "dispTitle": "照片里的第三只手", "surface": "一对情侣去废弃游乐园探险，回家整理照片发现某张合照里多了一只陌生的手。女友看后吓得把手机摔烂。为什么？", "cats": ["怪谈", "悬疑", "惊悚"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_a7c2020b9917", "srcNo": 1131, "title": "送别", "dispTitle": "送别", "surface": "明天有一个重要的仪式，所以我睡的很早，可在午夜，我腊胱中好像听到一阵清脆的金\n属碰撞声音，又听到一前一后两个脚步声。早上醒来，我家门口围满了人，地上有五具尸体。\n查明真相后，我把他们送到了他们该去的地方。", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_a82e25dc89d7", "srcNo": 456, "title": "小羊的毛衣", "dispTitle": "小羊的毛衣", "surface": "「妈妈，你给我织的毛衣，怎么停手了？」\n「妈妈，你怎么哭了？」\n「绳子太短了，放下去够不到妈妈呀。」\n「绳子怎么变长了，还混着灰毛毛？」\n「我抱住妈妈啦，可妈妈看不见我。我被狼守卫抓回去了。」\n「我的毛衣渡了遗忘河，怎么没有消失呀？」", "cats": ["怪谈", "温情"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_a84026db0d3d", "srcNo": 469, "title": "异样", "dispTitle": "异样", "surface": "公交车上，一个二十岁的男人反复大声问身边的中年男人：“树为什么在跑？”“我穿的衣服是什么颜色？”\n邻座的情侣忍不住嗤笑：“他怎么像个小孩子。”\n中年男人只说了一句话，情侣的笑容瞬间僵在脸上，车厢里陷入一片安静。", "cats": ["反转", "逻辑"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_a8471499667e", "srcNo": 22, "title": "灯塔看守员", "dispTitle": "灯塔看守员", "surface": "一个男人推开门，看到眼前的景象后立即跳楼自杀了。为什么？", "cats": ["悲剧"], "difficulty": 2, "src": "github:anchorAnc/astrbot_plugin_TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_a86f38e57afd", "srcNo": 1384, "title": "", "dispTitle": "无题 · boop-yyt #1384", "surface": "A black leader dies in Africa. How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_a8729117a936", "srcNo": 1167, "title": "赴净土", "dispTitle": "赴净土", "surface": "城中无啼锁门窗，棍棒底下出真章。临行明月仍残缺，沙弥忽闻有肉香。吾心明悟见难\n辩，真死丽已成白骨。人尘埃落定无杂念，一如既往赴净土。", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_a8951d0e3ad1", "srcNo": 311, "title": "083 · 下雨", "dispTitle": "083 · 下雨", "surface": "那天下着大雨，我站在十楼的阳台上，从来没有感到这么轻松过。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_a8a56a514808", "srcNo": 1317, "title": "", "dispTitle": "无题 · boop-yyt #1317", "surface": "A man sees sawdust and chooses to living. Why?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_a8c01bd11872", "srcNo": 917, "title": "噩梦重现", "dispTitle": "噩梦重现", "surface": "”妻子临产了，我要当爸爸啦~ 父母也从乡下搬来打算帮我照顾妻子。五年前，我失忆了，但现在我特别幸福。我看见外卖员那一刻好像惊呆了~ 妻子死了，父母大骂：“骗子！这和说好的不一样！！” 好美味呀~哈哈，我好像想起来这一幕发生过了！我明白我不是我。我是个恶魔！！我好痛苦啊~哈哈哈 快动手吧~永远活在痛苦里吧~“ 警方判定，这封信有一个字被修改了。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_a8c4918843a4", "srcNo": 239, "title": "003 · 让座", "dispTitle": "003 · 让座", "surface": "一天，老明和小明一同乘公交车。老明是年近八旬的老人，小明是一名年轻小伙。上车后，乘客却纷纷给小明让座，这是为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_a8df9d0bfa84", "srcNo": 782, "title": "早八", "dispTitle": "早八", "surface": "早八的课最痛苦，讲台上老师的话我一句都听不进，于是我溜去厕所摸鱼。等我从厕所回来时，老师和同学全都消失了。", "cats": ["悬疑", "推理", "犯罪", "都市"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_a8fb92054c63", "srcNo": 721, "title": "贝尔公主", "dispTitle": "贝尔公主", "surface": "我是贝尔公主，父王给我盛大婚礼，可婚礼上我却看不清王子的脸……", "cats": ["反转", "恐怖", "脑洞"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_a9028a27e084", "srcNo": 459, "title": "谢谢", "dispTitle": "谢谢", "surface": "一个人走进一家酒吧，向酒保要了一杯水。酒保没有给他水，而是掏出一把枪指着他。这个人愣了一下，然后笑着说“谢谢”，便离开了酒吧。请问发生了什么事？", "cats": ["其他"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_a979d7820985", "srcNo": 1139, "title": "姥姥的磊礼", "dispTitle": "姥姥的磊礼", "surface": "2 月 20号:姥姥去世了，我和区爸妈妈回到乡下参加姥姥的葬礼，夜晚在老宅睡觉的时\n候，我被姥姥家大黄狗的叫声吵醒，我好像听到院子里有人在劈柴。2 月 21 号: 守灵的时候，\n爸爸悄悄和我说: 你晚上自己住，妈妈好像有些不对。晚上我去看妈妈，妈妈抓着我说: “你\n爸爸有问题。明早我们就走! 2 月 22 号: 今天妈妈看起来恢复正常了。可在吃饭的时候，我\n还是发现了问题，我悄悄和爸爸说了我的发现，爸爸告诉我他有办法解决! 2月 23 号: 太棒\n了! 区爸果然解决了问题，只不过他不再去健身房。妈妈也不再化妆了。", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_a98b68e06111", "srcNo": 761, "title": "咳嗽", "dispTitle": "咳嗽", "surface": "小白一直咳嗽，去看医生医生却说他很健康。", "cats": ["搞笑", "日常"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_a9a0bddb7f7c", "srcNo": 38, "title": "旧的八音盒", "dispTitle": "旧的八音盒", "surface": "男孩和女孩从小是邻居，女孩过生日时，男孩送给她一个旧的八音盒，不久后女孩搬家了。", "cats": ["其他"], "difficulty": 3, "src": "github:anchorAnc/astrbot_plugin_TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_a9b861531fdd", "srcNo": 1391, "title": "", "dispTitle": "无题 · boop-yyt #1391", "surface": "A man is doing his job when his suit tears. Fifteen minutes later, he's dead. How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_a9e79f26f346", "srcNo": 818, "title": "车子不见了", "dispTitle": "车子不见了", "surface": "女子报案说自己的车在地下停车场「无故消失」，但警方调阅监视器却没看到任何异状。", "cats": ["悬疑", "推理", "日常", "都市"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_aa02ae9162dc", "srcNo": 421, "title": "余温", "dispTitle": "余温", "surface": "本作品为校园题材的第二部，根据真实事件创作。\n全班都守着一个缄默的秘密，只有她始终装作一无所知。旁人说，那份心思，早已在并肩的岁月里悄然生根。直到他彻底离开，她的世界才终于安静下来……\nWhat happened?", "cats": ["校园"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_aa37f540a278", "srcNo": 860, "title": "跳楼的女人", "dispTitle": "跳楼的女人", "surface": "女人对世界感到绝望，于是决定跳楼，没想到跳下去的瞬间电话响了，她感到后悔却来不及了。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_aa47859dde00", "srcNo": 606, "title": "外科医生的儿子", "dispTitle": "外科医生的儿子", "surface": "父子车祸，父亲死了，儿子重伤送医院。外科医生说：“我不能给这个男孩动手术，他是我儿子！”", "cats": ["逻辑"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_aa5f2024bd60", "srcNo": 1059, "title": "永不落幕的演出", "dispTitle": "永不落幕的演出", "surface": "一个剧团表演‘切开人体’的魔术，观众看得如痴如醉。直到表演结束，演员们都没有谢幕，观众才发现舞台上全是真的内脏。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_aa939a5ceff4", "srcNo": 1330, "title": "", "dispTitle": "无题 · boop-yyt #1330", "surface": "Joe wants to go home, but he can't go home because the man in the mask is waiting for him. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_aac5e74f3bff", "srcNo": 550, "title": "午夜的敲门声", "dispTitle": "午夜的敲门声", "surface": "男人独自住在山顶的小屋里，深夜突然听到急促的敲门声。他迷迷糊糊跑去开门，门外却空无一人。没过多久，敲门声再次响起，他又去开门，还是没人。反复几次后，敲门声终于消失了。第二天一早，男人打开门，发现山脚下围满了警察，而他自己也成了嫌疑人。", "cats": ["反转", "悲剧", "逻辑"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_aad7cc040aeb", "srcNo": 1018, "title": "生日快乐", "dispTitle": "生日快乐", "surface": "全家人围在一起为爷爷庆祝百岁生日，气氛很热烈。爷爷吹灭蜡烛后，全家人突然放声大哭，并开始推搡爷爷。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_aae201f13aee", "srcNo": 170, "title": "", "dispTitle": "无题 · KONpiGG #170", "surface": "在老公的帮助下，我成功减肥，但我在直播时突感身体不适，等我跑到厕所呕吐时却发现令人惊恐的一幕。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_aae55719369f", "srcNo": 7, "title": "红色雨伞", "dispTitle": "红色雨伞", "surface": "雨停后，她看到门口多了一把红色雨伞，于是决定搬家。", "cats": ["其他"], "difficulty": 1, "src": "github:17hczmsn/turtle_soup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_aaef84435260", "srcNo": 1273, "title": "", "dispTitle": "无题 · misc #1273", "surface": "A man walks into a bar and asks for a drink. The bartender pulls out a gun and points it at him. The man says, \"Thank you,\" and walks out. How could this be", "cats": ["其他"], "difficulty": 2, "src": "misc/repo-scan", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_ab1500f32c3f", "srcNo": 290, "title": "062 · 网约车", "dispTitle": "062 · 网约车", "surface": "有一对情侣，男生每天都开车送女生回家。这次送完女生回家，女生给了男生十块钱。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_ab6cf100d414", "srcNo": 37, "title": "诡异的画像", "dispTitle": "诡异的画像", "surface": "迷路的女孩找到了间空屋子，她很疲惫但她睡不着。第二天清晨，累得睡着的她醒过来，发现了异样，恐惧地逃离了屋子。", "cats": ["恐怖", "犯罪"], "difficulty": 2, "src": "github:anchorAnc/astrbot_plugin_TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_ab7525f53ba2", "srcNo": 730, "title": "相册", "dispTitle": "相册", "surface": "我是医生，一天有人把一本相册放在我面前，我知道他们发现了我所有秘密。", "cats": ["恐怖", "悬疑", "惊悚", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_abd814242616", "srcNo": 1173, "title": "倒计时: 7 天", "dispTitle": "倒计时: 7 天", "surface": "第一天 家里有一盒录像带，我观看后发现是经典电影《半夜恶铃》中贞女聆出电视机那\n一段。据说看了这个录像带的人都会先接到一通电话，除非又有别人观看，不然你就会在七天\n后死去。午夜时分，电话铃声响起，随后家里真的闹鬼了! 第二天 我在持续遇到灵异事件，\n我必须尽快解决，明天妻儿就回来了。一位大师和我说:“必须找到源头,用同样被诅咒过的\n人进行仪式，方可化解”第五天 我到岛国找到了贞女所在的那口井” 并进行了仪式，我付出\n了很多，希望能活下来。第七天 怎么回事! 贞女还是出现在我家里!我必须活下去，无论任\n何方法。", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_abf8e8b26ae2", "srcNo": 893, "title": "保姆", "dispTitle": "保姆", "surface": "新来的保姆总是偷懒，家里乱糟糟的，我跑去客厅跟父亲告状，父亲都说：”我们家没请保姆。“我回到卧室质问保姆，保姆却说：”你爸爸不是早就去世了吗。“我到底该相信谁？于是我冲出家门正好撞见邻居张阿姨，张阿姨的一席话，让我彻底崩溃了……", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_ac70caedcf34", "srcNo": 541, "title": "变态的发育，畸形的它", "dispTitle": "变态的发育，畸形的它", "surface": "森林深处举行了一场关于“异类”的审判。动物们聚集在一起，讨论那个让所有物种都感到费解的它。\n豹子率先跳上巨石甩动着尾巴语带嘲讽，冰冷的竖瞳里满是不屑: 我曾观察过它们“那个家伙是演化史上的笑话。在它们最初明明拥有四条腿，本该是全速飞奔的黄金期，却是它们一生中最软弱无力的时候，甚至连逃避捕食者的能力都没有。”\n鸵鸟扑棱着翅膀，语气中透着一丝傲慢: 你说谁呢，两条腿好用得很，它们终于意识到了两条腿的妙处了。虽然它们跑得没我快.\n这时，老狒狒走上前，眼神中充满了敬畏与哀悯：“你们都没看到它们的暮色时刻。当阴影拉长，它们会突然长出第三条腿。那是它们一生中最蹒跚的时刻，但也是它们最危险、最不可捉摸的时候。”\n一旁的袋鼠摸了摸自己强壮的尾巴，若有所思地低声嘀咕：“我理解那种感觉，多一个支点确实能让人站得更稳。但奇怪的是，我们的‘第三条腿’是肉长的，而它们的，却是从身体外面长出来的……”", "cats": ["逻辑"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_ac7f45f3b869", "srcNo": 558, "title": "出差", "dispTitle": "出差", "surface": "我出差很久，回到家之后突然全身发凉，知道我完了", "cats": ["其他"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_ac9bb5339472", "srcNo": 672, "title": "射门前的敲击", "dispTitle": "射门前的敲击", "surface": "足球训练时，一名队员在球前等待。助教分别敲响左右门柱，又在球门后喊了一声。队员没有看向助教，却随即起脚进球。为什么？", "cats": ["推理", "日常"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_ace8a94e1617", "srcNo": 592, "title": "隧道里的瞎子", "dispTitle": "隧道里的瞎子", "surface": "男人坐火车去邻镇看病，治好回程过隧道跳车自杀。为什么？", "cats": ["逻辑"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_acebe5e38366", "srcNo": 288, "title": "060 · 生还者", "dispTitle": "060 · 生还者", "surface": "男子精神正常，但却在船上挥起刀，将许多人的手一一砍断。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_acf47f31ac9f", "srcNo": 1075, "title": "海景房的窗帘", "dispTitle": "海景房的窗帘", "surface": "男子住进了一家豪华的海景酒店。他拉开窗帘看了一眼大海，却立刻脸色苍白地关灯躲进了被窝，祈祷天快点亮。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_acfe4ab75d5e", "srcNo": 720, "title": "一盘排骨", "dispTitle": "一盘排骨", "surface": "生日那天爸爸端上一盘排骨并说了一句话，我痛哭。", "cats": ["亲情", "反转", "温情"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_ad4c92d9fe1c", "srcNo": 633, "title": "送错外卖", "dispTitle": "送错外卖", "surface": "男人每天都会收到外卖，总会有一个陌生的胖女生过来取外卖\n一个月后，男人的女友死了。", "cats": ["悬疑", "本格"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_ad555550da64", "srcNo": 1341, "title": "", "dispTitle": "无题 · boop-yyt #1341", "surface": "John was watching television. Just after the midnight news there was a weather forecast:\" It is raining now and will rain for the next two days. However, in 72 hours it will be bright and sunny.\" \"Wrong again\" snorted John. He was correct but how did he know?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_ad566460928f", "srcNo": 673, "title": "送修的不是这辆车", "dispTitle": "送修的不是这辆车", "surface": "男人开着拖车把自己的轿车运到修理厂。轿车检查后完全正常，他并不意外。维修工处理了一处故障后，他开着轿车离开，却把拖车留在了厂里。为什么？", "cats": ["反转", "日常"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_ad7366ba2b30", "srcNo": 879, "title": "声音", "dispTitle": "声音", "surface": "”滋滋 嗡嗡嗡 呼呼呼 轰隆隆 哒哒哒 咔嚓 啊啊啊 嘣嘣 咕噜咕噜 滋滋“", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_ad9cefce00b1", "srcNo": 1279, "title": "", "dispTitle": "无题 · boop-yyt #1279", "surface": "A man sitting on a park bench reads a newspaper article headlined \"Death at Sea\" and knows a murder has been committed. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_adfe22f8ade8", "srcNo": 987, "title": "盲人旅行", "dispTitle": "盲人旅行", "surface": "几个盲人朋友坐火车旅行。当火车进入隧道时，其中一个盲人突然跳车自杀了。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_ae470c4660ec", "srcNo": 725, "title": "出租房", "dispTitle": "出租房", "surface": "我搬进便宜的新房，常听到像老鼠爬的声音却睡得香。后来房东谈了女友，声音没了，但诡异的安静让我睡不着。", "cats": ["怪谈", "恐怖", "悬疑", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_ae4828193420", "srcNo": 209, "title": "怀孕", "dispTitle": "怀孕", "surface": "妻子怀孕了两次，一次高兴 ，一次哭。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:wangyafu/haiguitangmcp", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_ae5a904a41fe", "srcNo": 272, "title": "042 · 初恋之死", "dispTitle": "042 · 初恋之死", "surface": "今天是你初恋出殡的日子，她是远近闻名的美女，乌木般的秀发，吹弹可破如雪一样的肌肤，追求者多如蚂蚁。你从未能正面好好看她一眼，这最后一刻，你想永远记住她的美貌。往棺木中一瞧，她穿着最爱的那条墨绿色裙子，你的目光沿着裙角往上……你惊呼一声，捂着嘴后退几步——老妇人是谁？", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_ae6f863dc691", "srcNo": 387, "title": "归燕", "dispTitle": "归燕", "surface": "唱曲渐消，故都春尽，他等燕归。\n今年燕归，他却亲手烧了整个巢。\n无人怪他，满城悲泣。", "cats": ["悬疑", "悲剧"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_aea0dcf7d165", "srcNo": 1137, "title": "宿舍规则怪谈", "dispTitle": "宿舍规则怪谈", "surface": "1. 不要在夜晚的时候使用卫生间: 2. 宿舍会提供食物，但不可以贪吃: 3. 室友不是两\n个，而是三个:4.| 室友只有两个，5. 室友只有一个。", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_aeb26bc5d1e5", "srcNo": 1067, "title": "双胞胎的恶意", "dispTitle": "双胞胎的恶意", "surface": "双胞胎兄弟掉进深井，只有一根绳子能拉上一人。哥哥对弟弟说：“你上去吧，照顾好妈妈。”弟弟上去后，却剪断了绳子。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_aeccc32ab02a", "srcNo": 359, "title": "薄如蝉翼", "dispTitle": "薄如蝉翼", "surface": "锣鼓点子密得像骤雨，震得我骨头缝里都在发颤。\n父亲用粗糙的拇指蘸了些温热的桐油，细细抹过我僵硬的关节和脸颊，那是他一天中最温柔的时刻。\n“囡囡，今儿个看客多，哪怕身上再疼，也要舞得好看些。”\n他低声说着，将三根冰冷的竹签熟练地插进我的脖颈和手腕。\n光亮起时，身体瞬间失去了重量。我被他高高挑起，猛地撞向那块滚烫雪白的纱幕，看着对面影影绰绰的人群，听话地手舞足蹈起来。", "cats": ["怪谈", "恐怖"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_aeed01c65116", "srcNo": 317, "title": "089 · 照片", "dispTitle": "089 · 照片", "surface": "我在手机里发现了一张我从未拍过的照片，照片上是我熟睡的样子。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_aef19f1b83f9", "srcNo": 150, "title": "", "dispTitle": "无题 · KONpiGG #150", "surface": "我以前有个很爱我的男朋友，但他后来开始欺负我，最后他死了。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_af198d3a47b7", "srcNo": 1207, "title": "Jed 1.33", "dispTitle": "Jed 1.33", "surface": "A man lies dead next to a feather. (PRO)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_af575778712a", "srcNo": 1390, "title": "", "dispTitle": "无题 · boop-yyt #1390", "surface": "A man shoots himself, and dies. How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_afa727cde8c6", "srcNo": 1186, "title": "你独自住在郊外，附近只有一户邻居", "dispTitle": "你独自住在郊外，附近只有一户邻居", "surface": "你独自住在郊外，附近只有一户邻居，是一对养牛的夫妻。你们两家之间隔着一片草坪。有一天深夜，你被一阵喧闹声惊醒，之后听见了牛叫，牛撞开栅栏和牛吃草的声音。过了一段时间，你又听到有东西在撞自己家的门，但你没有理会，继续睡了过去。第二天，警察敲响了你家的门。", "cats": ["其他"], "difficulty": 2, "src": "haiguitang.cn(wayback)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_afcadcf41f05", "srcNo": 1230, "title": "Jed 2.10", "dispTitle": "Jed 2.10", "surface": "A man was brought before a tribal chief, who asked him a question. If he had known the answer, he probably would have died. He didn't, and lived. (MWD original)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_b01ab097ade4", "srcNo": 30, "title": "五步上车", "dispTitle": "五步上车", "surface": "一个人离他的车有30米，但是他只走了五步就上车了，这是为什么?", "cats": ["其他"], "difficulty": 2, "src": "github:anchorAnc/astrbot_plugin_TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_b04ccdfb4118", "srcNo": 724, "title": "冰淇淋", "dispTitle": "冰淇淋", "surface": "哥哥很后悔：如果那天自己吃了冰淇淋，弟弟就不会死。", "cats": ["亲情", "悬疑"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_b072e15c06f8", "srcNo": 73, "title": "", "dispTitle": "无题 · KONpiGG #73", "surface": "婆婆给了我一瓶药水，我失去了最爱的男生。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_b0983dc05985", "srcNo": 718, "title": "广播", "dispTitle": "广播", "surface": "听到广播新闻后，我先庆幸随后痛哭。", "cats": ["反转", "悬疑"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_b0a7e1bf8727", "srcNo": 984, "title": "", "dispTitle": "无题 · xiquege #984", "surface": "展示给玩家的不完整故事片段\n-", "cats": ["其他"], "difficulty": 2, "src": "github:xiquege/ai-haigui-game", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_b0bdd82770e6", "srcNo": 412, "title": "完美晚宴", "dispTitle": "完美晚宴", "surface": "他精心准备了一场独享的晚宴，桌上摆着高级寿司、炸鸡和冰镇啤酒。他心情愉悦地按着手机键盘，屏幕里跳动着暧昧的辞藻。\n几步之外，传来越来越凄厉的干呕与哀嚎。那个曾经高高在上的女人，此刻一丝不挂地在污物中抽搐、翻滚，最终像一头失去理智的野兽般，一头扎进了冰冷干涸的浴缸。\n他听着那令人毛骨悚然的挣扎声，却觉得杯中的酒更加甘甜，甚至笑着又加点了一份披萨。\n直到第二天清晨，万籁俱寂。他冲出房门，在众目睽睽之下跪倒在急救担架旁，哭得撕心裂肺，甚至几度昏厥：“求求你，千万别丢下我一个人！”", "cats": ["悬疑", "犯罪", "猎奇"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_b1b63c563cf1", "srcNo": 118, "title": "", "dispTitle": "无题 · KONpiGG #118", "surface": "今天妈妈让我去探望来外婆家玩，我们一起吃了新鲜的肉，外婆的手艺还是这么棒，外婆还热情地让我喝了红酒，说这是一种不会醉的酒，我喝也没关系。晚上了，外婆说想看看我有没有哪里瘦了，让我脱了衣服陪她睡觉，不小心碰掉了外婆的帽子，我惊恐万分，疯狂干呕！", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_b1bf05333816", "srcNo": 243, "title": "009 · 外卖", "dispTitle": "009 · 外卖", "surface": "\"喂，您的外卖到了。\" 什么外卖，我没叫过外卖啊。你问妹妹，她摇头。你又问女朋友，她惊恐地摇了摇头。正当你想要拒绝外卖小哥时，门外冲进来几个壮汉，一把把你按倒在地。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_b1e8df709af4", "srcNo": 315, "title": "087 · 画像", "dispTitle": "087 · 画像", "surface": "一位艺术家为自己画了一幅自画像，画完之后，他死了。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_b1e9c85a7d03", "srcNo": 964, "title": "", "dispTitle": "无题 · wzk1015 #964", "surface": "').strip()\n answer = input('请输入", "cats": ["其他"], "difficulty": 2, "src": "github:wzk1015/GPT-turtlesoup", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_b275d02f1b7d", "srcNo": 581, "title": "人人", "dispTitle": "人人", "surface": "小a和小b被困山洞数天，这时候小a突然想到办法，说了句德爷吃虫子，小b怔了怔又哈哈大笑，小a也笑了，只是声音渐渐低了下去。但二人最终都没有活下来", "cats": ["猎奇", "脑洞"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_b2877d60b36b", "srcNo": 263, "title": "032 · 粉色连衣裙", "dispTitle": "032 · 粉色连衣裙", "surface": "你的新邻居是一个独居的年轻男人，有一天你看到一个穿粉色连衣裙浓妆艳抹的长发女人进了邻居家门。深夜，隔壁传来争吵摔东西的声音。第二天你在邻居家门口的垃圾袋里看到了被剪碎的粉色连衣裙和一把长发。你要报警吗？", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_b2a5f5e847bf", "srcNo": 1354, "title": "", "dispTitle": "无题 · boop-yyt #1354", "surface": "A flash of light, a man dies. How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_b2b973ea17e7", "srcNo": 856, "title": "保姆", "dispTitle": "保姆", "surface": "保姆已经一周没来了，但我发现家里好像有人。可能是害怕的原因，我每天都会掉头发，口臭，几天后警方发现了我和保姆的尸体。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_b2e6b0296473", "srcNo": 1029, "title": "逃出生天", "dispTitle": "逃出生天", "surface": "犯人策划了完美的越狱：躲进死掉囚犯的棺材，等送去墓地埋葬后，同伙再把他挖出来。当他躺在漆黑的棺材里得意地划着火柴时，他突然绝望地嚎哭起来。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_b300a2af7f37", "srcNo": 844, "title": "被困的大哥", "dispTitle": "被困的大哥", "surface": "三兄弟和别人打架，大哥被关了起来，三弟手足无措，二哥叫来了一堆社会上的朋友救了大哥，然后又和对面干起来了，后来对面大哥来了，双方达成和解。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_b35268fe3a24", "srcNo": 1252, "title": "最高的按钮", "dispTitle": "最高的按钮", "surface": "男孩第一次按到了电梯最上排的按钮，母亲当场哭了。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:lancelily6362-png/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_b3d5fa575635", "srcNo": 1046, "title": "永生者的悲哀", "dispTitle": "永生者的悲哀", "surface": "一个男人在深海中沉睡了千年，醒来后他看到阳光，发出了绝望的惨叫，然后拼命想把自己再次淹死。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_b3df136fb55a", "srcNo": 1007, "title": "看不见的观众", "dispTitle": "看不见的观众", "surface": "一名演员在空无一人的剧场排练，谢幕时他听到了雷鸣般的掌声，他脸色惨白地逃走了。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_b3f20408ff90", "srcNo": 1260, "title": "镜子里的第二盏灯", "dispTitle": "镜子里的第二盏灯", "surface": "女人半夜醒来，看见梳妆镜里比房间里多出一盏灯，立刻抱着孩子冲出门。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:lancelily6362-png/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_b444081699d5", "srcNo": 125, "title": "", "dispTitle": "无题 · KONpiGG #125", "surface": "她走到了一栋房子面前，她明白，自己马上就将回天无力了", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_b47d7df152f2", "srcNo": 443, "title": "下班", "dispTitle": "下班", "surface": "我是一个社畜，每天按时工作准点下班。但是今天出现了意外，我明明准时打卡却打卡失败了。", "cats": ["反转", "怪谈", "搞笑", "脑洞"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_b489becab7a5", "srcNo": 991, "title": "最后一张照片", "dispTitle": "最后一张照片", "surface": "一个业余登山者在雪山里失踪了。一年后，搜索队找到了他的尸体和相机。相机里最后一张照片是天空，但他却是吓死的。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_b4a2db900172", "srcNo": 1023, "title": "电梯里的对话", "dispTitle": "电梯里的对话", "surface": "两个人在电梯里闲聊。A问：‘你什么时候发现的？’B答：‘就在刚才。’然后A杀死了B。电梯门打开时，A自首了。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_b4bb38aae375", "srcNo": 1106, "title": "图书馆的低语", "dispTitle": "图书馆的低语", "surface": "图书馆里总是能听到有人在低语，但管理员找了一圈却没有人说话。", "cats": ["其他"], "difficulty": 2, "src": "github:Tenzyoo/turtle_soup_game", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_b5195df9aed6", "srcNo": 618, "title": "塞满", "dispTitle": "塞满", "surface": "我猛猛地塞\n全部塞进去\n直到将你塞满", "cats": ["其他"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_b5453b953650", "srcNo": 70, "title": "", "dispTitle": "无题 · KONpiGG #70", "surface": "哒..哒...哒....咚咚咚哒....哒...哒..哗啦哗啦哒..哒…哒…..\"我找到你了哦\"", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_b560a80af76b", "srcNo": 1288, "title": "", "dispTitle": "无题 · boop-yyt #1288", "surface": "The music stops and a woman dies. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_b562f6f0108b", "srcNo": 806, "title": "手机里的合照", "dispTitle": "手机里的合照", "surface": "一名男子带着女友去登山，沿途拍了许多合照。回到家后，女友传了一张他们在山上合照给他，他看到照片后立刻打电话报警。为什么？", "cats": ["悬疑", "惊悚", "推理", "犯罪"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_b5ad3b194605", "srcNo": 246, "title": "012 · 武术生", "dispTitle": "012 · 武术生", "surface": "苏亚和劳拉即将毕业，决定一起去旅游。乘大巴行驶在盘山公路上时，树林中突然窜出一帮劫匪，全车人惊恐万分，唯独苏亚和劳拉异常兴奋，这是为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_b5adb2443c5b", "srcNo": 1316, "title": "", "dispTitle": "无题 · boop-yyt #1316", "surface": "The light goes out and a man dies. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_b5b4eb60adf7", "srcNo": 758, "title": "侏儒", "dispTitle": "侏儒", "surface": "马戏团工作的侏儒被发现死在家里，周围都是散落木屑。发生了什么？", "cats": ["反转", "悬疑", "推理"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_b5e2220c95d0", "srcNo": 323, "title": "097 · 水草（经典版）", "dispTitle": "097 · 水草（经典版）", "surface": "男子和女友河边散步，女友落水，男子下水寻找未果，伤心离去。多年后故地重游，得知此河从未长过水草，男子跳河自尽。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_b635057dc9b7", "srcNo": 1247, "title": "门口的快递", "dispTitle": "门口的快递", "surface": "女人出差回家，看见门口早上的快递箱还原封不动地挡在门前，立刻知道丈夫昨晚根本没回家。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:lancelily6362-png/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_b67d60f46411", "srcNo": 819, "title": "新婚之夜", "dispTitle": "新婚之夜", "surface": "小明在新婚之夜时，被发现倒在马桶旁边，为什么？", "cats": ["搞笑", "日常", "脑洞"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_b68eb4ecad9f", "srcNo": 132, "title": "", "dispTitle": "无题 · KONpiGG #132", "surface": "有一天，约翰到监狱里探望乔治。接着约翰回家后就死了，而乔治却获释自由。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_b68ee90120ca", "srcNo": 814, "title": "辞职的原因", "dispTitle": "辞职的原因", "surface": "一名男子每天都准时搭同一班公交车上班。某天他突然决定辞职，原因竟然是因为公交车司机。", "cats": ["日常", "温情", "都市"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_b69913650fdf", "srcNo": 280, "title": "051 · 棺材里的死人", "dispTitle": "051 · 棺材里的死人", "surface": "在一条乡村路上，五个人走在一起，天突然开始下雨。五个人中有四个人加快了脚步，第五个人一点都不担心。最后五个人同时到达了目的地。加快脚步的四个人都淋湿了，而第五个人一点都没湿。这是怎么回事？", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_b6b544ca3df6", "srcNo": 508, "title": "床底的记号", "dispTitle": "床底的记号", "surface": "我五岁的女儿最近总说床底下有怪物。\n我趴在地上看了很多次，什么也没有。\n今晚她又哭了，我有点不耐烦，打开手电筒往床底照。\n床板上刻满了“正”字，密密麻麻。", "cats": ["恐怖", "悬疑", "脑洞"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_b6f21abb8183", "srcNo": 567, "title": "井中人偶", "dispTitle": "井中人偶", "surface": "一个偏远山村有个习俗：每年夏天，村民们会把一个制作精美的真人大小的人偶，穿上华丽的服饰，在隆重的仪式后，沉入村后的深井里。这个习俗已经延续了上百年，据说能保佑村庄风调雨顺。\n\n今年，负责制作人偶的是一位从城里回来的年轻人阿诚。他做的人偶格外逼真，几乎能以假乱真。仪式那天，村民们抬着人偶，在井边载歌载舞，然后将人偶推入井中。\n\n然而，就在人偶落水的瞬间，所有人突然听到了一声凄厉的尖叫，那声音不像是人偶，反而像是一个活生生的人。\n\n第二天，阿诚回城里了。", "cats": ["恐怖", "悬疑"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_b70036a88d5c", "srcNo": 1221, "title": "Jed 1.78", "dispTitle": "Jed 1.78", "surface": "A woman has incontrovertible proof in court that her husband was murdered by her sister. The judge declares, \"This is the strangest case I've ever seen. Though it's a cut-and-dried case, this woman cannot be punished.\" (This is different from #1.11.) (MH; from _How Come?_)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_b7523df2ab20", "srcNo": 1364, "title": "", "dispTitle": "无题 · boop-yyt #1364", "surface": "Variant wording: A man sends a package to someone in Europe and gets a note back saying \"Thank you. I received it.\" How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_b75ce1bb7f98", "srcNo": 201, "title": "", "dispTitle": "无题 · KONpiGG #201", "surface": "今天哥哥脸上受了伤，我生气极了！夜里，一模一样的伤口出现在我的脸上。滴答，滴答，从此，哥哥再也不会受伤了。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_b7c5a3a3b8cd", "srcNo": 733, "title": "诡异的记号", "dispTitle": "诡异的记号", "surface": "留学回家发现门旁被写了“X”，擦掉后又出现。夜里邻居家动画片声很吵，我去理论。次日门上X变成O，我疑惑时邻居开门，我意识到危险来了。", "cats": ["悬疑", "惊悚", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_b7eb296b1ca1", "srcNo": 1179, "title": "蔡罪", "dispTitle": "蔡罪", "surface": "牛郎织女多离分，羊儿回首欲报恩。四散球零寻归处，可识当年窃羊人?", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_b7f11aa92da7", "srcNo": 716, "title": "舞", "dispTitle": "舞", "surface": "六岁时爷爷去世，我去祭奠并和姐姐玩捉迷藏。我对妈妈说了一句话把她吓晕。我说了什么？", "cats": ["亲情", "恐怖", "悬疑", "惊悚"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_b870f4f22820", "srcNo": 1315, "title": "", "dispTitle": "无题 · boop-yyt #1315", "surface": "A man urinates and dies. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_b8bf95880236", "srcNo": 1085, "title": "", "dispTitle": "无题 · yinyyW #1085", "surface": "展示离奇故事片段作为起点。\n - 多轮问答：用户通过封闭式提问探索线索。\n - 揭晓", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_b8c79189fb1d", "srcNo": 1108, "title": "神秘的考卷", "dispTitle": "神秘的考卷", "surface": "考试前一天，一张和考试一模一样的试卷出现在垃圾桶里。", "cats": ["其他"], "difficulty": 2, "src": "github:Tenzyoo/turtle_soup_game", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_b92193139356", "srcNo": 839, "title": "圣诞老人", "dispTitle": "圣诞老人", "surface": "圣诞节到了，我又来完成孩子们的梦想了。第一个孩子想唱歌，他做到了；第二个孩子想去旅行，于是我送他环游世界，但他却被吃掉了；第三个孩子喜欢玩躲猫猫，于是我帮他藏起来，警官都找不到他，不过他明年自己就会出现。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_b93acb72f218", "srcNo": 626, "title": "田野里的降落伞", "dispTitle": "田野里的降落伞", "surface": "田野里躺着死人，旁边有个没打开的包裹。", "cats": ["逻辑"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_b9fdcd724950", "srcNo": 1126, "title": "圣诞礼物", "dispTitle": "圣诞礼物", "surface": "今天区爸让我早点睡觉，可深夜我却听到了毅门声，我好奇推开门去看，是不是爸爸准\n备好了圣诞礼物*。 客厅里一颗红色的圣诞树上挂满了装饰品，还没填料的火鸡摆在餐桌上,， 绿\n色的圣诞老人藏在了壁炉里，这时门外又响起了毅门声.……", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_ba0a80d94a62", "srcNo": 1145, "title": "红衣", "dispTitle": "红衣", "surface": "奔形回来后，室友和我说学校最近闹鬼了，好多人都梦到了一个红衣服的人对着你笑。\n晚上，我也梦到了，可我看清他时，却觉得眼熟。直到第二天晚上，我终于明白。", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_ba1afde7ba05", "srcNo": 1300, "title": "", "dispTitle": "无题 · boop-yyt #1300", "surface": "A woman is murdered in front of hundreds of people, but they all think it's an accident. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_ba1bc66986a7", "srcNo": 1019, "title": "最好的礼物", "dispTitle": "最好的礼物", "surface": "圣诞节，贫穷的妻子卖掉了自己引以为傲的长发，为丈夫买了一条昂贵的白金表链。回到家，她发现丈夫卖掉了祖传的金表，为她买了一套精美的发梳。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_ba4b9941a3ae", "srcNo": 361, "title": "三夜回魂", "dispTitle": "三夜回魂", "surface": "第一夜，家里传来的父母的哭声，以及排水声，我不停的安慰他们，显然这并不起作用；\n第二夜，家里传来了霹雳乓啷的声音，爸爸妈妈被吓了一跳，而后家里又传来了爸妈的争吵声、道歉声和哭声；\n第三夜，家里来了一个奇怪的人，他是谁？家里传来了一股奇怪的香味，我回想起来了，周身一阵温暖，我知道是时候逃离这座牢笼了。", "cats": ["家庭", "悲剧"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_ba77572eacd1", "srcNo": 425, "title": "脱胎换骨", "dispTitle": "脱胎换骨", "surface": "为了那场完美的蜕变，我搬进了热闹的集体宿舍。\n领队说我太重了，是因为身上趴着看不见的“脏东西”。\n为了驱逐它，十三位伙伴通宵达旦地协助我，拳头与铁器落在身上，是痛彻心扉的“排毒”。\n天亮时，他们拿一张唱片凑近我的唇边，盘面光洁如新，没有染上一丝雾气。\n“成功了，那个沉重的你不在了。”\n他们欢呼着，用滚烫的药水洗去我平庸的五官，将轻飘飘的我送入冰凉的溪流。\n终于，我不再是从前那个胖女孩了。", "cats": ["悲剧", "推理", "本格", "犯罪"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_ba9e9d7df69a", "srcNo": 760, "title": "家规", "dispTitle": "家规", "surface": "我和爸爸住在家里，他立下三条家规：喝水不能喝完、吃东西不能吃完、走路不能发出很大声音。后来有一天爸爸说不用再管这些该死家规。", "cats": ["反转", "推理", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_bacc1ab4c77c", "srcNo": 755, "title": "夹娃娃", "dispTitle": "夹娃娃", "surface": "背着十二个娃娃的小明从夹娃娃机前经过，物色他的第十三个娃娃。", "cats": ["恐怖", "悬疑", "校园", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_bafb21fa5402", "srcNo": 923, "title": "倒计时：7天", "dispTitle": "倒计时：7天", "surface": "第一天 家里有一盒录像带，我观看后发现是经典电影《半夜恶铃》中贞女爬出电视机那一段。据说看了这个录像带的人都会先接到一通电话，除非又有别人观看，不然你就会在七天后死去。午夜时分，电话铃声响起，随后家里真的闹鬼了！第二天 我在持续遇到灵异事件，我必须尽快解决，明天妻儿就回来了。一位大师和我说：”</span>必须找到源头，用同样被诅咒过的人进行仪式，方可化解“ 第五天 我到岛国找到了贞女所在的那口井，并进行了仪式，我付出了很多，希望能活下来。第七天 怎么回事！贞女还是出现在我家里！！我必须活下去，无论任何方法。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_bb122a333cab", "srcNo": 990, "title": "末班电车", "dispTitle": "末班电车", "surface": "一个女人在半夜坐最后一班电车。车厢里除了她，还有三个人：两个男人架着一个神色呆滞的女人。女人中途下车后，发现那两个男人一直在对她笑。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_bb9b8da83f0b", "srcNo": 1361, "title": "", "dispTitle": "无题 · boop-yyt #1361", "surface": "Music stops and a woman dies. How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_bb9cfe3405ab", "srcNo": 832, "title": "海龟汤", "dispTitle": "海龟汤", "surface": "一名男子到餐厅点了一碗汤，因为觉得汤里的肉吃起来很特别，所以询问了店家这是用了什么肉。店家告诉他，这是用「海龟肉」做的海龟汤，男子听完后便痛哭失声，且在那之后自杀了。请问是为什么？", "cats": ["日常"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_bba7971702d6", "srcNo": 604, "title": "为了再见到他", "dispTitle": "为了再见到他", "surface": "母女三人，妈死姐妹参加葬礼，妹见帅哥一见钟情。一个月后妹杀姐。为什么？", "cats": ["搞笑"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_bbca4242fa35", "srcNo": 368, "title": "期末考试", "dispTitle": "期末考试", "surface": "转学后这一个月,所有同学都认为我精神不正常,大家都排挤我。只有老师不这么想,可期末考试成绩下来后,我明白我真的不正常了....", "cats": ["怪谈"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_bbd785a01be1", "srcNo": 71, "title": "", "dispTitle": "无题 · KONpiGG #71", "surface": "邻居叔叔到学校通知我妈妈生病了，给我吃糖，安慰我。第二天我结婚了。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_bbde50a89713", "srcNo": 813, "title": "餐桌上的惊恐", "dispTitle": "餐桌上的惊恐", "surface": "一名女子在餐厅吃饭时，突然开始颤抖，瞳孔放大，然后尖叫着逃离现场，其他顾客和店员都对她的反应感到困惑。请问她为什么这么惊恐？", "cats": ["恐怖", "悬疑", "惊悚", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_bc096e55d3ba", "srcNo": 509, "title": "你终于赢了，也终于走了", "dispTitle": "你终于赢了，也终于走了", "surface": "我住在一个很小的地方，职责是把来者送去见“它”。\n我看着他死了一次又一次，又一次次若无其事地回到我面前。\n我每次都劝他别去，也对他说过无数遍“一定要小心”，可每次最后，都是我亲手把路指给他。\n我没法离开，也帮不了太多，只能一遍遍说着相同的话。\n后来，那个人终于赢了，头也不回地离开了这里。\n我很高兴，却也有点难过，他也许再也不会回到这里了吧。", "cats": ["脑洞", "逻辑"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_bc5e94bb9387", "srcNo": 230, "title": "车头灯关闭", "dispTitle": "车头灯关闭", "surface": "两个男人在车头灯关闭的情况下朝对方行驶。看不到月亮或星星，附近也没有电灯。两辆车都漆成黑色，没有反光表面。然而两人都知道何时该踩刹车并险些避免撞到对方。这怎么可能？", "cats": ["其他"], "difficulty": 2, "src": "github:wangyafu/haiguitangmcp", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_bc897458acc1", "srcNo": 184, "title": "", "dispTitle": "无题 · KONpiGG #184", "surface": "我和热恋中的女友去爬山，在山顶女友对我说了句话后，把我推了下去，我惊恐万分却并不怪她.", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_bcc2cc005fc0", "srcNo": 1020, "title": "看不见的杀手", "dispTitle": "看不见的杀手", "surface": "一个男人死在密闭的冰室里，死因是胸口中箭。室内没有其他人，没有发射装置，门窗从内部锁死。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_bcd10cbe509d", "srcNo": 646, "title": "缓慢的纪录", "dispTitle": "缓慢的纪录", "surface": "两人驾车完成一段封闭场地内的长距离挑战。车没改装，速度也不快，裁判却宣布创造了纪录。录像中，驾驶员几乎一直注意车尾的方向。为什么？", "cats": ["推理", "搞笑"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_bcda5d38f4bf", "srcNo": 255, "title": "022 · 签名", "dispTitle": "022 · 签名", "surface": "一名男子A请另一名男子B在纸上签上名字，随即杀死了B，为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_bd5f1d8672f3", "srcNo": 360, "title": "牺牲", "dispTitle": "牺牲", "surface": "弟弟很开朗，和很多女生玩得很好，\n但在家里和姐姐关系不是很好。\n长大后，到了谈婚论嫁的年纪，\n姐姐自杀了，遗书只留下了一句话：\n\n“爱情牺牲的为什么是我”", "cats": ["悲剧", "日常", "温情"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_bd809ff7729f", "srcNo": 354, "title": "琴音", "dispTitle": "琴音", "surface": "书生藏有一把旧琴，每至夜半，他便对月抚琴，可无论换多少次琴弦，弹奏未及半曲，弦必断裂，脆响惊破长夜。\n这般往复半载，书生终是心灰意冷，将琴束之高阁，再未触碰。\n可从那以后，每到他抚琴的时辰，阁楼中便会传来清越琴音，无人拨弦，琴却自鸣不止。", "cats": ["怪谈", "悲剧"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_bded913b3824", "srcNo": 138, "title": "", "dispTitle": "无题 · KONpiGG #138", "surface": "母亲死了，两个女儿参加他的葬礼，妹妹见到一个认识她们家的英俊的男子，与其交谈，回家后把姐姐杀了，为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_bdef38d13e0e", "srcNo": 559, "title": "便利店", "dispTitle": "便利店", "surface": "一个男人走进一家便利店，买了一瓶普通的矿泉水，结账时给了店员 100 元现金。店员找给他 98 元后，男人看了看找零，突然转身冲出了便利店，再也没回来。", "cats": ["其他"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_be036d1a868e", "srcNo": 1096, "title": "绿鞋子", "dispTitle": "绿鞋子", "surface": "一个女孩买了一双绿鞋子，穿了一段时间后她自杀了。", "cats": ["其他"], "difficulty": 2, "src": "github:Tenzyoo/turtle_soup_game", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_be2920661cad", "srcNo": 190, "title": "", "dispTitle": "无题 · KONpiGG #190", "surface": "生活拮据的孤寡老人杰克，被发现死在家中，生前好像正在吃饭，尸体被发现时已经残缺不全，而尸体周围的景象也十分诡异。推故事全貌和诡异景象是什么。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_be5cdc09f417", "srcNo": 1158, "title": "笔", "dispTitle": "笔", "surface": "今天没上班，我去逛街。一个女孩问我: “我今天漂亮吗? \"我礼角回答漂亮，她开心地\n走了。 我不小心撞到一个大爷,，他推了我一下，骂道:“做人得长眼睛! ”随后骂骂啊啊地走了。\n他走后，我在包里翻到了一支笔，我瞬间想到了什么，急忙跑去找我的同事。", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_be804a9d30c9", "srcNo": 1151, "title": "保姆", "dispTitle": "保姆", "surface": "新来的保姆总是偷懒，家里乱糟糟的，我跑去客厅跟父亲告状，父亲都说:“我们家没请\n保姆。\"我回到卧室质问保姆，保姆却说: “你爸爸不是早就去世了吗。?我到底该相信谁? 于\n是我冲出家门正好撞见邻居张阿姨，张阿姨的一席话，让我彻底裔溃了.……", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_bed167c568b8", "srcNo": 905, "title": "重映", "dispTitle": "重映", "surface": "我生病了，每天睡前妈妈都会喂我吃药。可吃完药后我总会做噩梦。第一天，我梦见我被急驰而来的卡车撞死了。第二天，我被包裹在睡袋里移动，什么都看不见。第三天，妈妈和我说她被公司辞退了，晚上我梦见妈妈癫狂的割下了我的头。第四天，原来那不是梦，吃完药后，我知道我活不过今晚了。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_bee4ceb14af5", "srcNo": 858, "title": "兄妹", "dispTitle": "兄妹", "surface": "我家楼上住着一对兄妹，哥哥十分开朗，妹妹沉默寡言却是一个知名主播，我每天都会看她直播。我很喜欢她，终于有一天她注意到我了，我喊了四个字，现在她每天除了直播都会陪着我了。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_bf0a44412d29", "srcNo": 1343, "title": "", "dispTitle": "无题 · boop-yyt #1343", "surface": "On a cold winter's day, drivers found that sheep from the fields nearby kept coming onto the road. There was no snow and the road was not warmer than the fields but whenever the sheep were ushered back to the fields they quickly returned to the road. Why?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_bf249bb05242", "srcNo": 47, "title": "好孩子", "dispTitle": "好孩子", "surface": "爸爸把地面弄脏了，妈妈又不想做饭了，这么大的人了，还是这么顽皮，不像我，我要做一个好孩子。", "cats": ["犯罪"], "difficulty": 3, "src": "github:anchorAnc/astrbot_plugin_TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_bf6dc1df19ca", "srcNo": 876, "title": "姥姥的葬礼", "dispTitle": "姥姥的葬礼", "surface": "2月20号 姥姥去世了，我和爸爸妈妈回到乡下参加姥姥的葬礼，夜晚在老宅睡觉的时候，我被姥姥家大黄狗的叫声吵醒，我好像听到院子里有人在劈柴。2月21号 守灵的时候，爸爸悄悄和我说：你晚上自己住，妈妈好像有些不对。晚上我去看妈妈，妈妈抓着我说：“你爸爸有问题。明早我们就走！2月22号 今天妈妈看起来恢复正常了。可在吃饭的时候，我还是发现了问题，我悄悄和爸爸说了我的发现，爸爸告诉我他有办法解决！2月23号 太棒了！爸爸果然解决了问题，只不过他不再去健身房。妈妈也不再化妆了。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_bfb3adb2480e", "srcNo": 1034, "title": "被诅咒的宝藏", "dispTitle": "被诅咒的宝藏", "surface": "探险家在沙漠发现了一具尸体，手里拿着一张地图，他看了一眼就说：‘他是渴死的，但他身边明明有水。’", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_bfd908cfc238", "srcNo": 777, "title": "哭声", "dispTitle": "哭声", "surface": "隔壁邻居很古怪，每到深夜都会发出凄惨哭声。直到有一天我经过他家门口，第二天我就搬走了。", "cats": ["怪谈", "恐怖", "悬疑", "惊悚"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_bff6e32d9b36", "srcNo": 637, "title": "不響的鬧鐘", "dispTitle": "不響的鬧鐘", "surface": "一個獨居的老爺爺每天早上七點都會準時被鬧鐘叫醒。某天早上鬧鐘沒有響，老爺爺卻比平時更早醒來。\n為何他起床後沒有去關鬧鐘，而是直接走進廚房開始做早餐？", "cats": ["家庭", "温情"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_c026a4977b0e", "srcNo": 1218, "title": "Jed 1.65", "dispTitle": "Jed 1.65", "surface": "A man was walking down a road when a stone lodged itself between his foot and his sandal. He leaned against a pole and, with his head down to watch, he shook his foot to dislodge the stone. Another man came up and broke the first man's arm in three places. (RB)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_c08749d6852f", "srcNo": 1092, "title": "", "dispTitle": "无题 · zhuqingxu #1092", "surface": "乐团排练结束后，一名乐手死在从内反锁的练习室内，钥匙落在室内一侧地面，外窗有铁栏。保安破门时门仍锁着。次日清点少了一只大型低音提琴硬壳箱。案件与这只箱子有关吗？", "cats": ["其他"], "difficulty": 2, "src": "github:zhuqingxu/ai-haigui-game", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_c0c1ebca2d3f", "srcNo": 1063, "title": "盲人的选择", "dispTitle": "盲人的选择", "surface": "三个盲人分一个蛋糕。他们约定每人切一块，剩下的留给第四个没来的朋友。切完后，其中一个盲人突然疯狂地攻击另外两个。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_c0c2a9b3d148", "srcNo": 1227, "title": "Jed 2.3", "dispTitle": "Jed 2.3", "surface": "A man pushes a car up to a hotel and tells the owner he's bankrupt. (DVS; partial AL and JM wording)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_c0de07ba2bbc", "srcNo": 1184, "title": "童话小镇怪谈", "dispTitle": "童话小镇怪谈", "surface": "1. 小红帽讨厌睡美人。2. 和白雪公主和巨人是好朋友。3:, 匹诺曹没办法说谎。4. 巨人问\n匹诺曹要了七颗苹果。5. 童话小镇中曾有一只绵羊。6: 童话小镇中来了一名善良的王子.7. 王\n子的武器是一面魔镜。8. 大家齐心协力打败了恶龙，保护了童话小镇。9. 童话小镇的居民都\n深爱着童话小镇，包括恶龙。", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_c12cc7f868a8", "srcNo": 627, "title": "滴水声与狗", "dispTitle": "滴水声与狗", "surface": "女孩半夜听见天花板滴水声，摸床边狗舔手才安心睡。第二天发现狗被吊死在天花板，滴的是狗血。", "cats": ["恐怖"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_c1684f23086e", "srcNo": 1170, "title": "辟梦重现", "dispTitle": "辟梦重现", "surface": "“妻子临产了,我要当和区爸啦~ 父母也从乡下搬来打算帮有我照顾麦子。五年前, 我失忆了，\n但现在我特别幸福。我看见外卖员那一刻好像惊呆了~ 妻子死了，父母大加二“骗子! 这和说\n好的不一样!! ”好美味呀~哈哈，我好像想起来这一幕发生过了 ! 我明白我不是我。我是个恶\n魔!! 我好痛苦啊~哈哈哈 快动手吧~永远活在痛苦里吧~”警方判定，这封信有一个字被修改\n了。", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_c19374c2a84a", "srcNo": 233, "title": "鱼缸", "dispTitle": "鱼缸", "surface": "我养了一缸热带鱼。昨天我给鱼缸换了水，用的是刚买的矿泉水。今天早上，鱼全死了。", "cats": ["日常"], "difficulty": 1, "src": "github:AZHi-xinxin/haiguitang-coop", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_c1a93b55fb8b", "srcNo": 521, "title": "别开门", "dispTitle": "别开门", "surface": "天黑了，噗呲，呜呜呜，爸爸不见了；夜深了，咚咚咚，门外传来了敲门声，爸爸妈妈都不在，我可不能随意开门。天亮了，爸爸在爬树，妈妈去哪儿了？打开门，我崩溃了。", "cats": ["恐怖", "悬疑", "本格"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_c2201ff1856c", "srcNo": 160, "title": "", "dispTitle": "无题 · KONpiGG #160", "surface": "\"隔壁好像搬来了一对情侣，当天晚上那个男人来找我借散粉，我没借给他，第二天却发现那个男人死在了屋子里，死相极其难看。\"", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_c22c68a56c1f", "srcNo": 566, "title": "人肉浇花", "dispTitle": "人肉浇花", "surface": "花匠说后院花还没开好，女友偷偷去看后心脏病发死了", "cats": ["恐怖"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_c235ed3afa7d", "srcNo": 650, "title": "两个完美的伪装", "dispTitle": "两个完美的伪装", "surface": "两个互不合作的窃贼分别偷走一幅画，各自把脸伪装得足以骗过监控。警方第二天根据画面分别找到他们，随后在各自住处查获赃画。伪装为什么反而帮了警方？", "cats": ["反转", "犯罪"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_c23857b4f49d", "srcNo": 350, "title": "别过来", "dispTitle": "别过来", "surface": "对面的8楼不对劲！\n窗户上有一列×字：别过来！\n我透过窗发现一个人形轮廓站在房间内\n诡异地抽动。\n我吓坏了，急忙拉上窗帘。\n第二天早上再观察时，我发现一个男人吊\n在麻绳上。", "cats": ["其他"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_c2569b43131f", "srcNo": 65, "title": "", "dispTitle": "无题 · KONpiGG #65", "surface": "两个宇航员a、b从太空回来，发现地球上只剩他们两个人，某天b死了，地球上人都回来了，a尝试跟他们对话后自杀了。请推断自杀的原因", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_c289acd5109e", "srcNo": 977, "title": "", "dispTitle": "无题 · hongqipiaopiao520 #977", "surface": "妹妹的房间传来很多球鞋摩擦地板的声音。", "cats": ["其他"], "difficulty": 2, "src": "github:hongqipiaopiao520/turtle-soup-chatroom", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_c29ae01ecae9", "srcNo": 279, "title": "050 · 双胞胎替换", "dispTitle": "050 · 双胞胎替换", "surface": "我一回家就立刻替死去的妹妹写遗书，对我来说，替她写遗书是很简单的，只要写下我想死的心情就好。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_c2f7a15f6c05", "srcNo": 790, "title": "分手", "dispTitle": "分手", "surface": "新闻报道一座雪山发生雪崩，以下是一段录音，请推理完整故事线：男「我们分手吧。」女「这是最后了？」男「嗯……」女「谢谢你，一直都给我这么多。」男「忘了吧，我们都需要新的开始。」", "cats": ["反转", "推理", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_c2fac9ec1da0", "srcNo": 1133, "title": "16 层公寓", "dispTitle": "16 层公寓", "surface": "我是一个高空清洁者，我正在探公寓 16 层窗户的时候，发现一对情侣正席在床上接吻，\n我只能看到男人的背影，但是女人特别漂亮,于是我绅士的先去清理别的楼层，等我再回来的\n时候，发现他们俩居然还在亲吻。于是我去把所有其他楼层都擦完了，可等我回到 16 层的时\n候，却发现床上只有一个剩下上半身的男人。", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_c38bb4781ca4", "srcNo": 492, "title": "油炸糕", "dispTitle": "油炸糕", "surface": "我从恶魔的地狱逃了出来，我吃不惯他们给的食物，但我依稀记得我最喜欢的是奶奶亲手做的油炸糕。\n我来到了奶奶家，但我看见有一头恶狼，在奶奶家厨房里徘徊，我打死了它，掉落了战利品，是油炸糕。", "cats": ["悲剧", "本格", "犯罪"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_c3dc8a18292b", "srcNo": 1177, "title": "人生倍速演算", "dispTitle": "人生倍速演算", "surface": "街上有很多同样的寻人启事: 张三 男 年龄: 20 岁 长相: 穿着白色的保罗衫，上面印\n有月亮图案。 身份; 生物学博士- 他曾发明出人类最伟大的科技一 人生倍速演算 此科技可在\n微观世界中演算出你人生的所有结果，帮助你找到最想要的那种。张三的备忘录: 1: 生物是\n怎么出现的?22: 他发现我了!41 或许会有和危险，他必须消失!!1 3: 我发现他了!5!4! 或许会有\n危险，我得提醒其他人!01!", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_c3e4256b231a", "srcNo": 202, "title": "100元钱", "dispTitle": "100元钱", "surface": "小明在图书馆看书，在一本书里翻到了100块钱，但是他却哭了。", "cats": ["其他"], "difficulty": 2, "src": "github:wangyafu/haiguitangmcp", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_c3eccad4ed5c", "srcNo": 573, "title": "永远不落幕的皮影戏", "dispTitle": "永远不落幕的皮影戏", "surface": "戏台上的锣鼓声喧天，光影摇晃，我正坐在龙椅上看着最喜欢的皮影戏。\n我好想去御花园扑蝶，可是我走不出这间大殿。\n我想给幕布上那个威风凛凛的将军盖上我的大红印章，但我发现我的朱砂印玺不见了。\n亚父夸我是个仁慈听话的好皇帝，说只要我乖乖喝下每天的“神仙玉露”，这出戏就能永远唱下去。\n可是，既然这皮影戏如此精彩，为什么那白绫幕布上，全是被我用力拍打出的、触目惊心的暗红斑块呢？", "cats": ["惊悚", "猎奇"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_c3ee67ea38bd", "srcNo": 176, "title": "", "dispTitle": "无题 · KONpiGG #176", "surface": "一个男人在路上走着，突然冲进电话亭打了一个无人接听的电话，之后心满意足的离开了，他在做什么？", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_c3fe6268a938", "srcNo": 848, "title": "美人鱼", "dispTitle": "美人鱼", "surface": "小美人鱼生活在自己的宫殿里，有一天，人类的王子落入了水中，被一条粉色的水蛇咬死了，过了好久，宫殿里没有其他食物，她只好把水蛇和王子都吃掉了。可能是吃撑了，她的肚子越来越大，最后被撑死在了水面上。水面上飘起了红色的水花。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_c40b385eec99", "srcNo": 580, "title": "绝望", "dispTitle": "绝望", "surface": "我被关在一个上下左右和后边都有墙的房间，房间内的温度正在不断升高。我想往前逃离房间，但是却发现前路被一堆丝絮堵住了。\n最终我绝望的被高温烫死了，我的灵魂从我破碎的身体中飘了出来", "cats": ["其他"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_c40eba2b5ea1", "srcNo": 1206, "title": "Jed 1.32", "dispTitle": "Jed 1.32", "surface": "A man is killed on a train. He is found to have written \"elf\" on the floor in his own blood. (MB, from \"The Problem of the Locked Caboose,\" by Edward D. Hoch)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_c4187685b9d1", "srcNo": 1084, "title": "最后一名宇航员", "dispTitle": "最后一名宇航员", "surface": "宇航员在太空舱里已经待了五年，补给耗尽。他决定打开舱门自我了断。开门后，他没有飘向太空，而是听到了热烈的掌声。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_c4452dce2ba3", "srcNo": 482, "title": "局内人", "dispTitle": "局内人", "surface": "本作品为校园题材的第一部，根据真实事件创作，致zyh（这是一个人名，对应汤面里的“他”，但字母本身不重要）。\n从六年级开始，他就对我格外留意。升入七年级后，他的态度变得愈发奇怪。\n也是从七年级开始，班里每周五都会匿名投票，选出一男一女。久而久之，投票结果几乎固定不变。\n我找他谈过，他只对我说了一句：“你是局内人。”\n很久以后，我才真正明白，这一切和每周的投票到底有着怎样的关联。", "cats": ["校园"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_c461111b43f5", "srcNo": 1134, "title": "侠客", "dispTitle": "侠客", "surface": "妊帮建籽一侠客，正在担灭那教，不知怎的来到这妖异之地，定是教头的琴音所致。这\n街上跑的飞快的四轮之物是什么? 哦? 竟有几人对我不敬，说我冯什么灯，定是那教之人,我\n剑气寒光, 将几人斩杀, 周围人四散而逃。这时来了几个蓝衣壮汉将我围住,看起来像当差的，\n我不愿与官家结仇，溜之大吉，却未曾想轻功失效，随即被的，带到了此地的县衙。我不知我\n为何会在此地? 几个年轻人来看我，届着叫我爸爸。可笑，我也不比几人大多少，一派胡言，\n可照镜子那一刻我呆住了,我怎苍老这般? 当差的把我带去问诊，可我清楚我没有病。你们能\n帮攻我吗?", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_c4cc3c0a63a6", "srcNo": 328, "title": "天界之笛", "dispTitle": "天界之笛", "surface": "地龙的新形态终于来了：速度暴涨，不再四倍弱冰，飞得又快又高。\n\n暴飞龙盯着他背上舒展的翅膀，脸色一变；巨金怪盯着他掠过的残影，脸色也一变。地龙正开心得转圈，忽然看见山巅上一条绿色身影正死死盯着他 —— 当晚，他把天界之笛埋进了流星瀑布最深处。", "cats": ["怪谈", "脑洞"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_c557ba8686a0", "srcNo": 762, "title": "人脸", "dispTitle": "人脸", "surface": "我玩手机，偶然看了一眼窗外，看到一张人脸，我知道我完了。", "cats": ["搞笑", "日常", "校园"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_c56c62db40b5", "srcNo": 712, "title": "午夜列车", "dispTitle": "午夜列车", "surface": "离午夜还有五分钟，男子上车逐个猜对乘客年龄。问到婆婆时她说：不是，再过五分钟我才69。男子脸色惨白。", "cats": ["怪谈", "悬疑", "惊悚"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_c5b078318d27", "srcNo": 127, "title": "", "dispTitle": "无题 · KONpiGG #127", "surface": "我躺在床上问妈妈：\"雪怪真的会来吗？\"妈妈说，只要你乖乖睡觉不下床就不会来。半夜，我见到了雪怪。但是，雪怪的原则，只有雪怪才会遵守。在看到雪怪的那一刻，我的结局就已经注定了。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_c67f366c50ed", "srcNo": 1392, "title": "", "dispTitle": "无题 · boop-yyt #1392", "surface": "An ordinary woman walks on water. How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_c69a4e625266", "srcNo": 399, "title": "盛世的丧钟", "dispTitle": "盛世的丧钟", "surface": "最后一次撞击。伴随着沉重的巨木撞上青铜，他感受到了脚下传来万军开拔般磅礴的震颤，眼前无尽的黑夜被漫天盛大的“红绸”映照得无比耀眼。滚烫的气浪扑面而来，那是新皇恩赐的暖意。老者满含热泪，朝着高塔下方恭敬地跪拜。他不知道的是，此时他的身下，其实早已没有一座完整的宫殿了。", "cats": ["反转", "悲剧"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_c6df7b68bd53", "srcNo": 932, "title": "奇怪的爸妈", "dispTitle": "奇怪的爸妈", "surface": "星期日 爸爸出差回来后抱着我哭了起来，我不明所以。晚上，我听见爸爸在院子里大喊“诡啊！！！”我很害怕，于是锁上房门等妈妈下班。星期三 妈妈递给我一个定位手表，严肃地和我说：“你爸爸不对劲！尽量远离他。”爸爸下班后和我说：“你妈妈不对劲，爸爸一会带你走！”我不想走，爸爸却直接将我打晕了。星期四 等我醒来，我发现我在一个山洞里，妈妈居然在这，她好像在埋什么，这有个大坑，她和我说：“儿子，走！回家了。”晚上妈妈找爸爸谈了好久，妈妈抱着爸爸大哭，爸爸脸色难看，但犹豫一下后还是安慰了妈妈。星期五 今天爸爸带我去了游乐场，我玩得很开心。回家后妈妈做了大餐，但爸爸又突然脸色难看，久久无言。晚上妈妈久违的抱着我睡觉了。星期一 爸爸下班回来后抱着我哭了起来“对不起。”爸爸说完这句话之后，我便没了意识。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_c750c42858e6", "srcNo": 910, "title": "猜名字", "dispTitle": "猜名字", "surface": "家里闹鬼了，我和爱人找来一位大师帮忙解决。大师说他有怨气，你们在屋里摆满白烛并喊他的名字，便可散其怨。午夜，阵阵阴风吹灭了蜡烛，爱人急忙喊其姓名，可听到后我却不可置信的看着她。我知道，我们死定了……", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_c75c0fe5e560", "srcNo": 607, "title": "东南西北", "dispTitle": "东南西北", "surface": "听说小镇最近很不太平，南西北三个方位都出现了命案，但不知为何，就算不杀掉他们，他们也活不下去了。凶手为什么要多此一举，似乎遵循某种规律？令人费解。夜晚，住在东方的一名女子突然明白了什么，面露惊恐，一阵阵疼痛传来，已经迟了........", "cats": ["逻辑"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_c7d9dd90b925", "srcNo": 105, "title": "", "dispTitle": "无题 · KONpiGG #105", "surface": "我和女朋友吵了一架，然后她和我都死了。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_c7ebf7e9dceb", "srcNo": 651, "title": "往回走才能逃出去", "dispTitle": "往回走才能逃出去", "surface": "故事里，一座桥连接甲乙两地。甲地守卫每隔几分钟才出来查看，严禁居民离开；对没有许可的来客，则一律命令原路返回。女人没有证件，想从甲地去乙地，最后却被守卫亲自赶去了乙地。她做了什么？", "cats": ["推理", "旅途"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_c824f2e2e39b", "srcNo": 101, "title": "", "dispTitle": "无题 · KONpiGG #101", "surface": "爸爸遇到了船难，儿子再也没动过了", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_c83298d35144", "srcNo": 1381, "title": "", "dispTitle": "无题 · boop-yyt #1381", "surface": "Two people are playing cards. One looks around and realizes he's going to die. How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_c84fc1792640", "srcNo": 325, "title": "099 · 棺材里的人（经典版）", "dispTitle": "099 · 棺材里的人（经典版）", "surface": "五个人走在路上，下雨了，四个人加快脚步，一个人不急。最终五人同时到达目的地，四人淋湿，一人未湿。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_c86242207350", "srcNo": 937, "title": "欺诈师", "dispTitle": "欺诈师", "surface": "警探，这次你要审问的是一名欺诈师，他与正常人不同，哪怕在潜意识层他也会有三次对你说谎的机会，请注意辨别。以下是你的任务：1. 调查戴维死因 2. 追回历史文献 3. 找到他的三个谎言 准备好了吗？我要开始进行意识链接了。欢迎X位来到我的精神世界，我将全力配合警方审讯。警探：查尔斯，你杀了最伟大的历史学家戴维，并偷走了刚出土的历史文献，你承认吗？查尔斯：是的，我承认。据说他发现了一个新的上古文明，文物价值连城，文献是能填补历史的空缺，谁会不心动呢？警探：历史文献被你藏在哪里了？查尔斯：当然藏在一个我一定会去的地方了。警探：你是怎么杀死戴维的。查尔斯：他让我杀死他的，我保证。警探：以上你的回答，全部属实吗？查尔斯：哈哈，当然不是了警官，我有三个谎言呢，你忘了吗？", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_c8cac6026c94", "srcNo": 1242, "title": "最后一根火柴", "dispTitle": "最后一根火柴", "surface": "一个人被困在冰天雪地的荒野里，身边只有几根火柴。他划亮最后一根火柴看了一眼，然后选择不再挣扎。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:lancelily6362-png/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_c90861a96fd3", "srcNo": 245, "title": "011 · 出租车", "dispTitle": "011 · 出租车", "surface": "杰克上了一辆出租车，让司机快点把他送到目的地。不久之后，他被枪杀了。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_c9a312d8972e", "srcNo": 842, "title": "吹蜡烛", "dispTitle": "吹蜡烛", "surface": "家里闹鬼了，我找了一个大师帮我解决，大师说要想保命就需要做到以下三点，过了今晚就会安然无恙：1. 这根用来驱邪的蜡烛你千万不要吹灭，不然就会死；2. 家里只有你一个人，任何人喊你的名字都不要回应，包括我；3. 哪怕过了今晚，你这辈子晚上都不要关灯，否则就会看到鬼。果然我平安度过了今天，但是却在几个月之后死了。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_c9a6ee02f379", "srcNo": 571, "title": "正义", "dispTitle": "正义", "surface": "我是一个正义的人，这天，我照常在保护一个女孩子，却被怪物吓疯了。", "cats": ["本格"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_c9a9818be587", "srcNo": 432, "title": "别开门", "dispTitle": "别开门", "surface": "妈妈说：“别开门。”爸爸说：“快开门。”我说：“快开门！”", "cats": ["犯罪", "逻辑"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_c9f8373199de", "srcNo": 1164, "title": "墓碑上的文字", "dispTitle": "墓碑上的文字", "surface": "我和和爸妈一起去旅行，回来时却出了意外，区妈立马打算要二胎。五十年后，儿孙满堂，\n爸妈去世了,我的孙子给爸妈操办了葬礼，我看着墓碑上的文字，却突然头皮发麻! 原来一切\n都错了!", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_ca14260d00d9", "srcNo": 658, "title": "迟迟不肯加速", "dispTitle": "迟迟不肯加速", "surface": "男人开着完好的车，速度始终很慢。旁边的乘客不断提醒他别开快。他不是新手，前面也不堵车，后面却有一群人一直跟着。为什么？", "cats": ["推理", "日常"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_ca1fd78e91b8", "srcNo": 497, "title": "顽固污渍", "dispTitle": "顽固污渍", "surface": "高端会所的休息室里，男人将一叠粉红色的纸砖甩在我的脸上，要求我清理他'过剩的欲望'。\n我退无可退，哭诉自己只负责清洗衣物，不负责清洗别的。\n他却咆哮着将我按倒在沙发上，以此证明权力的重量。\n在窒息的边缘，我摸到了包里那柄平日用来削去果皮的'铁片'。\n刹那间，红色的染料喷涌而出，染红了那叠钞票。\n事后，所有人都说，这下他终于彻底'干净'了。", "cats": ["反转", "推理", "犯罪"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_ca269cf19d03", "srcNo": 444, "title": "电梯矮子", "dispTitle": "电梯矮子", "surface": "矮子住10楼，每天上班坐电梯到1楼，但回来只坐到7楼自己爬楼梯，除非下雨天。为什么？", "cats": ["日常"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_ca411d1cf9c1", "srcNo": 1195, "title": "Jed 1.9", "dispTitle": "Jed 1.9", "surface": "An avid birdwatcher sees an unexpected bird. Soon he's dead. (RSB original)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_ca43702db709", "srcNo": 685, "title": "镜中时间", "dispTitle": "镜中时间", "surface": "我醒来瞥了眼镜子里的时钟又躺下，结果永远睡过去。", "cats": ["反转", "悬疑", "推理"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_ca618df9d6da", "srcNo": 1210, "title": "Jed 1.43", "dispTitle": "Jed 1.43", "surface": "The king dies and two men both claim to be his long-lost son. One of the king's advisors proposes a test to determine the identity of the true heir. One claimant agrees to the test; the other refuses. The one who agreed is sent packing; the one who refused is identified as the rightful heir. (SP, from _The Next Book of OMNI Games_; earlier from _How Come?_)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_ca6c5df5e1d3", "srcNo": 872, "title": "宿舍规则怪谈", "dispTitle": "宿舍规则怪谈", "surface": "1．不要在夜晚的时候使用卫生间；2．宿舍会提供食物，但不可以贪吃；3．室友不是两个，而是三个；4．室友只有两个；5．室友只有一个。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_ca6d37850951", "srcNo": 1180, "title": "444 究室", "dispTitle": "444 究室", "surface": "+汤底 学校住宿的同学们都知道三条规则不能触犯: 1. .23:00 之后千万不要离开究室〈因\n为23: 00 究室封究了) 2. 不要去厕所的第 4 隔间《〈这是最后一个隔间，用来存放打扫用品)\n3. 不要听 444 究室的录音机 我刚好就在 444 究室, 我好奇地打开了收音机。“我是什么佛”(这\n是倒放后的一句话，原话是: 倒放的是狗) 什么嘛，只是一段很正常的录音,- 于是我就去睡觉\n了。 (我并没有意识到这是一句倒放的语音)", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_cab98c529eaf", "srcNo": 108, "title": "", "dispTitle": "无题 · KONpiGG #108", "surface": "铛铛铛，\"这个没熟\"，铛铛铛，\"这个好像熟了！\"，突然，我的爸爸被吓出一身冷汗。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_cb03c5556b09", "srcNo": 723, "title": "1237", "dispTitle": "1237", "surface": "幼儿园小朋友数数总说“1，2，3，7”，我纠正她，她说是妈妈教的。我去家访后，也对她说“1，2，3，7”。", "cats": ["亲情", "日常", "温情"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_cb3f4181fcf6", "srcNo": 1101, "title": "从来不休息的同事", "dispTitle": "从来不休息的同事", "surface": "公司小王是一个工作狂，每天加班同事产出很优秀，而且从来没有人见过他休息的样子，他也从来没有和任何人吃过饭。奇怪的是他每天下午都会消失5分钟，这是为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:Tenzyoo/turtle_soup_game", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_cb48ce3aeb75", "srcNo": 1178, "title": "村中诡事", "dispTitle": "村中诡事", "surface": "小红经历过一场车祸，因此觉醒了超能力。可小红却不知道能力是什么，父母也不和她\n说, 只叫她做个正常人就好。 直到和丈夫离婚那天, 小红才明白她的能力!她很想成为正常人!1\n直到她在村子里做了某件事，才如愿以偿。", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_cb4c1c8363f6", "srcNo": 1129, "title": "牧场", "dispTitle": "牧场", "surface": "妈妈去世了，留给我一个废弃已久的牧场。第二天牧场里不知道从哪来了一只鸡，第三\n天又多了一头牛，第四天又多了一只羊，我很证异。接下来一个月二 牧场多了很多动物，我终\n于明白怎么回事了。于是我做了一个疯狂的决定，结果第二天牧场里多出了一个年轻的女人，\n看到她后我疯了.………", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_cb5ea96c19db", "srcNo": 859, "title": "笔仙", "dispTitle": "笔仙", "surface": "笔仙笔仙，你是我的前世，我是你的今生，如要与我续缘，请在纸上画圈。忧郁的男人第一个提问：“她是不是不爱我了？”笔动了，落在了“是”字上，看到答案，他松了一口气。华贵的老妇人接着问：“我是不是真的永远不会变老了？”“是”，老妇人露出了放心的笑容。美丽的少妇又问：“是不是有人知道我的秘密了？”“是”，少妇变得紧张起来。笔又自发地缓缓动起来，拼出了几个字：“你们知道，我是谁吗？”", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_cc0562ec66d0", "srcNo": 584, "title": "学艺不精", "dispTitle": "学艺不精", "surface": "开门的一瞬间，我后悔了。\n我明白了师傅为什么在临终时说我学艺不精。\n现在的我拥有很多财宝，但是我真正需要的东西却越来越少了。", "cats": ["悲剧", "本格"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_cc6c851e70e2", "srcNo": 660, "title": "陌生的口令", "dispTitle": "陌生的口令", "surface": "几名警员没学过某门外语，却被要求熟记其中几句命令。出勤时他们只需说，不必听懂对方的回答，也不需要翻译。为什么？", "cats": ["反转", "职场"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_cc7fc2bcb811", "srcNo": 1080, "title": "不会融化的冰块", "dispTitle": "不会融化的冰块", "surface": "夏日炎炎，男子在冰箱里发现了一块不会融化的冰，他好奇地舔了一口，然后惊恐地把自己关进了浴室开始疯狂洗胃。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_cc9e2fec9557", "srcNo": 890, "title": "给三兄弟的一封信", "dispTitle": "给三兄弟的一封信", "surface": "H₂O+SiO₂+Fe₃O₄+CO₂→∅，x2+y2−13=x2y3+∞", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_ccb1e81e83db", "srcNo": 158, "title": "", "dispTitle": "无题 · KONpiGG #158", "surface": "一对夫妻驾车旅游，在山路上抛锚了。因为新闻上说附近有一位连环杀人案的在逃犯，所以丈夫在下车求救前和妻子约定，如果敲车门三下就给开门。到了深夜，妻子听到了敲门声，但每次都是两下。请问，为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_ccc003a29e20", "srcNo": 485, "title": "红色高跟鞋", "dispTitle": "红色高跟鞋", "surface": "一位女士去鞋店里买了一双红色高跟鞋，这双高跟鞋预示了她今晚的死亡。", "cats": ["职场", "逻辑"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_cceb5339e47e", "srcNo": 556, "title": "听雨阁下的浊流", "dispTitle": "听雨阁下的浊流", "surface": "陈老爷将那卷泛黄的图纸摊在红木桌上，满脸红光地向我炫耀他为新纳的六姨太修建的“听雨阁”。\n那是一座立于荷塘中央的精美水榭，只有一条曲桥相连，看似是一处绝佳的静养之地。\n我盯着剖面图上那复杂的榫卯结构，目光越过飞檐，凝固在水面之下那层厚得不合常理的地基空腔上。\n“这底座的防潮设计确是下了血本，”我违心地称赞了一句，指尖却重重按在了一条连接书房与水榭地底的黑色管道上，\n“不过陈老爷，既然这只是一条用来排污的暗渠，为什么里面要铺上一层用来消音的软毡呢？”", "cats": ["悬疑", "本格"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_ccfc9c8ca8ae", "srcNo": 355, "title": "天使之泪", "dispTitle": "天使之泪", "surface": "深夜，女人走进了一家正热闹的酒吧，浏览菜单后为自己选了一杯酒。不久后，警察来了。", "cats": ["日常", "逻辑"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_cd1400cb152f", "srcNo": 642, "title": "John在路上开着车", "dispTitle": "John在路上开着车", "surface": "John在路上开着车，他打开了收音机听了几分钟。\n\n 忽然掉头回家，然后枪杀了他的妻子。\n\n 你猜猜这是怎么一回事呢？", "cats": ["其他"], "difficulty": 2, "src": "haiguitang.cn/海龟浓汤", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_cd62b214d9bf", "srcNo": 1058, "title": "外星人的礼物", "dispTitle": "外星人的礼物", "surface": "外星文明降临地球，没有战争，只是给全人类发放了一种‘永不枯竭的能量罐’。一年后，人类文明彻底毁灭了。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_cd9ed1dacda9", "srcNo": 963, "title": "", "dispTitle": "无题 · White-stone36 #963", "surface": "某日五名男子一同前行。突然天上下起雨来，只有四人加快了步伐，而最后，五人同时到达且的地。加快脚步的四人成了落汤鸡，而第五人却一点也没湿，请推理。", "cats": ["其他"], "difficulty": 2, "src": "github:White-stone36/Situation_puzzles_games", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_cdb125b07c4e", "srcNo": 810, "title": "小说家的遗书", "dispTitle": "小说家的遗书", "surface": "一名知名小说家被发现在家中自杀，现场留下了一封遗书，写着：「我已经无法再承受这样的压力，请不要找任何人负责。」警方原本认定是自杀案，但一名刑警读完遗书后却立刻表示：「这是一场谋杀案！」警方为什么这么确定？", "cats": ["悬疑", "推理", "犯罪"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_ce0cc6ec6eb1", "srcNo": 998, "title": "南极探险队", "dispTitle": "南极探险队", "surface": "探险队四人在南极迷路。当晚，他们决定每人守一角，轮流叫醒下一个人。第二天，他们都活了下来，但其中一个人却疯了。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_ce0d22772bbb", "srcNo": 1266, "title": "电梯里的陌生人", "dispTitle": "电梯里的陌生人", "surface": "一个人走进电梯，看到里面有一个陌生人。他按了10楼，陌生人按了5楼。电梯到达5楼时，陌生人出去了。这个人到了10楼后，突然意识到什么，立即报警。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:ns5601/ai-haigui-game", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_ce43cf3db28a", "srcNo": 152, "title": "", "dispTitle": "无题 · KONpiGG #152", "surface": "我吃了爷爷种的菜，我疯了，爷爷被警察带走了", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_ced8e1992e22", "srcNo": 301, "title": "073 · 永远的18岁", "dispTitle": "073 · 永远的18岁", "surface": "你的朋友D约你作为伴郎参加他的婚礼，但就在婚礼前几天，你接到了警察的电话，问你是否认识\"永远的十八岁\"这个人。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_cf1d3a3e63f6", "srcNo": 10, "title": "第三杯水", "dispTitle": "第三杯水", "surface": "桌上有三杯水，只有第三杯被喝完了。警察因此确定他在撒谎。", "cats": ["其他"], "difficulty": 2, "src": "github:17hczmsn/turtle_soup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_cf3e6fe7ac2d", "srcNo": 319, "title": "091 · 原版海龟汤（必玩）", "dispTitle": "091 · 原版海龟汤（必玩）", "surface": "一名男子走进餐厅，点了一碗海龟汤，喝了一口后，回家自杀了。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_cf76064afbb3", "srcNo": 112, "title": "", "dispTitle": "无题 · KONpiGG #112", "surface": "\"我要做个好孩子，我是个好孩子…\"我不停对自己说道。新闻报道了一起凶杀案，凶手至今下落不明…", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_cfaf83c37962", "srcNo": 752, "title": "生产", "dispTitle": "生产", "surface": "「生出来了，老婆你辛苦了。」「给我看看孩子。」孩子死了，老婆欣慰地笑了。", "cats": ["亲情", "反转", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_cfb39344e7bd", "srcNo": 763, "title": "长高", "dispTitle": "长高", "surface": "我好像长高了：眼睛平视四楼，脚却站在一楼。", "cats": ["怪谈", "恐怖", "悬疑", "惊悚"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_cfb9d8600517", "srcNo": 157, "title": "", "dispTitle": "无题 · KONpiGG #157", "surface": "day1 \"大哥，我今天和二哥一起唱歌了\" day2 \"大哥，我今天和二哥一起捉迷藏了\" day3 \"大哥，我今天和二哥一起下象棋了\"，大哥听后吓傻了 day4 大哥死了", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_cfceaaca7bff", "srcNo": 611, "title": "春蚕", "dispTitle": "春蚕", "surface": "为了根治严重的失眠，我花重金躺进了那台号称能提供完美深层睡眠的“春蚕”仿生舱。然而梦境系统似乎出了故障：我没有看到宣发中治愈的春日桑林，反而看到无数肥硕的苍白幼虫在啃食着人类的颅骨，它们吐出的丝线里，纠缠着暗红的血管和毛发；哪怕切换成“纯净”外观，舱壁上也全是指甲抓挠出的绝望血痕。我强忍着恶心，按下了说明书最后标注的“视角切换”键，强制开启了最高等级的“抽丝模式”。瞬间，那些令人作呕的画面消失了。一种前所未有的温暖和安全感包裹了我，我感到自己变得无比轻盈，仿佛有无数根柔软的银丝正从“我”的体内被源源不断地抽离出来，在虚空中交织成一个完美的避风港。我惬意地闭上眼，沉浸在这极度的舒适中。直到一阵仿佛要将五脏六腑彻底掏空的剧痛从腹腔猛烈袭来，我才猛然惊觉，那些被源源不断“抽离”出身体的，究竟是什么。", "cats": ["反转", "悬疑", "猎奇", "都市传说"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_d01c47bb82f4", "srcNo": 575, "title": "不死之身", "dispTitle": "不死之身", "surface": "我最好的朋友们在我身上砍了很多刀，但最终，我还是没有死", "cats": ["搞笑"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_d03a68f1e0d1", "srcNo": 84, "title": "", "dispTitle": "无题 · KONpiGG #84", "surface": "晚上，我在寝室洗了个头，结果室友和我都死了。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_d08b0db8da5e", "srcNo": 812, "title": "命运的倒转", "dispTitle": "命运的倒转", "surface": "一名男子遭遇意外，受伤倒在偏僻的马路旁，血流不止。他努力撑着最后一口气，终于看见远方有车辆驶来，内心充满希望。然而，当车停下来，驾驶下车后，男子看清楚对方的脸，却突然开始剧烈挣扎，拼命往后爬，脸上充满惊恐，似乎比刚才还要害怕……然后，不到两分钟，他便因失血过多死亡。请问，他为什么反应如此剧烈？", "cats": ["反转", "悬疑", "惊悚", "推理", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_d094556552e4", "srcNo": 847, "title": "村庄", "dispTitle": "村庄", "surface": "男孩第一次去女朋友家拜访，村子里都用异样的眼光看着男孩，他在女友家住了一夜。第二天早上醒来，男孩惊恐地发现，女朋友的父亲居然死了，而男孩则成为女友的老公。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_d0b574031241", "srcNo": 472, "title": "院落里的微光", "dispTitle": "院落里的微光", "surface": "我曾守着一处寂静的院落，四季如常，却总少了一抹应有的生机。旁人来看过，说我照料不周，眉眼间尽是疏离与苛责。他立在院中，左右为难，眼底藏着化不开的疲惫与心疼。 那日，他轻轻递来一页薄纸，我捧着那张纸，眼眶一热，怎么也止不住。曾冷若冰霜的目光，瞬间化作殷勤的暖意，生怕我转身离去。 我在长夜中静静思量，终是选择留在这座院落。此后多年，晨昏冷暖，皆被妥帖安放，一茶一饭，都盛满了小心翼翼的温柔。 直到整理旧物时，我才撞见那张被深藏的纸，恍然明白，原来是他替我扛起的整座院落。我奔向他，泪落如雨，他只轻轻拥我入怀，说不过是不愿我受半分委屈。 后来，我们从远方带回一束微光，以为是岁月馈赠的圆满。却不知，那束光本就扎根在别处，只是被悄悄移来，安放在了我们的院落里。", "cats": ["反转"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_d0df207d29a2", "srcNo": 769, "title": "手机", "dispTitle": "手机", "surface": "手机响了，疲惫的我看了一眼手机，瞬间毛骨悚然。", "cats": ["悬疑", "惊悚", "都市"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_d0e1ce0adbd1", "srcNo": 1263, "title": "没写完的遗书", "dispTitle": "没写完的遗书", "surface": "富商留下了一封只写到一半的遗书，警方却据此判断这不是自杀。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:lancelily6362-png/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_d1311dd29bf1", "srcNo": 520, "title": "不存在的笛手", "dispTitle": "不存在的笛手", "surface": "民俗学者在整理昭和初期的田野调查资料时，发现了一卷标记为《夜神乐：鬼降》的磁带。\n那是村落里一场极其罕见的太鼓独奏，鼓点密集得如同暴雨，令人窒息。\n学者在笔记中赞叹：‘鼓手的技艺通神，尤其是那忽隐忽现的伴奏笛声，凄厉婉转，如同幽灵的呜咽，在鼓点的间隙中挣扎求存，技艺绝伦。’\n但我反复听了那段录音，背脊发凉。\n因为查阅当年的祭典照片，舞台上自始至终只有那个疯魔般的鼓手一人。\n而且，那最后全村人整齐划一的一声喝彩，掩盖了一个极为沉重的、类似麻袋坠地的闷响。", "cats": ["怪谈", "悬疑"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_d150c051a079", "srcNo": 1121, "title": "奇怪的声音", "dispTitle": "奇怪的声音", "surface": "之前的支教坪了，于是把我派去山里支教，我借宿在村长家里，他们家门口贴了一张奇\n怪的黄纸，而且他们家每天晚上都会传来沉闷的吃吃声，我发现这个声音是有规律的，于是我\n记了下来 96924482622454，三天后，声音消失了，我也明白声音是什么了，是那五个字。", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_d17e476aeabd", "srcNo": 960, "title": "", "dispTitle": "无题 · White-stone36 #960", "surface": "一个男人走进一家餐馆，向服务员要了一杯凉水。然而服务员没有给他，并突然掏出一把枪顶在了男人的脑袋上。随后男人说了句谢谢，就离开了餐厅", "cats": ["其他"], "difficulty": 2, "src": "github:White-stone36/Situation_puzzles_games", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_d18a8dcc9c6c", "srcNo": 1228, "title": "Jed 2.5", "dispTitle": "Jed 2.5", "surface": "A black man dressed all in black, wearing a black mask, stands at a crossroads in a totally black-painted town. All of the streetlights in town are broken. There is no moon. A black-painted car without headlights drives straight toward him, but turns in time and doesn't hit him. (AL and RM wording; from _How Come?_)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_d1a2c033cc78", "srcNo": 442, "title": "外卖", "dispTitle": "外卖", "surface": "我每天中午都会点同一家外卖。\n连续一个月，每次送餐的都是同一个骑手。\n他从来不说话，把餐放在门口就走。\n今天我没点餐，门铃却响了。\n我打开门，他站在门口，手里没有餐。\n他说：“你一个月没出门了，我担心你。”", "cats": ["反转", "恐怖", "悬疑"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_d1d17a5e66de", "srcNo": 398, "title": "动画", "dispTitle": "动画", "surface": "我在泥泞里欢笑， 我的爸爸妈妈都不是人，爸爸妈妈很爱我", "cats": ["搞笑"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_d1fc971bd1d5", "srcNo": 500, "title": "马戏团", "dispTitle": "马戏团", "surface": "马戏团里有两个侏儒，瞎子侏儒比另一个侏儒矮。马戏团只需要一个侏儒，马戏团的侏儒当然是越矮越好了。两个侏儒决定比谁的个子矮，个子高的就去自杀。可是，在约定比个子的前一天，瞎子侏儒，也就是那个矮的侏儒已经在家里自杀死了，地上残留着许多碎木屑。他为什么自杀?", "cats": ["其他"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_d213c4660270", "srcNo": 1089, "title": "", "dispTitle": "无题 · zhuqingxu #1089", "surface": "便利店劫案监控拍到了劫匪摘头盔后的正脸，画面清晰。警方锁定某人，可他有高铁票与大量证人证明案发时整段车程都在列车上，列车与站台监控也能印证。劫案监控是实时而非回放。这可能吗？", "cats": ["其他"], "difficulty": 2, "src": "github:zhuqingxu/ai-haigui-game", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_d2c1a351b193", "srcNo": 273, "title": "043 · 艺术家的画", "dispTitle": "043 · 艺术家的画", "surface": "艺术家买了一幅画叫做《雨中的女郎》，一天他的朋友来到他家欣赏。次日，艺术家来到画室，《雨中女郎》旁边挂着一幅画，空气中有一股淡淡的味道，朋友失踪了，艺术家惊恐地烧了《雨中的女郎》。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_d2c29b709ab6", "srcNo": 476, "title": "道具", "dispTitle": "道具", "surface": "一位男子为自己的工作定制了一副全新的、镶有碎钻的金属工具。\n不过马上他就要后悔——因为今晚之后可能再也用不到它了", "cats": ["反转", "猎奇"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_d2c4b827fd86", "srcNo": 235, "title": "雨伞", "dispTitle": "雨伞", "surface": "下雨天，我撑着一把伞出门。回来的时候伞不见了，可我却浑身干爽。", "cats": ["日常", "逻辑"], "difficulty": 1, "src": "github:AZHi-xinxin/haiguitang-coop", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_d2f7e07d3cda", "srcNo": 536, "title": "魚缸", "dispTitle": "魚缸", "surface": "一名婦女將魚缸打碎，然後很滿意地微笑，為什麼？￼", "cats": ["反转", "逻辑"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_d3275183e3d1", "srcNo": 1253, "title": "湿透的狗", "dispTitle": "湿透的狗", "surface": "晴天回家时，女孩看到自家狗浑身湿透，立刻知道爷爷今天又偷偷出过门。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:lancelily6362-png/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_d3387b42d13a", "srcNo": 218, "title": "水池中的死者", "dispTitle": "水池中的死者", "surface": "一名男子被发现死在一间空荡荡的房间里，附近只有一池水。他怎么死的？", "cats": ["其他"], "difficulty": 2, "src": "github:wangyafu/haiguitangmcp", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_d3a85fa4202e", "srcNo": 378, "title": "喝水", "dispTitle": "喝水", "surface": "有一位男子常驻在了一家饭店，某一天他再也不敢喝饭店里的水了，请问为什么？", "cats": ["恐怖"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_d3bf05769a3c", "srcNo": 853, "title": "妹妹的房间", "dispTitle": "妹妹的房间", "surface": "妹妹的房间传来很多球鞋摩擦地板的声音，房门虚掩着，我开门看了一眼，妹妹空洞的眼神正望着我，我急忙去叫保安，结果我死了。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_d3c52f26b4cd", "srcNo": 628, "title": "灯塔关灯", "dispTitle": "灯塔关灯", "surface": "灯塔看守人半夜把灯关掉，导致海上多艘船相撞沉没，他自责自杀。", "cats": ["悬疑"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_d3c73d8a0731", "srcNo": 1387, "title": "", "dispTitle": "无题 · boop-yyt #1387", "surface": "Variant wording: Instead of \"home,\" say the man in the mask is standing on the corner. How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_d42d3da48c86", "srcNo": 518, "title": "最后的安眠", "dispTitle": "最后的安眠", "surface": "明亮的阳光包裹着我，我躺在草地上，浑身放松。青草的柔软触感如此真实，甚至能闻到泥土的气息。我懒洋洋地睁开眼，看见远处有几个模糊的人影在嬉闹。真舒服啊，我想一直这样躺着，什么都不用想……", "cats": ["恐怖", "本格", "犯罪"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_d4356e3192b7", "srcNo": 1209, "title": "Jed 1.37", "dispTitle": "Jed 1.37", "surface": "A man is running along a corridor with a piece of paper in his hand. The lights flicker and the man drops to his knees and cries out, \"Oh no!\" (MP)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_d4546e003ccd", "srcNo": 926, "title": "听妈妈的话", "dispTitle": "听妈妈的话", "surface": "7月12日 我在网上听说有一所废弃医院，晚上经常会传出恐怖的声响，我邀请朋友明天去探险，他爽快答应了。7月13日 “你能不能好好学习！”妈妈斥责我，随后把我锁在房间。我十分委屈，但只能和朋友说改天了。晚上，我偷偷地溜出去，独自前往那所废弃医院。里面有很多废弃医疗器械，还有一些小动物的尸体。我听到一个声音：“心脏，心脏！！！”真的闹鬼！7月16日 妈妈早上给我端来了一碗黏糊糊的东西，很好喝。我和朋友说了我在医院的经历，他约我再去一次，作业还没写完，我拒绝了他。7月17日 朋友实在太好奇我在医院里发生的灵异事件了，我虽然很抗拒，但还是被他生拉硬拽地带去了。我们除了地上的血迹什么都没发现，直到晚上，又传来了那个声音：“血液！眼球！！”远处出现一个满身是血的人，他手里拿着一颗腐烂的心脏和一把刀冲向我们。我们急忙开溜，逃跑的过程中还摔了一跤，但有惊无险地逃出去了。他并没有追上来，我松了一口气对朋友说了四个字。朋友愣愣地看着我。我见他没听清，又说了一次。他颤抖着逐渐与我拉开距离。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_d47dd44d7c3d", "srcNo": 1045, "title": "重叠的指纹", "dispTitle": "重叠的指纹", "surface": "一名科学家在实验室被杀，警方发现现场只有他自己的指纹。不久后，科学家在另一座城市‘复活’了，并向警方投案自首。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_d48624c2752a", "srcNo": 79, "title": "", "dispTitle": "无题 · KONpiGG #79", "surface": "我的妈妈很爱我，可自从下过一场大雨之后，她就把我关进了一个伸手不见五指的小黑屋，可当我再次见到她时，她已经变得面目全非！我知道，我们将会永远在一起！", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_d49ef38f39d9", "srcNo": 121, "title": "", "dispTitle": "无题 · KONpiGG #121", "surface": "爸爸带着女儿去了山上，进去后女儿说山上有个庙，她想去看看，爸爸没有放在心上，过了一会爸爸想叫女儿回家了，他找到了这个庙，推开门却发现里面只有一棵松树，四面都是白墙，却不见女儿的踪影 ……", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_d4c40981ff38", "srcNo": 429, "title": "乖孩子的礼服", "dispTitle": "乖孩子的礼服", "surface": "父亲为我穿上了一件沉重而特别的“礼服”，他说这是通往新世界的门票，能阻挡世间一切恶意。\n那是一场漫长的“私奔”，我们骑着咆哮的钢铁巨兽，在荒漠中把身后闪烁着红蓝光芒的“恶龙”远远甩开。\n我从未感到如此自由，每一次回身扣动手指，身后便绽开一朵绚烂的火花，击退那些试图靠近的利爪。那是独属于我和父亲的烟火祭典。\n当巨兽终于力竭倒下，我穿着那身引以为傲的礼服，向着赶来的人群走去，想要展示我的英勇。\n我以为迎接我的是新世界的加冕，可为什么，回应我的却是几十声震耳欲聋的雷鸣，和穿透胸膛的灼热？\n明明直到最后一刻，我都是最听爸爸话的乖孩子。", "cats": ["反转", "悲剧", "惊悚", "犯罪"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_d4d638dadd21", "srcNo": 653, "title": "安静的清晨", "dispTitle": "安静的清晨", "surface": "退休老人原本每天黎明前都会醒来。一天，他把院子里的一个活物送走，此后终于能睡到天亮。他没有换床，也没有服药。为什么？", "cats": ["日常"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_d54c7f270c6d", "srcNo": 1351, "title": "", "dispTitle": "无题 · boop-yyt #1351", "surface": "The music stops and a woman dies. How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_d55a409e3e25", "srcNo": 1226, "title": "Jed 1.92", "dispTitle": "Jed 1.92", "surface": "A man is dead in a room with a small pile of pieces of wood and sawdust in one corner. (from \"Coroner's Inquest,\" by Marc Connelly; earlier(?) from _How Come?_)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_d56eedd0c69d", "srcNo": 1293, "title": "", "dispTitle": "无题 · misc #1293", "surface": "A man is running along a corridor with a piece of paper in his hand. The lights flicker and the man drops to his knees and cries out, \"Oh no!\" What happened?", "cats": ["其他"], "difficulty": 2, "src": "misc/repo-scan", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_d593c033cea2", "srcNo": 965, "title": "", "dispTitle": "无题 · YanJiaHuan #965", "surface": "有一个男子在一家能看见海的餐厅，他叫了一碗海龟汤，只吃了几口就惊讶地询问店员：“这真的是海龟汤吗？”，店员回答：“是的，这是货真价实的海龟汤”，于是该名男子就跳下悬崖自杀了，请问是怎么一回事？", "cats": ["其他"], "difficulty": 2, "src": "github:YanJiaHuan/TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_d598836d8b62", "srcNo": 1142, "title": "井", "dispTitle": "井", "surface": "当我从井里疏出来时，我的朋友喜极而泣。但他突然又一脸的惊忍! 把我推了下去!", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_d5ad6e7a2851", "srcNo": 587, "title": "影子", "dispTitle": "影子", "surface": "一天我去公共厕所，那时已是晚上，我看见男厕所门口站着一个人，后面是他的影子，手里还拿着什么，我吓了一跳，不过很快就冷静下来。第二天警察找到我，问我看到尸体为什么不报警，我想了想瞬间吓呆了。", "cats": ["恐怖"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_d5e727b05f14", "srcNo": 451, "title": "商店", "dispTitle": "商店", "surface": "（一对情侣在逛街）\n女：“看，那家店在清仓大甩卖，好便宜啊！”\n男：（看了一眼，紧紧拉住女友的手，声音发抖）“快走！千万别进去！那不是我们能买得起的！”", "cats": ["恐怖", "犯罪"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_d5f2eb839af6", "srcNo": 586, "title": "消失的姐姐", "dispTitle": "消失的姐姐", "surface": "女儿问我姐姐去哪了?我矢口否认了姐姐的存在，可随后女儿拿出的照片却让我震惊了…", "cats": ["恐怖"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_d6803ffbacff", "srcNo": 1150, "title": "Who is liar", "dispTitle": "Who is liar", "surface": "老大: 我成了累痪，临死前好像听到谁跳楼。老二: 早就说过不要内讶，可老四活活勒\n死了老五，他自己的脸色也绿得吓人。老三: 老四和她男朋友乘公交车与我们分道扬镰了，令\n我没想到的是老五居然是男人。老四: 我中了一枪，由于分赃不均，大家心怀鬼胎，看来今天\n只能有一个人活着出去了。老五: 老四发现老六在给老四下毒，于是枪杀了老六，但她自己好\n像也中枪了。老六: 我看到老大做了饭，吃完饭老二杀死了老大-提示:=本格推理，故事中只\n有一个人在说谎，按顺序还原真相。 (推荐玩法: 最好不要依次询问说谎者，或使用二分法)", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_d6b767472fca", "srcNo": 1011, "title": "洗手间的镜子", "dispTitle": "洗手间的镜子", "surface": "男人在镜子前刷牙，他对着镜子里的自己笑了一下，然后他吓坏了。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_d6c26b01a5f4", "srcNo": 1050, "title": "记忆提取", "dispTitle": "记忆提取", "surface": "女子为了寻找失踪的未婚夫，提取了未婚夫留下的唯一一颗眼球里的最后记忆。看完后，她微笑着把自己关进了焚化炉。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_d6c8501d6b79", "srcNo": 1231, "title": "Jed 2.13", "dispTitle": "Jed 2.13", "surface": "A woman opens an envelope and dyes. (AL)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_d6cd2cb2dc12", "srcNo": 1314, "title": "", "dispTitle": "无题 · boop-yyt #1314", "surface": "A woman lies dead in the street near a car. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_d6feec941be6", "srcNo": 1171, "title": "曼德拉效应", "dispTitle": "曼德拉效应", "surface": "你们埋过时间胶圳吗? 我小时候埋过，今天打算挖出来看看。由于是陨铁的盒子，因此\n保存得很好。里面有一封信。“小鱼生病了，小鸟生病了，爸妈生病了，我也生病了，我不想\n死，可所有人都死了”这不可能是我写的!!! 这是我写的吗? ? 哦对，这就是我写的!1", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_d7016f1d33ac", "srcNo": 211, "title": "挑衅", "dispTitle": "挑衅", "surface": "一天，游手好闲的阿星在大街上游荡。正巧碰上一所小学放学，他在拥挤的人流中不幸被无良小学生倒，小学生不仅没有道歉而且还出言挑衅阿星，阿星却没有因此生气反而很高兴，这是为什么?", "cats": ["其他"], "difficulty": 2, "src": "github:wangyafu/haiguitangmcp", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_d78b09244b6c", "srcNo": 1113, "title": "火车", "dispTitle": "火车", "surface": "这是一辆行驶的火车，我刚上车不久，坐上了最后一节车硕，车厢里流了很多血，我知\n道我快要活不长了.…….", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_d796d6fce947", "srcNo": 974, "title": "", "dispTitle": "无题 · hongqipiaopiao520 #974", "surface": "optional\n- 连续普通问答：提高 none 概率，避免每句都表演\n- 绕远、无关、重复", "cats": ["其他"], "difficulty": 2, "src": "github:hongqipiaopiao520/turtle-soup-chatroom", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_d7bbd5509593", "srcNo": 754, "title": "猜拳", "dispTitle": "猜拳", "surface": "石头赢了布，布赢了剪刀，我输了，我死了。", "cats": ["悬疑", "推理", "校园"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_d7f03780cb45", "srcNo": 669, "title": "换过一次的货物", "dispTitle": "换过一次的货物", "surface": "一头牲畜发现，只要经过河流时故意趴进水里，背上的货物就会变轻。主人没有打它，却只换了一次货物，就让它以后再也不敢这么做。为什么？", "cats": ["反转"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_d85450d0c38a", "srcNo": 593, "title": "鬼啊！", "dispTitle": "鬼啊！", "surface": "“真是吓死人了！”\n“你怎么会被吓到？！”\n“不然你以为我怎么在这里？”", "cats": ["搞笑"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_d881a0a0c762", "srcNo": 205, "title": "关灯之后", "dispTitle": "关灯之后", "surface": "小明半夜起来喝水，然后把灯关上继续睡觉，醒了之后他就自杀了，为什么?", "cats": ["其他"], "difficulty": 2, "src": "github:wangyafu/haiguitangmcp", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_d8b3fca01c7c", "srcNo": 770, "title": "作业", "dispTitle": "作业", "surface": "今天没写作业，妈妈没有责骂我，只是不停看着我笑。", "cats": ["恐怖", "悬疑", "惊悚", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_d8b7c8088ed4", "srcNo": 734, "title": "永远在一起", "dispTitle": "永远在一起", "surface": "妈妈很爱我，但一场大雨后把我关进伸手不见五指的小黑屋。再次见到她时她已面目全非，我知道我们会永远在一起。", "cats": ["亲情", "反转", "怪谈"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_d8fed5da59e1", "srcNo": 969, "title": "", "dispTitle": "无题 · 906491213 #969", "surface": "T自洽：[ ]通过 [ ]修复 [ ]回炉 →", "cats": ["其他"], "difficulty": 2, "src": "github:906491213/writing-turtle-soup", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_d9078a59e095", "srcNo": 1274, "title": "", "dispTitle": "无题 · misc #1274", "surface": "A man sitting on a park bench reads a newspaper article headlined \"Death at Sea\" and knows a murder has been committed. How could this be", "cats": ["其他"], "difficulty": 2, "src": "misc/repo-scan", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_d9a053630dee", "srcNo": 617, "title": "回家", "dispTitle": "回家", "surface": "我是一名大学生，在异地上学。这一天爸爸妈妈给我打电话说他们想我了，让我找个时间回趟家。于是我趁着五一回家了，到家后我打电话给爸爸说我回家了，爸爸回家打开门的一瞬间却疯了。", "cats": ["医院", "恐怖"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_d9c56fa6081b", "srcNo": 1276, "title": "", "dispTitle": "无题 · boop-yyt #1276", "surface": "An avid birdwatcher sees an unexpected bird. Soon he's dead. How could this be", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_dae223da7048", "srcNo": 1258, "title": "重复的外卖单", "dispTitle": "重复的外卖单", "surface": "男人连续三天收到同一家店、同一套餐的外卖，虽然他一次也没下单。第四天他报警。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:lancelily6362-png/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_dae78e48974b", "srcNo": 338, "title": "墨泣", "dispTitle": "墨泣", "surface": "传闻李家老爷有一支通灵的‘状元笔’，只要写下心中所想的词，那笔便能牵引着手，画出魂魄深处的景象。\n众目睽睽之下，老爷提笔写下“喜悦”，那笔尖颤动，竟画出了一座由戒尺和废纸堆成的黑山；\n他又写下“恐惧”，笔锋急转，勾勒出一口井沿爬满青苔的枯井。\n最后，李老爷满怀期待地写下了“父亲”二字。\n然而这一次，笔尖没有勾勒任何线条，只是在纸上重重地顿住，墨汁疯狂涌出，化作了一团漆黑丑陋、毫无意义的污渍。\n宾客皆叹惋可惜，说是笔坏漏墨了。\n只有我知道，这支笔没有坏，它只是太懂“人心”了。", "cats": ["亲情", "怪谈", "恐怖", "悲剧"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_daedaedd8573", "srcNo": 155, "title": "", "dispTitle": "无题 · KONpiGG #155", "surface": "我接到了一个电话，然后杀死了一个人", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_db119146416d", "srcNo": 640, "title": "Chloe和几个朋友一起去酒吧喝酒聊天", "dispTitle": "Chloe和几个朋友一起去酒吧喝酒聊天", "surface": "Chloe和几个朋友一起去酒吧喝酒聊天，她点了一杯白葡萄酒，酒盛在高脚杯里，晶莹剔透，很是赏心悦目。\n\n 忽然她找服务员要了一根细吸管，开始用吸管喝葡萄酒，服务员和其他朋友们都诧异的看着她，她喝着喝着，竟然笑了。\n\n Chloe是个优雅的姑娘，她这是怎么了？\n\n 你猜猜这是怎么一回事呢？", "cats": ["其他"], "difficulty": 2, "src": "haiguitang.cn/海龟浓汤", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_db1fba2450f6", "srcNo": 358, "title": "囚", "dispTitle": "囚", "surface": "他把我关在地下室，每天给我送食物和水。\n我拼命求救，却没人相信我。\n直到那天，我看着他倒下，才第一次感到绝望。", "cats": ["悬疑", "本格"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_db2f404a3e00", "srcNo": 113, "title": "", "dispTitle": "无题 · KONpiGG #113", "surface": "我是一名医生，一天一个人拿着一本相册放在我面前，我知道他们发现了我所有的秘密。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_db8187280597", "srcNo": 792, "title": "深夜的脚步声", "dispTitle": "深夜的脚步声", "surface": "女孩半夜听到脚步声，却不以为意继续睡。隔天醒来她却报警了。", "cats": ["悬疑", "惊悚", "推理"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_dbd7adf84036", "srcNo": 372, "title": "掉了", "dispTitle": "掉了", "surface": "老李退休后，搬到了郊外的一栋老式平房里独居。他的儿子很孝顺，每周都会来看他，带些吃的用的。\n这一天傍晚，儿子像往常一样推门进来，发现屋里没开灯，很暗。他喊了几声“爸”，没人答应。借着窗外微弱的月光，他看到父亲老李正背对着他，一动不动地坐在摇椅上。\n儿子松了一口气，走过去拍了拍父亲的肩膀。\n这时，他突然听到了两样东西同时掉落在地板上的声音。\n一个是清脆的 “叮” ，像是金属；另一个是沉闷的 “咚” ，像是重物。\n儿子僵在原地，脸色惨白，然后慢慢地退出了屋子，并立刻报了警。", "cats": ["恐怖", "犯罪", "逻辑"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_dc5429fe6149", "srcNo": 455, "title": "无力回天", "dispTitle": "无力回天", "surface": "我来到一栋房子前，此时我突然明白，自己已经无力回天了。", "cats": ["悬疑", "搞笑"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_dcafcc0c285d", "srcNo": 619, "title": "过期干巴面包", "dispTitle": "过期干巴面包", "surface": "她大发善心\n他又来买陈面包\n居然丢工作", "cats": ["本格"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_dd1af577210e", "srcNo": 1282, "title": "", "dispTitle": "无题 · boop-yyt #1282", "surface": "An avid birdwatcher sees an unexpected bird. Soon he's dead. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_dd28995ece95", "srcNo": 1000, "title": "床底的眼睛", "dispTitle": "床底的眼睛", "surface": "一个独居的女孩每天晚上睡觉前都要看一眼床底才安心。某天晚上她看完床底后，立刻起身跑出了家门再也没有回来。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_dd2a7f143871", "srcNo": 1105, "title": "消失的作业", "dispTitle": "消失的作业", "surface": "老师收作业时发现一个学生的作业不见了，但学生说作业明明交了。第二天作业又出现在老师的桌子上。", "cats": ["其他"], "difficulty": 1, "src": "github:Tenzyoo/turtle_soup_game", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_dd45b48c2fd0", "srcNo": 1004, "title": "深夜的敲门声", "dispTitle": "深夜的敲门声", "surface": "住在顶楼的男人半夜听到敲门声，开门后没人。这种情况持续了三天，第四天男人死在了楼梯间。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_dd5eeb87f7de", "srcNo": 1386, "title": "", "dispTitle": "无题 · boop-yyt #1386", "surface": "Joe wants to go home, but he can't go home because the man in the mask is waiting for him. How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_dd6adc9d6ed3", "srcNo": 293, "title": "065 · 失忆", "dispTitle": "065 · 失忆", "surface": "每天清晨，他都要花上二十分钟才能让自己相信：她已经死了。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_dd81850fab14", "srcNo": 116, "title": "", "dispTitle": "无题 · KONpiGG #116", "surface": "一男子工作下班回到家，打开电视看新闻，然后被吓晕了。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_dda5ae1293bc", "srcNo": 903, "title": "爸爸的遗言", "dispTitle": "爸爸的遗言", "surface": "我整理爸爸的遗物的时候发现有一张被妈妈撕毁的字条，拼好后是这样一句话：”不爱微笑 到死还在哭“”不要心痛 宇宙都快毁灭了“。直到妈妈生日，我才明白爸爸的遗言。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_ddc27ab000da", "srcNo": 237, "title": "001 · 多了一个人", "dispTitle": "001 · 多了一个人", "surface": "有一对夫妻，丈夫深夜开车载着妻子在路上飞驰，不一会车没油了，丈夫锁好车门便去附近加油站取油，回来后发现车子完好无损，但车里面多了一个人。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_ddcab18ee8e4", "srcNo": 739, "title": "半根火柴", "dispTitle": "半根火柴", "surface": "沙漠里躺着他、一些行李、一盒火柴和半根火柴。", "cats": ["悬疑", "推理", "旅途"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_ddcb2a1ef3b9", "srcNo": 139, "title": "", "dispTitle": "无题 · KONpiGG #139", "surface": "在黑暗当中点亮火柴的男人，因为恐惧与绝望，就这样死了。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_dee420a25fc5", "srcNo": 1057, "title": "特殊的镜子", "dispTitle": "特殊的镜子", "surface": "镜子可以显示一个人未来的死因。男人看到镜子里的自己是老死的，于是他开始肆无忌惮地冒险。结果他第二天就因为重伤变成了植物人，在床上躺了50年最后老死。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_df035a53a0a4", "srcNo": 1366, "title": "", "dispTitle": "无题 · boop-yyt #1366", "surface": "Same without the puddle of water. How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_df06f36358ec", "srcNo": 1185, "title": "别过来", "dispTitle": "别过来", "surface": "对面的 8 楼不对劲! 窗户上有一列血字: 别过来! 我透过窗发现一个人型轮廓站在房间\n内诡异的抽动。我吓坏了, 急忙拉上窗帘。第二天早上再观察时, 我发现一个男估吊在麻绳上。", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_df309a615b30", "srcNo": 671, "title": "倒着飞的飞机", "dispTitle": "倒着飞的飞机", "surface": "女人在商店里看到“一架倒着飞的飞机”，随后花了一点钱买下某样东西。没过多久，她就辞去了工作。为什么？", "cats": ["反转", "脑洞"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_df556d06686a", "srcNo": 21, "title": "题目标题（可选）", "dispTitle": "题目标题（可选）", "surface": "谜题描述\n# 汤底: 答案解释\n# 难度: 1-5 (1最容易，5最难)\n# 标签: 主题标签，用逗号分隔\n#", "cats": ["其他"], "difficulty": 2, "src": "github:anchorAnc/astrbot_plugin_TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_df717ba5514e", "srcNo": 242, "title": "007 · 插队", "dispTitle": "007 · 插队", "surface": "山姆去医院取药，排在长龙队伍最后。半小时后前面依然有很多人，这时陌生人皮特过来强行插到山姆前面。山姆非常生气，但没过多久，山姆心里却非常高兴，这是为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_df7e08372ffa", "srcNo": 1183, "title": "露营", "dispTitle": "露营", "surface": "我们一家去森林露车，爸爸负责打猎,我帮妈妈做饭。夜里，我被奇怪的哨食声音吵醒，\n爸妈都不见了。我出帐篷寻找，却在森林里看到了惊念的一幕。妈妈浮在空中惨叫，身上缠着\n几条触手，和爸爸吹着口哨，双手奇怪地摆动，像是在祭拜什么。我害怕地往回跑，竟发现地上\n有很多血迹，一个怪异的生物笑睐睐地问我:“饿不饿? ”，我吓晕了过去。等我醒来时，已经\n在床上了，多和爸在远处恶狠狠地盯着我，妈妈严肃地警告我:“千万不要和别人说昨晚的事。”", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_df9bd6c3c973", "srcNo": 1073, "title": "唯一的火柴", "dispTitle": "唯一的火柴", "surface": "寒冷的冬夜，三个乞丐只有一根火柴和一点干草。他们互相谦让了很久，最后谁也没点火，第二天全部冻死了。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_e013f625c0a9", "srcNo": 895, "title": "二十", "dispTitle": "二十", "surface": "我嫁到了国外，临产期闺蜜飞来陪我。某天闺蜜害怕地和我说：”你家房子不对劲，我总能听到哭声。“晚上闺蜜突然摔死在我家后院，尸体旁歪歪斜斜写着两个血字”二十“。直到我来到某个房间，我终于明白这句话的意思了。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_e019fdc98552", "srcNo": 700, "title": "丢失的手机", "dispTitle": "丢失的手机", "surface": "手机不见了，找到时我吓了一跳。", "cats": ["悬疑", "惊悚", "都市"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_e02a56aaf17a", "srcNo": 1333, "title": "", "dispTitle": "无题 · misc #1333", "surface": "A man enters a store. After a short pause, he says \"pain.\" The storekeeper is confused, but then becomes annoyed. What happened?", "cats": ["其他"], "difficulty": 2, "src": "misc/repo-scan", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_e04f28bf895d", "srcNo": 312, "title": "084 · 镜子", "dispTitle": "084 · 镜子", "surface": "她走进电梯，看到镜子里的自己，大哭起来。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_e09338da20be", "srcNo": 49, "title": "音乐", "dispTitle": "音乐", "surface": "一群人在听音乐，音乐停了，他死了。", "cats": ["反转"], "difficulty": 2, "src": "github:anchorAnc/astrbot_plugin_TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_e09376d6caf2", "srcNo": 661, "title": "没有说话的电话", "dispTitle": "没有说话的电话", "surface": "男人在酒店里怎么都睡不着。他拿起电话打了一个号码，对方接通后，他一句话也没说就挂断。几分钟后，他很快睡着了。为什么？", "cats": ["反转", "日常"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_e0a6e3b06d86", "srcNo": 1009, "title": "自动导航", "dispTitle": "自动导航", "surface": "男子深夜驾车回家，开启了最新的自动驾驶模式。车子突然改道开向了墓地，男子尝试手动接管却发现车门锁死，导航语音说：“检测到乘客家属在目的地等候。”", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_e0be4da42458", "srcNo": 522, "title": "新人", "dispTitle": "新人", "surface": "“一对新人立台前\"\n“台下众人笑开颜”\n“无法相拥惹人泣”\n\"近如咫尺难团圆”", "cats": ["悲剧", "本格", "猎奇"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_e0d2daa2ca5f", "srcNo": 1016, "title": "特殊的道歉", "dispTitle": "特殊的道歉", "surface": "一个男人每天都给一个并不认识的女人送花，并附上‘对不起’的卡片。持续了十年后，女人终于在葬礼上见到了这个男人。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_e0d6ce92565c", "srcNo": 1204, "title": "Jed 1.29", "dispTitle": "Jed 1.29", "surface": "Every day a man drinks his breakfast and drinks his lunch. When his boss finds out, he is immediately fired. The man moves to another job and begins doing the same thing; this time, when his boss finds out, the boss jokingly tells him that he'll be fired if he stops. (RSW)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_e0f5ce7433b1", "srcNo": 837, "title": "最完美的作品", "dispTitle": "最完美的作品", "surface": "我是一个落魄画家，妻子为了我的事业陪我去乡下写生。山路颠簸崎岖，车子突然坏了。这时路过一个牵马的牧民，将我们送到村子里借宿。晚上妻子说很热很渴想去喝水，却一直没有回来。我很担心出去找妻子，看到妻子站在几口井中间，目光呆滞地跳进了其中一口井。我既害怕又兴奋，赶紧把这一幕画下来。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_e10fef909345", "srcNo": 746, "title": "半瓶香水", "dispTitle": "半瓶香水", "surface": "妈妈最近很反常：偷偷用我的香水、穿我的衣服，还老是半夜出去。那天我忍不住和她争执，不小心把她推倒，我上前扶她却发现双手沾满鲜血。", "cats": ["反转", "悬疑"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_e12f6b533563", "srcNo": 1374, "title": "", "dispTitle": "无题 · boop-yyt #1374", "surface": "A man is dead in a room with a small pile of pieces of wood and sawdust in one corner. (from \"Coroner's Inquest,\" by Marc Connelly; earlier How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_e17a195e10d0", "srcNo": 316, "title": "088 · 失踪的孩子", "dispTitle": "088 · 失踪的孩子", "surface": "每天下班，他都会看到一个小女孩在门口等他。今天，小女孩不见了，他笑了。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_e18beb2012af", "srcNo": 605, "title": "高跟鞋之谜", "dispTitle": "高跟鞋之谜", "surface": "一个女人穿着高跟鞋走进一片森林，不久后她死了。", "cats": ["其他"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_e19e8509d11e", "srcNo": 194, "title": "", "dispTitle": "无题 · KONpiGG #194", "surface": "有个男人开车去机场赶班机，在到了一个三岔口时，看见一个男孩蹲在地上哭泣。男人下车询问男孩为什么哭，男孩说他迷路了。于是男人带着小男孩朝他描述的大致方向找去，在开了很久的车之后，男孩说看见了自己的家，便跳下车。这时，男人发现自己已经误了班机的起飞时间。男人在车里沮丧起来，突然又吓的直冒汗，然后又欣慰的笑了。是什么事造成男人这样的情感变化?", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_e1ac53d5abe7", "srcNo": 164, "title": "", "dispTitle": "无题 · KONpiGG #164", "surface": "杰西卡的男友在杰西卡不在家时，到杰西卡家把杰西卡的爸爸、妈妈、弟弟杀了，只有杰西卡的妹妹没有被杀，请问，为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_e217416dd21d", "srcNo": 976, "title": "", "dispTitle": "无题 · hongqipiaopiao520 #976", "surface": "2月20日，媳妇去世了。\",\n \"我听到院子里有人窃窃私语。\",\n \"\",\n \"", "cats": ["其他"], "difficulty": 2, "src": "github:hongqipiaopiao520/turtle-soup-chatroom", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_e23969e9d87b", "srcNo": 971, "title": "", "dispTitle": "无题 · 906491213 #971", "surface": "零外部知识：[ ]通过 [ ]修复 [ ]回炉 →", "cats": ["其他"], "difficulty": 2, "src": "github:906491213/writing-turtle-soup", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_e24398bc436c", "srcNo": 742, "title": "五步", "dispTitle": "五步", "surface": "一个人离车有30米，却只走了五步就上车。", "cats": ["日常"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_e261f200472d", "srcNo": 1081, "title": "完美的逃生指南", "dispTitle": "完美的逃生指南", "surface": "一名男子被困在着火的大楼里，他严格按照墙上的‘逃生指南’行动，最后他死在了通风管道里。指南并没有错。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_e28d837bd239", "srcNo": 374, "title": "消失的第13楼", "dispTitle": "消失的第13楼", "surface": "我住的居民楼有一处诡异之处——这里只有12楼和14楼，两层楼的安全通道可以互通。\n电梯从12楼上升至14楼时，总会在中间无故停顿一下，仿佛13楼真的存在一样。\n我凑近电梯门缝看去，外面只有一堵冰冷的墙。\n后来物业修完电梯，这诡异的停顿就再也没有出现过。\n电梯为什么会在不存在的13楼无故停顿？", "cats": ["本格", "逻辑"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_e334c7747e0b", "srcNo": 1271, "title": "", "dispTitle": "无题 · boop-yyt #1271", "surface": "How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_e354d2e7148f", "srcNo": 1264, "title": "永远对不上的值班表", "dispTitle": "永远对不上的值班表", "surface": "剧院每个月的值班表总有一个名字和实际到场的人对不上，可工资单却始终没有问题。直到一场火灾后，导演才知道真相。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:lancelily6362-png/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_e354e23594ac", "srcNo": 927, "title": "小笙的十年陪伴", "dispTitle": "小笙的十年陪伴", "surface": "2010年7月：“铃铃铃”“喂？”“您……您好！”“你好啊，辛招娣”，脸上有伤的女孩惊讶捂嘴。2011年5月：“小笙哥，今天我打算搬家了哦，你今天开不开心呀？”“挺开心的，不过你伤好点了吗？”“嗯嗯，没关系的”，挂断后女孩用太阳光晒溢血的伤口。2015年8月：“小笙哥，今天捉迷藏被抓住了”“下次要藏好哦～”“知道了，小笙哥，我在吃东西，你今天开不开心呀？”“开心啊，你终于不用饿肚子了，要吃饱哦”“不过我的胃很小，不像男孩子”“三伏天食物容易腐烂，吃剩的食物注意放到阴凉处保存哦”“小笙哥，今晚我们真的会见面吗？”“当然了”。2015年9月：“小笙哥，你今天开心吗？我爸妈最近不开心”“那辛辛不要打扰他们哦，无聊可以去做我给你留的习题”“嗯嗯，好！”，女孩远远看着憔悴的父母。2018年1月：“小笙哥，新年快乐，我爸妈今天应该很开心，你今天开心吗？”“他们当然开心了，因为辛辛你实现了他们的愿望呀”“小笙哥，我们最近见面很频繁哦”“辛辛不喜欢吗？”“不是啦，我只是觉得每天都能见面，就没必要再打电话了，这8年我每天都在打给你，你也应该过属于自己的生活了”“那你要照顾好自己”“小笙哥……”“嗯？”“我喜欢你．”2020年7月：“喂，我是小笙”“嗯，我是辛辛”“那辛辛，你最近开心嘛？”“我很开心呀，因为又和小笙说话了”“辛辛，你要照顾好自己”“小笙……”“嗯，我也喜欢你”，挂断后小笙看了一眼通讯录里唯一的名字，把手机扔进火光中。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_e38ee532d9ac", "srcNo": 45, "title": "奶奶的橘子树", "dispTitle": "奶奶的橘子树", "surface": "我从奶奶房间拿了个橘子给爸爸，爸爸却惊恐万分。", "cats": ["温情", "犯罪"], "difficulty": 3, "src": "github:anchorAnc/astrbot_plugin_TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_e3d18f75d309", "srcNo": 189, "title": "", "dispTitle": "无题 · KONpiGG #189", "surface": "一个人在酒店房间睡觉，半夜突然被一阵电话铃声吵醒。他迷迷糊糊地接起电话，电话那头传来一个女人的哭泣声，他问女人怎么了，女人却不说话，只是不停地哭泣。过了一会儿，电话挂断了。他觉得很奇怪，第二天他向酒店工作人员询问，工作人员的回答让他惊恐万分，请问工作人员说了什么?", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_e4c365f5b151", "srcNo": 1208, "title": "Jed 1.36", "dispTitle": "Jed 1.36", "surface": "A flash of light, a man dies. (ST original)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_e4cf534664b7", "srcNo": 477, "title": "不可能的可能", "dispTitle": "不可能的可能", "surface": "一位極度嚴格的補習老師，正在批改學生的期末考卷。這是一份只有二十五道「四選一」單選題的艱澀試卷。\n\n批改結束後，老師發現學生的最終分數是「0分」，竟然一題都沒有猜中。\n\n老師看著這張零分考卷，不但沒有暴怒，反而流下了欣慰的眼淚，立刻打電話訂了餐廳，準備好好請自己愛徒吃一頓慶祝。", "cats": ["日常"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_e523f1cb58c8", "srcNo": 714, "title": "灰姑娘", "dispTitle": "灰姑娘", "surface": "我叫辛德瑞拉，丑陋可怜却嫁给王子。王子对我说一句话，我知道下一场舞会又要开始了。", "cats": ["恐怖", "悬疑", "犯罪", "脑洞"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_e5516f397fa6", "srcNo": 875, "title": "护膝", "dispTitle": "护膝", "surface": "3年了，我回到了家，可我吃不下家里的食物，我在忍耐。看着我的护膝，终于，我忍不住了。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_e5a1b17d3910", "srcNo": 753, "title": "父母", "dispTitle": "父母", "surface": "小男孩非常崇拜父母。这天父母外出，只有小男孩和“妹妹”在家。一阵敲门声后，“妹妹”死了。", "cats": ["反转", "恐怖", "悬疑", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_e5e90cc39dad", "srcNo": 462, "title": "為了榮譽！為了未來！", "dispTitle": "為了榮譽！為了未來！", "surface": "幾名男子被困在一座堅固的地下倉庫裡。\n\n倉庫裡堆滿了大量優質的小麥、玉米和馬鈴薯。外面戰火連天，他們與外界徹底斷絕了聯繫，沒有任何人能進來。\n\n幾個月後，友軍終於打退敵軍並打開了這座倉庫，卻發現這幾名男子已經全部活活餓死在裡面。而倉庫裡的大量糧食，連一顆都沒有少。\n\n他們死時沒有生病，手腳沒有被綁住，也沒有人拿槍威脅他們。", "cats": ["悲剧", "逻辑"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_e5f1984f361b", "srcNo": 348, "title": "夜游症", "dispTitle": "夜游症", "surface": "我和妻子结婚七年，感情一直很好。唯一的遗憾是她患有严重的夜游症，婚后这几年发作得越来越频繁。我看过医生，医生说没有特效药，只能注意安全，睡前关好门窗。为了这个，我把家里的门锁全部换成了需要钥匙才能从内打开的那种，睡前我把钥匙藏在只有我知道的地方。\n  上周三的早晨，我醒来发现妻子不在床上。我喊她的名字，没有回应。我下床去找，发现大门敞开着，钥匙插在锁孔上。我心里一紧，立刻冲出门去。妻子坐在楼梯间里，赤着脚，睡裙上沾着灰，头发乱糟糟的。她低着头，怀里紧紧抱着一只流浪猫。猫是活的，但后腿好像断了，奄奄一息地被她抱着。我松了口气，把她扶起来带回家。她全程不说话，眼神涣散，这是典型的发病状态。我把她安顿回床上，她几乎是沾枕头就睡着了。那只猫被我送去了宠物医院，医生说是被钝器击打导致骨折，很难救回来了。我付了钱，让医院尽力治，然后回了家。\n  当天晚上，我整理垃圾的时候，在厨房垃圾桶的最底下，发现了一根沾着猫毛和血迹的擀面杖。擀面杖是我家的，平时放在灶台旁边的架子上。我愣了很久，然后把擀面杖冲洗干净，放回原处，把垃圾袋打了死结，拎下楼扔了。\n  第二天，我又在垃圾桶里发现了同一根擀面杖。上面又沾了新鲜的猫毛和血。这次不是同一只猫。我突然想起一件事：医生说夜游症患者不会记得自己发作时的行为。但她每次发作，都是在我睡着的时候。\n  我从来没有亲眼见过她发作。", "cats": ["悬疑", "本格"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_e6c0007af520", "srcNo": 144, "title": "", "dispTitle": "无题 · KONpiGG #144", "surface": "卖火柴的小女孩点燃了一根火柴。\"能点燃的火柴越来越少了。\"她说着，享受着眼前的温暖。从火焰中投射的幻境里，没有奶奶，没有美味的火鸡，只有一具被吊在广场上的尸体。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_e701f3bbbbbe", "srcNo": 145, "title": "", "dispTitle": "无题 · KONpiGG #145", "surface": "一天下班后我在商店看到同事和一个男人在一起，第二天下班后回到家洗澡，在感到奇怪之时发现一切都晚了。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_e73349a28031", "srcNo": 151, "title": "", "dispTitle": "无题 · KONpiGG #151", "surface": "男人A给了B一张纸，B在上面写下一个名字以后，A马上把B鲨了，为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_e744d9c688be", "srcNo": 1017, "title": "窗外的死神", "dispTitle": "窗外的死神", "surface": "由于长期失眠，男子站在高楼窗边想跳下去。这时他看到窗外有一个‘死神’向他招手。他吓得立刻退回房间，再也不想自杀了。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_e896000a8c2f", "srcNo": 19, "title": "破碎的镜子", "dispTitle": "破碎的镜子", "surface": "镜子碎了，他却没有受伤。看到碎片的位置后，他向警方自首。", "cats": ["其他"], "difficulty": 3, "src": "github:17hczmsn/turtle_soup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_e8d8698eed56", "srcNo": 98, "title": "", "dispTitle": "无题 · KONpiGG #98", "surface": "美人鱼与人类王子相爱并一起来到了王子的国家，可不久后却传来了王子的死讯。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_e8e8737072bb", "srcNo": 1363, "title": "", "dispTitle": "无题 · boop-yyt #1363", "surface": "Charlie died when the music stopped. How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_e925351d389a", "srcNo": 934, "title": "诺亚方舟规则怪谈", "dispTitle": "诺亚方舟规则怪谈", "surface": "海平面逐渐降低，生物或将迎来灭绝。古籍记载百万年前同样发生过大灭绝，神明创造了诺亚方舟，带领生物躲过了灾难。昨天，海面上忽然出现了一艘巨大无比的船，科考队已经进入探查，全部死亡，只有露琪亚勉强存活，她提供了一些信息：1. 方舟中存在诡异的生物和植物，请绕行！山姆和杰斯死在了诡异生物之口，卡莎用科技枪勉强杀死一只。2. 方舟内存在不可名状之物，禁止触摸！马特因此断了一只手臂。3. 诺亚方舟帮助生物躲过了大灭绝。方舟内的信息记载了一切，古籍是真的！我们有救了。4. 方舟内有一本《诸神的黄昏》。经过简单的翻译，这本书大概讲述了神明大战，神明陨落，生物都是在诸神的黄昏后出现的，包括人类。5. 神明存在于诺亚方舟之内。神明体型巨大无比，且狰狞丑陋。他杀了马特，甚至还把卡莎吃掉了。只有我逃走了。6. 还有更多诺亚方舟。他们来了，人类即将灭绝。原来导致这两次大灭绝的原因是相同的。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_e98311164611", "srcNo": 430, "title": "地龙", "dispTitle": "地龙", "surface": "我指着‘暖阁’的修缮图纸，向掌印太监李公公夸耀那蜿蜒复杂的烟道设计，以此保证贵妃冬日的温暖。\n李公公的枯手却按住了图纸，指甲在连接后院枯井与地龙火膛的那条笔直暗渠上狠狠划了一道。\n“只有弯曲的肠子才能留住热气，但这宫里，有时候‘顺畅’比‘温暖’更重要。”\n他盯着那漆黑的火膛入口，幽幽地说道：\n“杂家见过这地龙翻身。它不仅吃炭，还吃那些不再会说话的‘湿柴’。这条直道，就是为了防止它们卡在喉咙里，惊扰了贵人的好梦。”", "cats": ["悬疑", "本格"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_e9aaa48c7116", "srcNo": 1311, "title": "", "dispTitle": "无题 · boop-yyt #1311", "surface": "A rope breaks. A bell rings. A boy dies. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_e9b9792d6aa3", "srcNo": 1008, "title": "冰冷的拥抱", "dispTitle": "冰冷的拥抱", "surface": "丈夫在雪难中为了给妻子取暖，紧紧抱着她。第二天救援队赶到，丈夫活了下来，妻子却死了。医生检查后说，如果不抱，妻子可能还活着。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_ea01667538b7", "srcNo": 1124, "title": "宿舍", "dispTitle": "宿舍", "surface": "今天天气很热，老大在宿舍门口吃冰棍，老三刚吃完饭，在远处探头看着我们，封究了，\n我准备睡觉了，有胱中我听到老五一声惨叫.……", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_ea51f598eee8", "srcNo": 435, "title": "最高的祭坛", "dispTitle": "最高的祭坛", "surface": "他是个极度自恋的艺术家，毕生都在追求最完美的演出。\n那晚，他将最珍爱的“女主角”带到了离天空最近的白色舞台。\n当来自天堂的聚光灯打在他们身上，试图终结这场苦难时，他却隐入阴影，挥手拒绝了谢幕。\n为了让自己的皇冠更耀眼，他需要一场悲剧作为点缀。\n他耐心地在风雪中伫立，看着“女主角”一点点失去温度，化作永恒的冰雕。\n世人皆为他的“深情”落泪，却不知道那只悬在峭壁上的“天眼”，默默记录了他亲手熄灭星光的瞬间。", "cats": ["悬疑", "犯罪", "都市"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_ea9919efc255", "srcNo": 743, "title": "天窗", "dispTitle": "天窗", "surface": "一名作家在截稿日“开天窗”，编辑们却非常感谢他。", "cats": ["反转", "日常", "温情", "职场"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_eaac95e2de3e", "srcNo": 119, "title": "", "dispTitle": "无题 · KONpiGG #119", "surface": "成为永日公司的舞蹈家是我最大的梦想，每个月永日公司都会推出本月首席在国际舞厅献舞直到新首席接替她，她们来自不同国家不同肤色，唯一的共同点就是都穿着红舞鞋，终于有一天我被选中做下个月的头牌，在等待下个月到来的几天里，我被要求补充大量营养食物和水。当我看到上一任首席和她的红舞鞋，我知道我再也回不去了……", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_eace40ad0af6", "srcNo": 1305, "title": "", "dispTitle": "无题 · boop-yyt #1305", "surface": "The music stops and the man dies. Why?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_eae6cfcd0c64", "srcNo": 851, "title": "唱戏的女人", "dispTitle": "唱戏的女人", "surface": "最近几天邻居们都说，夜里总能听到有女子唱戏曲的声音，声调还格外凄惨。今晚我回家时也听到了这声音，吓得立刻跑回了家。没过一会儿，楼上传来凄厉的惨叫声，我也终于弄明白那戏曲声到底是什么了。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_eae7686c9c2a", "srcNo": 766, "title": "结婚", "dispTitle": "结婚", "surface": "结婚当天，丈夫对妻子说：「我会对你好。」第二天妻子自杀了。", "cats": ["亲情", "反转", "悬疑", "温情"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_eb1e450ab294", "srcNo": 528, "title": "清剿猴妖", "dispTitle": "清剿猴妖", "surface": "我是一名修仙宗门的外门弟子，我接了一个简单的宗门任务，去一处凡人王老汉名下的灵桃园清剿一群作乱的猴妖。\n我来到灵桃园，这些灵桃似乎在墨长老的寿辰上见过，他用来招待来宾弟子。\n王老汉一家人对我毕恭毕敬，但言辞闪烁，眼神里充满了恐惧，只是催促我赶紧清剿猴妖。\n我与猴妖们交了几次手，发现它们并没有下死手，更像是在驱赶我。\n我突然想起来，不对，这片桃林灵气很充裕，不像是。。。。\n\n宗门的任务记录上，我因学艺不精，死于猴妖之手。", "cats": ["悬疑"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_eb29b057824f", "srcNo": 371, "title": "条件", "dispTitle": "条件", "surface": "男生喜欢女生好久了，他成绩非常不好，女生说只要两人能进同一所大学，就答应做他女朋友，后来他做到了，而女子却疯了，请推理。", "cats": ["恐怖", "悬疑", "本格"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_ebd560f6ef8e", "srcNo": 1024, "title": "盲人的画", "dispTitle": "盲人的画", "surface": "一个天生失明的画家，画出的肖像画居然和本人一模一样。人们惊叹这是奇迹，画家却在成名后毁掉了所有画作。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_ebfab81bc1df", "srcNo": 1239, "title": "Jed 2.33", "dispTitle": "Jed 2.33", "surface": "An ordinary woman walks on water. (_Math for Girls_)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_ec09d479ca14", "srcNo": 62, "title": "", "dispTitle": "无题 · KONpiGG #62", "surface": "开头：小红新买了双高跟鞋。结尾：小红寄了", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_ec85b50c08f6", "srcNo": 1100, "title": "无声的电话", "dispTitle": "无声的电话", "surface": "半夜电话响了，接起来却没有任何声音，第二天邻居被发现死在家里。", "cats": ["其他"], "difficulty": 2, "src": "github:Tenzyoo/turtle_soup_game", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_ecab42ccdd54", "srcNo": 1375, "title": "", "dispTitle": "无题 · boop-yyt #1375", "surface": "A pile of sawdust, no net, a man dies. How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_ecd3f8830a7b", "srcNo": 89, "title": "", "dispTitle": "无题 · KONpiGG #89", "surface": "这天我得了病需要住院几天，隔壁床有个跟我年龄相仿的人叫安妮，她挺不老实的，每次医生进来叫到安妮的名字的时候她就会大喊：\"我不是安妮！\"医生已经核对过了，医生很确定她就是安妮。我晚上睡觉的时候总感觉有什么东西在我床下面，第二天安妮出院了，我瞪大眼睛看着自己的腿，晕了过去。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_ecf4e3887af8", "srcNo": 447, "title": "桃花妆", "dispTitle": "桃花妆", "surface": "桃花坞，胭脂铺，\n铺里不收残花柳，专收含苞待放骨。\n白天捣花红满地，夜里花哭无处诉。\n客官皆赞颜色好，不知铺底尽是土。", "cats": ["怪谈", "恐怖", "悬疑", "本格"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_ed269e2fea3f", "srcNo": 214, "title": "日访三十国", "dispTitle": "日访三十国", "surface": "个没有护照的普通美国公民，一天之内访问了30多个国家。在每个国家里他都受到热情招待，并且离开时也完全自由。", "cats": ["其他"], "difficulty": 2, "src": "github:wangyafu/haiguitangmcp", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_edb83d6c5d1b", "srcNo": 764, "title": "女明星", "dispTitle": "女明星", "surface": "女明星领养了一个女儿，从女儿很小开始就时不时让她戴一顶帽子。某天带她去医院，女儿知道真相后自杀了。", "cats": ["反转", "恐怖", "惊悚", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_ede63d9d0ecb", "srcNo": 434, "title": "仲夏的毁灭", "dispTitle": "仲夏的毁灭", "surface": "我们的星球拥有绿色的大气层，上面全是黄金铸的房子，那是曾经从外太空输入的资源孕育而成的。有一天宇宙弥漫着末日般的热浪，大气层脱离，星球从中崩裂，我们的房子被怪物连根拔起，他们跟我们的房子长得很像，我们毫无还手之力，被碾碎后跌入到强腐蚀液体中无法逃离，坠入无尽的深渊。", "cats": ["本格"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_ee36f852b5c8", "srcNo": 57, "title": "不合适的帽子", "dispTitle": "不合适的帽子", "surface": "从小妈妈喜欢给女儿戴不合适的帽子，一天她带女儿去医院，女儿痛哭了。", "cats": ["其他"], "difficulty": 3, "src": "github:anchorAnc/astrbot_plugin_TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_ee3cd8f8fce0", "srcNo": 222, "title": "看病", "dispTitle": "看病", "surface": "一个人坐火车去临镇看病，看完之后病全好了。回来的路上火车经过一个隧道，这个人就跳车自杀了。", "cats": ["其他"], "difficulty": 2, "src": "github:wangyafu/haiguitangmcp", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_ee55e3c73f10", "srcNo": 1172, "title": "学院规则怪谈", "dispTitle": "学院规则怪谈", "surface": "1. 若不加入学院, 我就会被惩罚。2. 很多父母送学生过来了但学院只收身体健康的学生。\n嘻嘻~ 3. 学院成立百年，校训是“生长为人”。嘎嘎~ 4. 地下室禁止入内，上百名退休职工在休\n息。鸣鸣~ 5. 学院职工人数固定为 20 人。哼哼~ 6. 学生毕业后，须在学院入职。嘿嘿~ 7. 不\n要毕业!! 哈哈哈! 8. 我逃学失败了，-估计很快就会毕业了。呵呵!忆", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_ee579ea2f759", "srcNo": 1005, "title": "电梯里的邻居", "dispTitle": "电梯里的邻居", "surface": "女孩深夜回家坐电梯，电梯里有一个满脸横肉的男人。女孩很害怕，到了8楼赶紧跑回家。第二天，邻居被杀了，女孩庆幸自己逃过一劫。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_ee8cea6405d4", "srcNo": 511, "title": "五百遍默剧", "dispTitle": "五百遍默剧", "surface": "我为了换一张完美的脸，躺上了那张昂贵的流水线。\n金牌工匠向我保证，他会全程亲手雕琢这件艺术品。\n然而，当麻醉剂夺走我的意识，工匠便摘下手套离场，把凿子扔给了角落里的影子。\n吸管不知疲倦地吮吸着红色的颜料，机器空转了三个小时。\n在那之后，只有一位母亲坐在无声的屏幕前，流着泪把这段无人负责的录像，看了整整五百遍。", "cats": ["悬疑", "推理", "犯罪"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_ee8eecd3c58d", "srcNo": 1356, "title": "", "dispTitle": "无题 · boop-yyt #1356", "surface": "A man is running along a corridor with a piece of paper in his hand. The lights flicker and the man drops to his knees and cries out, \"Oh no!\" How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_ef36d39a419c", "srcNo": 1376, "title": "", "dispTitle": "无题 · boop-yyt #1376", "surface": "Variant wording: A seated woman is writing a letter. She dies because there's a thunderstorm outside. (SP, from The Next Book of OMNI Games) How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_ef419c30b721", "srcNo": 481, "title": "惩罚通知单", "dispTitle": "惩罚通知单", "surface": "小安死了，他身上的皮被全部剥下去了。\n小白也死了，教学楼上的钢筋滑落，插进了他的脑袋。\n短时间死了三个人，学校里人心惶惶，宣布停课。\n没想到第二天小陈死在了家中，死因是家里漏电，但没人相信小陈是意外，一定是他。\n小邓醒来，发现自己被困密室里，面前有一桶水，他知道他完了，默默地等待属于他的惩罚！", "cats": ["恐怖"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_ef4c27a715d5", "srcNo": 377, "title": "一个钱包", "dispTitle": "一个钱包", "surface": "有一天阳光正好，我在公园里遛狗，突然低头看到一个钱包，我知道我马上就要死了。", "cats": ["其他"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_ef652fe14c3e", "srcNo": 221, "title": "电梯里的人", "dispTitle": "电梯里的人", "surface": "一个人住在高层公寓楼里。每天下班回家后，他对电梯有一个不寻常的习惯。如果下雨，他总是乘电梯到他住的楼层，即 17 层。如果没有下雨，但电梯里还有其他人，那么他也乘电梯到17楼。但如果没有下雨，而且电梯里只有他一个人，那么他就会乘电梯到11楼，然后走楼梯走完剩下的路。", "cats": ["其他"], "difficulty": 2, "src": "github:wangyafu/haiguitangmcp", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_ef983ce23926", "srcNo": 1277, "title": "", "dispTitle": "无题 · boop-yyt #1277", "surface": "He was killed by breakfast. How could this be", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_eff22876fde2", "srcNo": 114, "title": "", "dispTitle": "无题 · KONpiGG #114", "surface": "夜晚，贫穷的拾荒者捡了一台洗衣机回家。半夜他从睡梦中惊醒，好像听到了洗衣机启动的声音。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_eff88fcec539", "srcNo": 262, "title": "031 · 拍照", "dispTitle": "031 · 拍照", "surface": "一对母子在游乐园中游玩，几天后死在了家中。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_f071b9032ef3", "srcNo": 807, "title": "欢迎回家", "dispTitle": "欢迎回家", "surface": "某天，一名男子出差回家，发现门半掩着、家里的灯也开着。他喊了几声妻子名字没人回应。走进客厅却看到妻子与两个孩子都端坐在沙发上，脸上带着微笑，目不转睛盯着电视，但他马上报警。为什么？", "cats": ["怪谈", "恐怖", "惊悚", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_f0dce23c378e", "srcNo": 436, "title": "玻璃片里的高个子", "dispTitle": "玻璃片里的高个子", "surface": "祖母从南洋带回来一个奇怪的铁匣子，那是个会发光的西洋戏法。\n她给了我三张画着彩漆的玻璃片，让我塞进铁匣的缝隙里，说要请“高个子叔叔”出来守护宅院。\n当煤油灯的光穿过玻璃，墙上的人影真的好高好高，细得像一根根立起来的筷子，在摇晃的光影里扭动。\n祖母说，第四张玻璃片最珍贵，上面住着最疼我的那位叔叔，但他不喜欢见生人。\n只有等母亲睡着了，悄悄把光打在她的床帐上，一边摇动把手一边喊他的名字，他才会出来。\n昨晚我照做了。那个细长得要把房顶顶穿的白影子，真的慢慢爬上了母亲的床头。\n母亲一定也很喜欢这个戏法，因为今早我看见她穿着最鲜艳的衣服，像个红灯笼一样，高高地挂在房梁上，陪着那位叔叔一起荡着。", "cats": ["悲剧", "惊悚"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_f11b65ee0498", "srcNo": 1285, "title": "", "dispTitle": "无题 · boop-yyt #1285", "surface": "There is blood on the ceiling of my bedroom. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_f14bc5692d02", "srcNo": 82, "title": "", "dispTitle": "无题 · KONpiGG #82", "surface": "一个人正坐在公园的长椅上看报纸，读到一篇报道，标题是《一起海上死亡事件》，他还没看完文章，立即就推测出这是一起谋杀，并知道了凶手是谁。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_f164e08939b3", "srcNo": 1120, "title": "五兄弟", "dispTitle": "五兄弟", "surface": "在一处废弃的教堂里，刚发生了二起惨案，高老爷子的尸体平静地躺在棺樟里，高老分\n子的五个儿子死在了一个巨大的祭坛上。 每个大的尸体都被工整地切割了一部分: 老大缺了头\n部，老二缺了胸部和手，老三缺了腹部，老四缺了大腿，老五缺了小腿。而高家的独苗，老三\n的儿子也在现场，他害怕地对警官说:“他们本来想复活爷和爷，结果却召唤出了恶魔，恶魔把\n他们全杀了。?”", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_f19f1c8dd5e9", "srcNo": 1342, "title": "", "dispTitle": "无题 · boop-yyt #1342", "surface": "A blind beggar had a brother who died. What relation was the blind beggar to the brother who died? (\"Brother\" is not the answer.)", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_f21afd2070b6", "srcNo": 1229, "title": "Jed 2.9", "dispTitle": "Jed 2.9", "surface": "Two people are playing cards. One looks around and realizes he's going to die. (JM original)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_f22cbcd4bcf0", "srcNo": 1114, "title": "圣诞老人", "dispTitle": "圣诞老人", "surface": "圣诞节到了二 我又来完成孩子们的梦想了。第一个孩子想唱歌，他做到了;， 第二个孩子\n想去旅行，于是我送他环游世界，但他却被吃掉了; 第三个孩子喜欢玩躲猫猫，于是我帮他茂\n起来，警官都找不到他，不过他明年自己就会出现。", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_f237de4176aa", "srcNo": 1091, "title": "", "dispTitle": "无题 · zhuqingxu #1091", "surface": "节庆游行里上百人穿着完全相同的吉祥物外套与头套经过广场。队伍行进时一人被刀刺伤，现场一片混乱，凶手却像瞬间消失。短时间内不可能换装逃离，周围全是「同一只熊」。凶手藏在哪里？", "cats": ["其他"], "difficulty": 2, "src": "github:zhuqingxu/ai-haigui-game", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_f27e0906d2d8", "srcNo": 203, "title": "保龄球", "dispTitle": "保龄球", "surface": "一个男人放手抛出保龄球。不久，他被送往医院急诊。", "cats": ["其他"], "difficulty": 2, "src": "github:wangyafu/haiguitangmcp", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_f2868cda45ce", "srcNo": 25, "title": "酒吧的枪", "dispTitle": "酒吧的枪", "surface": "一个男人走进酒吧，向酒保要了一杯水。酒保却拿出一把枪指着他。男人说\"谢谢你\"，然后离开了。为什么？", "cats": ["反转"], "difficulty": 2, "src": "github:anchorAnc/astrbot_plugin_TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_f2c502f50643", "srcNo": 68, "title": "", "dispTitle": "无题 · KONpiGG #68", "surface": "小明的弟弟养了一只仓鼠，有一天，小明弟弟的仓鼠死了，小明的弟弟很伤心，妈妈奖励她一会儿跟仓鼠大小的巧克力，过了不久，小明死了，这是为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_f3a67510b7c7", "srcNo": 502, "title": "重见光明", "dispTitle": "重见光明", "surface": "一个人坐火车去临镇看病，看完之后病全好了。回来的路上火车经过一个隧道，这个人就跳车自杀了。为什么?", "cats": ["其他"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_f3b012b87734", "srcNo": 1319, "title": "", "dispTitle": "无题 · boop-yyt #1319", "surface": "A seated woman is writing a letter. She dies because there's a thunderstorm outside. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_f3b4ea050546", "srcNo": 1087, "title": "", "dispTitle": "无题 · zhuqingxu #1087", "surface": "一间小屋从内反锁，钥匙在死者口袋里，门下只有很窄的透气缝。警察却从门缝看见里面曾充满灰白浓烟。破门后室温正常，没有火烧痕迹，也找不到烟灰或烟源。浓烟是哪来的？", "cats": ["其他"], "difficulty": 2, "src": "github:zhuqingxu/ai-haigui-game", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_f3c2517bfe74", "srcNo": 708, "title": "阳台上的女孩", "dispTitle": "阳台上的女孩", "surface": "女孩每天站在对面阳台和我打招呼，我却再也不敢踏进阳台。", "cats": ["怪谈", "恐怖", "悬疑", "惊悚"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_f3d383d9df0e", "srcNo": 1368, "title": "", "dispTitle": "无题 · boop-yyt #1368", "surface": "A rope breaks. A bell rings. A man dies. How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_f3efbb92481e", "srcNo": 1212, "title": "Jed 1.50", "dispTitle": "Jed 1.50", "surface": "A man kills his wife, then goes inside his house and kills himself. (DH original, from \"Nightmare in Yellow,\" by Fredric Brown)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_f3fa66c22535", "srcNo": 42, "title": "外婆的苹果", "dispTitle": "外婆的苹果", "surface": "6岁时外婆告诉我不要吃黄苹果。13岁时，外婆告诉我不要吃青苹果。18岁时外婆告诉我不要吃红苹果。20岁时外婆去世了，我向外婆祈愿：以后所有的苹果都可以吃了。", "cats": ["家庭"], "difficulty": 3, "src": "github:anchorAnc/astrbot_plugin_TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_f46d6b6806eb", "srcNo": 271, "title": "041 · 一见钟情", "dispTitle": "041 · 一见钟情", "surface": "你和男友是校友，他比你大三届，马上就要毕业了。你们感觉心有灵犀，一见钟情，约好了等你到了法定结婚年龄就结婚。国庆节，男友说不如来我家见见我父母吧。你欣然同意。然而，男友的父母一看到你的脸，大惊失色，坚决反对你们结婚。这是为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_f4974f92b944", "srcNo": 351, "title": "哥哥的指令", "dispTitle": "哥哥的指令", "surface": "哥哥说向前就是向后，向左就是向右\n“向前向前向前”\n听不到哥哥的声音了，我知道我也活不长了", "cats": ["脑洞"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_f4ccc9a94752", "srcNo": 804, "title": "沉浸式鬼屋", "dispTitle": "沉浸式鬼屋", "surface": "一对情侣参加「超真实沉浸式鬼屋」体验，主办强调都是设计好的不会有真正危险。体验结束没出意外，但几天后女友连续失眠、状态恶化，男友问发生什么事她只是摇头不说。为什么？", "cats": ["悬疑", "惊悚", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_f4d4db7a2195", "srcNo": 600, "title": "装下自己", "dispTitle": "装下自己", "surface": "一个男人走进一家店，说 “我要一个能装下我自己的东西”。店员没有多问，递给了他一个东西，男人满意地付钱离开了。", "cats": ["其他"], "difficulty": 1, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_f5273f493997", "srcNo": 1217, "title": "Jed 1.64", "dispTitle": "Jed 1.64", "surface": "A man tries to buy poison to kill his wife. The pharmacist figures out what he's up to and finds a way to ensure that he can't kill his wife. (CB, from _Flitterwochen in der Hoelle_)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_f53b7bd1e237", "srcNo": 644, "title": "妻子没有救他", "dispTitle": "妻子没有救他", "surface": "男人在家中突然倒地，妻子清楚看见全过程，却始终没碰到他。她立即联系急救，救援人员到场时他已经死亡。妻子没被捆住，也不想让他死。为什么？", "cats": ["反转", "悬疑"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_f57168e93bf0", "srcNo": 523, "title": "不動的老人", "dispTitle": "不動的老人", "surface": "一位老人在書房裡讀書，忽然屋頂塌下來壓住了他，但他並未試圖逃跑或呼救。發生什麼事？", "cats": ["反转", "脑洞", "逻辑"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_f57553ce91fe", "srcNo": 749, "title": "活", "dispTitle": "活", "surface": "我死在地下一楼，但我活在三楼。", "cats": ["校园", "温情"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_f581f7d53be5", "srcNo": 891, "title": "发夹", "dispTitle": "发夹", "surface": "我家隔壁传来”咚“的一声，之后又是哭声，于是我敲门询问是否需要帮助，开门的是一位女士，她和我说不用帮忙并表示感谢。回到家后，我急忙报了警。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_f5c5e10b8704", "srcNo": 131, "title": "", "dispTitle": "无题 · KONpiGG #131", "surface": "一天，一名男子告诉妻子：\"我们家院子里埋着枪\"。但这根本是一个谎言，那么男子为什么要撒谎呢？", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_f5d6427a6029", "srcNo": 506, "title": "一句話推理-", "dispTitle": "一句話推理-", "surface": "警方接到了一個奇怪的電話「請盡快過來，我被謀殺了，帶上疾控中心的人！」", "cats": ["本格"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_f5e005de8361", "srcNo": 29, "title": "天窗", "dispTitle": "天窗", "surface": "一名作家，在截稿日开了天窗，但是编辑们都非常感谢他，请问这是为什么?", "cats": ["反转"], "difficulty": 2, "src": "github:anchorAnc/astrbot_plugin_TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_f5f56eaefb41", "srcNo": 1109, "title": "新人", "dispTitle": "新人", "surface": "一对新人立台前，台下众人笑开颜，无法相拥营人泣，近如由尺难团圆。", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_f664ca72cde2", "srcNo": 1064, "title": "沉默的投票", "dispTitle": "沉默的投票", "surface": "十个人被困在孤岛，食物只够一个人活。他们决定进行匿名投票，得票最高的人被杀掉吃肉。九轮过后，最后剩下的那个人疯了。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_f67071b7a71a", "srcNo": 896, "title": "阿吉的画", "dispTitle": "阿吉的画", "surface": "4月9日，我在一个小乡村度假，村子里有一个叫阿吉的人，他很爱作画，他画了一幅沙滩上的木梳，很有艺术成分。但村民们不这么认为，大家都说他精神有问题。4月10日，今天在公路上捡到一只小猫，我很喜欢就带回了村，路上遇到了阿吉，今天他画了一张毛毯。4月11日，阿吉今天画了几串葡萄，画得太棒了，另外一位游客也夸阿吉画得很好！村里人对他的偏见太大了。4月12日，我要走了，阿吉送了我幅画，画的是两个山洞，真完美，我笑着对他说：”你以后一定能成为一个伟大的画家。“", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_f69651939ba4", "srcNo": 869, "title": "侠客", "dispTitle": "侠客", "surface": "吾乃建邺一侠客，正在剿灭邪教，不知怎的来到这妖异之地，定是教头的琴音所致。这街上跑的飞快的四轮之物是什么？哦？竟有几人对我不敬，说我闯什么灯，定是邪教之人，我剑气寒光，将几人斩杀，周围人四散而逃。这时来了几个蓝衣壮汉将我围住，看起来像当差的，我不愿与官家结仇，溜之大吉，却未曾想轻功失效，随即被擒，带到了此地的县衙。我不知我为何会在此地？几个年轻人来看我，哭着叫我爸爸。可笑，我也不比几人大多少，一派胡言，可照镜子那一刻我呆住了，我怎苍老这般？当差的把我带去问诊，可我清楚我没有病。你们能帮帮我吗？", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_f6e55601b9df", "srcNo": 247, "title": "013 · 亲爱的读者", "dispTitle": "013 · 亲爱的读者", "surface": "最惨绝人寰的事情发生了，但旁观者发现凶手后却笑了，请问发生了什么事？", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_f6f317bb36ea", "srcNo": 1168, "title": "你的名字", "dispTitle": "你的名字", "surface": "“你会被叫关阳青的杀死”在我很小的时候，亚位高僧警告我。我的人生一直躲着这个名\n字，直到结婚生子。结果我给孩子开家长会时死在了学校果然，我真的被叫关阳青的杀死了。", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_f715e86356f5", "srcNo": 691, "title": "白毛的水", "dispTitle": "白毛的水", "surface": "我洗完澡说了一句话，家人得知真相后都崩溃了。", "cats": ["恐怖", "悬疑", "惊悚"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_f7706d4b00fa", "srcNo": 1236, "title": "Jed 2.22", "dispTitle": "Jed 2.22", "surface": "A woman meets the king, cries \"Pain!\", and loses consciousness. (MI original)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_f7f8399079c1", "srcNo": 898, "title": "双鱼", "dispTitle": "双鱼", "surface": "1971年 我出生在一个偏远的山沟里，我有一个疯癫的妈妈，她总是嘀咕一个词——双鱼玉佩。我很好奇这是什么。1974年 村子里的女人基本上都被困在家里不允许出门，我问爸爸为什么，爸爸神秘的和我说：”这是村子里的秘密！“1978年 村东面有一个万丈深渊，为防止有人掉下去，村民用栅栏围了起来，我很好奇，有一天用望远镜偷偷去观察深渊，太深了！望远镜也看不清，只看到下面都是雪地。1979年 家里养了小鱼，妈妈很害怕，把鱼缸都给打碎了。这天放学，妈妈看着我的小人书突然激动起来：”这个神话是真的！是真的！！！“1993年 爸爸妈妈都去世了，我也再没回过村子，妈妈临终前，还在嘟囔着双鱼玉佩。1999年 我娶了一个心仪的妻子。并且由于小时候的种种奇怪现象，我成为了科考队的一员，我要开始寻找妈妈所说的双鱼玉佩了。2004年 出差在外的我收到妻子的短信：”不要再去找玉佩了，你要记住，我因你而死。“我急忙回家，妻子不见了，我找了一整年，一无所获。今年花园里的花异常旺盛，妻子却看不到了。2006年 我的一生都围绕着双鱼玉佩。今天，我终于找到了！等我打开匣子，里面却空空如也。我看着墙上的壁画，终于明白了妈妈为什么说那篇神话是真的了，我精神有些崩溃，也明白了全部，双鱼玉佩具有唯一性，我想我知道它在哪了。2007年 我回到了村庄，村子里的人全都死光了。该赎罪的不只有你，还有我。我去了该去的地方，结束了可悲的一生。", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_f801e925ab7c", "srcNo": 1251, "title": "打翻的牛奶", "dispTitle": "打翻的牛奶", "surface": "父亲回家看到地上的牛奶杯被打翻了，却高兴得几乎哭出来。为什么？", "cats": ["其他"], "difficulty": 2, "src": "github:lancelily6362-png/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_f814c03d1664", "srcNo": 981, "title": "", "dispTitle": "无题 · MZKT89 #981", "surface": "小明在学校的图书馆里发现了一本破旧的日记，从那以后他每天晚上都会做噩梦。已掌握的信息：小明做的噩梦和他在学校图书馆发现的破旧日记的内容有关；日记的主人是抑郁症患者。剩余提问次数：0。剩余回答次数：1。\n此时，你的剩余提问次数为0，根据规则5，你必须给出", "cats": ["其他"], "difficulty": 2, "src": "github:MZKT89/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_f823bba228a2", "srcNo": 529, "title": "别杀我", "dispTitle": "别杀我", "surface": "警察赶到现场后，发现房间是密室状态，门窗都从内部反锁，唯一的钥匙在死者口袋里。 死者趴在书桌上，手里紧紧攥着一支录音笔。 警察按下播放键，里面传来男人惊恐的声音：“别过来！求求你……别杀我！”随后是一声枪响，录音结束。", "cats": ["悬疑", "本格"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_f87a8927dba1", "srcNo": 676, "title": "沉默的回国者", "dispTitle": "沉默的回国者", "surface": "男人在国外遇到事故后被送回祖国。一路上他的名字和文件被反复核对，但没人要求他亲自答话或走过检查口。家人在目的地等候，却没准备接他回家。为什么？", "cats": ["反转", "悬疑"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_f8946799c97f", "srcNo": 560, "title": "黑猫的凝视", "dispTitle": "黑猫的凝视", "surface": "我杀了人，警察带我走时看到门口那只黑猫一直盯着我，我知道自己错了。", "cats": ["悬疑"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_f8b00b40b3c4", "srcNo": 1143, "title": "许愿", "dispTitle": "许愿", "surface": "我低下头许愿，愿望实现了，我却吕了。", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_f8bf768b7178", "srcNo": 1006, "title": "不会说话的娃娃", "dispTitle": "不会说话的娃娃", "surface": "女儿收到了一个非常逼真的洋娃娃，还会发出“妈妈”的叫声。妈妈看到后，尖叫着把娃娃剪开了。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_f92a616d0ec9", "srcNo": 463, "title": "悲剧性错误", "dispTitle": "悲剧性错误", "surface": "父亲半个月前从医院回来就不对劲，也许是母亲失踪对他打击太大，他总回避与我\n相处，独自在客厅看电视。\n“28日夜，我市警方在连江大桥下发现一具不知名女尸，面部特征无法识别。与已受理的失踪人员报案名单对比后，DNA信息均不相符，不排除刑事案件的可能..”\n父亲颤抖着起身，跑出了家门。", "cats": ["悬疑", "悲剧", "本格"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_f9609f329e42", "srcNo": 172, "title": "", "dispTitle": "无题 · KONpiGG #172", "surface": "某个学校里有一个传说，画室墙上挂的一副女人肖像，晚上会活过来。小李和小王两个人吹嘘壮胆，小李说根本不信不怕这个故事，于是小李答应小王晚上去做点什么试胆。第二天小李吓傻了。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_f96e1a0884ee", "srcNo": 1165, "title": "巨人", "dispTitle": "巨人", "surface": "出差前，我发现麦子画了一个陌生男人，她说:“这是个巨人，我梦见我被他握在手中杀\n死了。”只是梦境所以我并没有在意，可等我出差回来，我却发现妻子死在了家中，警察调查\n后叹了口气:“了唉，第十六个。”", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_f971bd1e4dd1", "srcNo": 488, "title": "祭窑", "dispTitle": "祭窑", "surface": "我花重金在鬼市定了一套名为“钟馗捉鬼”的孤品瓷俑，以此镇宅。\n第一次开箱验货，那百只形态各异的厉鬼瓷偶挤满了锦盒，个个栩栩如生，唯独正中央那个负责镇压的“钟馗”不见踪影。\n我大发雷霆，痛斥窑主欺诈，退货重烧。\n半月后，锦盒再次送达。这一次，那尊钟馗像赫然立于盒中，身形比常理大了一倍，釉色红得甚至有些烫手。\n然而，那一百只厉鬼瓷偶却全都消失了。\n我凑近细看，发现钟馗高高隆起的肚皮上，隐约浮现着百张痛苦扭曲的人脸花纹，正随着釉面的流光缓缓转动。", "cats": ["悬疑", "脑洞"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_f98c840ad6f9", "srcNo": 1161, "title": "重映", "dispTitle": "重映", "surface": "我生病了，每天睡前妈妈都会喂我吃药。可吃完药后我总会做慎梦。第一天，我梦见我\n被急驰而来的卡车撞死了。第二天，我被包庄在睡袋里移动，什么都看不见。 第三天，妈妈和\n我说她被公司辞退了，晚上我梦见妈妈瘾狂的割下了我的头。第四天，原来那不是梦，吃完药\n后，我知道我活不过今晚了。", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_f9b44ec880f2", "srcNo": 698, "title": "红高跟的高度", "dispTitle": "红高跟的高度", "surface": "一位女士去鞋店买了一双红色高跟鞋，这双鞋预示了她今晚的死亡。", "cats": ["反转", "悬疑", "推理", "都市"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_f9e9fb02ab7d", "srcNo": 4, "title": "空白照片", "dispTitle": "空白照片", "surface": "她洗出一卷旅行照片，所有照片都是空白。看完后，她马上取消了婚礼。", "cats": ["其他"], "difficulty": 2, "src": "github:17hczmsn/turtle_soup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_fa1b8cbe0344", "srcNo": 136, "title": "", "dispTitle": "无题 · KONpiGG #136", "surface": "我去乡下出差，朋友给我打电话说\"你妈真好…\"，第二天回到家后我崩溃了。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_fa1ed8ece75c", "srcNo": 277, "title": "048 · 遗书", "dispTitle": "048 · 遗书", "surface": "这两天为了补寒假作业把我搞得晕头转向，还好在开学那天补完了。今天一早，还没等妈妈起床，我便去学校报到，可到了学校，我却疯了。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_fa4b76e1b0c5", "srcNo": 264, "title": "033 · 女记者", "dispTitle": "033 · 女记者", "surface": "女记者去乡下采风，晚上住进了一个破旧的小旅馆。进房间后，光线很暗，床对面有幅画。第二天起来后她惊呆了好久。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_fa69fb12b874", "srcNo": 1283, "title": "", "dispTitle": "无题 · boop-yyt #1283", "surface": "He was killed by breakfast. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_fa7f7472ae6b", "srcNo": 699, "title": "回家报平安", "dispTitle": "回家报平安", "surface": "我是一名大学生，在异地上学。爸妈打电话说想我了，让我五一回家。我到家后给爸爸打电话说我回来了，爸爸回家开门的一瞬间却疯了。", "cats": ["恐怖", "悬疑", "惊悚", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_faa800c4c34d", "srcNo": 689, "title": "我正在看着你", "dispTitle": "我正在看着你", "surface": "女主爱在网上分享近况。某天收到一条留言被吓得夺门而出。也许她不该逃，第二天警方发现了尸体。", "cats": ["悬疑", "惊悚", "犯罪", "都市"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_fab9e4809ad5", "srcNo": 111, "title": "", "dispTitle": "无题 · KONpiGG #111", "surface": "\"咚\"  \"扑通\"  他笑了。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_fb44b3fabcd5", "srcNo": 226, "title": "街上的工作", "dispTitle": "街上的工作", "surface": "我正在街上努力工作，突然一个疯疯癫癫的女人向我扑来，爸爸赶紧把我抱回了家，但随后那个女人又跟来了。", "cats": ["其他"], "difficulty": 2, "src": "github:wangyafu/haiguitangmcp", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_fb5f4e257b17", "srcNo": 524, "title": "出租房", "dispTitle": "出租房", "surface": "我搬进了一个新房子，房间里经常有老鼠爬的声音，但毕竟便宜，我也睡得很香。后来房东谈了女朋友，老鼠的声音没了，但突然的安静却让我睡不着觉…", "cats": ["恐怖"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_fb6721918355", "srcNo": 1061, "title": "救命的谎言", "dispTitle": "救命的谎言", "surface": "地震后的废墟下，父亲和儿子被困。父亲不停地跟儿子说话，告诉他救援队就在头顶。三天后，儿子获救了，而父亲早已在第一天就去世了。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_fb77315aaeee", "srcNo": 1382, "title": "", "dispTitle": "无题 · boop-yyt #1382", "surface": "A man was brought before a tribal chief, who asked him a question. If he had known the answer, he probably would have died. He didn't, and lived. How could this be?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_fb9a627738a0", "srcNo": 232, "title": "闹钟", "dispTitle": "闹钟", "surface": "我定了早上7点的闹钟。早上它响了，我按掉，继续睡。10点我自然醒过来，一看手机，闹钟设置明明还是7点，可它再也没有响过第二次。", "cats": ["日常", "逻辑"], "difficulty": 1, "src": "github:AZHi-xinxin/haiguitang-coop", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_fbb763606133", "srcNo": 1348, "title": "", "dispTitle": "无题 · boop-yyt #1348", "surface": "A man sat perfectly still for 88 hours. Why?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_fbde9d409a5c", "srcNo": 1140, "title": "女明星", "dispTitle": "女明星", "surface": "有一天女明星在家里，坐在沙发上看电视，名然发出了撕心裂肺的惨叫。", "cats": ["其他"], "difficulty": 2, "src": "许二木海龟汤合集(OCR)", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_fbf3ed58597b", "srcNo": 773, "title": "爱犬", "dispTitle": "爱犬", "surface": "女孩独自在家，只有爱犬陪伴。半夜她听到奇怪水滴声，害怕的她把手伸到床边，爱犬舔了舔她的手。第二天狗死了。", "cats": ["恐怖", "惊悚", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_fc4a6ec26e32", "srcNo": 680, "title": "住进豪宅的人", "dispTitle": "住进豪宅的人", "surface": "女人签下一份为期一年的工作合同，随后搬进豪宅，不交房租，房主也很少来。一年后她按时搬走，还收到一笔钱。她没买房，也没继承财产。为什么？", "cats": ["日常", "职场"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_fc5d405d5cb8", "srcNo": 1053, "title": "上帝的橡皮擦", "dispTitle": "上帝的橡皮擦", "surface": "世界上的所有人都突然忘记了‘黄色’这个词。一名油漆工看着桶里的液体发疯了，他觉得那是‘不存在的颜色’。", "cats": ["其他"], "difficulty": 2, "src": "github:yinyyW/haiguitang", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_fc5e37b8dfde", "srcNo": 703, "title": "几节", "dispTitle": "几节", "surface": "“一节，两节，三节……”数完后我疯了。", "cats": ["怪谈", "悬疑", "惊悚"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_fc862134f0ca", "srcNo": 106, "title": "", "dispTitle": "无题 · KONpiGG #106", "surface": "妻子带回来一个小孩，丈夫却死了。", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_fcc08247e999", "srcNo": 308, "title": "080 · 第一名", "dispTitle": "080 · 第一名", "surface": "他这次考试得了全班第一，放学后却大哭了一场。", "cats": ["其他"], "difficulty": 2, "src": "github:bcefghj/rokid-collection", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_fccd2f662926", "srcNo": 1235, "title": "Jed 2.21", "dispTitle": "Jed 2.21", "surface": "Bruce wins the race, but he gets no trophy. (EMS)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_fd0d5c769d00", "srcNo": 1233, "title": "Jed 2.19", "dispTitle": "Jed 2.19", "surface": "A man marries twenty women in his village but isn't charged with polygamy.", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_fd2887197b0d", "srcNo": 474, "title": "密室里的半杯水", "dispTitle": "密室里的半杯水", "surface": "一名男子被发现死在自己反锁的书房里。房间里没有打斗痕迹，也没有明显外伤。桌上放着一杯喝了一半的水，水杯旁是一部联系人页面的手机。\n警方确认：\n房门和窗户都是从里面反锁的\n室内没有毒物残留\n手机里没有异常通话或短信\n但警方很快确定：这是一起他杀案件。", "cats": ["悬疑", "逻辑"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_fd3477ddff5b", "srcNo": 1203, "title": "Jed 1.27", "dispTitle": "Jed 1.27", "surface": "A man tells his boss, \"Don't take your planned flight today! I had a dream last night that if you do, your plane will crash and you'll die.\" The boss fires the man. (From _How Come?_)", "cats": ["其他"], "difficulty": 2, "src": "Jed's List of Situation Puzzles (1999)", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_fd3bdbe99457", "srcNo": 394, "title": "雨夜标本", "dispTitle": "雨夜标本", "surface": "\"暴雨夜我在女儿房间找到半瓶未开封的敌敌畏，窗台留着陌生男人的泥脚印。追踪三个月后，警方终于锁定住在对面的独居老人。可当我把凶器扔进警局证物箱时，镜面倒影里自己的袖口沾着一片紫丁香花瓣——那是女儿葬礼当天我才认识的品种。\"", "cats": ["家庭", "恐怖", "悲剧"], "difficulty": 3, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_fd4e96e66ef8", "srcNo": 765, "title": "女声", "dispTitle": "女声", "surface": "到站后我下了火车，火车在我面前缓缓开走，这时耳边响起冰冷女声，我崩溃了。", "cats": ["日常", "都市"], "difficulty": 1, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_fd5c37ac4e43", "srcNo": 473, "title": "不要回头", "dispTitle": "不要回头", "surface": "一群年轻人夜探废弃医院。\n我们约定，谁如果听到“自己的名字被喊”，绝对不能回头。 \n半夜，我突然隐隐约约听到了谁喊了我的名字。 \n我没有回头。 \n第二天，我却成了唯一一个“失踪”的人", "cats": ["悬疑", "日常", "本格"], "difficulty": 2, "src": "haiguitang.net", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_fd95aed7dcd9", "srcNo": 215, "title": "最棒的一天", "dispTitle": "最棒的一天", "surface": "他在公园的长椅上醒来。昨天晚上，他刚向苏珊求婚，而她已经几乎接受了他，并让他第二天下午去她家。他舒缓着酥麻的腿脚，叩响了她的门，喊着苏珊的名字。然而房门打开后，他才意识到有事情不对劲。", "cats": ["其他"], "difficulty": 2, "src": "github:wangyafu/haiguitangmcp", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_fddab6f49384", "srcNo": 1310, "title": "", "dispTitle": "无题 · boop-yyt #1310", "surface": "The music stopped and the man died. What happened?", "cats": ["其他"], "difficulty": 2, "src": "github:boop-yyt/situation_puzzle", "lang": "en", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_fde48ed43c23", "srcNo": 103, "title": "", "dispTitle": "无题 · KONpiGG #103", "surface": "幼儿园的一个小朋友数数总是说\"1，2，3，7\"，总是漏掉中间的\"4，5，6\"。可是当我纠正她时，她却说这是她妈妈教她的，我很疑惑，便提出去她家家访，家访结束后我也对她说是\"1，2，3，7\"", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_feb2743db136", "srcNo": 161, "title": "", "dispTitle": "无题 · KONpiGG #161", "surface": "一个小男孩叫了一声妈妈，接着就掉下了一个人头和一个身体", "cats": ["其他"], "difficulty": 2, "src": "github:KONpiGG/astrbot_plugin_soupai", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_fee52ece475e", "srcNo": 56, "title": "几节", "dispTitle": "几节", "surface": "\"一节，两节，三节…\"数完后我疯掉了。", "cats": ["怪谈", "恐怖"], "difficulty": 2, "src": "github:anchorAnc/astrbot_plugin_TurtleSoup", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_feea318deaaf", "srcNo": 838, "title": "火车", "dispTitle": "火车", "surface": "这是一辆行驶的火车，我刚上车不久，坐上了最后一节车厢，车厢里流了很多血，我知道我快要活不长了……", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_fef1d3664483", "srcNo": 751, "title": "妻子", "dispTitle": "妻子", "surface": "妻子对我的态度总是阴晴不定，直到有一天她把我杀了。", "cats": ["反转", "恐怖", "温情"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_ff0a78a2fd41", "srcNo": 1240, "title": "", "dispTitle": "无题 · misc #1240", "surface": "男人走进酒吧，向酒保要了一杯水；酒保拔枪指着他，他道谢后离开。为什么？", "cats": ["其他"], "difficulty": 2, "src": "misc/repo-scan", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}, {"id": "lib_ff6ce2d3c625", "srcNo": 664, "title": "差了一个单位", "dispTitle": "差了一个单位", "surface": "一艘无人飞船航行数月后，在接近目标行星时失联。发动机此前一直按指令工作，调查人员却在地面文件中发现：相同数字被两组人理解成了不同大小。发生了什么？", "cats": ["推理", "脑洞"], "difficulty": 2, "src": "haiguitang.top", "lang": "zh", "mode": "surface", "hasTruth": false, "truthSource": ""}, {"id": "lib_ff82650c1faa", "srcNo": 702, "title": "没熟", "dispTitle": "没熟", "surface": "铛铛铛：“这个没熟。”铛铛铛：“这个好像熟了！”爸爸吓出一身冷汗。", "cats": ["恐怖", "惊悚", "犯罪"], "difficulty": 3, "src": "haiguitang.top", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "recovered"}, {"id": "lib_ffbd1451be58", "srcNo": 854, "title": "宿舍", "dispTitle": "宿舍", "surface": "今天天气很热，老大在宿舍门口吃冰棍，老三刚吃完饭，在远处探头看着我们，封寝了，我准备睡觉了，朦胧中我听到老五一声惨叫……", "cats": ["其他"], "difficulty": 2, "src": "github:moxianbizi/haiguitang-php", "lang": "zh", "mode": "truth", "hasTruth": true, "truthSource": "original"}];
